-- Capability-driven input: executor branding does not guarantee API access.
local executorInput = {focused = true, held = {}, touchHeld = {}, backend = "unavailable", problem = false}
do
    local nativePress, nativeRelease = keypress, keyrelease
    local keys = {[0x20] = Enum.KeyCode.Space, [0xA0] = Enum.KeyCode.LeftShift,
        [0xA2] = Enum.KeyCode.LeftControl}
    for code = 0x41, 0x5A do keys[code] = Enum.KeyCode[string.char(code)] end
    local backends = {}
    local function addBackend(name, send)
        backends[#backends + 1] = {name = name, send = send, rejected = false}
    end
    if type(nativePress) == "function" and type(nativeRelease) == "function" then
        addBackend("executor keys", function(down, code)
            if down then nativePress(code) else nativeRelease(code) end
        end)
    end
    local ok, virtual = pcall(function() return input:CreateVirtualInput() end)
    if ok and virtual then
        addBackend("VirtualInput", function(down, code)
            virtual:SendKey(down, assert(keys[code], "Unknown key code"), false)
        end)
    end
    local available, manager = pcall(game.GetService, game, "VirtualInputManager")
    if available and manager then
        addBackend("VirtualInputManager", function(down, code)
            manager:SendKeyEvent(down, assert(keys[code], "Unknown key code"), false, game)
        end)
    end
    executorInput.available = #backends > 0
    executorInput.backend = backends[1] and (backends[1].name .. " (not yet exercised)") or "unavailable"
    local activeBackend
    function executorInput.send(down, code)
        if #backends == 0 or (down and not executorInput.available) then return false end
        if not executorInput.focused then return false end
        if down and executorInput.held[code] then return true end
        -- Release with the same backend that pressed this key, even after failover.
        if not down then
            local backend = executorInput.held[code] or activeBackend or backends[1]
            local sent, problem = pcall(backend.send, false, code)
            if sent then executorInput.held[code] = nil; return true end
            executorInput.problem, executorInput.available = tostring(problem), false
            warn(prefix .. "Key release failed; retained for cleanup: " .. tostring(problem))
            return false
        end
        local failures = {}
        for _, backend in ipairs(backends) do
            if not backend.rejected then
                local sent, problem = pcall(backend.send, true, code)
                if sent then
                    executorInput.held[code], activeBackend = backend, backend
                    executorInput.backend, executorInput.problem = backend.name, false
                    return true
                end
                backend.rejected = true
                failures[#failures + 1] = backend.name .. ": " .. tostring(problem)
            end
        end
        executorInput.problem, executorInput.available = table.concat(failures, "; "), false
        warn(prefix .. "Key input unavailable: " .. executorInput.problem)
        return false
    end
    function executorInput.releaseAll()
        executorInput.touchGeneration = (executorInput.touchGeneration or 0) + 1
        local pending = {}
        for code in pairs(executorInput.held) do pending[#pending + 1] = code end
        for _, code in ipairs(pending) do executorInput.send(false, code) end
        table.clear(executorInput.touchHeld)
    end
    function executorInput.keyDown(key)
        return executorInput.touchHeld[key] ~= nil or input:IsKeyDown(key)
    end
end
local keypress = executorInput.available and function(code) return executorInput.send(true, code) end or nil
local keyrelease = executorInput.available and function(code) return executorInput.send(false, code) end or nil
