local storageAvailable = type(isfile) == "function" and type(readfile) == "function" and type(writefile) == "function"
local reloadSourcePath = "GymRelease/mc1h-reload-source.lua"
local reloadSourceReady = false
if storageAvailable and type(source) == "string" then
    local ok, problem = pcall(function()
        if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder("GymRelease") then
            makefolder("GymRelease")
        end
        writefile(reloadSourcePath, source)
        assert(readfile(reloadSourcePath) == source, "Teleport source read-back differs")
    end)
    reloadSourceReady = ok
