local settings = {version = 1, revision = 0, slot = 1, autoLoad = false, reload = false, slots = {}}
local storageWarning
local writingSettings = false

-- Keep the previous valid revision if a file is interrupted during a write.
if storageAvailable then
    local hadFile
    for _, path in ipairs(hubControls.configFiles) do
        local checked, exists = pcall(isfile, path)
        if checked and exists then
            hadFile = true
            local valid, data = pcall(function() return http:JSONDecode(readfile(path)) end)
            if valid and type(data) == "table" and data.version == 1 and type(data.slots) == "table"
                and type(data.revision) == "number" and data.revision > settings.revision
                and data.revision < 1e12 and data.revision % 1 == 0 then
                settings = data
            end
        end
    end
    if hadFile and settings.revision == 0 then storageWarning = "Saved settings could not be read." end
end
settings.slot = (settings.slot == 2 or settings.slot == 3) and settings.slot or 1
settings.autoLoad = settings.autoLoad == true
local enableTeleportReload = settings.reload ~= true
settings.reload = true

local function saveSettings()
    if not storageAvailable or writingSettings then return false end
    writingSettings = true
    local revision = settings.revision
    settings.revision = revision + 1
    local path = hubControls.configFiles[(settings.revision - 1) % #hubControls.configFiles + 1]
    local ok = pcall(function()
        local encoded = http:JSONEncode(settings)
        writefile(path, encoded)
        assert(readfile(path) == encoded, "Settings write could not be verified.")
    end)
    writingSettings = false
    if not ok then settings.revision = revision end
    return ok
end

if enableTeleportReload and storageAvailable and not saveSettings() then
    warn(prefix .. "Teleport reload is enabled, but saving that preference failed.")
end

