if arrivalTicket then
    if not settings.reload or settings.ticket ~= arrivalTicket then return end
    arrivalConfig = type(settings.teleportConfig) == "table" and settings.teleportConfig or nil
    settings.ticket, settings.teleportConfig = nil, nil
    if not saveSettings() then
        warn(prefix .. "Could not verify the teleport reload ticket.")
