local function teleportListener(capture, onDeparture)
    local queuedTicket
    local function revoke()
        if queuedTicket and settings.ticket == queuedTicket then
            settings.ticket, settings.teleportConfig = nil, nil
            if not saveSettings() then warn(prefix .. "Could not revoke a queued reload.") end
        end
        queuedTicket = nil
    end
    local connection = player.OnTeleport:Connect(function(state)
        if state == Enum.TeleportState.Failed then
            traveling = false
            revoke()
        elseif state == Enum.TeleportState.Started or state == Enum.TeleportState.InProgress then
            if not traveling then
                traveling = true
                onDeparture()
            end
            if not settings.reload or not queueAvailable() or queuedTicket then return end
            local token = http:GenerateGUID(false)
            settings.ticket, settings.teleportConfig = token, capture()
            if settings.teleportConfig.rage and settings.teleportConfig.rage.keepFly == false then
                settings.teleportConfig.rage.fly = false
            end
            if not saveSettings() then
                settings.ticket, settings.teleportConfig = nil, nil
                warn(prefix .. "Could not save the teleport reload ticket.")
                return
            end
            queuedTicket = token
            local loader = string.format("local source = readfile(%q)\nreturn assert(loadstring(source, 'WizardHub'))(source, %q)", reloadSourcePath, token)
            local ok = pcall(queue_on_teleport, loader)
            if not ok then
                revoke()
                warn(prefix .. "Executor could not queue the teleport reload.")
            else
                warn(prefix .. "Dashboard queued for the next teleport.")
            end
        end
    end)
    return function()
        connection:Disconnect()
        revoke()
    end, revoke
end

