local jump = {
    name = "Jump shot", key = Enum.KeyCode.E, virtualKey = 0x45, keyName = "E",
    ready = "Equip a ball and face the basket.", maxHold = 0.90,
}
local dunk = {
    name = "Dunk", key = Enum.KeyCode.Space, virtualKey = 0x20, keyName = "SPACE",
    ready = "Equip a ball and move near the rim.", maxHold = 0.75,
}
local modes = {jump, dunk}
-- Physical controls stay separate from jump/dunk classification and timing.
local shotInput = {
    manualOnly = true,
    binds = {Shoot = Enum.KeyCode.ButtonX, JumpClutch = Enum.KeyCode.ButtonY, PassMenu = Enum.KeyCode.ButtonR1},
    nextRefresh = 0,
}
function shotInput.isGamepad(device)
    return device ~= nil and device.Name:match("^Gamepad[1-8]$") ~= nil
end
function shotInput.refresh(now)
    if now < shotInput.nextRefresh then return end
    shotInput.nextRefresh = now + 1
    if input.GamepadEnabled and not shotInput.native and type(getgc) == "function" then
        local ok, objects = pcall(getgc, true)
        if ok and type(objects) == "table" then
            for _, value in ipairs(objects) do
                if type(value) == "table" and type(rawget(value, "GetBinds")) == "function"
                    and type(rawget(value, "AddToTap")) == "function" then
                    local source = debug.info(value.AddToTap, "s")
                    if type(source) == "string" and source:find(".Modules.Components.Input.Gamepad", 1, true) then
                        shotInput.native = value
                        break
                    end
                end
            end
        end
    end
    if shotInput.native then
        local ok, bindings = pcall(shotInput.native.GetBinds, shotInput.native)
        if ok and type(bindings) == "table" then
            for _, action in ipairs({"Shoot", "JumpClutch", "PassMenu"}) do
                local name = bindings[action]
                local valid, key = pcall(function() return type(name) == "string" and name ~= "None" and Enum.KeyCode[name] end)
                shotInput.binds[action] = valid and key or false
            end
        end
    end
end
function shotInput.connected(device)
    local ok, connected = pcall(input.GetGamepadConnected, input, device)
    return ok and connected == true
end
function shotInput.buttonDown(device, key)
    if not key or not shotInput.connected(device) then return false end
    local ok, down = pcall(input.IsGamepadButtonDown, input, device, key)
    return ok and down == true
end
function shotInput.describe(mode, device, key)
    local gamepad = shotInput.isGamepad(device)
    local name = gamepad and (key == Enum.KeyCode.ButtonX and "X/Square"
        or key == Enum.KeyCode.ButtonY and "Y/Triangle" or key.Name) or mode.keyName
    return {device = device, key = key, label = name, gamepad = gamepad, mode = mode}
end
function shotInput.passMenu(device)
    return shotInput.buttonDown(device, shotInput.binds.PassMenu)
end
function shotInput.fromEvent(event)
    local mode
    if event.UserInputType == Enum.UserInputType.Keyboard then
        mode = event.KeyCode == jump.key and jump or event.KeyCode == dunk.key and dunk or nil
    elseif shotInput.isGamepad(event.UserInputType) and not shotInput.passMenu(event.UserInputType) then
        mode = event.KeyCode == shotInput.binds.Shoot and jump
            or event.KeyCode == shotInput.binds.JumpClutch and dunk or nil
    end
    if not mode then return end
    local control = shotInput.describe(mode, event.UserInputType, event.KeyCode)
    shotInput.lastPress, shotInput.lastPressAt = control, os.clock()
    return mode, control
end
function shotInput.held(mode)
    if executorInput.keyDown(mode.key) then
        return shotInput.describe(mode, Enum.UserInputType.Keyboard, mode.key)
    end
    local key = shotInput.binds[mode == dunk and "JumpClutch" or "Shoot"]
    if not key then return end
    local ok, pads = pcall(input.GetConnectedGamepads, input)
    if not ok or type(pads) ~= "table" then return end
    for _, device in ipairs(pads) do
        if not shotInput.passMenu(device) and shotInput.buttonDown(device, key) then
            return shotInput.describe(mode, device, key)
        end
    end
end
function shotInput.current()
    for _, mode in ipairs({dunk, jump}) do
        local control = shotInput.held(mode)
        if control then return mode, control end
    end
end
function shotInput.recent(now)
    local control = shotInput.lastPress
    if control and control.gamepad and now - shotInput.lastPressAt < 1
        and shotInput.connected(control.device) then return control end
end
function shotInput.matches(attempt, event)
    local control = attempt.inputControl
    if control and control.touch then return false end
    return event.KeyCode == (control and control.key or attempt.control.key)
        and event.UserInputType == (control and control.device or Enum.UserInputType.Keyboard)
end
function shotInput.isController(attempt)
    return attempt and attempt.inputControl and attempt.inputControl.gamepad == true
end
function shotInput.isNative(attempt)
    return attempt and attempt.inputControl
        and (attempt.inputControl.gamepad == true or attempt.inputControl.touch == true)
end
function shotInput.touchControl(mode)
    return {device = Enum.UserInputType.Touch, key = Enum.KeyCode.Unknown,
        label = "Touch", touch = true, mode = mode}
end

