local appearance = {basePalette = table.clone(colors), nodes = {}, roles = {}, corners = {}, backgrounds = {}, style = "Default"}
local gameAppearance = {}
local sceneOverrides = {}
local renderOptions = {}
-- Typeface: Builder Sans where the client has it, Gotham otherwise. Bold is kept for page titles
-- and the name only; everything else is regular or medium.
do
    local function face(name, fallback)
        local ok, found = pcall(function() return Enum.Font[name] end)
        return ok and found or fallback
    end
    appearance.fonts = {
        [Enum.Font.Gotham] = face("BuilderSans", Enum.Font.Gotham),
        [Enum.Font.GothamMedium] = face("BuilderSansMedium", Enum.Font.GothamMedium),
        [Enum.Font.GothamBold] = face("BuilderSansMedium", Enum.Font.GothamMedium),
        [Enum.Font.GothamBlack] = face("BuilderSansBold", Enum.Font.GothamBold),
    }
end

function appearance.paint(object, property, role)
    local roles = appearance.roles[object]
    if not roles then
        roles = {}
        appearance.roles[object] = roles
    end
    roles[property] = role
    object[property] = colors[role]
end

-- Motion: short eased changes for hover, press, switches, page changes and opening the menu.
appearance.tweens = game:GetService("TweenService")
function appearance.ease(object, seconds, goal)
    local ok, tween = pcall(function()
        return appearance.tweens:Create(object, TweenInfo.new(seconds, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), goal)
    end)
    if ok and tween then
        tween:Play()
        return tween
    end
    for property, value in pairs(goal) do object[property] = value end
    return nil
end

local function create(className, parent, properties)
    local object = Instance.new(className)
    for property, value in pairs(properties) do object[property] = value end
    local face = properties.Font and appearance.fonts[properties.Font]
    if face then
        -- Large bold text (page titles) stays bold; small bold text becomes medium.
        if properties.Font == Enum.Font.GothamBold and (properties.TextSize or 0) >= 20 then
            face = appearance.fonts[Enum.Font.GothamBlack]
        end
        object.Font = face
    end
    if appearance.nodes[parent] then
        appearance.nodes[object] = true
        for _, property in ipairs({"BackgroundColor3", "TextColor3", "PlaceholderColor3", "ScrollBarImageColor3", "Color"}) do
            local value = properties[property]
            if value ~= nil then
                for role, color in pairs(appearance.basePalette) do
                    if value == color then appearance.paint(object, property, role); break end
                end
            end
        end
        if className == "UICorner" then appearance.corners[object] = properties.CornerRadius.Offset end
    end
    object.Parent = parent
    return object
end

local function rounded(object, radius)
    create("UICorner", object, {CornerRadius = UDim.new(0, radius)})
    return object
end

local function label(parent, value, x, y, width, height, textSize, font, color)
    -- Page titles were 25; a little smaller reads calmer.
    if textSize == 25 then textSize = 22 end
    return create("TextLabel", parent, {
        BackgroundTransparency = 1, Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(width, height),
        Text = value, Font = font, TextSize = textSize, TextColor3 = color, TextXAlignment = Enum.TextXAlignment.Left,
    })
end

local function button(parent, value, x, y, width, height, background, color)
    local object = rounded(create("TextButton", parent, {
        BackgroundColor3 = background, BorderSizePixel = 0, Position = UDim2.fromOffset(x, y),
        Size = UDim2.fromOffset(width, height), Text = value, TextColor3 = color,
        Font = Enum.Font.GothamMedium, TextSize = 13, AutoButtonColor = false,
    }), 8)
    local veil = rounded(create("Frame", object, {
        Name = "WizardHover", BorderSizePixel = 0, Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = colors.text, BackgroundTransparency = 1,
    }), 8)
    local inside, held = false, false
    local function show()
        appearance.ease(veil, held and 0.08 or 0.16, {BackgroundTransparency = held and 0.86 or (inside and 0.93 or 1)})
    end
    object.MouseEnter:Connect(function() inside = true; show() end)
    object.MouseLeave:Connect(function() inside, held = false, false; show() end)
    object.MouseButton1Down:Connect(function() held = true; show() end)
    object.MouseButton1Up:Connect(function() held = false; show() end)
    return object
end

function appearance.colorChip(parent, x, y, width, height, color)
    local chip = button(parent, "", x, y, width, height, colors.card, colors.text)
    appearance.roles[chip].BackgroundColor3 = nil
    chip.BackgroundColor3 = color
    return chip
end

