task.spawn(function()
    -- The page icons: one white sheet (4 across, 32 px cells), written out once from the text below.
    local okIcons, sheet = pcall(function()
        local path = "GymRelease/wizardhub-icons-1.png"
        if not isfile(path) then
            local packed = ""
            local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
            local values, bytes, bits, count = {}, {}, 0, 0
            for position = 1, 64 do values[string.byte(alphabet, position)] = position - 1 end
            for position = 1, #packed do
                local value = values[string.byte(packed, position)]
                if value then
                    bits, count = bits * 64 + value, count + 6
                    if count >= 8 then
                        count -= 8
                        local byte = math.floor(bits / 2 ^ count)
                        bits -= byte * 2 ^ count
                        bytes[#bytes + 1] = string.char(byte)
                    end
                end
            end
            writefile(path, table.concat(bytes))
        end
        return getcustomasset(path)
    end)
    if okIcons and type(sheet) == "string" and sheet ~= "" then
        appearance.iconSheet = sheet
        for _, image in ipairs(appearance.navIcons) do image.Image = sheet end
    end
end)
