local function showSwitch(control, enabled)
    local before = control.pill.BackgroundColor3
    appearance.paint(control.pill, "BackgroundColor3", enabled and "accent" or "line")
    appearance.paint(control.knob, "BackgroundColor3", enabled and "ink" or "muted")
    local place = UDim2.fromOffset(enabled and 16 or 2, 2)
    if control.shown == nil or control.shown == enabled or not gui.Enabled then
        control.knob.Position = place
    else
        local after = control.pill.BackgroundColor3
        control.pill.BackgroundColor3 = before
        appearance.ease(control.pill, 0.18, {BackgroundColor3 = after})
        appearance.ease(control.knob, 0.18, {Position = place})
    end
    control.shown = enabled
end

local sliders = {}
local function showSlider(item, value)
    if type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then value = item.default end
    local step = item.step or 0.01
    item.value = math.clamp(math.floor(value / step + 0.5) * step, item.min, item.max)
    local fraction = (item.value - item.min) / (item.max - item.min)
    item.fill.Size = UDim2.fromScale(fraction, 1)
    item.knob.Position = UDim2.fromScale(fraction, 0.5)
    item.amount.Text = string.format(item.format, item.value * (item.displayScale or 1))
    if item.onChange then item.onChange() end
end

local function slider(parent, caption, x, y, min, max, value, format, displayScale)
    -- The card behind the control, made first so that it sits underneath.
    local plate = rounded(create("Frame", parent, {
        Name = "WizardSliderCard", BorderSizePixel = 0, Position = UDim2.fromOffset(x, y - 2),
        Size = UDim2.fromOffset(316, 42), BackgroundColor3 = colors.card,
    }), 8)
    appearance.paint(create("UIStroke", plate, {Name = "WizardRowOutline", Thickness = 1}), "Color", "divider")
    label(parent, caption, x + 12, y, 206, 22, 13, Enum.Font.GothamMedium, colors.text)
    local amount = create("TextBox", parent, {
        Text = "", Position = UDim2.fromOffset(x + 220, y), Size = UDim2.fromOffset(84, 22),
        BackgroundTransparency = 1, TextSize = 12, Font = Enum.Font.Gotham,
        TextColor3 = colors.muted, ClearTextOnFocus = false,
    })
    amount.TextXAlignment = Enum.TextXAlignment.Right
    local track = button(parent, "", x + 12, y + 20, 292, 18, colors.surface, colors.text)
    track.AutoButtonColor = false
    track.BackgroundTransparency = 1
    local veil = track:FindFirstChild("WizardHover")
    if veil then veil:Destroy() end
    local bar = rounded(create("Frame", track, {
        Position = UDim2.fromOffset(0, 7), Size = UDim2.new(1, 0, 0, 4), BorderSizePixel = 0,
        BackgroundColor3 = colors.line,
    }), 2)
    local fill = rounded(create("Frame", bar, {BorderSizePixel = 0, BackgroundColor3 = colors.accent}), 2)
    local knob = rounded(create("Frame", track, {
        AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(12, 12), BorderSizePixel = 0,
        BackgroundColor3 = colors.text,
    }), 7)
    create("UIStroke", knob, {Name = "WizardKnobRing", Color = colors.card, Thickness = 2})
    track.MouseEnter:Connect(function() appearance.ease(knob, 0.16, {Size = UDim2.fromOffset(14, 14)}) end)
    track.MouseLeave:Connect(function() appearance.ease(knob, 0.16, {Size = UDim2.fromOffset(12, 12)}) end)
    local item = {track = track, amount = amount, fill = fill, knob = knob, min = min, max = max,
        format = format:gsub("%%([+%-]?)d", "%%%1.2f"):gsub("%%%.1f", "%%.2f"),
        default = value, displayScale = displayScale, step = 0.01 / math.abs(displayScale or 1)}
    amount.FocusLost:Connect(function()
        local typed = tonumber(amount.Text) or tonumber(amount.Text:match("[+%-]?%d*%.?%d+"))
        showSlider(item, typed and typed / (item.displayScale or 1) or item.value)
    end)
    table.insert(sliders, item)
    showSlider(item, value)
    return item
end

