    local function normalizeHex(value)
        if type(value) ~= "string" then return end
        local digits = value:match("^%s*#?(%x%x%x%x%x%x)%s*$")
        return digits and digits:upper()
    end

    local function updateTransparency()
        local fade = opacity.value / 100
        for object, original in pairs(appearance.backgrounds) do
            local base = original
            if object == dashboard then base = selected.surfaceFade or 0
            elseif object == sidebar then base = selected.railFade or (menuLayout.preset == "Classic" and 1 or 0)
            elseif object == appearance.header then base = selected.headerFade or (menuLayout.preset == "Classic" and 1 or 0) end
            object.BackgroundTransparency = 1 - (1 - base) * (1 - fade)
        end
    end
    appearance.updateTransparency = updateTransparency

    function appearance.capture()
        return {style = selected.name, accent = customAccent, transparency = opacity.value, look = 3}
    end

    function appearance.apply(saved)
        saved = type(saved) == "table" and saved or {}
        selected = byName[saved.style] or themes[1]
        appearance.style = selected.name
        customAccent = normalizeHex(saved.accent)
        -- The old default pink was saved as if it had been picked; it gives way to the style's accent once.
        if saved.look ~= 3 and (customAccent == "FF548A" or customAccent == "7688FF") then customAccent = nil end
        for role, color in pairs(appearance.basePalette) do colors[role] = color end
        for role, hex in pairs(selected.palette or {}) do colors[role] = Color3.fromHex(hex) end
        local hex = customAccent or selected.accent
        colors.accent = Color3.fromHex(hex)
        if customAccent then
            colors.line = colors.surface:Lerp(colors.accent, 0.55)
            local lightness = colors.accent.R * 0.299 + colors.accent.G * 0.587 + colors.accent.B * 0.114
            colors.ink = Color3.fromHex(lightness > 0.53 and "100E14" or "FFFFFF")
        end
        colors.selection = colors.sidebar:Lerp(colors.accent, selected.name == "Ivory" and 0.16 or 0.22)
        colors.tint = colors.card:Lerp(colors.accent, 0.18)
        for object, roles in pairs(appearance.roles) do
            for property, role in pairs(roles) do object[property] = colors[role] end
        end
        for corner, radius in pairs(appearance.corners) do
            corner.CornerRadius = UDim.new(0, math.round(radius * selected.radius))
        end
        appearance.brand.Font = selected.font or appearance.fonts[Enum.Font.GothamBlack]
        appearance.border.Thickness = selected.border
        appearance.header.Visible = selected.headerFade ~= nil
        appearance.headerAccent.Visible = selected.stripe ~= nil
        if selected.stripe then appearance.headerAccent.Size = UDim2.fromOffset(selected.stripe[1], selected.stripe[2]) end
        appearance.endMarker = selected.endMarker == true
        appearance.stripe = selected.stripe
        menuLayout.styleChrome()
        for name, card in pairs(cards) do
            local active = name == selected.name
            appearance.paint(card.button, "TextColor3", active and "accent" or "text")
            appearance.paint(card.border, "Color", active and "accent" or "divider")
            card.border.Thickness = active and 2 or 1
        end
        local transparency = saved.transparency
        showSlider(opacity, type(transparency) == "number" and transparency == transparency and math.round(transparency) or 0)
        hexBox.Text = "#" .. hex
        accentStatus.Text = customAccent and "Custom accent" or "Using the style’s accent"
    end

    function appearance.bind(connectControl, redraw)
        local backgrounds = {surface = true, sidebar = true, card = true, tint = true, dangerBackground = true}
        for object, roles in pairs(appearance.roles) do
            if backgrounds[roles.BackgroundColor3] then appearance.backgrounds[object] = object.BackgroundTransparency or 0 end
        end
        opacity.onChange = updateTransparency
        local function showPane(name)
            appearance.layoutPane.Visible = name == "Layouts"
            appearance.themePane.Visible = name == "Colors"
            appearance.gamePane.Visible = name == "Game"
            appearance.performancePane.Visible = name == "Performance"
            appearance.paint(appearance.layoutTab, "TextColor3", name == "Layouts" and "accent" or "text")
            appearance.paint(appearance.themeTab, "TextColor3", name == "Colors" and "accent" or "text")
            appearance.paint(appearance.gameTab, "TextColor3", name == "Game" and "accent" or "text")
            appearance.paint(appearance.performanceTab, "TextColor3", name == "Performance" and "accent" or "text")
            for tab, pane in pairs({[appearance.layoutTab] = "Layouts", [appearance.themeTab] = "Colors",
                [appearance.gameTab] = "Game", [appearance.performanceTab] = "Performance"}) do
                appearance.paint(tab, "BackgroundColor3", name == pane and "tint" or "card")
            end
        end
        connectControl(appearance.layoutTab.Activated, function() showPane("Layouts") end)
        connectControl(appearance.themeTab.Activated, function() showPane("Colors") end)
        connectControl(appearance.gameTab.Activated, function() showPane("Game") end)
        connectControl(appearance.performanceTab.Activated, function() showPane("Performance") end)
        showPane("Colors")
        local function selectStyle(style, accent)
            appearance.apply({style = style, accent = accent, transparency = opacity.value, look = 3})
            redraw()
        end
        for name, card in pairs(cards) do
            connectControl(card.button.Activated, function() selectStyle(name, customAccent) end)
        end
        for _, chip in ipairs(chips) do
            connectControl(chip.button.Activated, function() selectStyle(selected.name, chip.hex) end)
        end
        connectControl(hexBox.FocusLost, function()
            local hex = normalizeHex(hexBox.Text)
            if not hex then
                hexBox.Text = "#" .. (customAccent or selected.accent)
                accentStatus.Text = "Enter a six-digit hex color, such as #49BDFF."
            elseif hex ~= (customAccent or selected.accent) then
                selectStyle(selected.name, hex)
            end
        end)
        connectControl(useStyle.Activated, function() selectStyle(selected.name, nil) end)
        connectControl(reset.Activated, function() appearance.apply(nil); redraw() end)
        appearance.apply(nil)
    end
end

local hud = {}
do
    local defaults = {
        enabled = true, modules = true, feedback = true, fps = true, ping = true, rated = true, title = true,
        corner = 1, accent = "#2F7DF6", text = "#ECEDF0", panel = "#131417", perfect = "#68D391",
    }
    local state = table.clone(defaults)
    local corners = {
        {name = "Top right", x = 1, y = 0}, {name = "Top left", x = 0, y = 0},
        {name = "Bottom right", x = 1, y = 1}, {name = "Bottom left", x = 0, y = 1},
    }
    local toggles = {
        {"enabled", "Show HUD"}, {"modules", "Enabled modules"}, {"feedback", "Shot feedback"},
        {"fps", "Live FPS"}, {"ping", "Live Data Ping"}, {"rated", "Rated shot stats"}, {"title", "Wizard Hub title"},
    }
    local colorTargets = {{"accent", "Accent"}, {"text", "Text"}, {"panel", "Panels"}, {"perfect", "Perfect"}}
    local palette = {"#2F7DF6", "#7688FF", "#FF548A", "#68D391", "#FFD16C", "#ECEDF0", "#131417"}

    local function normalizeHex(value)
        if type(value) ~= "string" then return end
        local digits = value:match("^%s*#?(%x%x%x%x%x%x)%s*$")
        if digits then return "#" .. digits:upper() end
    end

    local function fromHex(value)
        return Color3.fromRGB(tonumber(value:sub(2, 3), 16), tonumber(value:sub(4, 5), 16), tonumber(value:sub(6, 7), 16))
    end

    label(hudSettings, "HUD Settings", 0, 0, 480, 35, 25, Enum.Font.GothamBold, colors.text)
    divider(hudSettings, 0, 71, 699, 1)
    label(hudSettings, "Overlay", 0, 83, 327, 20, 12, Enum.Font.GothamMedium, colors.muted)
    label(hudSettings, "Appearance", 359, 83, 327, 20, 12, Enum.Font.GothamMedium, colors.muted)
    for index, item in ipairs(toggles) do
        item.control = switch(hudSettings, item[2], 0, 104 + (index - 1) * 33)
    end

    local anchorButton = button(hudSettings, "", 359, 105, 315, 30, colors.card, colors.text)
    local sizeSlider = slider(hudSettings, "HUD scale", 359, 141, 65, 145, 100, "%d%%")
    local marginSlider = slider(hudSettings, "Screen margin", 359, 186, 8, 64, 18, "%d px")
    local opacitySlider = slider(hudSettings, "Panel opacity", 359, 231, 0, 100, 60, "%d%%")
    local holdSlider = slider(hudSettings, "Show shot feedback for", 0, 337, 1, 12, 4, "%d s")
    local resetStats = button(hudSettings, "Reset shot stats", 0, 385, 151, 25, colors.card, colors.muted)
    local resetAppearance = button(hudSettings, "Reset appearance", 520, 353, 154, 29, colors.card, colors.muted)
    local slidersByName = {scale = sizeSlider, margin = marginSlider, opacity = opacitySlider, hold = holdSlider}
    local picked = "accent"
    local swatches = {}
    for index, target in ipairs(colorTargets) do
        target.button = button(hudSettings, target[2], 359 + (index - 1) * 80, 280, 75, 27, colors.card, colors.text)
    end
    for index, hex in ipairs(palette) do
        local chip = appearance.colorChip(hudSettings, 359 + (index - 1) * 46, 317, 39, 25, fromHex(hex))
        chip.Name = "WizardHudSwatch" .. hex:sub(2)
        create("UIStroke", chip, {Color = colors.divider, Thickness = 1})
        swatches[index] = chip
    end
    local hexBox = rounded(create("TextBox", hudSettings, {
        Name = "WizardHudHexColor", Position = UDim2.fromOffset(359, 353), Size = UDim2.fromOffset(149, 29),
        BackgroundColor3 = colors.card, BorderSizePixel = 0, TextColor3 = colors.text, TextSize = 13,
        Font = Enum.Font.GothamMedium, ClearTextOnFocus = false, PlaceholderText = "#2F7DF6",
    }), 8)
    local hexStatus = label(hudSettings, "Choose a color or enter a hex code.", 359, 385, 315, 19, 11, Enum.Font.Gotham, colors.muted)

    local overlay = create("ScreenGui", playerGui, {Name = "WizardHubHUD", DisplayOrder = 18, ResetOnSpawn = false})
    hud.overlay = overlay
    local screen = create("Frame", overlay, {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1)})
    local column = create("Frame", screen, {
        BackgroundTransparency = 1, Size = UDim2.fromOffset(0, 0), AutomaticSize = Enum.AutomaticSize.XY,
    })
    local arrangement = create("UIListLayout", column, {
        SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 3),
    })
    local overlayScale = create("UIScale", column, {})
    local allRows, moduleRows = {}, {}
    local function makeRow(name, order, font, colorName, withBar)
        local row = rounded(create("TextLabel", column, {
            Name = name, LayoutOrder = order, AutomaticSize = Enum.AutomaticSize.X,
            Size = UDim2.fromOffset(0, 24), BorderSizePixel = 0, Font = font, TextSize = 13,
            TextStrokeTransparency = 0.85, Visible = false,
        }), 6)
        create("UIPadding", row, {PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10)})
        local bar = withBar and create("Frame", row, {
            BorderSizePixel = 0, Size = UDim2.new(0, 2, 1, -6),
        }) or nil
        local entry = {row = row, bar = bar, colorName = colorName}
        table.insert(allRows, entry)
        return entry
    end

    local title = makeRow("WizardHudTitle", 0, Enum.Font.GothamBlack, "accent", true)
    title.row.Text, title.row.TextSize = "Wizard Hub", 14
    local metrics = makeRow("WizardHudMetrics", 1, Enum.Font.GothamMedium, "text")
    local rated = makeRow("WizardHudRatedShots", 2, Enum.Font.GothamMedium, "text")
    local feedback = makeRow("WizardHudShotFeedback", 3, Enum.Font.GothamBold, "text")
    local contestMeter = create("BillboardGui", playerGui, {
        Name = "WizardHubContestMeter", Enabled = false, ResetOnSpawn = false,
        AlwaysOnTop = true, LightInfluence = 0, Size = UDim2.fromOffset(146, 30),
    })
    local contestText = rounded(create("TextLabel", contestMeter, {
        Name = "WizardHudContest", Size = UDim2.fromScale(1, 1), BorderSizePixel = 0,
        Font = Enum.Font.GothamBold, TextSize = 12, TextYAlignment = Enum.TextYAlignment.Top,
        TextStrokeTransparency = 0.68,
    }), 6)
    create("UIPadding", contestText, {PaddingTop = UDim.new(0, 3)})
    local contestTrack = rounded(create("Frame", contestText, {
        BorderSizePixel = 0, BackgroundColor3 = colors.divider,
        Position = UDim2.new(0, 8, 1, -8), Size = UDim2.new(1, -16, 0, 4),
    }), 2)
    local contestFill = rounded(create("Frame", contestTrack, {
        Name = "WizardHudContestFill", BorderSizePixel = 0, Size = UDim2.fromScale(0, 1),
    }), 2)
    local lightContest, heavyContest = Color3.fromRGB(255, 193, 92), Color3.fromRGB(255, 103, 113)
    local contestValue, contestHeight
    local session = {rated = 0, perfect = 0, streak = 0}
    local lastRating, lastMode, lastRatingAt
    local now = 0
    local seconds, frameCount, fps, dataPing, nextSample = 0, 0, nil, nil, 0
    local enabledNames = {}

    local function positionHud()
        local corner = corners[state.corner]
        local viewport = screen.AbsoluteSize
        local margin = math.max(4, math.min(marginSlider.value, math.floor(math.min(viewport.X, viewport.Y) / 8)))
        column.AnchorPoint = Vector2.new(corner.x, corner.y)
        column.Position = UDim2.new(corner.x, corner.x == 0 and margin or -margin, corner.y, corner.y == 0 and margin or -margin)
        arrangement.HorizontalAlignment = corner.x == 1 and Enum.HorizontalAlignment.Right or Enum.HorizontalAlignment.Left
        local contentHeight = 0
        for _, entry in ipairs(allRows) do
            if entry.row.Visible then contentHeight += entry.row.Size.Y.Offset + 3 end
            entry.row.TextXAlignment = corner.x == 1 and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left
            if entry.bar then
                entry.bar.AnchorPoint = Vector2.new(corner.x, 0)
                entry.bar.Position = UDim2.new(corner.x, corner.x == 1 and 6 or -6, 0, 3)
            end
        end
        local widthLimit = viewport.X > 0 and (viewport.X - 2 * margin) / 332 or math.huge
        local heightLimit = viewport.Y > 0 and (viewport.Y - 2 * margin) / math.max(26, contentHeight) or math.huge
        overlayScale.Scale = math.max(0.25, math.min(sizeSlider.value / 100, widthLimit, heightLimit))
    end

    local function updateRows()
        title.row.Visible = state.title
        metrics.row.Visible = state.fps or state.ping
        rated.row.Visible = state.rated
        feedback.row.Visible = state.feedback and lastRatingAt ~= nil and now - lastRatingAt < holdSlider.value
        local live = {}
        if state.fps then table.insert(live, fps and string.format("FPS %d", fps) or "FPS —") end
        if state.ping then table.insert(live, dataPing and string.format("Data Ping %.2f ms", dataPing) or "Data Ping —") end
        metrics.row.Text = table.concat(live, "  ·  ")
        local percent = session.rated > 0 and string.format("%.0f%%", 100 * session.perfect / session.rated) or "—"
        rated.row.Text = string.format("Rated shots %d  ·  Perfect %s  ·  Streak %d", session.rated, percent, session.streak)
        feedback.row.Text = lastRating and (lastMode .. "  ·  " .. privacy.redact(lastRating)) or ""
        feedback.colorName = lastRating and lastRating:lower() == "perfect release" and "perfect" or "text"
        positionHud()
    end

    local function applyColors()
        local chosen = {
            accent = fromHex(state.accent), text = fromHex(state.text), panel = fromHex(state.panel), perfect = fromHex(state.perfect),
        }
        for _, entry in ipairs(allRows) do
            entry.row.TextColor3 = chosen[entry.colorName]
            entry.row.BackgroundColor3 = chosen.panel
            entry.row.BackgroundTransparency = 1 - opacitySlider.value / 100
            if entry.bar then entry.bar.BackgroundColor3 = chosen.accent end
        end
        contestText.TextColor3 = chosen.text
        contestText.BackgroundColor3 = chosen.panel
        contestText.BackgroundTransparency = 1 - opacitySlider.value / 100
        if contestValue and contestValue < 20 then contestFill.BackgroundColor3 = chosen.perfect end
    end

    local function refreshSettings()
        overlay.Enabled = state.enabled
        contestMeter.Enabled = state.enabled and contestValue ~= nil
        for _, item in ipairs(toggles) do showSwitch(item.control, state[item[1]]) end
        anchorButton.Text = "Corner   /   " .. corners[state.corner].name .. "     ›"
        for _, target in ipairs(colorTargets) do
            local active = picked == target[1]
            appearance.paint(target.button, "BackgroundColor3", active and "tint" or "card")
            appearance.paint(target.button, "TextColor3", active and "accent" or "text")
        end
        hexBox.Text = state[picked]
        updateRows()
        applyColors()
    end

    function hud.refresh(names)
        if names then
            enabledNames = table.clone(names)
            table.sort(enabledNames, function(left, right)
                if #left == #right then return left < right end
                return #left > #right
            end)
        end
        for index, name in ipairs(enabledNames) do
            local entry = moduleRows[index]
            if not entry then
                entry = makeRow("WizardHudModule", 10 + index, Enum.Font.GothamBold, "accent", true)
                moduleRows[index] = entry
            end
            entry.row.Text = name
        end
        for index, entry in ipairs(moduleRows) do entry.row.Visible = state.modules and index <= #enabledNames end
        updateRows()
        applyColors()
    end

    function hud.sample(currentTime, frameTime, pingMs)
        now = currentTime
        if type(frameTime) == "number" and frameTime > 0 and frameTime < math.huge then
            seconds += frameTime
            frameCount += 1
        end
        if now < nextSample then return end
        nextSample = now + 0.25
        fps = frameCount > 0 and math.floor(frameCount / seconds + 0.5) or nil
        dataPing = type(pingMs) == "number" and pingMs > 0 and pingMs < math.huge and pingMs or nil
        seconds, frameCount = 0, 0
        if state.enabled then updateRows() end
    end

    function hud.setContest(value, adornee, height)
        if contestValue == value and contestMeter.Adornee == adornee and contestHeight == height then return end
        contestValue, contestHeight = value, height
        contestMeter.Adornee = adornee
        contestMeter.Enabled = state.enabled and value ~= nil
        if value then
            contestMeter.StudsOffsetWorldSpace = Vector3.new(0, height, 0)
            contestText.Text = string.format("Contest est.  %d/100", value)
            contestFill.Size = UDim2.fromScale(value / 100, 1)
            contestFill.BackgroundColor3 = value >= 55 and heavyContest or (value >= 20 and lightContest or fromHex(state.perfect))
        end
    end

    function hud.owns(object)
        return object:IsDescendantOf(overlay) or object:IsDescendantOf(contestMeter)
    end

    function hud.onRating(modeName, rating)
        local perfect = rating:lower() == "perfect release"
        if gameAppearance.onRating then gameAppearance.onRating(rating) end
        session.rated += 1
        session.perfect += perfect and 1 or 0
        session.streak = perfect and session.streak + 1 or 0
        lastMode, lastRating, lastRatingAt = modeName, rating, now
        updateRows()
        applyColors()
    end

    -- Puts the game's own name for the shot on the feedback line once it is known.
    function hud.describe(shotName)
        if not lastRatingAt or now - lastRatingAt > 6 then return end
        lastMode = shotName
        updateRows()
        applyColors()
    end

    function hud.capture()
        local saved = table.clone(state)
        for name, item in pairs(slidersByName) do saved[name] = item.value end
        saved.look = 3
        return saved
    end

    function hud.apply(saved)
        saved = type(saved) == "table" and saved or {}
        for key, default in pairs(defaults) do
            local value = saved[key]
            if type(default) == "boolean" then
                state[key] = default
                if type(value) == "boolean" then state[key] = value end
            elseif key == "corner" then
                state[key] = type(value) == "number" and corners[value] and value or default
            else
                local hex = normalizeHex(value)
                -- A config saved under the old look carries that look's default colours as if they
                -- had been chosen. They move to the new defaults once; colours picked since stay.
                if saved.look ~= 3 and (hex == ({accent = "#FF548A", text = "#F6F4F7", panel = "#120F15", perfect = "#7BE3A7"})[key]
                    or (key == "accent" and hex == "#7688FF")) then hex = nil end
                state[key] = hex or default
            end
        end
        for name, item in pairs(slidersByName) do
            local value = saved[name]
            showSlider(item, type(value) == "number" and value == value and value or item.default)
        end
        refreshSettings()
        hud.refresh()
    end

    function hud.connect(connect)
        for _, item in ipairs(toggles) do
            local key = item[1]
            connect(item.control.row.Activated, function()
                state[key] = not state[key]
                refreshSettings()
                hud.refresh()
            end)
        end
        connect(anchorButton.Activated, function()
            state.corner = state.corner % #corners + 1
            refreshSettings()
        end)
        connect(resetStats.Activated, function()
            session = {rated = 0, perfect = 0, streak = 0}
            lastRating, lastMode, lastRatingAt = nil, nil, nil
            updateRows()
        end)
        for _, target in ipairs(colorTargets) do
            connect(target.button.Activated, function()
                picked = target[1]
                refreshSettings()
            end)
        end
        for index, chip in ipairs(swatches) do
            connect(chip.Activated, function()
                state[picked] = palette[index]
                refreshSettings()
            end)
        end
        connect(hexBox.FocusLost, function()
            local value = normalizeHex(hexBox.Text)
            if value then state[picked] = value end
            hexStatus.Text = value and "Choose a color or enter a hex code." or "Enter six hex digits, such as #FF548A."
            refreshSettings()
        end)
        connect(resetAppearance.Activated, function()
            state.corner = defaults.corner
            for _, target in ipairs(colorTargets) do state[target[1]] = defaults[target[1]] end
            for _, item in ipairs({sizeSlider, marginSlider, opacitySlider}) do showSlider(item, item.default) end
            refreshSettings()
        end)
        connect(screen:GetPropertyChangedSignal("AbsoluteSize"), positionHud)
        sizeSlider.onChange = function()
            local scale = sizeSlider.value / 100
            contestMeter.Size = UDim2.fromOffset(146 * scale, 30 * scale)
            contestText.TextSize = math.round(12 * scale)
            positionHud()
        end
        marginSlider.onChange = positionHud
        opacitySlider.onChange, holdSlider.onChange = applyColors, updateRows
        refreshSettings()
    end

    function hud.destroy()
        contestMeter:Destroy()
        overlay:Destroy()
    end
end

menuLayout.resetButton = button(hudSettings, "Reset menu layout", 164, 385, 151, 25, colors.card, colors.muted)

do
    local root = pages.Defense
