    defense.guardPane = create("Frame", root, {Name = "WizardGuardPane", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1)})
    defense.guardTab = button(root, "Guard", 466, 1, 105, 32, colors.card, colors.text)
    defense.blockTab = button(root, "Blocking", 583, 1, 105, 32, colors.card, colors.text)
    local panel = defense.guardPane
    defense.toggle = switch(panel, "Auto Guard", 0, 83)
    defense.manualSwitch = switch(panel, "Manual Override", 0, 120)
    defense.footworkSwitch = switch(panel, "Auto footwork", 0, 157)
    defense.bind = button(panel, "", 359, 84, 315, 32, colors.card, colors.text)
    defense.modeButtons = {
