    defense.modeButtons.Legit.Name, defense.modeButtons.Blatant.Name = "GuardLegitMode", "GuardBlatantMode"
    defense.status = label(panel, "Auto Guard is off.", 0, 194, 325, 30, 11, Enum.Font.GothamMedium, colors.muted)
    defense.status.TextWrapped = true
    antiStun.toggle = switch(panel, "Anti-Stun", 359, 157)
    antiStun.status = label(panel, "Anti-Stun is off.", 359, 194, 315, 30, 11, Enum.Font.Gotham, colors.muted)
    antiStun.status.TextWrapped = true
    defense.settingsPanel = rounded(create("ScrollingFrame", panel, {
        Name = "GuardModeSettings", Position = UDim2.fromOffset(0, 230), Size = UDim2.fromOffset(699, 181),
        CanvasSize = UDim2.fromOffset(0, 370), BackgroundColor3 = colors.sidebar, BorderSizePixel = 0,
        ScrollBarThickness = 3, ScrollBarImageColor3 = colors.accent, ScrollingDirection = Enum.ScrollingDirection.Y,
    }), 9)
    local settingsPanel = defense.settingsPanel
    defense.settingsTitle = label(settingsPanel, "", 10, 5, 660, 22, 12, Enum.Font.GothamBold, colors.accent)
    defense.range = slider(settingsPanel, "Engage distance", 10, 35, 4, 28, 12, "%d studs")
    defense.spacing = slider(settingsPanel, "Guard spacing", 10, 83, 2, 8, 4, "%d studs")
    defense.stance = slider(settingsPanel, "Stance distance", 10, 131, 3, 16, 7, "%d studs")
    defense.paintSpacing = slider(settingsPanel, "Inside spacing", 10, 179, 1, 6, 4, "%d studs")
    defense.lead = slider(settingsPanel, "Anticipate movement", 359, 35, 0, 300, 100, "%d ms")
    defense.response = slider(settingsPanel, "Response interval", 359, 83, 16, 140, 50, "%d ms")
    defense.stickiness = slider(settingsPanel, "Target stickiness", 359, 131, 0, 6, 2, "%d studs")
    defense.smoothing = slider(settingsPanel, "Movement smoothing", 359, 179, 0, 180, 90, "%d ms")
    defense.pressureSwitch = switch(settingsPanel, "Close pressure", 10, 232)
    defense.blockPerimeter = true
    defense.perimeterSwitch = switch(settingsPanel, "Block midrange / 3-point shots", 359, 232)
    defense.teleportSwitch = switch(settingsPanel, "Teleport to opponent", 10, 272)
    defense.settingsNote = label(settingsPanel, "", 10, 318, 660, 42, 11, Enum.Font.Gotham, colors.muted)
    defense.settingsNote.TextWrapped = true
    defense.collapsedNote = label(panel, "Turn on Auto Guard, then select Legit or Blatant to reveal its settings.",
        0, 244, 680, 38, 12, Enum.Font.Gotham, colors.muted)
    defense.collapsedNote.TextWrapped = true

    local keys = {"range", "spacing", "stance", "lead", "response", "paintSpacing", "stickiness", "smoothing"}
    local defaults = {
        Legit = {range = 12, spacing = 4, stance = 7, lead = 100, response = 50, paintSpacing = 4, stickiness = 2, smoothing = 90, pressure = false},
        Blatant = {range = 18, spacing = 3, stance = 10, lead = 180, response = 25, paintSpacing = 2, stickiness = 3, smoothing = 30, pressure = true},
    }
    defense.profiles = {Legit = table.clone(defaults.Legit), Blatant = table.clone(defaults.Blatant)}
    local function storeProfile()
        local profile = defense.profiles[defense.mode]
        for _, key in ipairs(keys) do profile[key] = defense[key].value end
    end
    local function displayProfile()
        local profile = defense.profiles[defense.mode]
        for _, key in ipairs(keys) do showSlider(defense[key], profile[key]) end
    end

    function defense.refresh()
        showSwitch(defense.toggle, defense.enabled)
        showSwitch(defense.footworkSwitch, defense.footwork)
        showSwitch(defense.manualSwitch, defense.manualOverride)
        showSwitch(defense.perimeterSwitch, defense.blockPerimeter)
        for mode, control in pairs(defense.modeButtons) do
            local selected = mode == defense.mode
            control.Text = mode .. (selected and (defense.expanded and "  -" or "  +") or "  ›")
            appearance.paint(control, "BackgroundColor3", selected and "tint" or "card")
            appearance.paint(control, "TextColor3", selected and "accent" or "muted")
        end
        defense.settingsPanel.Visible = defense.enabled and defense.expanded
        defense.collapsedNote.Visible = not defense.settingsPanel.Visible
        defense.settingsTitle.Text = defense.mode .. " guard settings"
        defense.teleportSwitch.row.Visible = defense.mode == "Blatant"
        showSwitch(defense.teleportSwitch, defense.teleport.enabled)
        defense.pressureSwitch.row.Visible = defense.mode == "Blatant"
        showSwitch(defense.pressureSwitch, defense.profiles.Blatant.pressure)
        defense.settingsNote.Text = defense.mode == "Legit"
            and "Smooth positioning with normal movement keys. Manual Override pauses the guard when you steer."
            or "Teleport to opponent jumps beside the opposing ball handler while the guard key is held. It pauses for shots, contact and movement locks."
    end

    function defense.selectMode(mode)
        if not defaults[mode] then return end
        storeProfile()
        if mode == defense.mode and defense.enabled then defense.expanded = not defense.expanded else defense.expanded = true end
        defense.mode = mode
        defense.enabled = true
        displayProfile()
        if defense.stop then defense.stop("Selected " .. mode .. " guard.") end
        defense.refresh()
    end

    function defense.capture()
        storeProfile()
        return {mode = defense.mode, manualOverride = defense.manualOverride, footwork = defense.footwork, blockPerimeter = defense.blockPerimeter, teleportToOpponent = defense.teleport.enabled,
            expanded = defense.expanded, profiles = {Legit = table.clone(defense.profiles.Legit), Blatant = table.clone(defense.profiles.Blatant)}}
    end

    function defense.apply(saved)
        defense.teleport.apply(type(saved) == "table" and saved.teleportToOpponent == true)
        defense.blockPerimeter = type(saved) ~= "table" or saved.blockPerimeter ~= false
        if type(saved) ~= "table" then
            defense.mode, defense.manualOverride, defense.expanded = "Legit", true, true
            defense.profiles.Legit = table.clone(defaults.Legit)
            defense.profiles.Blatant = table.clone(defaults.Blatant)
            for _, key in ipairs({"paintSpacing", "stickiness", "smoothing"}) do showSlider(defense[key], defaults.Legit[key]) end
            storeProfile() -- Legacy sliders have already been restored by the caller.
        else
            defense.mode = saved.mode == "Blatant" and "Blatant" or "Legit"
            defense.manualOverride, defense.expanded = saved.manualOverride ~= false, saved.expanded ~= false
            if type(saved.footwork) == "boolean" then defense.footwork = saved.footwork end
            local profiles = type(saved.profiles) == "table" and saved.profiles or {}
            for mode, fallback in pairs(defaults) do
                local data = type(profiles[mode]) == "table" and profiles[mode] or {}
                local profile = table.clone(fallback)
                for _, key in ipairs(keys) do
                    local value = data[key]
                    if type(value) == "number" and value == value and math.abs(value) < math.huge then
                        local control = defense[key]
                        profile[key] = math.clamp(value, control.min, control.max)
                    end
                end
                if type(data.pressure) == "boolean" then profile.pressure = data.pressure end
                defense.profiles[mode] = profile
            end
            displayProfile()
        end
        if defense.stop then defense.stop() end
        defense.refresh()
    end

    function defense.bindControls(connectControl, redraw)
        connectControl(defense.teleportSwitch.row.Activated, function()
            defense.teleport.apply(not defense.teleport.enabled)
            defense.stop()
            redraw()
        end)
        connectControl(defense.perimeterSwitch.row.Activated, function()
            defense.blockPerimeter = not defense.blockPerimeter
            defense.stop()
            redraw()
        end)
        connectControl(defense.manualSwitch.row.Activated, function()
            defense.manualOverride = not defense.manualOverride
            defense.stop()
            redraw()
        end)
        for mode, control in pairs(defense.modeButtons) do
            connectControl(control.Activated, function() defense.selectMode(mode); redraw() end)
        end
        connectControl(defense.pressureSwitch.row.Activated, function()
            defense.profiles.Blatant.pressure = not defense.profiles.Blatant.pressure
            defense.stop()
            redraw()
        end)
        defense.refresh()
    end
end

do
    local panel = pages.Privacy
    local alias = "Anonymous"
    local names = {}
    local otherNames, otherUsernames, aliases = {}, {}, {}
    local nextAlias, nextRosterCheck = 0, 0
    local tracked, dirty, rootLinks = {}, {}, {}
    local hiddenPlayerList
    local fields = {
        TextLabel = {"Text"}, TextButton = {"Text"}, TextBox = {"Text", "PlaceholderText"},
        Humanoid = {"DisplayName"}, ProximityPrompt = {"ActionText", "ObjectText"},
        Tool = {"ToolTip"}, Dialog = {"InitialPrompt", "GoodbyeDialog"},
        DialogChoice = {"UserDialog", "ResponseDialog", "GoodbyeDialog"},
    }

    label(panel, "Privacy", 0, 0, 480, 35, 25, Enum.Font.GothamBold, colors.text)
    label(panel, "Replace player names with aliases on your screen.",
        0, 39, 680, 21, 13, Enum.Font.Gotham, colors.muted)
    divider(panel, 0, 71, 699, 1)
    local toggle = switch(panel, "Name Protect", 0, 96)
    local everyoneToggle = switch(panel, "Whole-game Name Protect", 359, 96)
    label(panel, "Give other players numbered aliases.", 359, 134, 316, 22, 12, Enum.Font.Gotham, colors.muted)
    label(panel, "Display alias", 0, 145, 300, 22, 14, Enum.Font.GothamBold, colors.text)
    local aliasBox = rounded(create("TextBox", panel, {
        Name = "WizardAliasInput", Position = UDim2.fromOffset(0, 175), Size = UDim2.fromOffset(315, 36),
        BackgroundColor3 = colors.card, BorderSizePixel = 0, TextColor3 = colors.text,
        Font = Enum.Font.GothamMedium, TextSize = 14, Text = alias, ClearTextOnFocus = false,
    }), 8)
    local status = label(panel, "", 0, 219, 680, 22, 12, Enum.Font.GothamMedium, colors.muted)
    label(panel, "Screen masking is local. Roblox still uses your account identity.",
        0, 261, 680, 22, 13, Enum.Font.Gotham, colors.muted)

    local function rememberNames()
        for _, name in ipairs({player.Name, player.DisplayName or ""}) do
            if name ~= "" then names[name:lower()] = true end
        end
    end

    local function rememberRoster()
        local changed = false
        for _, member in ipairs(players:GetPlayers()) do
            if member == player then continue end
            local id = member.UserId or member.Name
            if not aliases[id] then
                nextAlias += 1
                aliases[id] = string.format("Player %02d", nextAlias)
            end
            local replacement = aliases[id]
            local username = member.Name:lower()
            if otherUsernames[username] ~= replacement then
                otherUsernames[username], changed = replacement, true
            end
            local displayName = member.DisplayName
            if type(displayName) == "string" and displayName ~= "" then
                local key = displayName:lower()
                local existing = otherNames[key]
                local resolved = existing and existing ~= replacement and "Player" or replacement
                if existing ~= resolved then otherNames[key], changed = resolved, true end
            end
        end
        return changed
    end

    local function active()
        return privacy.enabled or privacy.everyone
    end

    local function findName(lower, start, includeOthers)
        local first, last, replacement
        local function consider(name, value, wholeWord)
            local a, b = lower:find(name, start, true)
            while a and wholeWord and (lower:sub(a - 1, a - 1):match("[%w_\128-\255]") and a > 1
                or lower:sub(b + 1, b + 1):match("[%w_\128-\255]")) do
                a, b = lower:find(name, a + 1, true)
            end
            if a and (not first or a < first or (a == first and b > last)) then
                first, last, replacement = a, b, value
            end
        end
        for name in pairs(names) do
            consider(name, alias, false)
        end
        if includeOthers then
            for name, value in pairs(otherUsernames) do consider(name, value, true) end
            for name, value in pairs(otherNames) do
                if not otherUsernames[name] then consider(name, value, true) end
            end
        end
        return first, last, replacement
    end

    local function validAlias(value)
        if type(value) ~= "string" then return end
        value = value:match("^%s*(.-)%s*$")
        local length = utf8.len(value)
        if length and length > 0 and length <= 24 and not value:find("[%c<>&]")
            and not findName(value:lower(), 1) then
            return value
        end
    end

    local function defaultAlias()
        return validAlias("Anonymous") or validAlias("Hidden") or validAlias("Guest") or "•••"
    end

    local function visibleText(raw)
        local parts, indexes, cursor = {}, {}, 1
        local function append(first, last)
            parts[#parts + 1] = raw:sub(first, last)
            for index = first, last do indexes[#indexes + 1] = index end
        end
        for first, last in function() return raw:find("<[^<>]*>", cursor) end do
            append(cursor, first - 1)
            cursor = last + 1
        end
        append(cursor, #raw)
        return table.concat(parts), indexes
    end

    local function maskText(raw, rich)
        local visible, indexes = raw, nil
        if rich and raw:find("<", 1, true) then
            visible, indexes = visibleText(raw)
        end
        local lower = visible:lower()
        local first, last, replacement = findName(lower, 1, privacy.everyone)
        if not first then return raw end
        local parts, cursor = {}, 1
        while first do
            local rawFirst = indexes and indexes[first] or first
            parts[#parts + 1] = raw:sub(cursor, rawFirst - 1)
            parts[#parts + 1] = replacement
            if indexes then
                -- Preserve formatting tags inside a name split across styled spans.
                for index = first, last - 1 do
                    if indexes[index + 1] > indexes[index] + 1 then
                        parts[#parts + 1] = raw:sub(indexes[index] + 1, indexes[index + 1] - 1)
                    end
                end
            end
            cursor = (indexes and indexes[last] or last) + 1
            first, last, replacement = findName(lower, last + 1, privacy.everyone)
        end
        parts[#parts + 1] = raw:sub(cursor)
        return table.concat(parts)
    end

    function privacy.redact(text)
        return active() and maskText(text, false) or text
    end

    function privacy.readText(object)
        local text = object.Text
        local entry = tracked[object] and tracked[object].Text
        return entry and entry.masked == text and entry.original or text
    end

    local function restore(entry)
        if entry.masked == nil then return end
        pcall(function()
            if entry.object[entry.property] == entry.masked then
                entry.object[entry.property] = entry.original
            end
        end)
        entry.original, entry.masked = nil, nil
    end

    local function mask(entry)
        local object, property = entry.object, entry.property
        local ok, current, rich, editable, fallback = pcall(function()
            local text = object[property]
            return text, property == "Text" and object.RichText,
                property == "Text" and object.ClassName == "TextBox" and object.TextEditable,
                property == "DisplayName" and object.Parent and object.Parent.Name
        end)
        if not ok or type(current) ~= "string" then return end
        if editable then
            restore(entry)
            return
        end
        local raw = current == entry.masked and entry.original or current
        local shown = raw == "" and fallback or raw
        local owner = privacy.everyone and fallback and otherUsernames[fallback:lower()]
        local masked = owner or maskText(shown, rich)
        if masked == shown then
            restore(entry)
        elseif masked ~= current and pcall(function() object[property] = masked end) then
            entry.original, entry.masked = raw, masked
        end
    end

    local function forget(object)
        local entries = tracked[object]
        if not entries then return end
        tracked[object] = nil
        for _, entry in pairs(entries) do
            for _, connection in ipairs(entry.links) do connection:Disconnect() end
            dirty[entry] = nil
            restore(entry)
        end
    end

    local function track(object, root)
        local properties = fields[object.ClassName]
        if not active() or not properties or tracked[object] then return end
        if root == playerGui and (object:IsDescendantOf(gui) or hud.owns(object)) then return end
        local entries = {}
        tracked[object] = entries
        for _, property in ipairs(properties) do
            local entry = {object = object, property = property, links = {}}
            entries[property] = entry
            local function listen(field)
                local ok, connection = pcall(function()
                    return object:GetPropertyChangedSignal(field):Connect(function()
                        if tracked[object] == entries then dirty[entry] = true end
                    end)
                end)
                if ok then table.insert(entry.links, connection) end
            end
            listen(property)
            if property == "Text" then
                listen("RichText")
                if object.ClassName == "TextBox" then listen("TextEditable") end
            end
            mask(entry)
        end
    end

    local function attach(root)
        if not root then return false end
        local ok, descendants, added, removing = pcall(function()
            return root:GetDescendants(), root.DescendantAdded, root.DescendantRemoving
        end)
        if not ok then return false end
        local attached = pcall(function()
            table.insert(rootLinks, added:Connect(function(object) track(object, root) end))
            table.insert(rootLinks, removing:Connect(forget))
        end)
        for _, object in ipairs(descendants) do track(object, root) end
        return attached
    end

    local function refreshMasks()
        for _, entries in pairs(tracked) do
            for _, entry in pairs(entries) do mask(entry) end
        end
    end

    function privacy.watch(now)
        if privacy.everyone and now >= nextRosterCheck then
            nextRosterCheck = now + 0.75
            if rememberRoster() then refreshMasks() end
        end
        if not next(dirty) then return end
        local pending = dirty
        dirty = {}
        for entry in pairs(pending) do
            if tracked[entry.object] then mask(entry) end
        end
    end

    function privacy.stop()
        privacy.enabled, privacy.everyone = false, false
        for _, connection in ipairs(rootLinks) do connection:Disconnect() end
        table.clear(rootLinks)
        for object in pairs(tracked) do forget(object) end
        table.clear(dirty)
        if hiddenPlayerList then
            pcall(function()
                hiddenPlayerList:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, true)
            end)
            hiddenPlayerList = nil
        end
    end

    local function start()
        attach(playerGui)
        attach(workspace)
        local coreOk, core = pcall(game.GetService, game, "CoreGui")
        if coreOk and attach(core) then return end
        -- Some clients protect CoreGui. Hide the stock player list when we cannot update it.
        pcall(function()
            local starterGui = game:GetService("StarterGui")
            if starterGui:GetCoreGuiEnabled(Enum.CoreGuiType.PlayerList) then
                starterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, false)
                hiddenPlayerList = starterGui
            end
        end)
    end

    local function updateControls(message)
        showSwitch(toggle, privacy.enabled)
        showSwitch(everyoneToggle, privacy.everyone)
        aliasBox.Text = alias
        status.Text = message or (hiddenPlayerList and "The built-in player list is hidden while Name Protect is on."
            or "Enter an alias and press Enter to apply it.")
    end

    function privacy.capture()
        return {enabled = privacy.enabled, everyone = privacy.everyone, alias = alias}
    end

    function privacy.apply(saved)
        rememberNames()
        saved = type(saved) == "table" and saved or {}
        alias = validAlias(saved.alias) or defaultAlias()
        local wasActive = active()
        privacy.enabled, privacy.everyone = saved.enabled == true, saved.everyone == true
        if privacy.everyone then rememberRoster() end
        if not active() then
            privacy.stop()
        elseif wasActive then
            refreshMasks()
        else
            start()
        end
        updateControls()
    end

    function privacy.bind(connectControl, redraw)
        rememberNames()
        alias = defaultAlias()
        updateControls()
        connectControl(toggle.row.Activated, function()
            privacy.apply({enabled = not privacy.enabled, everyone = privacy.everyone, alias = alias})
            redraw()
        end)
        connectControl(everyoneToggle.row.Activated, function()
            privacy.apply({enabled = privacy.enabled, everyone = not privacy.everyone, alias = alias})
            redraw()
        end)
        connectControl(aliasBox.FocusLost, function()
            local value = validAlias(aliasBox.Text)
            if value then
                alias = value
                refreshMasks()
            end
            updateControls(not value and "Use 1–24 characters without your Roblox names or <, >, and &." or nil)
        end)
        local ok, changed = pcall(function() return player:GetPropertyChangedSignal("DisplayName") end)
        if ok and changed then
            connectControl(changed, function()
                rememberNames()
                alias = validAlias(alias) or defaultAlias()
                refreshMasks()
                updateControls()
            end)
        end
    end
end

hubControls.keysSwitch = switch(shooting, "Auto Green", 0, 112)
hubControls.pingSwitch = switch(shooting, "Ping compensation", 0, 146)
hubControls.pingStatus = label(shooting, "Measuring Shift+F3 data ping…", 0, 178, 329, 21, 11, Enum.Font.GothamMedium, colors.muted)
hubControls.approachSwitch = switch(shooting, "Auto Dunk", 359, 112)
hubControls.jellySwitch = switch(shooting, "Auto Jelly", 359, 148)
shotInput.manualSwitch = switch(shooting, "Require shot input", 359, 231)
hubControls.jumpBias = slider(shooting, "Jump-shot release offset", 0, 204, -30, 30, 0, "%+d ms")
hubControls.finishBias = slider(shooting, "Finish release offset", 0, 252, -30, 30, 0, "%+d ms")
hubControls.styleButton = button(shooting, "", 359, 191, 316, 32, colors.card, colors.text)
hubControls.jellyStatus = label(shooting, "", 359, 272, 316, 33, 12, Enum.Font.Gotham, colors.muted)
hubControls.jellyStatus.TextWrapped = true
label(visuals, "Visuals", 0, 0, 480, 35, 25, Enum.Font.GothamBold, colors.text)
divider(visuals, 0, 71, 699, 1)
label(visuals, "Court lines", 0, 83, 137, 20, 12, Enum.Font.GothamBold, colors.muted)
hubControls.threeSwitch = switch(visuals, "Draw 3 pt line", 0, 106)
hubControls.visualStatus = label(visuals, "Highlights both three-point arcs.", 137, 83, 178, 20, 10, Enum.Font.Gotham, colors.muted)
hubControls.visualStatus.TextXAlignment = Enum.TextXAlignment.Right
local visualExtras = {teammates = false, contest = false, contestMeter = false}
function visualExtras.normalizeHex(value)
    if type(value) ~= "string" then return end
    local hex = value:match("^%s*#?(%x%x%x%x%x%x)%s*$")
    return hex and string.upper(hex)
end

do
    divider(visuals, 0, 246, 315, 1)
    divider(visuals, 340, 88, 1, 306)
    label(visuals, "Teammates", 0, 251, 315, 20, 12, Enum.Font.GothamMedium, colors.muted)
    label(visuals, "Contest", 359, 83, 325, 20, 12, Enum.Font.GothamMedium, colors.muted)
    local teammateSwitch = switch(visuals, "Highlight teammates", 0, 272)
    local contestSwitch = switch(visuals, "Contest circle", 359, 108)
    local contestMeterSwitch = switch(visuals, "Contest meter", 359, 142)
    visualExtras.lineTransparency = slider(visuals, "3-point line transparency", 0, 200, 0, 100, 0, "%d%%")
    visualExtras.teamTransparency = slider(visuals, "Teammate transparency", 0, 366, 0, 100, 0, "%d%%")
    visualExtras.radius = slider(visuals, "Contest radius", 359, 178, 3, 30, 8, "%d studs")
    visualExtras.height = slider(visuals, "Height above court", 359, 222, 0, 6, 0, "%d studs")
    visualExtras.width = slider(visuals, "Circle line width", 359, 266, 50, 200, 100, "%d%%")
    visualExtras.teammateStatus = label(visuals, "Outlines players on your team.", 137, 251, 178, 20, 10, Enum.Font.Gotham, colors.muted)
    visualExtras.teammateStatus.TextXAlignment = Enum.TextXAlignment.Right
    visualExtras.contestStatus = label(visuals, "Marks the selected range around you.", 359, 366, 325, 19, 12, Enum.Font.Gotham, colors.muted)
    label(visuals, "The meter uses this radius and shows above you with the ball.", 359, 387, 325, 19, 11, Enum.Font.Gotham, colors.muted)

    local palette = {"FF548A", "FF6864", "FFC46D", "7BE3A7", "61DBEF", "769DFF", "BD8FFF", "FFFFFF"}
    local editors = {}
    local function colorEditor(key, name, caption, x, y, default)
        label(visuals, caption, x, y, 194, 26, 13, Enum.Font.GothamBold, colors.text)
        local box = rounded(create("TextBox", visuals, {
            Name = name, Position = UDim2.fromOffset(x + 209, y), Size = UDim2.fromOffset(106, 26),
            BackgroundColor3 = colors.card, BorderSizePixel = 0, ClearTextOnFocus = false,
            Font = Enum.Font.GothamMedium, TextSize = 12, TextColor3 = colors.text,
        }), 6)
        local swatches = {}
        for index, hex in ipairs(palette) do
            local swatch = appearance.colorChip(visuals, x + 40 * (index - 1), y + 31, 35, 18, Color3.fromHex(hex))
            swatches[index] = {button = swatch, hex = hex, selection = create("UIStroke", swatch, {
                Color = colors.text, Thickness = 1.5, ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            })}
        end
        local function set(value)
            local hex = visualExtras.normalizeHex(value) or default
            visualExtras[key] = hex
            box.Text = "#" .. hex
            for _, swatch in ipairs(swatches) do swatch.selection.Enabled = swatch.hex == hex end
        end
        set(default)
        editors[key] = {box = box, swatches = swatches, set = set}
    end
    colorEditor("lineHex", "ThreePointColor", "3-point line color", 0, 144, "FF548A")
    colorEditor("teamHex", "TeammateColor", "Teammate color", 0, 310, "7BE3A7")
    colorEditor("contestHex", "ContestColor", "Circle color", 359, 313, "61DBEF")

    function visualExtras.refresh()
        showSwitch(teammateSwitch, visualExtras.teammates)
        showSwitch(contestSwitch, visualExtras.contest)
        showSwitch(contestMeterSwitch, visualExtras.contestMeter)
    end

    function visualExtras.capture()
        return {teammates = visualExtras.teammates, contest = visualExtras.contest, contestMeter = visualExtras.contestMeter,
            lineHex = visualExtras.lineHex, teamHex = visualExtras.teamHex, contestHex = visualExtras.contestHex,
            lineTransparency = visualExtras.lineTransparency.value, teamTransparency = visualExtras.teamTransparency.value,
            radius = visualExtras.radius.value, height = visualExtras.height.value, width = visualExtras.width.value}
    end

    function visualExtras.apply(data)
        data = type(data) == "table" and data or {}
        visualExtras.teammates, visualExtras.contest = data.teammates == true, data.contest == true
        visualExtras.contestMeter = data.contestMeter == true
        for key, editor in pairs(editors) do editor.set(data[key]) end
        for _, key in ipairs({"radius", "height", "width", "lineTransparency", "teamTransparency"}) do
            local control, value = visualExtras[key], data[key]
            showSlider(control, type(value) == "number" and value == value
                and value or control.default)
        end
        visualExtras.watch(os.clock(), true)
    end

    function visualExtras.bind(connectControl, redraw)
        connectControl(teammateSwitch.row.Activated, function()
            visualExtras.teammates = not visualExtras.teammates
            visualExtras.watch(os.clock(), true)
            redraw()
        end)
        connectControl(contestSwitch.row.Activated, function()
            visualExtras.contest = not visualExtras.contest
            visualExtras.watch(os.clock(), true)
            redraw()
        end)
        connectControl(contestMeterSwitch.row.Activated, function()
            visualExtras.contestMeter = not visualExtras.contestMeter
            visualExtras.watchContest(os.clock(), true)
            redraw()
        end)
        for key, editor in pairs(editors) do
            local function commit(value)
                editor.set(visualExtras.normalizeHex(value) or visualExtras[key])
                if key == "lineHex" then visualExtras.styleThreePointLines() end
                visualExtras.watch(os.clock(), true)
            end
            connectControl(editor.box.FocusLost, function() commit(editor.box.Text) end)
            for _, swatch in ipairs(editor.swatches) do
                connectControl(swatch.button.Activated, function() commit(swatch.hex) end)
            end
        end
    end
end
