local function refresh()
    for name, item in pairs(nav) do
        local active = name == currentPage
        item.mark.Visible = active
        local background = appearance.style == "Default" and menuLayout.preset == "Classic" and (active and "selection" or "surface")
            or (active and "selection" or "sidebar")
        appearance.paint(item.row, "BackgroundColor3", background)
        appearance.paint(item.caption, "TextColor3", active and "text" or "muted")
        if appearance.backgrounds[item.row] ~= nil then
            appearance.backgrounds[item.row] = (active or background ~= "surface") and 0 or 1
        end
    end
    appearance.updateTransparency()
    for name, panel in pairs(pages) do panel.Visible = name == currentPage end
    if appearance.shownPage ~= currentPage then
        local panel, origin = pages[currentPage], menuLayout.pageOrigin
        if appearance.shownPage and panel and origin and gui.Enabled then
            panel.Position = UDim2.fromOffset(origin[1], origin[2] + 10)
            appearance.pageTween = appearance.ease(panel, 0.24, {Position = UDim2.fromOffset(origin[1], origin[2])})
        end
        appearance.shownPage = currentPage
    end
    showSwitch(hubControls.keysSwitch, assistKeys)
    showSwitch(hubControls.pingSwitch, network.enabled)
    showSwitch(hubControls.approachSwitch, autoDunk)
    showSwitch(shotInput.manualSwitch, shotInput.manualOnly)
    showSwitch(hubControls.jellySwitch, autoJelly)
    showSwitch(hubControls.threeSwitch, drawThree)
    showSwitch(hubControls.movementSwitch, config.movement)
    showSwitch(hubControls.boostSwitch, config.boost)
    showSwitch(hubControls.glideSwitch, config.glide)
    showSwitch(defense.toggle, defense.enabled)
    showSwitch(defense.footworkSwitch, defense.footwork)
    defense.refresh()
    rage.refresh()
    if antiContestV2.refresh then antiContestV2.refresh() end
    showSwitch(antiStun.toggle, antiStun.enabled)
    if autoBlock.refresh then autoBlock.refresh() end
    showSwitch(courtJoin.toggle, courtJoin.enabled)
    local guardBind = bindings["Auto Guard"]
    defense.bind.Text = capturing == "Auto Guard" and "Press a key…"
        or (guardBind and ("Hold " .. guardBind.Name .. "   /   Click to rebind") or "Bind Auto Guard")
    visualExtras.refresh()
    local enabled = {}
    for _, feature in ipairs({
        {assistKeys, "Auto Green"}, {network.enabled, "Ping Compensation"},
        {autoDunk, "Auto Dunk"}, {autoJelly, "Auto Jelly"},
        {config.movement, "Movement Tuning"}, {config.boost, "Dribble Boost"},
        {config.glide, "Dribble Glide"}, {visualExtras.threeActive, "3-Point Lines"},
        {visualExtras.teammates, "Teammate Highlight"}, {visualExtras.contest, "Contest Circle"}, {defense.enabled, "Auto Guard"},
        {visualExtras.contestMeter, "Contest Meter"},
        {privacy.enabled, "Name Protect"},
        {privacy.everyone, "Whole-game Name Protect"},
        {courtJoin.enabled, "Auto Join Court"},
        {antiStun.enabled, "Anti-Stun"}, {autoBlock.enabled, "Auto Block"},
        {rage.enabled, "Rage"}, {rage.noclip.enabled, "Noclip"}, {rage.courtTeleport.enabled, "Court teleport"}, {antiContestV2.enabled, "Anti Contest v2"},
    }) do
        if feature[1] then table.insert(enabled, feature[2]) end
    end
    hud.refresh(enabled)
    local style = hubControls.finishStyles[config.finish]
    hubControls.styleButton.Text = style.name .. (style.key and ("  /  " .. style.key.Name) or "") .. "     ›"
    for name, row in pairs(hubControls.bindRows) do
        row.Text = capturing == name and "Press a key…" or (bindings[name] and bindings[name].Name or "Unbound")
    end
    hubControls.bindingStatus.Text = hubControls.bindStatus
    menuHint.Text = capturing == "Menu" and "Press a key…" or menuLayout.preset == "Compact Rail" and bindings.Menu.Name
        or ("Menu key  ·  " .. bindings.Menu.Name)
    hubControls.moveName.Text = selectedMove[1]
    if selectedMove == spinMove then
        hubControls.moveInputs.Text = string.format("Auto hand  /  R: %s  ·  L: %s  ·  Fast taps", spinMove.hands.Right, spinMove.hands.Left)
    else
        local taps = table.concat(string.split(selectedMove[2], ""), " → ")
        hubControls.moveInputs.Text = selectedMove[3] and (selectedMove[3]:gsub(" ", " + ") .. " + " .. taps) or taps
    end
    hubControls.bindMacroButton.Text = capturing == selectedMove and "Press a key…"
        or (bindings[selectedMove] and ("Bind  " .. bindings[selectedMove].Name) or "Bind key")
    combo.singlePane.Visible = not combo.editing
    combo.editPane.Visible = combo.editing
    appearance.paint(combo.movesTab, "BackgroundColor3", combo.editing and "card" or "selection")
    appearance.paint(combo.comboTab, "BackgroundColor3", combo.editing and "selection" or "card")
    combo.bind.Text = capturing == "Dribble combo" and "Press a key…" or (bindings["Dribble combo"] and bindings["Dribble combo"].Name or "Bind key")
    for i, row in ipairs(combo.rows) do
        local move = combo.moves[i]
        row.Text = string.format("%d    %s", i, move and move[1] or "Empty")
        appearance.paint(row, "BackgroundColor3", i == combo.slot and "selection" or "card")
    end
    hubControls.dribbleStatus.Text = hubControls.macroStatus
    local highlighted = selectedMove
    if combo.editing then highlighted = combo.moves[combo.slot] end
    for move, row in pairs(hubControls.moveRows) do
        appearance.paint(row, "BackgroundColor3", move == highlighted and "card" or "sidebar")
        appearance.paint(row, "TextColor3", move == highlighted and "accent" or "muted")
    end
    local slot = tostring(settings.slot)
    hubControls.slotButton.Text = "Slot " .. slot .. (settings.slots[slot] and "   •   Saved" or "   •   Empty") .. "      ›"
    showSwitch(hubControls.autoLoadSwitch, settings.autoLoad)
    showSwitch(hubControls.reloadSwitch, queueAvailable() and settings.reload)
    hubControls.configMessage.Text = hubControls.configStatus
end

local drag
local function moveDashboard(x, y)
    dashboard.Position = UDim2.new(0.5, x, 0.5, y)
end

local function resize()
    local size = backdrop.AbsoluteSize
    if input.TouchEnabled then
        local factor = math.clamp(menuLayout.zoom, 0.85, 1.6)
        scale.Scale = factor
        dashboard.AnchorPoint = Vector2.zero
        dashboard.Position = UDim2.fromOffset(12, 12)
        backdrop.CanvasSize = UDim2.fromOffset(width * factor + 24, height * factor + 24)
        local position = backdrop.CanvasPosition
        backdrop.CanvasPosition = Vector2.new(math.clamp(position.X, 0, math.max(0, width * factor + 24 - size.X)),
            math.clamp(position.Y, 0, math.max(0, height * factor + 24 - size.Y)))
        menuLayout.sizeLabel.Text = string.format("%d%%", math.round(factor * 100))
        return
    end
    if size.X > 24 and size.Y > 24 then
        menuLayout.baseScale = math.min(1, (size.X - 24) / width, (size.Y - 24) / height)
    end
    local fit = math.min((size.X - 8) / width, (size.Y - 8) / height)
    if fit > 0 then menuLayout.zoom = math.min(menuLayout.zoom, fit / menuLayout.baseScale) end
    scale.Scale = menuLayout.baseScale * menuLayout.zoom
    menuLayout.sizeLabel.Text = string.format("%d%%", math.round(menuLayout.zoom * 100))
end

function menuLayout.recover()
    if input.TouchEnabled then resize(); return end
    local viewport, pos, factor = backdrop.AbsoluteSize, dashboard.Position, scale.Scale
    if viewport.X < 25 or viewport.Y < 25 then return end
    local left = viewport.X / 2 + pos.X.Offset + (dragHandle.Position.X.Offset - width / 2) * factor
    local top = viewport.Y / 2 + pos.Y.Offset + (dragHandle.Position.Y.Offset - height / 2) * factor
    local gripWidth, gripHeight = dragHandle.Size.X.Offset * factor, dragHandle.Size.Y.Offset * factor
    local visibleWidth = math.min(viewport.X, left + gripWidth) - math.max(0, left)
    local visibleHeight = math.min(viewport.Y, top + gripHeight) - math.max(0, top)
    if visibleWidth < math.min(gripWidth, 24) or visibleHeight < math.min(gripHeight, 14) then
        moveDashboard(0, 0)
    end
end

function menuLayout.capture()
    return {zoom = menuLayout.zoom, x = dashboard.Position.X.Offset, y = dashboard.Position.Y.Offset, preset = menuLayout.preset}
end

function menuLayout.apply(saved)
    saved = type(saved) == "table" and saved or {}
    local function finite(value, fallback)
        return type(value) == "number" and math.abs(value) < 100000 and value or fallback
    end
    menuLayout.zoom = math.clamp(finite(saved.zoom, 1), 0.55, 1.6)
    moveDashboard(finite(saved.x, 0), finite(saved.y, 0))
    menuLayout.setPreset(saved.preset)
end

do
    local presets = {
        {name = "Classic", width = 944, height = 524, page = {219, 86}, nav = {13, 84, 164, 423},
            row = {159, 26, 1, 0, 3, 26}, divider = {190, 86, 0, 0}, panel = true},
        {name = "Right Sidebar", width = 944, height = 524, page = {25, 86}, nav = {767, 84, 164, 423},
            row = {159, 26, 1, 0, 3, 26}, divider = {752, 86, 1, 408}, columns = true},
        {name = "Top Tabs", width = 748, height = 630, page = {24, 185}, nav = {24, 78, 700, 83},
            row = {111, 31, 6, 6, 7, 4}, divider = {24, 166, 700, 1}, horizontal = true, panel = true},
        {name = "Bottom Dock", width = 748, height = 640, page = {24, 86}, nav = {24, 520, 700, 77},
            row = {111, 31, 6, 6, 7, 3}, divider = {24, 509, 700, 1}, horizontal = true, columns = true},
        {name = "Compact Rail", width = 812, height = 524, page = {96, 86}, nav = {13, 84, 66, 423},
            row = {64, 25, 1, 0, 3, 3}, divider = {85, 86, 1, 408}, rail = true, panel = true},
        {name = "Tile Dashboard", width = 1000, height = 554, page = {276, 99}, nav = {16, 84, 235, 453},
            row = {112, 46, 2, 7, 6, 32}, divider = {262, 99, 1, 411}, tiles = true, panel = true},
    }
    local byName, cards = {}, {}
    local current = presets[1]
    for _, preset in ipairs(presets) do byName[preset.name] = preset end

    local function geometry(object, x, y, w, h)
        object.Position = UDim2.fromOffset(x, y)
        object.Size = UDim2.fromOffset(w, h)
    end

    local function rowPosition(preset, index)
        local row = preset.row
        return 1 + ((index - 1) % row[3]) * (row[1] + row[4]), row[6] + math.floor((index - 1) / row[3]) * (row[2] + row[5])
    end

    function menuLayout.styleChrome()
        appearance.header.Visible = appearance.style ~= "Default" or current.name ~= "Classic"
        if appearance.stripe then
            local stripeWidth = appearance.stripe[1] == 908 and width - 36 or math.min(appearance.stripe[1], width - 36)
            appearance.headerAccent.Size = UDim2.fromOffset(stripeWidth, appearance.stripe[2])
        end
        for _, item in pairs(nav) do
            local w, h = item.row.Size.X.Offset, item.row.Size.Y.Offset
            if current.horizontal then
                geometry(item.mark, 5, h - 3, w - 10, 2)
            else
                geometry(item.mark, appearance.endMarker and w - 3 or 0, 3, appearance.endMarker and 3 or 2, h - 6)
            end
        end
    end

    local function updateCards()
        for name, card in pairs(cards) do
            appearance.paint(card.button, "TextColor3", name == current.name and "accent" or "text")
            appearance.paint(card.border, "Color", name == current.name and "accent" or "divider")
            card.border.Thickness = name == current.name and 2 or 1
        end
    end

    function menuLayout.setPreset(name)
        current = byName[name] or presets[1]
        menuLayout.preset = current.name
        drag = nil
        width, height = current.width, current.height
        dashboard.Size = UDim2.fromOffset(width, height)
        geometry(appearance.header, 8, 8, width - 16, 50)
        geometry(menuLayout.headerDivider, 18, 66, width - 36, 1)
        geometry(hubControls.closeButton, width - 51, 15, 34, 32)
        local sizeX = width - (current.horizontal and 360 or 184)
        geometry(menuLayout.smaller, sizeX, 18, 32, 28)
        geometry(menuLayout.sizeLabel, sizeX + 32, 18, 48, 28)
        geometry(menuLayout.larger, sizeX + 80, 18, 32, 28)
        geometry(dragHandle, 17, 10, sizeX - 28, 49)
        geometry(sidebar, unpack(current.nav))
        geometry(menuLayout.navDivider, unpack(current.divider))
        if appearance.pageTween then appearance.pageTween:Cancel(); appearance.pageTween = nil end
        menuLayout.pageOrigin = current.page
        for _, panel in pairs(pages) do geometry(panel, current.page[1], current.page[2], 700, 411) end
        menuLayout.navHeading.Visible = not current.horizontal and not current.rail
        geometry(menuLayout.navHeading, 13, 4, 140, 16)
        menuLayout.contentPlate.Visible = current.panel == true
        geometry(menuLayout.contentPlate, current.page[1] - 8, current.page[2] - 6, 716, 425)
        for index, column in ipairs(menuLayout.columns) do
            column.Visible = current.columns == true
            geometry(column, current.page[1] - 6 + (index - 1) * 359, current.page[2] + 78, 331, 332)
        end
        for index, module in ipairs(modules) do
            local item = nav[module[1]]
            local x, y = rowPosition(current, index)
            geometry(item.row, x, y, current.row[1], current.row[2])
            item.caption.TextSize = current.horizontal and 12 or (current.rail and 9 or (current.tiles and 12 or 13))
            item.icon.TextSize = current.rail and 12 or 14
            item.caption.TextXAlignment = current.rail and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left
            if current.rail then
                geometry(item.icon, 0, 2, 64, 12)
                geometry(item.caption, 2, 13, 60, 11)
            elseif current.horizontal then
                geometry(item.icon, 7, 0, 20, 31)
                geometry(item.caption, 31, 0, 78, 31)
            elseif current.tiles then
                geometry(item.icon, 9, 0, 22, 46)
                geometry(item.caption, 36, 0, 74, 46)
            else
                geometry(item.icon, 9, 0, 22, 26)
                geometry(item.caption, 38, 0, 115, 26)
            end
        end
        if current.horizontal then
            hubControls.unloadButton.Parent, menuHint.Parent = dashboard, dashboard
            geometry(hubControls.unloadButton, width - 235, 15, 145, 32)
            geometry(menuHint, 24, height - 31, 156, 26)
        else
            hubControls.unloadButton.Parent, menuHint.Parent = sidebar, sidebar
            geometry(hubControls.unloadButton, current.rail and 1 or 1, height - 146, current.rail and 64 or current.nav[3] - 5, 30)
            geometry(menuHint, current.rail and 1 or 9, height - 113, current.nav[3] - 13, 26)
        end
        hubControls.unloadButton.TextSize = current.rail and 9 or 13
        menuHint.TextSize = current.rail and 9 or 11
        menuLayout.styleChrome()
        updateCards()
        appearance.updateTransparency()
        resize()
        if gui.Enabled then menuLayout.recover() end
    end

    local panel = appearance.layoutPane
    label(panel, "Menu layout", 0, 85, 450, 22, 15, Enum.Font.GothamBold, colors.text)
    for index, preset in ipairs(presets) do
        local x, y = ((index - 1) % 3) * 235, 143 + math.floor((index - 1) / 3) * 122
        local card = button(panel, preset.name, x, y, 220, 110, colors.card, colors.text)
        card.Name = "WizardLayout" .. preset.name:gsub(" ", "")
        card.TextYAlignment = Enum.TextYAlignment.Top
        create("UIPadding", card, {PaddingTop = UDim.new(0, 7)})
        local preview = rounded(create("Frame", card, {
            Position = UDim2.fromOffset(11, 27), Size = UDim2.fromOffset(198, 68),
            BorderSizePixel = 0, BackgroundColor3 = colors.surface,
        }), 4)
        local factor = math.min(198 / preset.width, 68 / preset.height)
        local inset = (198 - preset.width * factor) / 2
        local function sample(x0, y0, w, h, color)
            create("Frame", preview, {Position = UDim2.fromOffset(inset + x0 * factor, y0 * factor),
                Size = UDim2.fromOffset(math.max(1, w * factor), math.max(1, h * factor)),
                BorderSizePixel = 0, BackgroundColor3 = color})
        end
        sample(10, 9, preset.width - 20, 43, colors.sidebar)
        sample(preset.page[1], preset.page[2], 700, 411, colors.card)
        sample(preset.nav[1], preset.nav[2], preset.nav[3], preset.nav[4], colors.sidebar)
        for moduleIndex = 1, #modules do
            local rx, ry = rowPosition(preset, moduleIndex)
            sample(preset.nav[1] + rx, preset.nav[2] + ry, preset.row[1], preset.row[2],
                moduleIndex == 1 and colors.accent or colors.divider)
        end
        cards[preset.name] = {button = card, border = create("UIStroke", card, {
            Color = colors.divider, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        })}
    end

    function menuLayout.bind(connectControl, redraw)
        for name, card in pairs(cards) do
            connectControl(card.button.Activated, function()
                menuLayout.setPreset(name)
                redraw()
            end)
        end
        menuLayout.setPreset("Classic")
    end
end

local function report(mode, message)
    mode.result = message
    refresh()
    warn(prefix .. mode.name .. " | " .. privacy.redact(message))
end

