local function updateThreePointLines()
    visualExtras.threeActive = false
    if lineOverlay then
        lineOverlay:Destroy()
        lineOverlay = nil
    end
    if not drawThree then
        hubControls.visualStatus.Text = "Highlights both three-point arcs."
        return
    end

    local assets = workspace:FindFirstChild("Assets")
    local court = assets and assets:FindFirstChild("Court")
    local band = practiceBand() or (court and court:FindFirstChild("CourtFloor", true))
    local functionals = assets and assets:FindFirstChild("Functionals")
    local zones = functionals and functionals:FindFirstChild("Zones")
    local threePoint = zones and zones:FindFirstChild("ThreePoint")
    if not band or not band:IsA("BasePart") or not threePoint then
        hubControls.visualStatus.Text = "Waiting for compatible court geometry."
        return
    end

    local overlay = Instance.new("Folder")
    overlay.Name = "GymReleaseThreePointLines"
    local floorHeight = band.Position.Y + band.Size.Y / 2 + 0.08
    local count = 0
    for _, line in ipairs(threePoint:GetDescendants()) do
        if line:IsA("MeshPart") and line.Name:match("^ThreePointLine") then
            local copy = line:Clone()
            if copy then
                copy:ClearAllChildren()
                copy.Size = Vector3.new(line.Size.X, 0.06, line.Size.Z)
                copy.CFrame = line.CFrame + Vector3.new(0, floorHeight - line.Position.Y, 0)
                copy.TextureID = ""
                copy.MaterialVariant = ""
                copy.Material = Enum.Material.Neon
                copy.LocalTransparencyModifier = 0
                copy.Anchored = true
                copy.CanCollide, copy.CanTouch, copy.CanQuery, copy.CastShadow = false, false, false, false
                copy.Parent = overlay
                count += 1
            end
        end
    end
    if count == 0 then
        overlay:Destroy()
        hubControls.visualStatus.Text = "The court line meshes are unavailable."
        return
    end
    overlay.Parent = workspace
    lineOverlay = overlay
    visualExtras.threeActive = true
    visualExtras.styleThreePointLines()
    hubControls.visualStatus.Text = string.format("Showing %d three-point arcs.", count)
end

local appliedLineTransparency
function visualExtras.styleThreePointLines()
    if not lineOverlay then return end
    local color = Color3.fromHex(visualExtras.lineHex)
    appliedLineTransparency = visualExtras.lineTransparency.value
    for _, line in ipairs(lineOverlay:GetChildren()) do
        line.Color = color
        line.Transparency = appliedLineTransparency / 100
    end
end

local function findCharacter()
    local characters = workspace:FindFirstChild("Characters")
    local character = characters and characters:FindFirstChild(player.Name) or player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    return character, root
end

function defense.perimeterShot(character, root, goal)
    if not character or not root or not goal then return false end
    local action = character:GetAttribute("Action")
    if type(action) ~= "string" then return false end
    action = action:lower()
    if action:find("dunk", 1, true) or action:find("layup", 1, true) or action:find("gather", 1, true)
        or action:find("clutch", 1, true) then return false end
    local shooting = action:find("shoot", 1, true) or action:find("jump", 1, true) or action:find("fade", 1, true)
    local delta = root.Position - goal.Position
    return shooting ~= nil and Vector3.new(delta.X, 0, delta.Z).Magnitude >= 7
end

-- Shared ownership keeps sky, FPS, and Full Bright restoration independent.
do
    local records = {}
    local function equal(a, b)
        if a == b then return true end
        local kind = typeof(a)
        if kind ~= typeof(b) then return false end
        if kind == "NumberSequence" or kind == "ColorSequence" then
            local left, right = a.Keypoints, b.Keypoints
            if #left ~= #right then return false end
            for i, point in ipairs(left) do
                local other = right[i]
                if point.Time ~= other.Time or point.Value ~= other.Value then return false end
                if kind == "NumberSequence" and point.Envelope ~= other.Envelope then return false end
            end
            return true
        elseif kind == "NumberRange" then return a.Min == b.Min and a.Max == b.Max end
        return false
    end
    local function apply(record)
        local readable, current = pcall(function() return record.object[record.property] end)
        if not readable then return false, current end
        if record.written ~= nil and not equal(current, record.written) then record.base = current end
        local best
        for _, request in pairs(record.owners) do
            if not best or request.priority > best.priority then best = request end
        end
        local wanted = record.base
        if best then wanted = best.value end
        if type(wanted) == "function" then
            local ok, value = pcall(wanted, record.base)
            if not ok then return false, value end
            wanted = value
        end
        if equal(current, wanted) then record.written = current; return true end
        record.writing = true
        local ok, problem = pcall(function() record.object[record.property] = wanted end)
        if ok then record.written = wanted end
        record.writing = false
        return ok, problem
    end
    function sceneOverrides.set(owner, object, property, value, priority)
        local fields = records[object]
        local record = fields and fields[property]
        if not record then
            local ok, base = pcall(function() return object[property] end)
            if not ok or base == nil then return false, "Unavailable property " .. property end
            fields = fields or {}; records[object] = fields
            record = {object = object, property = property, base = base, owners = {}}
            fields[property] = record
            pcall(function()
                record.connection = object:GetPropertyChangedSignal(property):Connect(function()
                    if record.writing then return end
                    local readable, current = pcall(function() return object[property] end)
                    if readable and not equal(current, record.written) then record.base = current; apply(record) end
                end)
            end)
        end
        record.owners[owner] = {value = value, priority = priority or 0}
        return apply(record)
    end
    function sceneOverrides.clear(owner, onlyObject)
        local function clearObject(object, fields)
            for property, record in pairs(fields) do
                if record.owners[owner] then record.owners[owner] = nil; apply(record) end
                if not next(record.owners) then
                    if record.connection then record.connection:Disconnect() end
                    fields[property] = nil
                end
            end
            if not next(fields) then records[object] = nil end
        end
        -- Map teardown calls this for each descendant. Look up that object directly.
        if onlyObject ~= nil then
            local fields = records[onlyObject]
            if fields then clearObject(onlyObject, fields) end
            return
        end
        for object, fields in pairs(records) do clearObject(object, fields) end
    end
    function sceneOverrides.count(owner)
        local count = 0
        for _, fields in pairs(records) do for _, record in pairs(fields) do
            if not owner or record.owners[owner] then count += 1 end
        end end
        return count
    end
    function sceneOverrides.restoreAll()
        for _, fields in pairs(records) do for _, record in pairs(fields) do
            if record.connection then record.connection:Disconnect() end
            table.clear(record.owners)
            apply(record)
        end end
        table.clear(records)
    end
end

do
    local Lighting = game:GetService("Lighting")
    local defaults = {enabled = false, fullBright = false, keepHub = true, brightness = 25, exposure = 20,
        shadows = true, post = true, particles = true, trails = false, lights = false,
        materials = false, textures = false, water = false, fog = false}
    local state = table.clone(defaults)
    local rows, boxes = {}, {}
    local panel = appearance.performancePane
    label(panel, "FPS BOOST", 0, 0, 315, 22, 13, Enum.Font.GothamBold, colors.text)
    label(panel, "FULL BRIGHT", 350, 0, 315, 22, 13, Enum.Font.GothamBold, colors.text)
    local boostToggle = switch(panel, "FPS Boost", 0, 34)
    local brightToggle = switch(panel, "Full Bright", 350, 34)
    local choices = {{"shadows", "Disable shadows"}, {"post", "Disable post effects"},
        {"particles", "Hide particles, smoke and fire"}, {"trails", "Hide beams and trails"},
        {"lights", "Disable decorative lights"}, {"materials", "Simplify map materials"},
        {"textures", "Hide map decals and mesh textures"}, {"water", "Simplify terrain water"},
        {"fog", "Remove world fog and clouds"}}
    local function checkbox(key, text, x, y)
        local row = button(panel, "", x, y, 318, 32, colors.surface, colors.text)
        row.BackgroundTransparency = 1
        row.Name = "WizardFpsOption" .. key
        local box = rounded(create("Frame", row, {Position = UDim2.fromOffset(0, 6), Size = UDim2.fromOffset(19, 19),
            BackgroundColor3 = colors.card, BorderSizePixel = 0}), 4)
        create("UIStroke", box, {Color = colors.divider, Thickness = 1})
        local tick = label(box, "✓", 2, -1, 17, 20, 14, Enum.Font.GothamBold, colors.accent)
        label(row, text, 30, 0, 286, 32, 12, Enum.Font.GothamMedium, colors.text)
        rows[key], boxes[key] = row, {box = box, tick = tick}
    end
    for index, entry in ipairs(choices) do checkbox(entry[1], entry[2], 0, 83 + (index - 1) * 43) end
    checkbox("keepHub", "Keep Wizard effects and overlays", 350, 227)
    local brightness = slider(panel, "Brightness", 350, 93, 10, 60, defaults.brightness, "%.1f", .1)
    local exposure = slider(panel, "Exposure", 350, 155, 0, 100, defaults.exposure, "+%.2f", .01)
    local stats = label(panel, "FPS  --", 350, 288, 315, 80, 13, Enum.Font.GothamMedium, colors.text)
    stats.TextWrapped = true
    local hint = label(panel, "Choose the changes to apply while FPS Boost is on. Full Bright works independently. Turning a feature off restores its changes.",
        350, 383, 315, 80, 12, Enum.Font.Gotham, colors.muted)
    hint.TextWrapped = true
    local restore = button(panel, "Reset performance options", 350, 482, 315, 32, colors.card, colors.text)
    local status = label(panel, "FPS Boost and Full Bright are off.", 0, 506, 318, 49, 11, Enum.Font.Gotham, colors.muted)
    status.TextWrapped = true
    local note = label(panel, "Players, the ball, court physics, and controls stay active. FPS changes depend on your hardware and the scene.",
        0, 579, 670, 43, 11, Enum.Font.Gotham, colors.muted)
    note.TextWrapped = true
    local queue, pending, cursor, needScan = {}, {}, 1, false
    local alive, frames, span, fps, baseline, nextStats = true, 0, 0, nil, nil, 0
    local applied, unsupported = 0, {}
    local invisible = NumberSequence.new(1)
    local function active() return alive and (state.enabled or state.fullBright) end
    local function protected(object)
        if not state.keepHub then return false end
        local current = object
        while current and current ~= workspace and current ~= Lighting do
            if current.Name:match("^Wizard") or current.Name:match("^GymRelease") or current.Name:match("^PracticalBasketballGymRelease") then return true end
            current = current.Parent
        end
        return false
    end
    local function environment(object)
        local current = object
        while current and current ~= workspace do
            if current.Name == "Characters" or current.Name == "Basketballs" or current.Name == "Hoops" then return false end
            if current:IsA("Model") and current:FindFirstChildOfClass("Humanoid") then return false end
            current = current.Parent
        end
        return current == workspace
    end
    local function set(owner, object, property, value, priority)
        local ok = sceneOverrides.set(owner, object, property, value, priority)
        if ok then applied += 1 else unsupported[object.ClassName .. "." .. property] = true end
    end
    local function enqueue(object)
        if active() and not pending[object] then pending[object] = true; queue[#queue + 1] = object end
    end
    local function updateGlobals()
        sceneOverrides.clear("fps", Lighting)
        sceneOverrides.clear("bright", Lighting)
        local terrain = workspace:FindFirstChildOfClass("Terrain")
        if terrain then sceneOverrides.clear("fps", terrain) end
        if state.enabled then
            if state.shadows then set("fps", Lighting, "GlobalShadows", false, 30) end
            if state.fog then
                set("fps", Lighting, "FogStart", 1000000, 30)
                set("fps", Lighting, "FogEnd", 1001000, 30)
            end
            if state.water and terrain then
                for property, value in pairs({WaterWaveSize = 0, WaterWaveSpeed = 0, WaterReflectance = 0, WaterTransparency = 1}) do
                    set("fps", terrain, property, value, 30)
                end
            end
        end
        if state.fullBright then
            for property, value in pairs({Brightness = state.brightness / 10, ExposureCompensation = state.exposure / 100,
                ClockTime = 14, Ambient = Color3.fromRGB(220, 220, 220), OutdoorAmbient = Color3.fromRGB(220, 220, 220),
                GlobalShadows = false, EnvironmentDiffuseScale = 1}) do set("bright", Lighting, property, value, 40) end
        end
    end
    local function applyObject(object)
        if not object.Parent or protected(object) then return end
        local class = object.ClassName
        if state.enabled then
            if state.post and object:IsA("PostEffect") then set("fps", object, "Enabled", false, 30) end
            if state.particles then
                if class == "ParticleEmitter" then
                    set("fps", object, "Enabled", false, 30)
                    set("fps", object, "Transparency", invisible, 30)
                elseif class == "Fire" or class == "Smoke" or class == "Sparkles" then set("fps", object, "Enabled", false, 30) end
            end
            if state.trails and (class == "Beam" or class == "Trail") then
                set("fps", object, "Enabled", false, 30)
                set("fps", object, "Transparency", invisible, 30)
            end
            if state.lights and object:IsA("Light") then set("fps", object, "Enabled", false, 30) end
            if state.fog then
                if class == "Atmosphere" then
                    set("fps", object, "Density", 0, 30); set("fps", object, "Haze", 0, 30); set("fps", object, "Glare", 0, 30)
                elseif class == "Clouds" then set("fps", object, "Enabled", false, 30) end
            end
            if state.materials and object:IsA("BasePart") and environment(object) then
                set("fps", object, "Material", Enum.Material.SmoothPlastic, 30)
                set("fps", object, "MaterialVariant", "", 30)
                set("fps", object, "Reflectance", 0, 30)
            end
            if state.textures and environment(object) then
                if class == "Decal" or class == "Texture" then set("fps", object, "Transparency", 1, 30)
                elseif class == "MeshPart" then set("fps", object, "TextureID", "", 30) end
            end
        end
        if state.fullBright and (class == "ColorCorrectionEffect" or class == "ColorGradingEffect") then set("bright", object, "Enabled", false, 40) end
    end
    local function rebuild()
        sceneOverrides.clear("fps")
        sceneOverrides.clear("bright")
        table.clear(queue); table.clear(pending); cursor = 1
        applied, unsupported = 0, {}
        updateGlobals()
        needScan = active()
    end
    function renderOptions.refresh()
        showSwitch(boostToggle, state.enabled); showSwitch(brightToggle, state.fullBright)
        for key, entry in pairs(boxes) do
            entry.tick.Visible = state[key]
            appearance.paint(entry.box, "BackgroundColor3", state[key] and "tint" or "card")
        end
        showSlider(brightness, state.brightness); showSlider(exposure, state.exposure)
        status.Text = state.enabled and "Selected FPS options are active." or "FPS Boost is off. Checked options are saved."
        if state.fullBright then status.Text ..= " Full Bright is on." end
    end
    function renderOptions.capture() return table.clone(state) end
    function renderOptions.apply(saved)
        saved = type(saved) == "table" and saved or {}
        alive = true
        for key, value in pairs(defaults) do
            if type(value) == "boolean" then state[key] = saved[key] == nil and value or saved[key] == true end
        end
        state.brightness = type(saved.brightness) == "number" and saved.brightness == saved.brightness and math.clamp(saved.brightness, 10, 60) or defaults.brightness
        state.exposure = type(saved.exposure) == "number" and saved.exposure == saved.exposure and math.clamp(saved.exposure, 0, 100) or defaults.exposure
        rebuild(); renderOptions.refresh()
    end
    function renderOptions.watch(now, dt)
        if not alive then return end
        if type(dt) == "number" and dt > 0 and dt < 1 then
            frames, span = frames + 1, span + dt
            if span >= .6 then fps = frames / span; frames, span = 0, 0 end
        end
        if needScan then
            needScan = false
            for _, root in ipairs({workspace, Lighting}) do
                for _, object in ipairs(root:GetDescendants()) do enqueue(object) end
            end
        end
        local began, processed = os.clock(), 0
        while cursor <= #queue and processed < 150 and os.clock() - began < .0025 do
            local object = queue[cursor]
            cursor += 1; processed += 1; pending[object] = nil
            applyObject(object)
        end
        if cursor > #queue then table.clear(queue); cursor = 1 end
        if now >= nextStats then
            nextStats = now + .5
            local trend = state.enabled and baseline and fps and string.format("  ·  %+.0f%% vs enable", (fps / baseline - 1) * 100) or ""
            local remaining = math.max(0, #queue - cursor + 1)
            local unavailable = 0; for _ in pairs(unsupported) do unavailable += 1 end
            stats.Text = string.format("FPS  %s%s\n%d visual changes%s%s", fps and string.format("%.0f", fps) or "--", trend,
                sceneOverrides.count("fps"), remaining > 0 and "\nApplying selected options…" or "",
                unavailable > 0 and string.format("\n%d changes unavailable in this session", unavailable) or "")
        end
    end
    function renderOptions.stop()
        alive = false
        sceneOverrides.clear("fps"); sceneOverrides.clear("bright")
        table.clear(queue); table.clear(pending); cursor = 1; needScan = false
    end
    function renderOptions.bind(connectControl)
        connectControl(boostToggle.row.Activated, function()
            state.enabled = not state.enabled
            baseline = state.enabled and fps or nil
            rebuild(); renderOptions.refresh()
        end)
        connectControl(brightToggle.row.Activated, function() state.fullBright = not state.fullBright; rebuild(); renderOptions.refresh() end)
        for key, row in pairs(rows) do connectControl(row.Activated, function()
            state[key] = not state[key]; rebuild(); renderOptions.refresh()
        end) end
        brightness.onChange = function() if state.brightness ~= brightness.value then state.brightness = brightness.value; if state.fullBright then updateGlobals() end end end
        exposure.onChange = function() if state.exposure ~= exposure.value then state.exposure = exposure.value; if state.fullBright then updateGlobals() end end end
        connectControl(restore.Activated, function() renderOptions.apply(nil) end)
        for _, root in ipairs({workspace, Lighting}) do
            connectControl(root.DescendantAdded, enqueue)
            connectControl(root.DescendantRemoving, function(object)
                sceneOverrides.clear("fps", object); sceneOverrides.clear("bright", object)
            end)
        end
        renderOptions.refresh()
    end
    function renderOptions.diagnostics()
        return {active = active(), pending = math.max(0, #queue - cursor + 1), fps = fps,
            properties = sceneOverrides.count("fps"), brightnessProperties = sceneOverrides.count("bright")}
    end
end

