    local active, effectFolder = {}, nil
    local skyRecords, atmosphereRecords, courtRecords = {}, {}, {}
    local skyCache, ownedSky = {}, nil
    local nextCourtScan, nextSkyScan, lastGreen, lastPreview = 0, 0, -math.huge, -math.huge
