    local function normalizeHex(value)
        local hex = type(value) == "string" and value:match("^%s*#?(%x%x%x%x%x%x)%s*$")
        return hex and hex:upper()
    end
    local function restoreRecords(records)
        for obj, record in pairs(records) do
            pcall(function()
                for key, value in pairs(record.base) do
                    if obj[key] == record.last[key] then obj[key] = value end
                end
            end)
        end
        table.clear(records)
    end
    local function setTracked(records, obj, key, value)
        local record = records[obj]
        if not record then record = {base = {}, last = {}}; records[obj] = record end
        if record.base[key] == nil or (record.last[key] ~= nil and obj[key] ~= record.last[key]) then
            record.base[key] = obj[key]
        end
        obj[key], record.last[key] = value, value
    end
    local function clearEffects()
        table.clear(active)
        if effectFolder then effectFolder:Destroy(); effectFolder = nil end
    end
    local function restoreSky()
        skyGeneration += 1
        sceneOverrides.clear("sky")
        if ownedSky then ownedSky:Destroy(); ownedSky = nil end
        currentSky = "Original"
    end
    local function decode64(encoded)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local values = {}
        for i = 1, #alphabet do values[alphabet:byte(i)] = i - 1 end
        local bytes, accumulator, bits = {}, 0, 0
        for i = 1, #encoded do
            local value = values[encoded:byte(i)]
            if value then
                accumulator, bits = accumulator * 64 + value, bits + 6
                if bits >= 8 then
                    bits -= 8
                    local divisor = 2 ^ bits
                    bytes[#bytes + 1] = string.char(math.floor(accumulator / divisor))
                    accumulator %= divisor
                end
            end
        end
        return table.concat(bytes)
    end
    local function registerSkyFile(key, face, packed, extension)
        local loader = type(getcustomasset) == "function" and getcustomasset
            or type(getsynasset) == "function" and getsynasset
            or type(syn) == "table" and type(syn.getcustomasset) == "function" and syn.getcustomasset
        if not loader or type(writefile) ~= "function" then error("This executor needs writefile and a custom asset loader for sky textures.") end
        local directory = ""
        if type(makefolder) == "function" then
            local rootOk = pcall(makefolder, "GymRelease")
            local folderOk = pcall(makefolder, "GymRelease/wizard-skies-v3")
            -- Some executors throw when the folder already exists.
            if folderOk or (type(isfolder) == "function" and isfolder("GymRelease/wizard-skies-v3")) then directory = "GymRelease/wizard-skies-v3/" end
        end
        local filename = directory .. "WizardSkyV3-" .. key:lower() .. "-" .. face:lower() .. "." .. extension
        local bytes = decode64(packed)
        local cached = false
        if type(isfile) == "function" and type(readfile) == "function" then
            local ok, existing = pcall(function() return isfile(filename) and readfile(filename) end)
            cached = ok and existing == bytes
        end
        if not cached then writefile(filename, bytes) end
        local asset = loader(filename)
        assert(type(asset) == "string" and asset ~= "", "Sky texture registration failed")
        return asset
    end
    local function skyAssets(name)
        if skyCache[name] then return skyCache[name] end
        local definition = skyDefinitions[name]
        local files = definition and skyData[definition.key]
        assert(files, "Unknown sky preset")
        local assets = {}
        for _, face in ipairs({"Bk", "Dn", "Ft", "Lf", "Rt", "Up"}) do
            assets[face] = registerSkyFile(definition.key, face, files[face], files.Ext or "png")
        end
        skyCache[name] = assets
        return assets
    end
    local function applySkyScene(assets)
        local skies = {}
        for _, obj in ipairs(Lighting:GetChildren()) do if obj:IsA("Sky") then skies[#skies + 1] = obj end end
        if #skies == 0 then
            ownedSky = create("Sky", Lighting, {Name = "WizardCustomSky"})
            skies[1] = ownedSky
        end
        for _, obj in ipairs(skies) do
            for face, asset in pairs(assets) do sceneOverrides.set("sky", obj, "Skybox" .. face, asset, 10) end
            sceneOverrides.set("sky", obj, "CelestialBodiesShown", false, 10)
            sceneOverrides.set("sky", obj, "StarCount", 0, 10)
            sceneOverrides.set("sky", obj, "SkyboxOrientation", Vector3.new(0, state.rotation, 0), 10)
        end
        local keep = 1 - state.clarity / 100
        for _, obj in ipairs(Lighting:GetChildren()) do
            if obj:IsA("Atmosphere") then
                sceneOverrides.set("sky", obj, "Density", function(base) return base * keep end, 10)
                sceneOverrides.set("sky", obj, "Haze", function(base) return base * keep end, 10)
                sceneOverrides.set("sky", obj, "Glare", function(base) return base * keep end, 10)
            end
        end
        sceneOverrides.set("sky", Lighting, "FogStart", function(base) return base + (1000000 - base) * state.clarity / 100 end, 10)
        sceneOverrides.set("sky", Lighting, "FogEnd", function(base) return base + (1001000 - base) * state.clarity / 100 end, 10)
        local terrain = workspace:FindFirstChildOfClass("Terrain")
        if terrain then for _, obj in ipairs(terrain:GetChildren()) do
            if obj:IsA("Clouds") then sceneOverrides.set("sky", obj, "Enabled", false, 10) end
        end end
    end
    local function selectSky(name)
        restoreSky()
        state.sky = skySet[name] and name or "Original"
        if state.sky == "Original" then skyStatus.Text = "Original game sky."; return end
        local generation, requested = skyGeneration, state.sky
        skyStatus.Text = "Loading " .. requested .. "…"
        task.spawn(function()
            local ok, assets = pcall(skyAssets, requested)
            if ok then
                local providerOk, provider = pcall(game.GetService, game, "ContentProvider")
                if providerOk and provider then
                    local textures = {}; for _, asset in pairs(assets) do textures[#textures + 1] = asset end
                    local failed = false
                    ok = pcall(function() provider:PreloadAsync(textures, function(_, status)
                        if status ~= Enum.AssetFetchStatus.Success then failed = true end
                    end) end)
                    if failed then ok, assets = false, "A sky texture could not load." end
                end
            end
            if not alive or generation ~= skyGeneration then return end
            if ok then ok, assets = pcall(function() applySkyScene(assets) end) end
            if ok then currentSky = requested; skyStatus.Text = requested .. " · ready"
            else
                restoreSky(); state.sky = "Original"
                skyStatus.Text = "Sky unavailable. Original restored."
                warn(prefix .. "Skybox: " .. tostring(assets))
            end
            gameAppearance.refresh()
        end)
    end
    local function loadSkyPreviews()
        local current = Lighting:FindFirstChildOfClass("Sky")
        skyImages.Original.Image = current and current.SkyboxFt or "rbxasset://textures/sky/sky512_ft.tex"
        for _, name in ipairs(skyNames) do
            if name ~= "Original" and alive then
                local definition = skyDefinitions[name]
                local files = skyData[definition.key]
                local ok, asset = pcall(registerSkyFile, definition.key, files.Thumb and "thumb" or "Ft", files.Thumb or files.Ft, files.Ext or "png")
                if ok and alive and skyImages[name].Parent then skyImages[name].Image = asset end
                task.wait()
            end
        end
    end

    local function courtRole(obj)
        if not obj:IsA("BasePart") or obj.Transparency >= 0.8 then return end
        if obj.Name == "PerimeterZone" or obj.Name == "CourtBand" then return "floorColor" end
        if obj.Name == "InsideZone" then return "insideColor" end
        if obj.Name == "PaintZone" then return "paintColor" end
        local parent = obj.Parent
        if parent and parent.Name == "Lines" or obj.Name:match("_L$") then return "lineColor" end
    end
    local function scanCourts()
        if not state.courts then restoreRecords(courtRecords); courtStatus.Text = "Court recoloring is off."; return end
        local _, root = findCharacter()
        if not state.allCourts and not root then
            restoreRecords(courtRecords)
            courtStatus.Text = "Waiting for your character."
            return
        end
        local map = workspace:FindFirstChild("Map")
        local courtRoot = map and map:FindFirstChild("Courts")
        local groups = {}
        for _, court in ipairs(courtRoot and courtRoot:GetChildren() or {}) do
            local items = court:FindFirstChild("Items")
            if items then groups[#groups + 1] = {name = court.Name, items = items:GetDescendants()} end
        end
        if #groups == 0 then
            local assets = workspace:FindFirstChild("Assets")
            local court = assets and assets:FindFirstChild("Court")
            local floor = court and court:FindFirstChild("Floor")
            if floor then groups[1] = {name = "Gym", items = floor:GetDescendants()} end
        end
        local nearest, nearestDistance = nil, math.huge
        for _, group in ipairs(groups) do
            for _, obj in ipairs(group.items) do
                local role = courtRole(obj)
                if role and role ~= "lineColor" and root then
                    local delta = obj.Position - root.Position
                    local distance = delta.X * delta.X + delta.Z * delta.Z
                    if distance < nearestDistance then nearestDistance, nearest = distance, group end
                end
            end
        end
        local seen, count = {}, 0
        for _, group in ipairs(groups) do
            if state.allCourts or group == nearest then
                for _, obj in ipairs(group.items) do
                    local role = courtRole(obj)
                    if role then
                        seen[obj], count = true, count + 1
                        local record = courtRecords[obj]
                        if record and obj.Color ~= record.last.Color then record.base.Color = obj.Color end
                        local original = record and record.base.Color or obj.Color
                        setTracked(courtRecords, obj, "Color", original:Lerp(Color3.fromHex(state[role]), state.strength / 100))
                    end
                end
            end
        end
        for obj, record in pairs(courtRecords) do
            if not seen[obj] then
                pcall(function() if obj.Color == record.last.Color then obj.Color = record.base.Color end end)
                courtRecords[obj] = nil
            end
        end
        courtStatus.Text = count == 0 and "Waiting for compatible court surfaces."
            or string.format("%s · %d surfaces recolored", state.allCourts and "All loaded courts" or nearest.name, count)
    end

    local function effectPart(parent, color, size, position, shape)
        return create("Part", parent, {Name = "WizardGreenVisual", Anchored = true, CanCollide = false,
            CanTouch = false, CanQuery = false, CastShadow = false, Material = Enum.Material.Neon,
            Color = color, Size = size, CFrame = CFrame.new(position), Transparency = 0.1,
            Shape = shape or Enum.PartType.Block})
    end
    local function playEffect(preview)
        local now = os.clock()
        if preview and now - lastPreview < 0.25 then return end
        if preview then lastPreview = now end
        local character, root = findCharacter()
        if not root then effectStatus.Text = "Waiting for your character."; return end
        local name = (not preview and state.random) and effects[math.random(1, #effects)] or state.effect
        if not effectFolder then effectFolder = create("Folder", workspace, {Name = "WizardGreenEffects"}) end
        if #active >= 3 then active[1].folder:Destroy(); table.remove(active, 1) end
        local folder = create("Folder", effectFolder, {Name = name:gsub(" ", "")})
        local entry = {folder = folder, began = now, life = state.duration / 100, anim = {}}
        active[#active + 1] = entry
        local scale, color = state.scale / 100, Color3.fromHex(state.effectColor)
        local origin = root.Position - Vector3.new(0, 2.8, 0)
        local ray = RaycastParams.new()
        ray.FilterType, ray.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, {character, effectFolder}
        local hit = workspace:Raycast(root.Position + Vector3.new(0, 1, 0), Vector3.new(0, -14, 0), ray)
        if hit then origin = hit.Position + Vector3.new(0, 0.12, 0) end
        local function animate(callback) entry.anim[#entry.anim + 1] = callback end
        local function ring(center, radius, delay, vertical, phase, tint)
            local pieces, segments = {}, 32
            for i = 1, segments do pieces[i] = effectPart(folder, tint or color, Vector3.new(.12, .12, .5), center) end
            animate(function(t)
                local u = math.clamp((t - (delay or 0)) / (1 - (delay or 0)), 0, 1)
                local r = radius * scale * (.18 + u * .82)
                local rotation = CFrame.Angles(vertical and math.pi / 2 or 0, phase or 0, 0)
                for i, part in ipairs(pieces) do
                    local a, b = (i - 1) / segments * math.pi * 2, i / segments * math.pi * 2
                    local p0 = (CFrame.new(center) * rotation * CFrame.new(math.cos(a) * r, 0, math.sin(a) * r)).Position
                    local p1 = (CFrame.new(center) * rotation * CFrame.new(math.cos(b) * r, 0, math.sin(b) * r)).Position
                    part.Size = Vector3.new(.12 * scale, .12 * scale, (p1 - p0).Magnitude + .035)
                    part.CFrame = CFrame.lookAt((p0 + p1) / 2, p1)
                    part.Transparency = t < (delay or 0) and 1 or .1 + .9 * u
                end
            end)
        end
        local function burst(center, texture, count, speed, tint, down)
            local anchor = effectPart(folder, tint or color, Vector3.new(.1, .1, .1), center)
            anchor.Transparency = 1
            local emitter = create("ParticleEmitter", anchor, {Name = "WizardGreenParticles", Enabled = false,
                Texture = texture, Rate = 0, Color = ColorSequence.new(tint or color),
                Lifetime = NumberRange.new(entry.life * .5, entry.life), Speed = NumberRange.new(speed * scale * .6, speed * scale),
                SpreadAngle = Vector2.new(180, 180), LightEmission = 1, LightInfluence = 0,
                Size = NumberSequence.new({NumberSequenceKeypoint.new(0, .65 * scale), NumberSequenceKeypoint.new(1, 0)}),
                Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(.65, .2), NumberSequenceKeypoint.new(1, 1)}),
                Acceleration = Vector3.new(0, down and -16 or -3, 0), Drag = 1.3,
                Rotation = NumberRange.new(0, 360), RotSpeed = NumberRange.new(-90, 90)})
            emitter:Emit(count)
        end
        local function orbit(count, height, radius, turns, tint)
            for i = 1, count do
                local part = effectPart(folder, tint or color, Vector3.new(.24, .24, .24) * scale, origin, Enum.PartType.Ball)
                animate(function(t)
                    local angle = i / count * math.pi * 2 + t * math.pi * 2 * turns
                    part.Position = origin + Vector3.new(math.cos(angle) * radius * scale,
                        (height + math.sin(t * math.pi) * 1.4) * scale, math.sin(angle) * radius * scale)
                    part.Transparency = t * t
                end)
            end
        end
        if name == "Pulse Ring" then ring(origin, 7)
        elseif name == "Twin Rings" then ring(origin, 7); ring(origin + Vector3.new(0, .25, 0), 5, .18)
        elseif name == "Shockwave" then for i = 0, 2 do ring(origin + Vector3.new(0, i * .15, 0), 10 - i * 1.5, i * .18) end
        elseif name == "Spark Burst" then burst(origin + Vector3.new(0, 3, 0), sparkleTexture, 75, 15)
        elseif name == "Starfall" then burst(origin + Vector3.new(0, 10 * scale, 0), sparkleTexture, 90, 5, nil, true)
        elseif name == "Confetti" then
            for i = 1, 42 do
                local angle, speed, lift = math.random() * math.pi * 2, (2 + math.random() * 5) * scale, (5 + math.random() * 5) * scale
                local part = effectPart(folder, Color3.fromHSV(i / 42, .65, 1), Vector3.new(.18, .38, .06) * scale, origin)
                animate(function(t)
                    local elapsed = t * entry.life
                    part.CFrame = CFrame.new(origin + Vector3.new(math.cos(angle) * speed * elapsed,
                        2 + lift * elapsed - 6 * elapsed * elapsed, math.sin(angle) * speed * elapsed)) * CFrame.Angles(t * 10, angle + t * 8, t * 6)
                    part.Transparency = math.max(0, (t - .5) * 2)
                end)
            end
        elseif name == "Spiral" then
            for i = 1, 36 do
                local part = effectPart(folder, color, Vector3.new(.18, .18, .18) * scale, origin, Enum.PartType.Ball)
                animate(function(t)
                    local angle, h = i / 36 * math.pi * 4 + t * math.pi * 4, i / 36 * 6 + t * 2
                    part.Position = origin + Vector3.new(math.cos(angle) * 2.1, h, math.sin(angle) * 2.1) * scale
                    part.Transparency = t
                end)
            end
        elseif name == "Halo" then ring(origin + Vector3.new(0, 6.5 * scale, 0), 2.5); orbit(16, 6.5, 2.5, .8)
        elseif name == "Lightning" then
            for bolt = 1, 7 do
                local angle, previous = bolt / 7 * math.pi * 2, origin + Vector3.new(0, 7 * scale, 0)
                for segment = 1, 5 do
                    local nextPoint = origin + Vector3.new(math.cos(angle) * segment * .65 + (math.random() - .5),
                        7 - segment * 1.3, math.sin(angle) * segment * .65 + (math.random() - .5)) * scale
                    local part = effectPart(folder, color:Lerp(Color3.new(1, 1, 1), .4), Vector3.new(.11 * scale, .11 * scale, (nextPoint - previous).Magnitude), previous)
                    part.CFrame = CFrame.lookAt((previous + nextPoint) / 2, nextPoint)
                    previous = nextPoint
                    animate(function(t) part.Transparency = math.clamp(t + math.abs(math.sin(t * 32)) * .3, 0, 1) end)
                end
            end
        elseif name == "Flame Crown" then
            for i = 1, 8 do
                local a = i / 8 * math.pi * 2
                burst(origin + Vector3.new(math.cos(a) * 2, .5, math.sin(a) * 2) * scale,
                    "rbxasset://textures/particles/fire_main.dds", 10, 7, color:Lerp(Color3.fromRGB(255, 124, 33), .7))
            end
        elseif name == "Ice Shards" then
            for i = 1, 18 do
                local a, r = i / 18 * math.pi * 2, (1.5 + math.random() * 2) * scale
                local part = create("WedgePart", folder, {Name = "WizardIceShard", Anchored = true, CanCollide = false,
                    CanTouch = false, CanQuery = false, CastShadow = false, Material = Enum.Material.Neon,
                    Color = color:Lerp(Color3.fromRGB(170, 230, 255), .75), Size = Vector3.new(.4, 2.8, .65) * scale})
                animate(function(t)
                    part.CFrame = CFrame.new(origin + Vector3.new(math.cos(a) * r * (.5 + t), math.sin(t * math.pi) * 3 * scale, math.sin(a) * r * (.5 + t))) * CFrame.Angles(t, -a, .3)
                    part.Transparency = t
                end)
            end
        elseif name == "Heart Burst" then
            for i = 1, 16 do
                local a = i / 16 * math.pi * 2
                local anchor = effectPart(folder, color, Vector3.new(.1, .1, .1), origin); anchor.Transparency = 1
                local billboard = create("BillboardGui", anchor, {Name = "WizardGreenHeart", Adornee = anchor,
                    Size = UDim2.fromOffset(32 * scale, 32 * scale), AlwaysOnTop = false, LightInfluence = 0})
                local text = create("TextLabel", billboard, {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1),
                    Text = "♥", TextScaled = true, TextColor3 = color, Font = Enum.Font.GothamBold})
                animate(function(t)
                    anchor.Position = origin + Vector3.new(math.cos(a) * t * 5, 2 + t * 5, math.sin(a) * t * 5) * scale
                    text.TextTransparency = t * t
                end)
            end
        elseif name == "Fireworks" then
            for i = 1, 5 do
                local a = i / 5 * math.pi * 2
                burst(origin + Vector3.new(math.cos(a) * 3, 5 + i * .5, math.sin(a) * 3) * scale, sparkleTexture, 30, 11,
                    Color3.fromHSV(i / 5, .5, 1))
            end
        elseif name == "Portal" then
            ring(origin + Vector3.new(0, 3 * scale, 0), 3.5, 0, true)
            ring(origin + Vector3.new(0, 3 * scale, 0), 3.5, .12, true, math.pi / 2)
            orbit(20, 3, 3.5, 1.7)
        elseif name == "Supernova" then
            local ball = effectPart(folder, color, Vector3.new(1, 1, 1), origin + Vector3.new(0, 3 * scale, 0), Enum.PartType.Ball)
            animate(function(t) ball.Size = Vector3.new(1, 1, 1) * (.25 + math.sin(t * math.pi) * 7) * scale; ball.Transparency = .35 + .65 * t end)
            ring(origin, 10); burst(origin + Vector3.new(0, 3 * scale, 0), sparkleTexture, 100, 18)
        end
        for _, callback in ipairs(entry.anim) do callback(0) end
        effectStatus.Text = (preview and "Preview: " or "Perfect Release · ") .. name
    end

    function gameAppearance.refresh()
        for _, key in ipairs({"enabled", "random", "courts", "allCourts"}) do
            showSwitch(controls[key], state[key] == true)
        end
        for name, card in pairs(effectCards) do
            appearance.paint(card, "BackgroundColor3", state.effect == name and "tint" or "card")
            appearance.paint(card, "TextColor3", state.effect == name and "accent" or "text")
        end
        for name, card in pairs(skyCards) do
            appearance.paint(card, "BackgroundColor3", state.sky == name and "tint" or "card")
            appearance.paint(skyCaptions[name], "TextColor3", state.sky == name and "accent" or "text")
        end
        for key, box in pairs(colorBoxes) do box.Text = "#" .. state[key] end
        for _, key in ipairs({"scale", "duration", "clarity", "strength", "rotation"}) do showSlider(controls[key], state[key]) end
    end
    function gameAppearance.capture() return table.clone(state) end
    function gameAppearance.apply(saved)
        saved = type(saved) == "table" and saved or {}
        alive = true
        clearEffects()
        restoreRecords(courtRecords)
        for key, value in pairs(defaults) do
            local candidate = saved[key]
            if type(value) == "boolean" then state[key] = candidate == nil and value or candidate == true
            elseif key:find("Color", 1, true) then state[key] = normalizeHex(candidate) or value
            elseif type(value) == "number" then
                local item = controls[key]
                state[key] = type(candidate) == "number" and candidate == candidate and math.clamp(math.round(candidate), item.min, item.max) or value
            else state[key] = value end
        end
        state.effect = effectSet[saved.effect] and saved.effect or defaults.effect
        selectSky(skySet[saved.sky] and saved.sky or "Original")
        nextCourtScan = 0
        gameAppearance.refresh()
    end
    function gameAppearance.onRating(rating)
        if not state.enabled or type(rating) ~= "string" or rating:lower() ~= "perfect release" then return end
        local now = os.clock()
        if now - lastGreen < .15 then return end
        lastGreen = now
        local ok, problem = pcall(playEffect, false)
        if not ok then clearEffects(); warn(prefix .. "Green effect: " .. tostring(problem)) end
    end
    function gameAppearance.watch(now)
        if not alive then return end
        for index = #active, 1, -1 do
            local entry = active[index]
            local t = math.clamp((now - entry.began) / entry.life, 0, 1)
            if t >= 1 then entry.folder:Destroy(); table.remove(active, index)
            else for _, callback in ipairs(entry.anim) do callback(t) end end
        end
        if now >= nextCourtScan then nextCourtScan = now + .8; if state.courts or next(courtRecords) then scanCourts() end end
        if currentSky ~= "Original" and now >= nextSkyScan then
            nextSkyScan = now + 1
            applySkyScene(skyCache[currentSky])
        end
    end
    function gameAppearance.stop()
        alive = false
        clearEffects()
        restoreSky()
        restoreRecords(courtRecords)
    end
    function gameAppearance.bind(connectControl)
        for _, key in ipairs({"enabled", "random", "courts", "allCourts"}) do
            connectControl(controls[key].row.Activated, function()
                state[key] = not state[key]
                if key == "enabled" and not state.enabled then clearEffects() end
                if key == "courts" or key == "allCourts" then nextCourtScan = 0; scanCourts() end
                gameAppearance.refresh()
            end)
        end
        for name, card in pairs(effectCards) do
            connectControl(card.Activated, function() state.effect = name; gameAppearance.refresh() end)
        end
        for name, card in pairs(skyCards) do connectControl(card.Activated, function() selectSky(name); gameAppearance.refresh() end) end
        connectControl(controls.preview.Activated, function()
            local ok, problem = pcall(playEffect, true)
            if not ok then clearEffects(); effectStatus.Text = "Preview unavailable."; warn(prefix .. tostring(problem)) end
        end)
        for _, key in ipairs({"scale", "duration", "clarity", "strength", "rotation"}) do
            controls[key].onChange = function()
                state[key] = controls[key].value
                if key == "strength" then nextCourtScan = 0
                elseif (key == "clarity" or key == "rotation") and currentSky ~= "Original" then applySkyScene(skyCache[currentSky]) end
            end
        end
        for key, box in pairs(colorBoxes) do
            connectControl(box.FocusLost, function()
                state[key] = normalizeHex(box.Text) or state[key]
                nextCourtScan = 0
                gameAppearance.refresh()
            end)
            for _, chip in ipairs(colorChips[key]) do
                connectControl(chip.button.Activated, function() state[key] = chip.hex; nextCourtScan = 0; gameAppearance.refresh() end)
            end
        end
        connectControl(reset.Activated, function() gameAppearance.apply(nil) end)
        task.spawn(loadSkyPreviews)
        gameAppearance.refresh()
    end
end


local function positiveTeamId(character, attribute)
    local value = character and character:GetAttribute(attribute)
    if type(value) == "number" and value > 0 and value < math.huge and value % 1 == 0 then return value end
end

local function characterGoal(character)
    local attributes = character and character:FindFirstChild("Attributes")
    local goal = attributes and attributes:FindFirstChild("Goal")
    return goal and goal:IsA("ObjectValue") and goal.Value
end

-- Full-court teams attack opposite goals; court membership is independent of basket.
local function sameDefenseCourt(character, goal, opponent, otherGoal)
    local matched = false
    for _, name in ipairs({"MatchId", "CourtNumber", "CourtIndex", "GameIndex"}) do
        local own, other = positiveTeamId(character, name), positiveTeamId(opponent, name)
        if own and other then
            if own ~= other then return false end
            matched = true
        end
    end
    return matched or (goal ~= nil and goal == otherGoal)
end

do
    local segmentCount = 48
    local segmentAngle = 2 * math.pi / segmentCount
    local ring
    local floorRay
    local floorRoot, floorY, nextFloorSample
    local highlights = {}
    local nextTeamSample = 0
    local appliedTeamTransparency

    local function clearRing()
        if ring then ring.model:Destroy() end
        ring, floorRoot, floorY, nextFloorSample = nil, nil, nil, nil
    end

    local function ringCenter(character, root, now)
        local position = root.Position
        if floorRoot ~= root then
            floorRay = floorRay or RaycastParams.new()
            floorRay.FilterType = Enum.RaycastFilterType.Exclude
            floorRay.IgnoreWater = true
            floorRay.RespectCanCollide = true
            local exclusions = {workspace:FindFirstChild("Characters") or character}
            for _, name in ipairs({"Basketballs", "Hoops"}) do
                local object = workspace:FindFirstChild(name)
                if object then table.insert(exclusions, object) end
            end
            floorRay.FilterDescendantsInstances = exclusions
            floorRoot, nextFloorSample = root, nil
        end
        if not nextFloorSample or now >= nextFloorSample then
            nextFloorSample = now + 0.06
            local result = workspace:Raycast(position, Vector3.new(0, -28, 0), floorRay)
            floorY = result and result.Position.Y
        end
        local height = (floorY or position.Y - 3.8) + visualExtras.height.value + 0.07
        return Vector3.new(position.X, height, position.Z)
    end

    local function createRing(center)
        local model = create("Model", workspace, {Name = "WizardHubContestCircle", WorldPivot = CFrame.new(center)})
        local parts = {}
        for index = 1, segmentCount do
            parts[index] = create("Part", model, {
                Name = "CircleSegment", Anchored = true, CanCollide = false, CanTouch = false,
                CanQuery = false, CastShadow = false, Material = Enum.Material.Neon,
            })
        end
        return {model = model, parts = parts, center = center}
    end

    local function restyleRing(current, radius, width, hex)
        current.radius, current.width, current.hex = radius, width, hex
        local thickness = 0.13 * width / 100
        local innerRadius = radius * math.cos(segmentAngle / 2)
        local length = 2 * radius * math.sin(segmentAngle / 2) + 0.02
        local size, color, pose = Vector3.new(length, 0.06, thickness), Color3.fromHex(hex), CFrame.new(current.center)
        for index, part in ipairs(current.parts) do
            local angle = (index - 1) * segmentAngle
            part.Color, part.Size = color, size
            part.CFrame = pose * CFrame.new(innerRadius * math.cos(angle), 0, innerRadius * math.sin(angle))
                * CFrame.Angles(0, -angle - math.pi / 2, 0)
        end
    end

    local function watchRing(now)
        if not visualExtras.contest then
            clearRing()
            visualExtras.contestStatus.Text = "Marks the selected range around you."
            return
        end
        local character, root = findCharacter()
        if not root then
            clearRing()
            visualExtras.contestStatus.Text = "Waiting for your character."
            return
        end
        local center = ringCenter(character, root, now)
        if not ring or not ring.model.Parent then ring = createRing(center) end
        if (ring.center - center).Magnitude >= 0.01 then
            ring.center = center
            ring.model:PivotTo(CFrame.new(center))
        end
        local radius, width, hex = visualExtras.radius.value, visualExtras.width.value, visualExtras.contestHex
        if ring.radius ~= radius or ring.width ~= width or ring.hex ~= hex then
            restyleRing(ring, radius, width, hex)
            visualExtras.contestStatus.Text = string.format("Showing a %.2f-stud radius.", radius)
        end
    end

    local function clearHighlight(participant)
        local highlight = highlights[participant]
        if highlight then highlight:Destroy() end
        highlights[participant] = nil
    end

    local function sameTeam(localTeam, localIndex, localNative, localGoal, singleCourt, participant, character)
        local team, index = positiveTeamId(character, "Team"), positiveTeamId(character, "TeamIndex")
        if (localTeam and team) or (not localTeam and not team and localIndex and index) then
            if not singleCourt and (not localGoal or characterGoal(character) ~= localGoal) then return false end
            return localTeam == team and (localTeam ~= nil or localIndex == index)
        end
        return localNative and not participant.Neutral and participant.Team == localNative
    end

    local function watchHighlights()
        if not visualExtras.teammates then
            for participant in pairs(highlights) do clearHighlight(participant) end
            visualExtras.teammateStatus.Text = "Outlines players on your team."
            return
        end

        local roster = workspace:FindFirstChild("Characters")
        local character = roster and roster:FindFirstChild(player.Name) or player.Character
        local localTeam, localIndex = positiveTeamId(character, "Team"), positiveTeamId(character, "TeamIndex")
        local localNative = not player.Neutral and player.Team
        local localGoal, singleCourt = characterGoal(character), practiceBand() ~= nil
        local seen, count = {}, 0
        local color = Color3.fromHex(visualExtras.teamHex)
        local fade = appliedTeamTransparency / 100
        if localTeam or localIndex or localNative then
            for _, participant in ipairs(players:GetPlayers()) do
                if participant ~= player then
                    local model = roster and roster:FindFirstChild(participant.Name) or participant.Character
                    if model and model.Parent and sameTeam(localTeam, localIndex, localNative, localGoal, singleCourt, participant, model) then
                        local highlight = highlights[participant]
                        if not highlight or not highlight.Parent or highlight.Adornee ~= model then
                            clearHighlight(participant)
                            highlight = create("Highlight", model, {
                                Name = "WizardHubTeammate", Adornee = model, DepthMode = Enum.HighlightDepthMode.Occluded,
                            })
                            highlights[participant] = highlight
                        end
                        highlight.FillColor, highlight.OutlineColor = color, color
                        highlight.FillTransparency, highlight.OutlineTransparency = 0.73 + 0.27 * fade, 0.05 + 0.95 * fade
                        seen[participant], count = true, count + 1
                    end
                end
            end
        end
        for participant in pairs(highlights) do
            if not seen[participant] then clearHighlight(participant) end
        end
        visualExtras.teammateStatus.Text = count > 0 and string.format("Highlighted teammates: %d", count)
            or ((localTeam or localIndex or localNative) and "No teammates to highlight." or "No team assigned in this gym.")
    end

    function visualExtras.watch(now, force)
        visualExtras.watchContest(now, force)
        if drawThree and not lineOverlay and now >= (visualExtras.nextGeometrySample or 0) then
            visualExtras.nextGeometrySample = now + 1
            updateThreePointLines()
            if visualExtras.threeActive then refresh() end
        end
        if lineOverlay and appliedLineTransparency ~= visualExtras.lineTransparency.value then
            visualExtras.styleThreePointLines()
        end
        if visualExtras.contest or ring or force then watchRing(now) end
        local transparency = visualExtras.teamTransparency.value
        if (visualExtras.teammates or next(highlights) or force)
            and (force or now >= nextTeamSample or appliedTeamTransparency ~= transparency) then
            nextTeamSample = now + 0.25
            appliedTeamTransparency = transparency
            watchHighlights()
        end
    end

    function visualExtras.clear()
        clearRing()
        for participant in pairs(highlights) do clearHighlight(participant) end
    end
end

local function heldBall(character)
    local attributes = character and character:FindFirstChild("Attributes")
    local basketball = attributes and attributes:FindFirstChild("Basketball")
    if attributes then return basketball and basketball:IsA("ObjectValue") and basketball.Value or nil end
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local joint = root and root:FindFirstChild("Basketball")
    return joint and joint:IsA("Motor6D") and joint.Part1
end

do
    local r15 = {"Head", "UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand",
        "RightUpperArm", "RightLowerArm", "RightHand", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
        "RightUpperLeg", "RightLowerLeg", "RightFoot"}
    local r6 = {"Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg"}
    local cosmeticNames = {Accessories = true, RightShoe = true, LeftShoe = true, Nose = true, RightEar = true, LeftEar = true,
        RightFoot_Mascot = true, LeftFoot_Mascot = true}
    local selection = {mode = "original", everyone = false, defaultOthers = false}
    local generation, nextRosterCheck = 0, 0
    local targets, templates = {}, {}
    local skeletonOutfitId = {}
    local renderGui, viewport, renderWorld

    local function accountInput(value)
        if type(value) ~= "string" then return end
        value = value:match("^%s*@?(.-)%s*$")
        if value:match("^%d+$") then
            local id = tonumber(value)
            if id and id > 0 and id <= 9007199254740991 then return value end
        elseif #value >= 1 and #value <= 20 and value:match("^[%w_]+$") then
            return value
        end
    end

    local function clearAppearance(target)
        if not target.model then return end
        for part, original in pairs(target.hidden) do
            if part.Parent and part.LocalTransparencyModifier == 1 then part.LocalTransparencyModifier = original end
        end
        target.model:Destroy()
        target.model = nil
        table.clear(target.hidden)
        table.clear(target.links)
    end

    function avatar.suspend()
        generation += 1
        for _, target in pairs(targets) do clearAppearance(target) end
        for _, template in pairs(templates) do
            if template.model then template.model:Destroy() end
        end
        table.clear(targets)
        table.clear(templates)
        if renderGui then renderGui:Destroy() end
        renderGui, viewport, renderWorld = nil, nil, nil
        nextRosterCheck = 0
    end

    local function getRenderWorld(camera)
        if not renderWorld then
            -- Keep visual rigs outside Workspace so game scripts and physics never see them as court characters.
            renderGui = create("ScreenGui", nil, {
                Name = "WizardAvatarVisuals", ResetOnSpawn = false, IgnoreGuiInset = true,
                ScreenInsets = Enum.ScreenInsets.None, ClipToDeviceSafeArea = false,
            })
            viewport = create("ViewportFrame", renderGui, {
                Name = "Avatars", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1),
                Active = false, Interactable = false, CurrentCamera = camera,
            })
            renderWorld = create("WorldModel", viewport, {Name = "AvatarRenderWorld"})
            renderGui.Parent = playerGui
        end
        return renderWorld
    end

    function avatar.capture()
        return table.clone(selection)
    end

    local function refreshScopeControls()
        avatar.scopeButton.Text = selection.everyone and "Apply to everyone: On" or "Apply to everyone: Off"
        appearance.paint(avatar.scopeButton, "TextColor3", selection.everyone and "accent" or "text")
        avatar.defaultOthersButton.Text = selection.defaultOthers and "Default look for others: On" or "Default look for others: Off"
        appearance.paint(avatar.defaultOthersButton, "TextColor3", selection.defaultOthers and "accent" or "text")
        for key, chip in pairs(avatar.presetButtons) do
            appearance.paint(chip, "TextColor3", selection.mode == key and "accent" or "text")
            appearance.paint(chip, "BackgroundColor3", selection.mode == key and "tint" or "card")
        end
    end

    function avatar.apply(saved)
        avatar.suspend()
        local account = type(saved) == "table" and accountInput(saved.account)
        local mode = type(saved) == "table" and saved.mode
        if type(mode) ~= "string" or (not avatar.presets[mode] and (mode ~= "account" or not account)) then mode = "original" end
        selection = {mode = mode, account = account or nil, everyone = type(saved) == "table" and saved.everyone == true,
            defaultOthers = type(saved) == "table" and saved.defaultOthers == true}
        if account then avatar.accountBox.Text = account end
        refreshScopeControls()
        avatar.status.Text = selection.defaultOthers and "Waiting for other players." or
            (mode == "original" and "Original avatar." or "Waiting for your character.")
    end

    function avatar.bind()
        local function applyAccount()
            local account = accountInput(avatar.accountBox.Text)
            if not account then avatar.status.Text = "Enter a Roblox username or numeric user ID."; return end
            avatar.apply({mode = "account", account = account, everyone = selection.everyone, defaultOthers = selection.defaultOthers})
        end
        connect(avatar.accountButton.Activated, applyAccount)
        connect(avatar.accountBox.FocusLost, function(enter) if enter then applyAccount() end end)
        for key, chip in pairs(avatar.presetButtons) do
            connect(chip.Activated, function()
                avatar.apply({mode = key, account = selection.account, everyone = selection.everyone, defaultOthers = selection.defaultOthers})
            end)
        end
        connect(avatar.resetButton.Activated, function()
            avatar.apply({mode = "original", account = selection.account, everyone = selection.everyone})
        end)
        connect(avatar.scopeButton.Activated, function()
            selection.everyone = not selection.everyone
            nextRosterCheck = 0
            refreshScopeControls()
        end)
        connect(avatar.defaultOthersButton.Activated, function()
            selection.defaultOthers = not selection.defaultOthers
            nextRosterCheck = 0
            if selection.defaultOthers then
                for key, template in pairs(templates) do
                    if template.mode == "default" and template.failed then templates[key] = nil end
                end
                for _, target in pairs(targets) do
                    if target.mode == "default" then target.failed = nil end
                end
            elseif selection.mode == "original" then
                avatar.suspend()
                avatar.status.Text = "Original avatar."
            end
            refreshScopeControls()
        end)
    end

    local function visualPart(part)
        part.Anchored, part.CanCollide, part.CanTouch, part.CanQuery = true, false, false, false
        part.CastShadow = false
    end

    local function getSkeletonOutfitId(bundleId)
        if skeletonOutfitId[bundleId] then return skeletonOutfitId[bundleId] end
        local bundle = game:GetService("AssetService"):GetBundleDetailsAsync(bundleId)
        for _, item in ipairs(bundle.Items) do
            if item.Type == "UserOutfit" and type(item.Id) == "number" and item.Id > 0 then
                skeletonOutfitId[bundleId] = item.Id
                return item.Id
            end
        end
        error("The Roblox bundle has no outfit")
    end

    -- A character built from blocks. Every body part is an invisible unit cube; the blocks hang off
    -- them with sizes and offsets given as fractions of that body part, which fitModel then scales
    -- to the real body. The face is a grid of 8 x 8 squares on the front of a cube head.
    function avatar.blockModel(kind, rigType)
        local model = Instance.new("Model")
        local full = rigType == Enum.HumanoidRigType.R15
        local wide = full and 1 or 0.5
        local function block(anchor, hex, sx, sy, sz, ox, oy, oz)
            if anchor.Name == "Head" then sx, ox = sx * wide, (ox or 0) * wide end
            local part = Instance.new("Part")
            part.Name = "Block"
            part.Size = Vector3.new(sx, sy, sz)
            part.Color = Color3.fromHex(hex)
            part.Material = Enum.Material.SmoothPlastic
            part.TopSurface, part.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
            part.Anchored = true
            part:SetAttribute("WizardScaled", true)
            local weld = Instance.new("Weld")
            weld.Name = "AccessoryWeld"
            weld.Part0, weld.Part1 = part, anchor
            weld.C1 = CFrame.new(ox or 0, oy or 0, oz or 0)
            weld.Parent = part
            part.Parent = model
        end
        local side, lift = 1.55, 0.275
        local function face(anchor, hex, column, row, w, h, raise)
            local cell = side / 8
            block(anchor, hex, w * cell, h * cell, 0.03, (column + w / 2 - 4) * cell, (4 - row - h / 2) * cell + lift,
                -(side / 2 + 0.012 + (raise or 0)))
        end
        local looks = {
            zombie = {
                head = function(part)
                    block(part, "58914A", side, side, side, 0, lift, 0)
                    face(part, "44753A", 0, 0, 8, 2)
                    face(part, "44753A", 0, 2, 1, 1)
                    face(part, "44753A", 7, 2, 1, 1)
                    face(part, "151A14", 1, 4, 2, 1)
                    face(part, "151A14", 5, 4, 2, 1)
                    face(part, "3A6431", 3, 5, 2, 1)
                    face(part, "2C4D26", 2, 6, 4, 1)
                end,
                chest = function(part) block(part, "12A5A5", 1, 1, 1) end,
                hips = function(part) block(part, "4038A0", 1.07, 1, 1.16) end,
                upperArm = function(part) block(part, "12A5A5", 1.3, 1, 1) end,
