        assert(rangeCount==1,"Native coordinate range unavailable or ambiguous")
        local body = assert(controller.Controllers.Player.Character, "Waiting for a character")
        local gate = shared.WizardHubShootGate
        assert(type(gate) == "table" and type(gate.sender) == "table"
            and rawget(gate.sender, "Fire") == gate.filter, "Waiting for the native shoot gate")
        local character, root = findCharacter()
        local proxy = body.ProxyCharacter
        assert(character and root and body.data.model == character and typeof(proxy) == "Instance"
            and proxy:IsA("BasePart") and proxy.Parent, "Waiting for the current proxy")
        local lib, config = controller.Shared.Replication.Buffer, controller.Shared.Replication.ReplicationConfig
        local codec = lib.RangedFloat16
        assert(lib.Float64.Size == 8 and codec.Size == 2 and lib.Int8.Size == 1 and lib.UInt8.Size == 1
            and lib.Int16.Size == 2, "Native packet primitive widths changed")
        local write = rawget(codec, "Write")
        local module = game:GetService("ReplicatedStorage").Aero.Shared.Replication.Buffer
        assert(type(write) == "function" and not table.isfrozen(codec)
            and debug.info(write, "s") == module:GetFullName(), "Native position writer has changed")
        local jump = controller.Services.InputService.Jump
        assert(type(jump) == "table" and type(rawget(jump, "Fire")) == "function" and not table.isfrozen(jump),
            "Native jump sender unavailable")
        local id, scale, epoch = character:GetAttribute("ReplicationId"), config.Character.SPEED_SCALE, config.Network.SERVER_START_TIME
        assert(finite(id) and id % 1 == 0 and id >= 0 and id <= feature.build.maxId, "Invalid replication identity")
        assert(finite(scale) and scale > 0 and finite(epoch), "Native replication configuration unavailable")
