        assert(remote and (remote:IsA("RemoteEvent") or remote:IsA("UnreliableRemoteEvent")), "Replication remote unavailable")
        local candidate = {controller = controller, body = body, character = character, root = root, proxy = proxy,
            lib = lib, codec = codec, write = write, jump = jump, jumpFire = rawget(jump, "Fire"),
            int8=lib.Int8,int8Write=rawget(lib.Int8,"Write"),bufferSource=module:GetFullName(),
            clockCodec=lib.Float64,clockWrite=rawget(lib.Float64,"Write"),nativeHeartbeat=nativeHeartbeat,
