    local function chooseBounds(position,normalOnly)
        local assets = workspace:FindFirstChild("Assets")
        local bounds = assets and assets:FindFirstChild("CourtBounds")
        if not bounds then return nil, nil, "Court bounds are unavailable." end
        for _, part in ipairs(bounds:GetChildren()) do
            if part:IsA("BasePart") and part.CFrame.UpVector:Dot(Vector3.yAxis) > .9999 and inBounds(part, position, 0) then
                local y = normalOnly and position.Y or part.Position.Y + part.Size.Y / 2 - feature.margin - .1
                local target = Vector3.new(position.X, y, position.Z)
                if finite(y) and inBounds(part, target, normalOnly and 0 or feature.margin, feature.edgeMargin) then return part, y end
            end
        end
        return nil, nil, "No validated position inside this court."
    end
    function feature.filter(data, send, now)
        if type(data) ~= "table" or type(data.Shoot) ~= "boolean" then return false end
        if peer and peer.clockState and peer.clockState.phase=="drain" then
            if data.Shoot==false then blocked=false end
            feature.message="Native shot unchanged while the previous clock offset drains."
            trace("v2_skipped",{reason="clock cleanup pending"});return false
        end
        if data.Shoot == false then
            if blocked then blocked = false; return true end
            if burst and not burst.sent then cancelPending("Shot cancelled before acknowledgement."); return true end
            if burst and burst.sent then feature.markRelease() end
            return false
        end
        if not feature.enabled or not supported() or (gameplaySafety and not gameplaySafety.ready) then return false end
        local clockOnly=feature.variant=="v3" and feature.v3ReturnAt=="clock"
        if now<retryUntil then return false end
        if now<correctionUntil then
            feature.message="Native shot unchanged while server movement settles."
            trace("v2_skipped",{reason="server reposition cooldown"});return false
        end
        feature.useAvoidance=false
        if data.Input ~= nil and data.Input ~= "E" and data.Input ~= "EE" then return false end
        if blocked then return true end
        if burst then return not burst.sent end
        if peer and peer.clockState then
            feature.message="Native shot unchanged while the previous clock offset drains."
            trace("v2_skipped",{reason="clock cleanup pending"});return false
        end
        local character = findCharacter()
        if not character or not heldBall(character) then return false end
        if forcedFrame(character) or ((clockOnly or feature.options.protectContact) and contact(character)) then
            feature.message="Contact/fall state: V2 paused to preserve the ball."
            trace("v2_skipped",{reason="contact",action=character:GetAttribute("Action")})
            return false
        end
        local kind=classify(peer,data)
        if clockOnly then
            local goal=characterGoal(character)
            if (kind~="standing" and kind~="moving") or not goal or not goal:IsA("BasePart") then
                feature.message="Jump-shot clock experiment skips finishes; native shot unchanged."
                trace("v2_skipped",{reason="clock jump shots only",context=kind});return false
            end
        end
        if not feature.options[kind] then
            feature.message="V2 is disabled for "..kind.." shots."
            trace("v2_skipped",{reason="shot type disabled",context=kind})
            return false
        end
        local action = tostring(character:GetAttribute("Action") or ""):lower()
        if action:find("shoot", 1, true) or action:find("dunk", 1, true)
            or action:find("layup", 1, true) or action:find("clutch", 1, true) then return false end
        local function reject(message)
            blocked = true
            if data.UseSpace then blockedJumpUntil = os.clock() + .15 end
            feature.message = message .. " Release the shot button and try again."
            if feature.cancelTracked then pcall(feature.cancelTracked, character, now) end
            return true
        end
        if stopped or traveling or not robloxFocused() or gui.Enabled or input:GetFocusedTextBox() or capturing then
            return reject("V2 is paused.")
        end
        if peer and (peer.reconnectPending or rawget(peer.codec,"Write")~=peer.wrapper
            or rawget(peer.jump,"Fire")~=peer.jumpWrapper
            or rawget(peer.clockCodec,"Write")~=peer.clockWrite or peer.clockHooked) then
            -- A native packet can finish the drain before watch reinstalls the
            -- ordinary shot/Jump hooks. Forward this input without arming a trial.
            peer.reconnectPending=true
            feature.available=false
            nextResolve=0
            feature.message="Native shot unchanged while shot and Jump hooks reconnect."
            trace("v2_skipped",{reason="core hooks reconnecting"});return false
        end
        if peer and current(peer) and not peer.protocolReady then
            feature.message="Native shot unchanged while PB replication is verified."
            trace("v2_skipped",{reason="native protocol validation"});return false
        end
        if not peer or not feature.available or not current(peer) then return reject("Waiting for the native shot connection.") end
        if clockOnly then
            local eligible,currentKind,reason=clockEligibility(peer,{clockOnly=true,character=character})
            if not eligible then
                feature.message="Native shot unchanged: "..reason.."."
                trace("v2_skipped",{reason=reason,context=currentKind});return false
            end
            kind=currentKind
        end
