        if not vectorFinite(position) then return reject("Native position is invalid.") end
        local bounds, y, problem = chooseBounds(position,clockOnly)
        if not bounds and problem=="Court bounds are unavailable." then
            feature.message="Native shot unchanged: this PB area has no court bounds."
            trace("v2_skipped",{reason="court bounds unavailable"});return false
        end
        if not bounds or math.abs(y) >= peer.range then return reject(problem or "Position is outside the packet range.") end
        feature.useAvoidance=false
        local late=feature.variant=="v3" and feature.v3ReturnAt=="release" or feature.variant~="v3" and (kind~="standing" and feature.method=="late")
        burst = {began = now, deadline = now + .5, expires = now + 3, bounds = bounds, targetY = y,kind=kind,
            data = table.clone(data), send = send, character = character, useSpace = data.UseSpace == true,
            packets = 0, meters = 0, sent = late,late=late,networkActive=not late,variant=feature.variant,wasShifted=false,returnPoint=feature.v3ReturnAt,meterSerialAtStart=lastMeterSerial}
        if clockOnly then
            burst.clockOnly,burst.clockCourt=true,clockCourtIdentity(character)
            burst.targetY=position.Y
            burst.clockReports={}
            peer.clockState={phase="active",attempt=burst,court=burst.clockCourt,serial=0,epoch=peer.epoch,
                id=peer.id,actor=character,skew=CLOCK_SKEW}
            local installed,problem=pcall(installClockWriter,peer)
            if not installed then feature.fail(problem);return true end
            local active=burst
            local ok,stamp,issuedPosition=pcall(sendPosition,peer,nil,active)
            if not ok then feature.fail(stamp);return true end
            if burst~=active then return true end
            active.clockReported=true
            active.stamp,active.position=stamp,issuedPosition
