            trace("v2_native_start",{state=feature.liveState()})
            return false
        end
        local ok, stamp, issuedPosition = pcall(sendPosition, peer, y)
        if not ok then feature.fail(stamp); return true end
        burst.wasShifted=true
        burst.stamp = stamp
        burst.position = issuedPosition
        trace("v2_shot_pending",{state=feature.liveState()})
        feature.message = "Waiting for the server acknowledgement; release to cancel."
        return true
    end
    function feature.prepareRelease(now,releaseAt)
        local attempt=burst
        if not attempt or not attempt.late or attempt.networkActive or attempt.releasedAt or attempt.restoreIssuedAt or attempt.meters==0 or not feature.enabled
            or not peer or not current(peer) or not finite(releaseAt) or stopped or traveling or not robloxFocused() then return end
        if forcedFrame(attempt.character) or (feature.options.protectContact and contact(attempt.character)) then
            endBurst("Contact/fall state: late shift cancelled.",nil,forcedFrame(attempt.character));return
        end
        local lead=(feature.lead and feature.lead.value or 120)/1000
        local remaining=releaseAt-now
        if remaining>lead or remaining<.015 then return end
        local position=peer.proxy.Position
        if not vectorFinite(position) or not inBounds(attempt.bounds,Vector3.new(position.X,attempt.targetY,position.Z),feature.margin,feature.edgeMargin) then
            endBurst("Late shift skipped outside the validated court area.");return
        end
        attempt.networkActive,attempt.awaitingAck=true,true
        attempt.deadline=now+.5
        attempt.plannedReleaseAt=releaseAt
        local ok,stamp,issued=pcall(sendPosition,peer,attempt.targetY)
        if not ok then feature.fail(stamp);return end
        if burst~=attempt then return end
        attempt.wasShifted=true
        attempt.stamp,attempt.position=stamp,issued
        trace("v2_late_shift",{remainingMs=remaining*1000,state=feature.liveState()})
        feature.message="Late shift sent; native release timing is unchanged."
    end
    function feature.markRelease()
        if not burst or not burst.sent or burst.releasedAt then return end
        burst.releasedAt=os.clock()
        trace("v2_native_release",{state=feature.liveState()})
        if burst.late and not burst.networkActive then endBurst("Native release: no late-shift plan was available.") end
    end
    function feature.restoreNativeHeight(expected,phase)
        local attempt,candidate=burst,peer
        if not attempt or (expected and expected~=attempt) or attempt.variant~="v3" or attempt.restoreIssuedAt
            or attempt.clockOnly or not attempt.sent or not attempt.networkActive or not feature.enabled or not candidate or not current(candidate) then return end
        if phase=="start" and not (attempt.startForwardedAt and attempt.startMeterAt) then return end
        if phase=="start" and attempt.startMeterDeadline and os.clock()>=attempt.startMeterDeadline then
            endBurst("V3 server shot-start response arrived too late; native height resumed.");return
        end
        if phase=="release" and not attempt.releaseForwardedAt then return end
        if stopped or traveling or forcedFrame(attempt.character) or (feature.options.protectContact and contact(attempt.character)) then
            cancelPending("V3 yielded to native movement before returning height.",true);return
        end
        if phase=="release" and not attempt.releasedAt then
            attempt.releasedAt=attempt.releaseForwardedAt
            trace("v2_native_release",{state=feature.liveState()})
        end
        -- Stop rewriting before publishing the real position. Native updates that
        -- follow this call must never reassert the elevated height.
        attempt.networkActive,attempt.awaitingAck=false,false
        local ok,stamp,position=pcall(sendPosition,candidate,nil)
        if not ok then feature.fail("V3 normal-height return failed: "..tostring(stamp));return end
        if burst~=attempt or peer~=candidate then return end
        attempt.restoreIssuedAt,attempt.restoreStamp,attempt.restorePosition=os.clock(),stamp,position
        attempt.restorePhase=phase
        attempt.awaitingRestore,attempt.restoreDeadline=true,os.clock()+.5
        trace("v2_restore_sent",{position=position,state=feature.liveState()})
        feature.message="V3 normal height sent after "..phase.."; checking server acknowledgement."
    end
    function feature.afterRelease(expected)
        local attempt=burst
        if not attempt or(expected and expected~=attempt)or attempt.variant~="v3"then return end
        attempt.releaseForwardedAt=attempt.releaseForwardedAt or os.clock()
        if attempt.clockOnly then
            trace("v2_clock_release_forwarded",{state=feature.liveState()})
            return
        end
        if attempt.returnPoint~="start"then feature.restoreNativeHeight(attempt,"release")
        elseif not attempt.restoreIssuedAt then
            endBurst("V3 start response did not arrive before release; native height resumed without trial credit.")
        end
    end
    function feature.forwardRelease(send,...)
        local expected=burst
        local result=table.pack(pcall(send,...))
        if not result[1] then
            if expected and expected.variant=="v3" and burst==expected then feature.fail("Native shot release failed") end
            error(result[2],0)
        end
        if expected and burst==expected then
            local ok,problem=pcall(feature.afterRelease,expected)
            if not ok then feature.fail(problem) end
        end
        return table.unpack(result,2,result.n)
    end
    function feature.meter(meterType,serial)
        local fresh=finite(serial) and serial%1==0 and serial>lastMeterSerial
        if fresh then lastMeterSerial=serial end
        if burst and burst.sent and peer and current(peer) then
            burst.meters += 1
            if burst.clockOnly and fresh and serial>burst.meterSerialAtStart
                and type(meterType)=="string" and meterType~="" and meterType~="None" then
                burst.clockMeterAt=burst.clockMeterAt or os.clock()
                burst.clockMeterSerial,burst.clockMeterType=serial,meterType
            end
            if burst.variant=="v3" and burst.returnPoint=="start" and not burst.restoreIssuedAt
                and fresh and serial>burst.meterSerialAtStart and type(meterType)=="string" and meterType~="" and meterType~="None" then
                burst.startMeterAt=burst.startMeterAt or os.clock()
                burst.startMeterSerial,burst.startMeterType=serial,meterType
            end
            trace("v2_meter",{state=feature.liveState()})
            if burst.variant=="v3" and burst.returnPoint=="start" and burst.startForwardedAt then
                feature.restoreNativeHeight(burst,"start")
            end
        end
    end
    function feature.feedback(value)
        if not burst or not burst.sent or burst.meters == 0 or not peer or not current(peer) then return end
        if not finite(value) or value < 0 or value > 100 then feature.fail("invalid contest feedback"); return end
        local key=resultKey(burst.variant,burst.returnPoint)
        feature.lastActual=value
        feature.results[key].lastActual=value
        if forcedFrame(burst.character) or ((burst.clockOnly or feature.options.protectContact) and contact(burst.character)) then
            endBurst(string.format("Actual contest %.2f%%; contact/forced movement excluded this attempt from trial credit.",value),value,forcedFrame(burst.character));return
        end
        if burst.clockOnly then
            local eligible,kind,reason=clockEligibility(peer,burst)
            if not eligible then
                endBurst(string.format("Actual contest %.2f%%; clock trial excluded because %s.",value,reason),value);return
            end
            burst.kind=kind
            if not (burst.clockReported and burst.clockAckAt and burst.startForwardedAt and burst.clockMeterAt
                and burst.releaseForwardedAt and burst.releasedAt and burst.networkActive and not burst.restoreIssuedAt
                and peer.clockHooked and peer.clockState and peer.clockState.phase=="active" and peer.clockState.attempt==burst
                and finite(burst.echoedClockStamp) and finite(burst.clockAckReportStamp)
                and math.abs(burst.echoedClockStamp-burst.clockAckReportStamp)<=.00011
                and burst.clockAckReportStamp>=burst.clockIssuedStamp-.00011
                and burst.clockAckAt<=burst.startForwardedAt and burst.startForwardedAt<=burst.releaseForwardedAt) then
                endBurst(string.format("V3 actual contest %.2f%%; the clock-only start/release trial was not verified.",value),value);return
            end
        elseif not burst.wasShifted then endBurst("Native shot rated without a contest position change.");return
        elseif burst.variant=="v3" and not (burst.elevatedAckAt and burst.restoreIssuedAt and burst.restoreAckAt and burst.releaseForwardedAt
            and (burst.returnPoint~="start" or (burst.startMeterAt and burst.restoreAckAt<=burst.releaseForwardedAt))) then
            feature.lastActual=value
            feature.results[key].lastActual=value
            endBurst(string.format("V3 actual contest %.2f%%; normal-height return was not verified.",value),value);return
        end
        local result=feature.results[key]
        result.lastActual,result.completed=value,result.completed+1
        feature.lastActual,feature.completed=value,result.completed
        endBurst(string.format("Last game result: %.2f%% contest.", value), value)
        if value > 0 then trace("v2_nonzero_result",{contest=value,enabled=feature.enabled}) end
    end
    function feature.capture() return {enabled = feature.enabled,variant=feature.variant,v3ReturnAt=feature.v3ReturnAt,options=table.clone(feature.options),method=feature.method,
        releaseLead=feature.lead and feature.lead.value or 120} end
    function feature.liveState()
        local attempt=burst and {began=burst.began,deadline=burst.deadline,expires=burst.expires,stamp=burst.stamp,
