            position=burst.position,data=table.clone(burst.data),jumpQueued=burst.jump~=nil,context=burst.kind,
            late=burst.late,networkActive=burst.networkActive,awaitingAck=burst.awaitingAck,releasedAt=burst.releasedAt,
            plannedReleaseAt=burst.plannedReleaseAt,variant=burst.variant,wasShifted=burst.wasShifted,elevatedAckAt=burst.elevatedAckAt,
            releaseForwardedAt=burst.releaseForwardedAt,restoreIssuedAt=burst.restoreIssuedAt,restoreAckAt=burst.restoreAckAt,
            restoreStamp=burst.restoreStamp,restorePosition=burst.restorePosition,awaitingRestore=burst.awaitingRestore,
            returnPoint=burst.returnPoint,restorePhase=burst.restorePhase,startForwardedAt=burst.startForwardedAt,
            clockOnly=burst.clockOnly,clockReported=burst.clockReported,reportRawclock=burst.reportRawclock,
            clockAckAt=burst.clockAckAt,echoedClockStamp=burst.echoedClockStamp,clockAckReportStamp=burst.clockAckReportStamp,
            clockAckReportPosition=burst.clockAckReportPosition,clockReportCount=burst.clockReports and #burst.clockReports,
            clockIssuedAt=burst.clockIssuedAt,clockIssuedStamp=burst.clockIssuedStamp,clockLastNativeStamp=burst.clockLastNativeStamp,
            clockEligibilityLost=burst.clockEligibilityLost,clockEligibilityReason=burst.clockEligibilityReason,
            clockInterruptedReason=burst.clockInterruptedReason,
            clockMeterAt=burst.clockMeterAt,clockMeterSerial=burst.clockMeterSerial,clockMeterType=burst.clockMeterType,
            clockCourt=burst.clockCourt,jumpForwardedAt=burst.jumpForwardedAt,
            startMeterAt=burst.startMeterAt,startMeterDeadline=burst.startMeterDeadline,
            startMeterSerial=burst.startMeterSerial,startMeterType=burst.startMeterType,meterSerialAtStart=burst.meterSerialAtStart} or nil
        local state=peer and peer.clockState
        local clockDrain=state and {phase=state.phase,began=state.drainBegan,deadline=state.drainDeadline,
            skew=clockOffset(state,os.clock()),lastReportedStamp=state.lastReported,lastNativeStamp=state.lastNativeStamp,
            clockCourt=state.court,hooked=peer.clockHooked}
        return {enabled=feature.enabled,available=feature.available,message=feature.message,lastActual=feature.lastActual,attempt=attempt,clockDrain=clockDrain,
            variant=feature.variant,v3ReturnAt=feature.v3ReturnAt,options=table.clone(feature.options),method=feature.method,recovering=feature.enabled and os.clock()<retryUntil}
    end
    function feature.apply(saved)
        feature.stop("Anti Contest v2 is off.")
        retryUntil=0
        feature.enabled = type(saved) == "table" and saved.enabled == true and saved.variant ~= "v3"
        feature.variant = "v2"
        feature.v3ReturnAt=returnPoint(type(saved)=="table" and saved.v3ReturnAt)
        local result=feature.results[resultKey(feature.variant,feature.v3ReturnAt)]
        feature.lastActual,feature.completed=result.lastActual,result.completed
        local options=type(saved)=="table" and type(saved.options)=="table" and saved.options or {}
        for _,key in ipairs({"standing","moving","finishes","protectContact"}) do feature.options[key]=options[key]==nil or options[key]==true end
        feature.method=type(saved)=="table" and saved.method=="full" and "full" or "late"
        if feature.lead then
            local lead=type(saved)=="table" and saved.releaseLead
            showSlider(feature.lead,finite(lead) and math.clamp(lead,40,300) or 120)
        end
        if feature.enabled then
            feature.message = "Waiting for native Blacktop or Park connections."
        end
        nextResolve = 0
        if feature.enabled then pcall(feature.watch, os.clock()) end
        if feature.redraw then feature.redraw() else feature.refresh() end
    end
    function feature.refresh()
        showSwitch(feature.toggle, feature.enabled and feature.variant~="v3")
        if feature.optionSwitches then for key,item in pairs(feature.optionSwitches) do showSwitch(item,feature.options[key]) end end
        if feature.methodButton then feature.methodButton.Text=feature.method=="late" and "Moving/finish method: late shift" or "Moving/finish method: full shift" end
    end
    function feature.bind(connectControl, redraw)
        feature.redraw = redraw
        connectControl(feature.toggle.row.Activated, function()
            local saved=feature.capture();saved.enabled=not(feature.enabled and feature.variant=="v2");saved.variant="v2";feature.apply(saved)
            redraw()
        end)
        if feature.optionSwitches then for key,item in pairs(feature.optionSwitches) do
            connectControl(item.row.Activated,function()
                local saved=feature.capture();saved.options[key]=not saved.options[key];feature.apply(saved);redraw()
            end)
        end end
        if feature.methodButton then connectControl(feature.methodButton.Activated,function()
            local saved=feature.capture();saved.method=feature.method=="late" and "full" or "late";feature.apply(saved);redraw()
        end) end
    end
    function feature.diagnostics()
        local copy = {}
        for index, row in ipairs(history) do copy[index] = table.clone(row) end
        return {version = feature.variant=="v3" and 3 or 2,variant=feature.variant,v3ReturnAt=feature.v3ReturnAt,enabled = feature.enabled, available = feature.available == true,
            shotAvoidance=feature.useAvoidance,
            message = feature.message, completed = feature.completed, cancelled = feature.cancelled,
            lastActual = feature.lastActual, active = burst ~= nil, pending = burst ~= nil and not burst.sent,
            recovering=feature.enabled and os.clock()<retryUntil,retryAt=retryUntil>os.clock() and retryUntil or nil,
            options=table.clone(feature.options),method=feature.method,
            compatibility={identity=supported(),verified=peer~=nil and peer.protocolReady==true,range=peer and peer.range,
                reason=peer and peer.protocolError,policy="PB universe and native interfaces; no place-version list"},
            jobPrefix = game.JobId:sub(1, 8), placeId = game.PlaceId, placeVersion = game.PlaceVersion, history = copy}
    end
    function feature.watch(now)
        if peer and peer.clockState and peer.clockState.phase=="drain" then watchClockDrain(peer,now) end
        if not feature.enabled then
            if peer or burst then feature.stop("Anti Contest v2 is off.") end
        elseif not supported() then
            if peer or burst then feature.stop("Waiting for Practical Basketball.") end
            feature.message = "Waiting for Practical Basketball."
        elseif type(getconnections) ~= "function" or type(getupvalues) ~= "function" then
            feature.message = "Native replication inspection is unavailable in this executor."
        elseif stopped or traveling or not robloxFocused() then
            if burst then cancelPending("V2 paused while gameplay is inactive.") end
        elseif gameplaySafety and not gameplaySafety.ready then
            if burst then cancelPending("V2 paused while match entry settles.") end
        elseif now<retryUntil then
            -- Keep the selected toggle while native handling runs during recovery.
        else
            local draining=peer and peer.clockState and peer.clockState.phase=="drain" and peer.clockState.trialHooksReleased
            if peer and (peer.reconnectPending or not current(peer) or rawget(peer.codec, "Write") ~= (draining and peer.write or peer.wrapper)
                or rawget(peer.jump, "Fire") ~= (draining and peer.jumpFire or peer.jumpWrapper)) then detach("Reconnecting after a native state change.") end
            if not peer and now >= nextResolve then
                nextResolve = now + .5
                local ok, problem = pcall(resolve)
                if not ok then detach(tostring(problem))
                else feature.message = "Checking native PB replication for build "..tostring(game.PlaceVersion).."." end
            end
            if peer and not peer.protocolReady then
                feature.message=peer.protocolError and ("Native replication is incompatible: "..peer.protocolError)
                    or "Waiting for a valid native PB player record."
            end
            if burst then
                local eligible,kind,reason=clockEligibility(peer,burst)
                if eligible then burst.kind=kind end
                if forcedFrame(burst.character) or ((burst.clockOnly or feature.options.protectContact) and contact(burst.character)) then
                    local forced=forcedFrame(burst.character)
                    if burst.sent then endBurst("Contact/fall detected; native position handling resumed.",nil,forced)
                    else blocked=true;cancelPending("Contact/fall detected before acknowledgement.",forced) end
                elseif burst.clockOnly and not eligible then
                    if burst.sent then endBurst("Clock experiment ended: "..reason..".")
                    else blocked=true;cancelPending("Clock experiment cancelled before acknowledgement: "..reason..".") end
                elseif burst.awaitingRestore and now>=burst.restoreDeadline then
                    endBurst("V3 normal-height acknowledgement timed out; native shot was not replayed.")
                elseif burst.startMeterDeadline and not burst.restoreIssuedAt and now>=burst.startMeterDeadline then
                    endBurst("V3 server shot-start response timed out; native height resumed without replay.")
                elseif burst.awaitingAck and now>=burst.deadline then
                    endBurst("Late shift was not acknowledged; native position restored.")
                elseif not burst.sent and now >= burst.deadline then
                    blocked = true; cancelPending(burst.clockOnly and "No exact clock acknowledgement; shot cancelled."
                        or "No position acknowledgement; shot cancelled.")
                elseif burst.releasedAt and now-burst.releasedAt>.8 then
                    endBurst("No matching feedback after release; native position restored.")
                elseif now >= burst.expires then
                    endBurst("No matching shot result before timeout.")
                elseif gui.Enabled or input:GetFocusedTextBox() or capturing then cancelPending("V2 paused while the menu is active.") end
            end
        end
        if now >= nextDisplay then
            nextDisplay = now + .1
            feature.status.Text = string.format("%s\nLast server contest: %s  |  Rated shots: %d  |  Cancelled: %d",
                feature.message, feature.lastActual ~= nil and string.format("%.2f%%", feature.lastActual) or "--",
                feature.completed, feature.cancelled)
        end
        if dirty and not burst and storageAvailable and now >= nextFlush then
            nextFlush = now + 1
            local ok = pcall(function()
                writefile("GymRelease/anti-contest-v2.json", http:JSONEncode({version = 2, placeId = game.PlaceId,
                    placeVersion = game.PlaceVersion, completed = feature.completed, history = history}))
            end)
            if ok then dirty = false end
        end
    end
end
antiContestV2.initialise()

function gameplaySafety.initialise()
    local controller,body,character,root,seenAt,clearAt,finished,entryKey
    local nextResolve,correctionConnection=0,nil
    gameplaySafety.ready=false
    local function finishAction(model)
        local action=tostring(model and model:GetAttribute("Action") or ""):lower()
        return action:find("shoot",1,true) or action:find("dunk",1,true) or action:find("layup",1,true)
            or action:find("clutch",1,true) or action:find("gather",1,true) or action:find("block",1,true)
    end
    local function insideCourt(position)
        local assets=workspace:FindFirstChild("Assets")
        local bounds=assets and assets:FindFirstChild("CourtBounds")
        if not bounds then return false end
        for _,part in ipairs(bounds:GetChildren()) do if part:IsA("BasePart") then
            local p,h=part.CFrame:PointToObjectSpace(position),part.Size/2
            if math.abs(p.X)<=h.X and math.abs(p.Y)<=h.Y and math.abs(p.Z)<=h.Z then return true end
        end end
        return false
    end
    function gameplaySafety.stop()
        if correctionConnection then correctionConnection:Disconnect();correctionConnection=nil end
        controller,body,character,root,seenAt,clearAt,finished,entryKey=nil,nil,nil,nil,nil,nil,nil,nil
        gameplaySafety.ready=false
    end
    function gameplaySafety.actor() return body,character,root end
    function gameplaySafety.physics()
        if not antiContestV2.isSupported() then return end
        if stopped or traveling or not body or not character or not character.Parent or not seenAt
            or finished or os.clock()-seenAt>30 or finishAction(character) then return end
        local proxy=body.ProxyCharacter
        local hold=body.MainMovementPosition
        if not proxy or not proxy.Parent or proxy.Anchored or body:GetAttribute("CanMove")~=false
            or not hold or not hold.Parent or not hold:IsA("BodyPosition") then return end
        local force=hold.MaxForce
        if force.X<=0 and force.Z<=0 then return end
        local target=hold.Position
        local destination=Vector3.new(force.X>0 and target.X or proxy.Position.X,proxy.Position.Y,force.Z>0 and target.Z or proxy.Position.Z)
        if not insideCourt(destination) then return end
        local gap=(destination-proxy.Position).Magnitude
        if gap>.02 then proxy.CFrame+=destination-proxy.Position end
        local velocity=proxy.AssemblyLinearVelocity
        proxy.AssemblyLinearVelocity=Vector3.new(force.X>0 and 0 or velocity.X,velocity.Y,force.Z>0 and 0 or velocity.Z)
        proxy.AssemblyAngularVelocity=Vector3.zero
        local recorder=antiContestV2.recorder
        if gap>1 and recorder then recorder.emit("entry_lock_settled",{gap=gap,target=destination,source="Native BodyPosition",canMove=false}) end
    end
    function gameplaySafety.watch(now)
        if traveling or stopped then gameplaySafety.ready=false;return end
        if not antiContestV2.isSupported() then gameplaySafety.ready=true;return end
        local assets=workspace:FindFirstChild("Assets")
        if not assets or not assets:FindFirstChild("CourtBounds") then
            gameplaySafety.stop();gameplaySafety.ready=true;return
        end
        if now>=nextResolve then
            nextResolve=now+.5
            local module=player.PlayerScripts.Aero.Controllers:FindFirstChild("Replication")
            if module and type(getconnections)=="function" and type(getupvalues)=="function" then
                for _,connection in ipairs(getconnections(run.Heartbeat)) do
                    local fn=connection.Function
                    if type(fn)=="function" and debug.info(fn,"s")==module:GetFullName() then
                        for _,value in pairs(getupvalues(fn)) do
                            if type(value)=="table" and type(rawget(value,"Packets"))=="table" and type(rawget(value,"CreatePacket"))=="function" then controller=value end
                        end
                    end
                end
            end
            local model,newRoot=findCharacter()
            local newBody=controller and controller.Controllers.Player.Character
            if not newBody or not newBody.data or newBody.data.model~=model then newBody=nil end
            local key=model and (tostring(model:GetAttribute("CourtNumber")).."|"..tostring(model:GetAttribute("Team"))
                .."|"..tostring(model:GetAttribute("InGame")).."|"..tostring(model:GetAttribute("OnCourt")).."|"..tostring(model:GetAttribute("ReplicationId")))
            if model~=character or newRoot~=root or newBody~=body or key~=entryKey then
                character,root,body=model,newRoot,newBody
                entryKey=key
                seenAt,clearAt,finished=now,nil,false
                gameplaySafety.ready=false
            end
            if not correctionConnection then
                local rs=game:GetService("ReplicatedStorage")
                local aero=rs:FindFirstChild("Aero")
                local services=aero and aero:FindFirstChild("AeroRemoteServices")
                local physics=services and services:FindFirstChild("PhysicsService")
                local remote=physics and physics:FindFirstChild("SetCFrame")
                if remote then correctionConnection=remote.OnClientEvent:Connect(function()
                    clearAt=nil
                    if not finished then gameplaySafety.ready=false;pcall(gameplaySafety.physics) end
                end) end
            end
        end
        if not body or not root or not root.Parent or not body.ProxyCharacter or not body.ProxyCharacter.Parent then gameplaySafety.ready=false;return end
        if finished then gameplaySafety.ready=true;return end
        local proxy=body.ProxyCharacter
        local ground=body.raycastResult
        local roaming=workspace:GetAttribute("Gamemode")=="Park" and body:GetAttribute("InGame")==false
            and body:GetAttribute("OnCourt")==false and ground and math.abs(proxy.Position.Y-ground.Position.Y)<8
        local valid=body:GetAttribute("CanMove")~=false and not proxy.Anchored and (insideCourt(proxy.Position) or roaming)
            and (proxy.Position-root.Position).Magnitude<2 and proxy.AssemblyLinearVelocity.Magnitude<60
        if valid then clearAt=clearAt or now else clearAt=nil end
        gameplaySafety.ready=clearAt~=nil and now-clearAt>=.6
        if gameplaySafety.ready then finished=true end
    end
end
gameplaySafety.initialise()
function rage.initialiseFly()
    local fly=rage.fly
    fly.method="vector-force"
    local state
    local function trace(kind,data)
        if antiContestV2.recorder then pcall(antiContestV2.recorder.emit,kind,data) end
    end
    local function finite(value) return type(value)=="number" and value==value and math.abs(value)<1e6 end
    local function court(position)
        local assets=workspace:FindFirstChild("Assets")
        local folder=assets and assets:FindFirstChild("CourtBounds")
        if not folder then return end
        for _,part in ipairs(folder:GetChildren()) do
            if part:IsA("BasePart") and part.CFrame.UpVector:Dot(Vector3.yAxis)>.9999 then
                local p,h=part.CFrame:PointToObjectSpace(position),part.Size/2
                if math.abs(p.X)<=h.X and math.abs(p.Y)<=h.Y and math.abs(p.Z)<=h.Z then return part end
            end
        end
    end
    function fly.stop(reason)
        local old=state;state=nil
        fly.active=false;gameplaySafety.flying=false;fly.desiredVelocity=nil
        if old then
            if old.step then pcall(old.step.Disconnect,old.step) end
            if old.correction then pcall(old.correction.Disconnect,old.correction) end
            if old.lift then pcall(old.lift.Destroy,old.lift) end
            if old.attachment then pcall(old.attachment.Destroy,old.attachment) end
            pcall(function()
                if old.hold.Parent and old.written and old.hold.MaxForce==old.written then
                    old.hold.MaxForce=old.holdBase
                end
            end)
            trace("fly_stopped",{reason=reason,method=fly.method})
        end
        fly.message=reason or "Fly is off."
    end
    function fly.close() fly.stop("Fly unloaded") end
    function fly.physics(dt)
        if not fly.enabled or not rage.enabled or stopped or traveling or not gameplaySafety.ready or not robloxFocused()
            or gui.Enabled or input:GetFocusedTextBox() then fly.stop("Fly paused");return end
        local body,character=gameplaySafety.actor()
        local proxy=body and body.ProxyCharacter
        local action=tostring(character and character:GetAttribute("Action") or ""):lower()
        if not body or not character or not character.Parent or not proxy or not proxy.Parent or proxy.Anchored
            or heldBall(character) or body:GetAttribute("CanMove")==false or body:GetAttribute("CFrame")~=nil
            or body:GetAttribute("SeatCFrame")~=nil or action:find("shoot",1,true) or action:find("dunk",1,true)
            or action:find("layup",1,true) or action:find("clutch",1,true) or action:find("fall",1,true)
            or action:find("contact",1,true) or action:find("stun",1,true) then
            fly.stop("Fly pauses for the ball, contact and native movement locks.");return
        end
        local hold,main=body.MovementPosition,body.MainMovementPosition
        local bounds=court(proxy.Position)
        if not bounds or not hold or not hold.Parent or not main or not main.Parent or main.MaxForce.Y>0 then
            fly.stop("Waiting for court clearance and native vertical movement.");return
        end
        if state and (state.body~=body or state.proxy~=proxy or state.hold~=hold or state.bounds~=bounds) then fly.stop("Fly character or court changed") end
        if not state then
            local mass=proxy.AssemblyMass
            if not finite(mass) or mass<=0 or not finite(workspace.Gravity) or workspace.Gravity<=0 then fly.stop("Native flight physics unavailable");return end
            local attachment=Instance.new("Attachment")
            local lift=Instance.new("VectorForce")
            state={body=body,character=character,proxy=proxy,hold=hold,main=main,bounds=bounds,lift=lift,
                attachment=attachment,holdBase=hold.MaxForce,began=os.clock()}
            attachment.Name="WizardFlyAttachment";attachment.Parent=proxy
            lift.Name="WizardFlyLift";lift.Attachment0=attachment
            lift.RelativeTo=Enum.ActuatorRelativeTo.World;lift.ApplyAtCenterOfMass=true
            lift.Force=Vector3.new(0,mass*workspace.Gravity,0);lift.Enabled=true;lift.Parent=proxy
            local s=state
            -- Register after this character's native ground step so the two vertical controls cannot fight.
            s.step=run.Stepped:Connect(function(_,stepDt)
                if state~=s then return end
                local ok,problem=pcall(fly.physics,stepDt)
                if not ok then fly.stop("Fly error: "..tostring(problem)) end
            end)
            local physics=body.Services and body.Services.PhysicsService
            local correction=physics and physics.SetCFrame
            if correction and type(correction.Connect)=="function" then
                s.correction=correction:Connect(function()
                    if state~=s then return end
                    fly.enabled=false
                    fly.stop("Server repositioned the character; flight ended.")
                    trace("fly_server_rejected",{method=fly.method,elapsed=os.clock()-s.began,action="disabled"})
                    if rage.refresh then pcall(rage.refresh) end
                end)
            end
            fly.active=true;gameplaySafety.flying=true
            trace("fly_started",{position=proxy.Position,method=fly.method,horizontal="native movement"})
        end
        local s=state
        if not s.lift.Parent then fly.stop("Flight force was removed");return end
        local force=hold.MaxForce
        if not s.written or force~=s.written then s.holdBase=force end
        s.written=Vector3.new(force.X,0,force.Z);hold.MaxForce=s.written
        local y=(executorInput.keyDown(Enum.KeyCode.R) and 1 or 0)-(executorInput.keyDown(Enum.KeyCode.LeftControl) and 1 or 0)
        local half=bounds.Size/2
        local localPosition=bounds.CFrame:PointToObjectSpace(proxy.Position)
        local top=half.Y-3
        local ground=body.lastValidHeight
        if not finite(ground) then fly.stop("Waiting for native ground height");return end
        local bottom=math.max(bounds.Position.Y-half.Y+3,ground)
        if bottom>bounds.Position.Y+top then fly.stop("Insufficient vertical clearance");return end
        local desired=y*6
        if desired>0 then desired=math.min(desired,math.max(0,top-localPosition.Y)*6)
        elseif desired<0 then desired=-math.min(-desired,math.max(0,proxy.Position.Y-bottom)*6) end
        local mass=proxy.AssemblyMass
        local acceleration=math.clamp((desired-proxy.AssemblyLinearVelocity.Y)*30,-90,90)
        s.lift.Force=Vector3.new(0,mass*(workspace.Gravity+acceleration),0)
        fly.desiredVelocity=Vector3.new(proxy.AssemblyLinearVelocity.X,desired,proxy.AssemblyLinearVelocity.Z)
        fly.message="Fly active · native WASD · R up · Ctrl down"
    end
end
rage.initialiseFly()

function rage.initialiseNoclip()
    local noclip=rage.noclip
    local state
    local names={"Update","WouldPastBarrier","WouldPastBarrierSingle"}
    local function trace(kind,data)
        if antiContestV2.recorder then pcall(antiContestV2.recorder.emit,kind,data) end
    end
    local function eligible()
        return noclip.enabled and not stopped and not traveling and gameplaySafety.ready
            and robloxFocused() and not input:GetFocusedTextBox()
    end
    local function owns(s,self)
        if state~=s or not noclip.active or self~=s.collision or not eligible() then return false end
        local body,character=gameplaySafety.actor()
        return body==s.body and character==s.character and character.Parent~=nil
            and body.ProxyCharacter==s.proxy and s.proxy.Parent~=nil and body.Collision==s.collision
    end
    function noclip.stop(reason)
        local old=state;state=nil;noclip.active=false
        if old then
            if old.added then old.added:Disconnect() end
            for _,hook in ipairs(old.hooks) do
                if rawget(old.collision,hook.name)==hook.wrapper then
                    pcall(rawset,old.collision,hook.name,hook.raw)
                end
            end
            for part,field in pairs(old.parts) do
                pcall(function()
                    if part.Parent and field.written and part.CanCollide==false then part.CanCollide=field.base end
                end)
            end
            trace("noclip_stopped",{reason=reason,parts=old.count})
        end
        noclip.message=reason or "Noclip is off."
    end
    local function partOwned(s,part)
        return part==s.proxy or part:IsDescendantOf(s.character)
    end
    local function track(s,part)
        if state~=s or not part:IsA("BasePart") or not partOwned(s,part) or s.parts[part] then return end
        local ball=heldBall(s.character)
        if ball and (part==ball or part:IsDescendantOf(ball)) then return end
        s.parts[part]={base=part.CanCollide,written=false};s.count+=1
    end
    local function moduleSource()
        local scripts=player:FindFirstChild("PlayerScripts")
        local aero=scripts and scripts:FindFirstChild("Aero")
        local modules=aero and aero:FindFirstChild("Modules")
        local components=modules and modules:FindFirstChild("Components")
        local character=components and components:FindFirstChild("Character")
        local collision=character and character:FindFirstChild("Collision")
        return collision and collision:GetFullName()
    end
    local function attach(body,character,proxy)
        local object=body.Collision
        local source=moduleSource()
        if not source or type(object)~="table" or object.State~=body or object.HumanoidRootPart~=proxy
            or (table.isfrozen and table.isfrozen(object)) then return false end
        local hooks={}
        for _,name in ipairs(names) do
            local original=object[name]
            if type(original)~="function" or debug.info(original,"s")~=source then return false end
            hooks[#hooks+1]={name=name,original=original,raw=rawget(object,name)}
        end
        local s={body=body,character=character,proxy=proxy,collision=object,hooks=hooks,parts={},count=0}
        state=s
        for _,hook in ipairs(hooks) do
            hook.wrapper=function(self,...)
                if owns(s,self) then
                    if hook.name~="Update" then return false end
                    return
                end
                return hook.original(self,...)
            end
            rawset(object,hook.name,hook.wrapper)
        end
        for _,part in ipairs(character:GetDescendants()) do track(s,part) end
        track(s,proxy)
        s.added=character.DescendantAdded:Connect(function(part)
            local ok,problem=pcall(track,s,part)
            if not ok then noclip.stop("Noclip paused: "..tostring(problem)) end
        end)
        noclip.active=true
        trace("noclip_started",{parts=s.count,collisionSource=source})
        return true
    end
    function noclip.watch()
        if not eligible() then noclip.stop(noclip.enabled and "Noclip waiting for focus and match entry." or "Noclip is off.");return end
        local body,character=gameplaySafety.actor()
        local proxy=body and body.ProxyCharacter
        if not body or not character or not character.Parent or not proxy or not proxy.Parent then
            noclip.stop("Waiting for a live basketball character.");return
        end
        if state and not owns(state,state.collision) then noclip.stop("Noclip character changed.") end
        if not state and not attach(body,character,proxy) then
            noclip.message="Noclip waiting for the supported native collision component.";return
        end
        local s=state
        for part,field in pairs(s.parts) do
            if not part.Parent or not partOwned(s,part) then
                if part.Parent and field.written and part.CanCollide==false then part.CanCollide=field.base end
                s.parts[part]=nil;s.count-=1
            elseif part.CanCollide~=false then
                field.base=part.CanCollide;part.CanCollide=false;field.written=true
            end
        end
        noclip.message="Noclip active · local parts, players and barriers"
    end
    function noclip.apply(enabled)
        noclip.stop("Noclip settings changed.")
        noclip.enabled=enabled==true
        showSwitch(noclip.toggle,noclip.enabled)
    end
    function noclip.diagnostics()
        return {enabled=noclip.enabled,active=noclip.active,message=noclip.message,
            parts=state and state.count or 0,nativeHooks=state and #state.hooks or 0}
    end
    function noclip.close()
        noclip.stop("Noclip unloaded.")
        if shared.WizardHubNoclip==noclip then shared.WizardHubNoclip=nil end
    end
    shared.WizardHubNoclip=noclip
end
rage.initialiseNoclip()

function rage.initialiseCourtTeleport()
    local feature=rage.courtTeleport
    local context,lastHop,nextHop,correction,pending=nil,nil,0,nil,nil
    local blockUntil=0
    local function finite(n) return type(n)=="number" and n==n and math.abs(n)<1e6 end
    local function flat(v) return Vector3.new(v.X,0,v.Z) end
    local function trace(kind,data)
        if antiContestV2.recorder then pcall(antiContestV2.recorder.emit,kind,data) end
    end
    local function message(text) feature.message=text;if feature.status then feature.status.Text=text end end
    local function inside(part,p,margin)
        local q,h=part.CFrame:PointToObjectSpace(p),part.Size/2
        return math.abs(q.X)<=h.X-margin and math.abs(q.Y)<=h.Y-2 and math.abs(q.Z)<=h.Z-margin
    end
    local function geometry()
        local body,character,root=gameplaySafety.actor()
        local proxy=body and body.ProxyCharacter
        if not body or not character or not root or not proxy or not proxy.Parent or not character.Parent then return nil,"Waiting for a live court character." end
        local goal=characterGoal(character)
        local util=body.Shared and body.Shared.Util and body.Shared.Util.GameUtil
        if not goal or not goal:IsA("BasePart") or not util or type(util.GetThreePointMagnitude)~="function" or type(util.CheckInsideArc)~="function" then
            return nil,"Waiting for the assigned hoop and native three-point boundary."
        end
        local assets=workspace:FindFirstChild("Assets")
        local folder=assets and assets:FindFirstChild("CourtBounds")
        local bounds
        for _,part in ipairs(folder and folder:GetChildren() or {}) do
            if part:IsA("BasePart") and part.CFrame.UpVector:Dot(Vector3.yAxis)>.9999 then
                local p,h=part.CFrame:PointToObjectSpace(proxy.Position),part.Size/2
                if math.abs(p.X)<=h.X and math.abs(p.Y)<=h.Y and math.abs(p.Z)<=h.Z then bounds=part;break end
            end
        end
        local ground=body.raycastResult
        local height=body.lastValidHeight
        if not bounds or not ground or not finite(height) then return nil,"Waiting for current court bounds and ground height." end
        local offset=height-ground.Position.Y
        if not finite(offset) or offset<.5 or offset>8 then return nil,"Native ground clearance is unavailable." end
        local forward=flat(bounds.Position-goal.Position)
        if forward.Magnitude<1 then return nil,"The assigned hoop has no valid court direction." end
        forward=forward.Unit
        local right=Vector3.new(-forward.Z,0,forward.X)
        local characters=workspace:FindFirstChild("Characters")
        local excluded={character,proxy}
        if characters then table.insert(excluded,characters) end
        local balls=workspace:FindFirstChild("Basketballs")
        if balls then table.insert(excluded,balls) end
        local ray=RaycastParams.new();ray.FilterType=Enum.RaycastFilterType.Exclude
        ray.FilterDescendantsInstances=excluded;ray.RespectCanCollide=true
        local overlap=OverlapParams.new();overlap.FilterType=Enum.RaycastFilterType.Exclude
        overlap.FilterDescendantsInstances=excluded;overlap.RespectCanCollide=true
        local arcMargin=math.max(1.5,root.Size.X/2+.5)
        local function candidate(side,lateral,extra)
            local direction=right*(side*lateral)+forward*math.sqrt(1-lateral*lateral)
            local ok,radius=pcall(util.GetThreePointMagnitude,util,goal,goal.Position+direction*100)
            if not ok or not finite(radius) or radius<5 or radius>150 then return end
            local p=goal.Position+direction*(radius+extra)
            p=Vector3.new(p.X,height,p.Z)
            if not inside(bounds,p,3) then return end
            local hit=workspace:Raycast(p+Vector3.new(0,8,0),Vector3.new(0,-24,0),ray)
            if not hit or hit.Normal.Y<.98 or math.abs(hit.Position.Y-ground.Position.Y)>1.25 then return end
            p=Vector3.new(p.X,hit.Position.Y+offset,p.Z)
            if not inside(bounds,p,3) then return end
            local checked,inArc,edge,distance=pcall(util.CheckInsideArc,util,goal,p)
            if not checked or inArc~=false or not finite(edge) or not finite(distance) or distance<edge+arcMargin then return end
            local pose=CFrame.new(p,Vector3.new(goal.Position.X,p.Y,goal.Position.Z))
            for _,part in ipairs(workspace:GetPartBoundsInBox(pose,root.Size+Vector3.new(.5,.2,.5),overlap)) do
                if part.CanCollide then return end
            end
            for _,other in ipairs(characters and characters:GetChildren() or {}) do
                local otherRoot=other~=character and other:FindFirstChild("HumanoidRootPart")
                if otherRoot and math.abs(otherRoot.Position.Y-p.Y)<6 and flat(otherRoot.Position-p).Magnitude<3 then return end
            end
            return {side=side,position=p,pose=pose,arcClearance=distance-edge}
        end
        for _,lateral in ipairs({.8,.75,.7,.65,.6}) do
            for _,extra in ipairs({2.5,3.5,4.5,5.5}) do
                local left,rightPoint=candidate(-1,lateral,extra),candidate(1,lateral,extra)
                if left and rightPoint and flat(left.position-rightPoint.position).Magnitude>12 then
                    return {body=body,character=character,root=root,proxy=proxy,bounds=bounds,goal=goal,points={[-1]=left,[1]=rightPoint}}
                end
            end
        end
        return nil,"No clear opposite wings outside this court's three-point line."
    end
    function feature.preview()
        local found,problem=geometry()
        if not found then return nil,problem end
        return {court=found.bounds.Name,left=found.points[-1].position,right=found.points[1].position,
            leftClearance=found.points[-1].arcClearance,rightClearance=found.points[1].arcClearance}
    end
    function feature.stop()
        if correction then correction:Disconnect();correction=nil end
        context,lastHop,pending=nil,nil,nil;blockUntil=0;feature.keyHeld=false
    end
    function feature.hop()
        if not feature.enabled then message("Enable Court teleport in Rage first.");return false end
        if stopped or traveling or not gameplaySafety.ready or not robloxFocused() or gui.Enabled or capturing
            or input:GetFocusedTextBox() or shot or macro or jelly or pendingRelease or rage.fly.active then
            message("Court teleport waits for active gameplay and an idle shot.");return false
        end
        local now=os.clock()
        if pending then feature.watch(now) end
        if pending or now<nextHop or now<blockUntil
            or (defense.teleport and defense.teleport.blocksMovement and defense.teleport.blocksMovement(now)) then return false end
        local body,character=gameplaySafety.actor()
        local action=tostring(character and character:GetAttribute("Action") or ""):lower()
        if not body or body:GetAttribute("CanMove")==false or body:GetAttribute("CFrame")~=nil or body:GetAttribute("SeatCFrame")~=nil
            or (action~="" and action~="moving" and action~="dribbling" and action~="guarding" and action~="contesting" and action~="defending")
            or (antiContestV2.diagnostics and antiContestV2.diagnostics().active) then
            message("Court teleport pauses during shots, contact and movement locks.");return false
        end
        local proxy=body.ProxyCharacter
        local hold=body.MainMovementPosition
        if not proxy or proxy.Anchored or not finite(body.lastValidHeight) or math.abs(proxy.Position.Y-body.lastValidHeight)>1
            or math.abs(proxy.AssemblyLinearVelocity.Y)>5 or (hold and (hold.MaxForce.X>0 or hold.MaxForce.Z>0 or hold.MaxForce.Y>0))
            or (body.MainAlignPosition and body.MainAlignPosition.Enabled) then
            message("Wait until grounded and free to move.");return false
        end
        local found,problem=geometry()
        if not found then message(problem);return false end
        if context and (context.bounds~=found.bounds or context.goal~=found.goal or context.body~=found.body) then
            feature.stop();feature.lastSide=nil
        end
        context=found
        local side=feature.lastSide and -feature.lastSide
        if not side then
            side=flat(proxy.Position-found.points[-1].position).Magnitude>flat(proxy.Position-found.points[1].position).Magnitude and -1 or 1
        end
        if flat(proxy.Position-found.points[side].position).Magnitude<6 then side=-side end
        local target=found.points[side]
        local current=gameplaySafety.actor()
        if current~=body or not found.root.Parent then message("Character changed before teleport.");return false end
        if rage.pauseMovement then rage.pauseMovement(1.5) end
        rage.stop();defense.stop();autoBlock.stop()
        local started=os.clock()
        local ok,stamp=pcall(function()
            return workspace:GetServerTimeNow()-body.Shared.Replication.ReplicationConfig.Network.SERVER_START_TIME
        end)
        if not ok or not finite(stamp) then stamp=nil end
        local attempt={body=body,character=character,root=found.root,proxy=proxy,target=target.position,
            actorId=character:GetAttribute("ReplicationId"),stamp=stamp,started=started,deadline=started+2}
        pending=attempt;lastHop=started;nextHop=started+.8;blockUntil=started+1.5
        if not correction then
            local physics=body.Services and body.Services.PhysicsService
            local event=physics and physics.SetCFrame
            if event and type(event.Connect)=="function" then correction=event:Connect(function(frame)
                if lastHop and os.clock()-lastHop<4 then
                    local now=os.clock()
                    pending=nil;nextHop=math.max(nextHop,now+2);blockUntil=math.max(blockUntil,now+1.5)
                    if rage.pauseMovement then rage.pauseMovement(1.5) end
                    message("Server repositioned the character after the hop.")
                    trace("court_teleport_server_move",{position=frame and frame.Position})
                end
            end) end
        end
        proxy.AssemblyLinearVelocity=Vector3.zero;proxy.AssemblyAngularVelocity=Vector3.zero
        if pending~=attempt then return false end
        proxy.CFrame=target.pose
        if pending~=attempt then return false end
        found.root.CFrame=target.pose
        if pending~=attempt then return false end
        feature.lastSide=side
        message((side==-1 and "Left" or "Right").." wing requested · awaiting server position.")
        trace("court_teleport_hop",{side=side,position=target.position,arcClearance=target.arcClearance,court=found.bounds.Name,echoClockAvailable=stamp~=nil})
        return true
    end
    function feature.blocksMovement(now)
        return (now or os.clock())<blockUntil
    end
    function feature.observeOwnPosition(id,stamp,position)
        local a=pending
        if not a or os.clock()>a.deadline or not finite(a.stamp) or not finite(stamp) or stamp<a.stamp-.00011
            or id~=a.actorId or typeof(position)~="Vector3" or not finite(position.X) or not finite(position.Y) or not finite(position.Z) then return end
        local body,character,root=gameplaySafety.actor()
        if body~=a.body or character~=a.character or root~=a.root or not a.proxy.Parent then return end
        local delta=position-a.target
        if flat(delta).Magnitude>3 or math.abs(delta.Y)>1 then return end
        pending=nil
        message("Server echoed a position near the requested wing.")
        trace("court_teleport_echo",{position=position,stamp=stamp,elapsed=os.clock()-a.started})
    end
    function feature.watch(now)
        local body,character,root=gameplaySafety.actor()
        if pending and (traveling or stopped or not gameplaySafety.ready or not pending.proxy.Parent
            or body~=pending.body or character~=pending.character or root~=pending.root) then
            pending=nil;blockUntil=0
        elseif pending and now>=pending.deadline then
            pending=nil;nextHop=math.max(nextHop,now+1)
            message("Teleport outcome unconfirmed; no matching server position arrived.")
            trace("court_teleport_unconfirmed",{})
        end
    end
    function feature.press()
        if feature.keyHeld then return false end
        feature.keyHeld=true
        local ok,moved=pcall(feature.hop)
        if not ok then message("Court teleport paused: "..tostring(moved));trace("court_teleport_error",{error=tostring(moved)});return false end
        return moved
    end
    function feature.release() feature.keyHeld=false end
    function feature.capture() return {enabled=feature.enabled,lastSide=feature.lastSide} end
    function feature.apply(saved)
        feature.stop();feature.enabled=type(saved)=="table" and saved.enabled==true
        feature.lastSide=type(saved)=="table" and (saved.lastSide==1 or saved.lastSide==-1) and saved.lastSide or nil
        nextHop=0;message(feature.enabled and "Press the bound key to switch outside-arc wings." or "Court teleport is off.")
        feature.refresh()
    end
    function feature.refresh()
        showSwitch(feature.toggle,feature.enabled)
        local key=bindings["Court teleport"]
        if key~=feature.boundKey then feature.keyHeld=false;feature.boundKey=key end
        feature.bindButton.Text=capturing=="Court teleport" and "Press a key…" or "Teleport key · "..(key and key.Name or "Unbound")
    end
    function feature.bind(connectControl,redraw,bindKey)
        connectControl(feature.toggle.row.Activated,function()
            local saved=feature.capture();saved.enabled=not saved.enabled;feature.apply(saved);redraw()
        end)
        connectControl(feature.bindButton.Activated,function()feature.release();bindKey("Court teleport")end)
        connectControl(input.InputEnded,function(event)
            if event.KeyCode==bindings["Court teleport"] then feature.release() end
        end)
        connectControl(input.WindowFocusReleased,feature.release)
    end
    function feature.diagnostics() return {enabled=feature.enabled,lastSide=feature.lastSide,message=feature.message,
        key=bindings["Court teleport"] and bindings["Court teleport"].Name,keyHeld=feature.keyHeld==true,pending=pending~=nil,blockUntil=blockUntil} end
    message("Court teleport is off.")
    shared.WizardHubCourtTeleport=feature
end
rage.initialiseCourtTeleport()
function defense.initialiseTeleport()
    local feature=defense.teleport
    local actor,correction,lastHop,nextHop=nil,nil,nil,0
    local settleUntil,placementVersion=0,0
    local function flat(v)return Vector3.new(v.X,0,v.Z)end
    local function finite(n)return type(n)=="number"and n==n and math.abs(n)<1e6 end
    local function trace(kind,data)
        if antiContestV2.recorder then pcall(antiContestV2.recorder.emit,kind,data)end
    end
    local function message(text)feature.message=text end
    local function inside(bounds,p,margin)
        local q,h=bounds.CFrame:PointToObjectSpace(p),bounds.Size/2
        return math.abs(q.X)<=h.X-margin and math.abs(q.Y)<=h.Y-2 and math.abs(q.Z)<=h.Z-margin
    end
    local function destination(character,root,handler,opponent,goal)
        local body,model,currentRoot=gameplaySafety.actor()
        local proxy=body and body.ProxyCharacter
        if model~=character or currentRoot~=root or not proxy or not proxy.Parent or proxy.Anchored
            or not handler or not handler.Parent or not opponent or not opponent.Parent or opponent.Parent~=handler
            or not goal or not goal:IsA("BasePart") then return nil,"Waiting for live defense characters."end
        local ownTeam,otherTeam=positiveTeamId(character,"Team"),positiveTeamId(handler,"Team")
        if not ownTeam or not otherTeam or ownTeam==otherTeam or heldBall(character) or not heldBall(handler)
            or not sameDefenseCourt(character,characterGoal(character),handler,goal) then
            return nil,"Waiting for an opposing ball handler on this court."
        end
        local action=tostring(body:GetAttribute("Action")or""):lower()
        if body:GetAttribute("CanMove")==false or body:GetAttribute("CFrame")~=nil or body:GetAttribute("SeatCFrame")~=nil
            or (action~=""and action~="moving"and action~="guarding"and action~="defending"and action~="contesting"and action~="defensivestance") then
            return nil,"Guard teleport pauses during contact and movement locks."
        end
        local ground,height=body.raycastResult,body.lastValidHeight
        local hold=body.MainMovementPosition
        if not ground or not finite(height) or math.abs(proxy.Position.Y-height)>1 or math.abs(proxy.AssemblyLinearVelocity.Y)>5
            or (hold and hold.MaxForce.Magnitude>0)or(body.MainAlignPosition and body.MainAlignPosition.Enabled)then
            return nil,"Guard teleport waits until grounded and free to move."
        end
        local clearance=height-ground.Position.Y
        if not finite(clearance)or clearance<.5 or clearance>8 then return nil,"Waiting for native ground clearance."end
        local assets=workspace:FindFirstChild("Assets")
        local folder=assets and assets:FindFirstChild("CourtBounds")
        local bounds
        for _,part in ipairs(folder and folder:GetChildren()or{})do
            if part:IsA("BasePart")and part.CFrame.UpVector:Dot(Vector3.yAxis)>.9999 and inside(part,proxy.Position,0)
                and inside(part,Vector3.new(opponent.Position.X,height,opponent.Position.Z),0)then bounds=part;break end
        end
        if not bounds then return nil,"Both players must be inside the same court."end
        local forward=flat(goal.Position-opponent.Position)
        if forward.Magnitude<.5 then forward=flat(bounds.Position-opponent.Position)end
        if forward.Magnitude<.5 then return nil,"No clear guard direction."end
        forward=forward.Unit
        local side=Vector3.new(-forward.Z,0,forward.X)
        local characters=workspace:FindFirstChild("Characters")
        local exclusions={character,proxy}
        if characters then table.insert(exclusions,characters)end
        local balls=workspace:FindFirstChild("Basketballs")
        if balls then table.insert(exclusions,balls)end
        local ray=RaycastParams.new();ray.FilterType=Enum.RaycastFilterType.Exclude
        ray.FilterDescendantsInstances=exclusions;ray.RespectCanCollide=true
        local overlap=OverlapParams.new();overlap.FilterType=Enum.RaycastFilterType.Exclude
        overlap.FilterDescendantsInstances=exclusions;overlap.RespectCanCollide=true
        local spacing=math.max(2.75,(root.Size.X+opponent.Size.X)/2+.45,math.clamp(defense.spacing.value,2,6))
        local function candidate(direction)
            local p=opponent.Position+direction*spacing
            p=Vector3.new(p.X,height,p.Z)
            if not inside(bounds,p,2.5)then return end
            local hit=workspace:Raycast(p+Vector3.new(0,8,0),Vector3.new(0,-24,0),ray)
            if not hit or hit.Normal.Y<.98 or math.abs(hit.Position.Y-ground.Position.Y)>1.25 then return end
            p=Vector3.new(p.X,hit.Position.Y+clearance,p.Z)
            if not inside(bounds,p,2.5)then return end
            local pose=CFrame.new(p,Vector3.new(opponent.Position.X,p.Y,opponent.Position.Z))
            for _,part in ipairs(workspace:GetPartBoundsInBox(pose,root.Size+Vector3.new(.4,.2,.4),overlap))do
                if part.CanCollide then return end
            end
            for _,other in ipairs(characters and characters:GetChildren()or{})do
                local otherRoot=other~=character and other:FindFirstChild("HumanoidRootPart")
                if otherRoot and math.abs(otherRoot.Position.Y-p.Y)<6
                    and flat(otherRoot.Position-p).Magnitude<(root.Size.X+otherRoot.Size.X)/2+.35 then return end
            end
            return {body=body,proxy=proxy,root=root,handler=handler,opponent=opponent,position=p,pose=pose,court=bounds.Name,spacing=spacing}
        end
        for _,offset in ipairs({0,.5,-.5,1,-1})do
            local found=candidate((forward+side*offset).Unit)
            if found then return found end
        end
        return nil,"Waiting for a clear spot beside the ball handler."
    end
    function feature.preview(character,root,handler,opponent,goal)
        local found,problem=destination(character,root,handler,opponent,goal)
        if not found then return nil,problem end
        return {position=found.position,court=found.court,spacing=found.spacing,opponent=handler.Name}
    end
    function feature.stop()
        if correction then correction:Disconnect();correction=nil end
        actor,lastHop=nil,nil
    end
    function feature.apply(enabled)
        feature.stop();feature.enabled=enabled==true;nextHop=0
        message(feature.enabled and "Hold the guard key in Blatant mode to teleport to the ball handler."or"Guard teleport is off.")
    end
    function feature.blocksMovement(now) return (now or os.clock())<settleUntil end
    function feature.try(character,root,handler,opponent,goal,now,releaseKeys)
        if not feature.enabled or defense.mode~="Blatant"or not defense.enabled then return false end
        local bind=bindings["Auto Guard"]
        if not bind or not executorInput.keyDown(bind)or stopped or traveling or not gameplaySafety.ready or not robloxFocused()
            or gui.Enabled or capturing or input:GetFocusedTextBox()or shot or macro or jelly or pendingRelease or rage.fly.active
            or (antiContestV2.diagnostics and antiContestV2.diagnostics().active)then return false end
        if now<nextHop or feature.blocksMovement(now)
            or (rage.courtTeleport.blocksMovement and rage.courtTeleport.blocksMovement(now)) then return false end
        if not root or not opponent then return false end
        if flat(root.Position-opponent.Position).Magnitude<=math.max(6,defense.spacing.value+2)then return false end
        nextHop=now+.15
        local found,problem=destination(character,root,handler,opponent,goal)
        if not found then message(problem);return false end
        local body=gameplaySafety.actor()
        if body~=found.body or not found.root.Parent or not found.opponent.Parent then return false end
        if actor~=body then feature.stop();actor=body end
        if not correction then
            local physics=body.Services and body.Services.PhysicsService
            local event=physics and physics.SetCFrame
            if event and type(event.Connect)=="function"then correction=event:Connect(function(frame)
                nextHop=math.max(nextHop,os.clock()+2)
                if lastHop and os.clock()-lastHop<4 then
                    local at=os.clock();placementVersion+=1;settleUntil=math.max(settleUntil,at+1.5)
                    if rage.pauseMovement then rage.pauseMovement(1.5) end
                    message("Server repositioned after guard teleport; pausing.")
                    trace("defense_teleport_server_move",{position=frame and frame.Position,opponent=feature.target})
                end
            end)end
        end
        releaseKeys()
        if rage.pauseMovement then rage.pauseMovement(1.5) end
        rage.stop();autoBlock.stop()
        lastHop=now;settleUntil=math.max(settleUntil,now+1.5)
        local revision=placementVersion
        found.proxy.AssemblyLinearVelocity=Vector3.zero;found.proxy.AssemblyAngularVelocity=Vector3.zero
        local movement=body.Movement and body.Movement.MovementVelocity
        if movement then movement.Velocity=Vector3.zero end
        found.proxy.CFrame=found.pose
        if revision~=placementVersion then return false end
        found.root.CFrame=found.pose
        if revision~=placementVersion then return false end
        lastHop=now;nextHop=now+.85;feature.count=(feature.count or 0)+1;feature.target=handler.Name
        message("Teleported beside the opposing ball handler.")
        trace("defense_teleport_hop",{position=found.position,opponent=handler.Name,court=found.court,spacing=found.spacing})
        return true
    end
    function feature.attempt(...)
        local ok,moved=pcall(feature.try,...)
        if not ok then
            nextHop=os.clock()+1;message("Guard teleport paused: "..tostring(moved))
            trace("defense_teleport_error",{error=tostring(moved)});return false
        end
        return moved
    end
    function feature.diagnostics()return {enabled=feature.enabled,activeMode=defense.mode=="Blatant",count=feature.count or 0,
        target=feature.target,message=feature.message,cooldownMs=math.max(0,math.floor((nextHop-os.clock())*1000))}end
    feature.apply(false)
    shared.WizardHubDefenseTeleport=feature
end
defense.initialiseTeleport()



local function ballHand(character, root, ball)
    local hand = character:GetAttribute("Hand")
    if hand == "R" then return "Right" end
    if hand == "L" then return "Left" end
    if not root or not ball:IsA("BasePart") then return end
    local side = root.CFrame:PointToObjectSpace(ball.Position).X
    if side > 0.35 then return "Right" end
    if side < -0.35 then return "Left" end
end

local function findMeter(root)
    local meter = root and root:FindFirstChild("VerticalMeter")
    local fill = meter and meter:FindFirstChild("Meter_Fill")
    local gradient = fill and fill:FindFirstChild("FillGradient")
    local feedback = root and root:FindFirstChild("ShotFeedback")
    local rating = feedback and feedback:FindFirstChild("ReleaseTiming")
    if meter and meter:IsA("BillboardGui") and gradient and gradient:IsA("UIGradient")
        and feedback and feedback:IsA("BillboardGui") and rating and rating:IsA("TextLabel") then
        return meter, gradient, feedback, rating
    end
end

local function releaseKey(key)
    if type(keyrelease) ~= "function" then return end
    if robloxFocused() then
        keyrelease(key)
    else
        -- Real needs Roblox focus to deliver key-up.
        pendingKeys[key] = true
        if not pendingRelease then
            pendingRelease = input.WindowFocused:Once(function()
                pendingRelease = nil
                for pending in pairs(pendingKeys) do keyrelease(pending) end
                table.clear(pendingKeys)
            end)
        end
    end
end

do
    local promptService = game:GetService("ProximityPromptService")
    local guiService = game:GetService("GuiService")
    local shownPrompts, labelLinks, captions, guiLinks = {}, {}, {}, {}
    local heldUntil, heldPrompt, nextInputAt, awaitingUntil
    local finishJoin, checkConfirmation
    local attributeLinks, trackedCharacter = {}, nil
    local joinCaption, leaveCaption = "join spot", "leave spot"

    local function normalize(text)
        return (text:gsub("<[^<>]*>", ""):lower():gsub("%s+", " "):match("^%s*(.-)%s*$"))
    end

    local function courtTitle(text)
        return normalize(text):match("^court %d+$")
    end

    local function visible(labelObject)
        local size = labelObject.AbsoluteSize
        if size.X <= 0 or size.Y <= 0 or labelObject.TextTransparency >= 0.98 then return false end
        local camera = workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize
        local position = labelObject.AbsolutePosition
        if viewport and (position.X >= viewport.X or position.Y >= viewport.Y
            or position.X + size.X <= 0 or position.Y + size.Y <= 0) then
            return false
        end
        local current = labelObject
        while current and current ~= playerGui do
            if current:IsA("ScreenGui") then return current.Enabled end
            if current:IsA("GuiObject") and not current.Visible then return false end
            if current:IsA("CanvasGroup") and current.GroupTransparency >= 0.98 then return false end
            current = current.Parent
        end
        return false
    end

    local function displayedCourt()
        local selected, multiple
        for action, text in pairs(captions) do
            if (text ~= joinCaption and text ~= leaveCaption) or not visible(action) then continue end
            local group = action.Parent
            for _ = 1, 4 do
                if not group or not group:IsA("GuiObject") then break end
                local title, hasKey, ambiguous
                for candidate, caption in pairs(captions) do
                    if (caption == "e" or caption:match("^court %d+$"))
                        and candidate:IsDescendantOf(group) and visible(candidate) then
                        if caption == "e" then
                            hasKey = true
                        elseif title and title ~= caption then
                            ambiguous = true
                        else
                            title = caption
                        end
                    end
                end
                if title and not ambiguous and (hasKey or text == leaveCaption) then
                    if text == leaveCaption then return nil, true end
                    if selected and selected ~= title then multiple = true end
                    selected = selected or title
                    break
                end
                group = group.Parent
            end
        end
        return not multiple and selected or nil
    end

    local function promptPosition(prompt)
        local anchor = prompt.Parent
        if not anchor then return end
        if anchor:IsA("Attachment") then return anchor.WorldPosition end
        if anchor:IsA("BasePart") then return anchor.Position end
        if anchor:IsA("Model") then return anchor:GetPivot().Position end
    end

    local function closestPrompt(root)
        local nearest, title, nearestDistance
        for prompt in pairs(shownPrompts) do
            if not prompt.Enabled or prompt.KeyboardKeyCode ~= jump.key or not prompt:IsDescendantOf(workspace) then continue end
            local court = courtTitle(prompt.ObjectText)
            if not court then continue end
            local action = normalize(prompt.ActionText)
            local position = promptPosition(prompt)
            local distance = position and (position - root.Position).Magnitude
            if action == leaveCaption and distance and distance <= prompt.MaxActivationDistance then return nil, nil, true end
            if action ~= joinCaption then continue end
            if distance and distance <= prompt.MaxActivationDistance and (not nearest or distance < nearestDistance) then
                nearest, title, nearestDistance = prompt, court, distance
            end
        end
        return title, nearest
    end

    local function release()
        if not heldUntil then return end
        local prompt = heldPrompt
        heldUntil, heldPrompt = nil, nil
        if prompt then pcall(prompt.InputHoldEnd, prompt) else releaseKey(jump.virtualKey) end
    end

    local function track(labelObject)
        if not courtJoin.enabled then return end
        if labelObject.ClassName ~= "TextLabel" and labelObject.ClassName ~= "TextButton" then return end
        if labelLinks[labelObject] or labelObject:IsDescendantOf(gui) or hud.owns(labelObject) then return end
        local function update()
            local text = normalize(privacy.readText(labelObject))
            if text == joinCaption or text == leaveCaption or text == "e" or text:match("^court %d+$") then
                captions[labelObject] = text
            else
                captions[labelObject] = nil
            end
            if courtJoin.enabled and text == leaveCaption and visible(labelObject) then finishJoin("Joined spot") end
        end
        labelLinks[labelObject] = {
            labelObject:GetPropertyChangedSignal("Text"):Connect(update),
            labelObject:GetPropertyChangedSignal("Visible"):Connect(update),
        }
        update()
    end

    local function forget(labelObject)
        local link = labelLinks[labelObject]
        if link then for _, connection in ipairs(link) do connection:Disconnect() end end
        labelLinks[labelObject], captions[labelObject] = nil, nil
    end

    local function confirmedAttributes(object)
        return object and (object:GetAttribute("OnSpot") == true or object:GetAttribute("OnCourt") == true or object:GetAttribute("InGame") == true)
    end

    checkConfirmation = function()
        if not courtJoin.enabled then return false end
        local character, root = findCharacter()
        if confirmedAttributes(player) or confirmedAttributes(character) then finishJoin("Joined spot or court"); return true end
        for labelObject, text in pairs(captions) do
            if text == leaveCaption and visible(labelObject) then finishJoin("Joined spot"); return true end
        end
        if root and root:IsA("BasePart") then
            local _, _, joined = closestPrompt(root)
            if joined then finishJoin("Joined spot"); return true end
        end
        return false
    end

    local function confirmationWindow()
        local ping = type(network.latest) == "number" and network.latest == network.latest and network.latest >= 0 and network.latest < 10 and network.latest or .15
        return math.max(.16, ping * 2 + .10)
    end

    local function clearAttributeLinks()
        for _, link in ipairs(attributeLinks) do link:Disconnect() end
        table.clear(attributeLinks)
        trackedCharacter = nil
    end

    local function bindConfirmationAttributes(character)
        if trackedCharacter == character and #attributeLinks > 0 then return end
        clearAttributeLinks()
        trackedCharacter = character
        for _, object in ipairs(character and {player, character} or {player}) do
            for _, attribute in ipairs({"OnSpot", "OnCourt", "InGame"}) do
                attributeLinks[#attributeLinks + 1] = object:GetAttributeChangedSignal(attribute):Connect(checkConfirmation)
            end
        end
    end

    function courtJoin.apply(enabled)
        if enabled == courtJoin.enabled then
            if enabled then checkConfirmation() end
            return
        end
        courtJoin.enabled = enabled
        if enabled then
            awaitingUntil, nextInputAt = nil, nil
            bindConfirmationAttributes(findCharacter())
            if checkConfirmation() then return end
            guiLinks[1] = playerGui.DescendantAdded:Connect(track)
            guiLinks[2] = playerGui.DescendantRemoving:Connect(forget)
            for _, object in ipairs(playerGui:GetDescendants()) do track(object) end
            if courtJoin.enabled then courtJoin.status.Text = "Stand near a Park join spot."; checkConfirmation() end
        else
            release()
            clearAttributeLinks()
            for _, link in ipairs(guiLinks) do link:Disconnect() end
            table.clear(guiLinks)
            for object in pairs(labelLinks) do forget(object) end
            nextInputAt, awaitingUntil = nil, nil
            courtJoin.status.Text = "Auto Join Court is off."
        end
    end

    finishJoin = function(reason)
        if not courtJoin.enabled then return end
        courtJoin.apply(false)
        courtJoin.status.Text = reason .. ". Auto Join stopped."
        refresh()
        warn(prefix .. "Auto Join: confirmation received; all retries stopped.")
    end

    function courtJoin.bind()
        courtJoin.interval.onChange = function() if not awaitingUntil or os.clock() >= awaitingUntil then nextInputAt = nil end end
        if not promptService then return end
        connect(promptService.PromptShown, function(prompt) shownPrompts[prompt] = true; checkConfirmation() end)
        connect(promptService.PromptHidden, function(prompt) shownPrompts[prompt] = nil end)
    end

    function courtJoin.onE(now)
        if checkConfirmation() then return false end
        if heldUntil and not heldPrompt then return true end
        if courtJoin.enabled then
            awaitingUntil = now + confirmationWindow()
            nextInputAt = now + math.max(confirmationWindow(), courtJoin.interval.value / 100)
        end
        return false
    end

    function courtJoin.watch(now)
        if not courtJoin.enabled then return end
        bindConfirmationAttributes(findCharacter())
        if checkConfirmation() then return end
        local blocked = traveling or gui.Enabled or capturing or input:GetFocusedTextBox()
            or (guiService and guiService.MenuIsOpen) or not robloxFocused()
        if heldUntil then
            local promptChanged = heldPrompt and (not shownPrompts[heldPrompt] or not heldPrompt.Enabled
                or normalize(heldPrompt.ActionText) ~= joinCaption)
            if blocked or now >= heldUntil or promptChanged then release() end
            return
        end
        if awaitingUntil and now < awaitingUntil then
            courtJoin.status.Text = "Waiting for join confirmation…"
            return
        end
        if blocked or shot or macro or jelly or pendingRelease or (nextInputAt and now < nextInputAt)
            or executorInput.keyDown(jump.key) then return end
        local character, root = findCharacter()
        if not root or not root:IsA("BasePart") or heldBall(character) then return end
        local title, busy = displayedCourt()
        local nativeTitle, prompt, nativeBusy = closestPrompt(root)
        if busy or nativeBusy then
            finishJoin("Joined spot")
            return
        end
        if title and automationAvailable() and (not nativeTitle or (title == nativeTitle and prompt.HoldDuration == 0)) then
            prompt = nil
        else
            title = nativeTitle
        end
        if not title then
            courtJoin.status.Text = "Stand near a Park join spot."
            return
        end
        -- The Join Spot prompt can remain visible while someone else occupies the spot.
        -- Recheck it before each retry so Leave Spot never triggers another input.
        local interval = courtJoin.interval.value / 100
        local holdDuration = math.min(0.04, interval / 2)
        if prompt and prompt.HoldDuration > 0 then holdDuration = math.max(holdDuration, prompt.HoldDuration + 0.02) end
        awaitingUntil = now + confirmationWindow()
        nextInputAt = now + math.max(interval, confirmationWindow())
        heldPrompt = prompt
        heldUntil = now + holdDuration
        local sent
        if prompt then sent = pcall(prompt.InputHoldBegin, prompt) else sent = pcall(keypress, jump.virtualKey) end
        if not sent then release() end
        if courtJoin.enabled then
            courtJoin.status.Text = sent and ("Trying " .. title:upper() .. ". Waiting for confirmation…") or "Join input could not be sent."
        end
    end

    courtJoin.release = release
    courtJoin.checkConfirmation = checkConfirmation
end

do
    -- Auto Guard.
    --
    -- While the guard bind is held this plays on-ball defense with the ordinary movement keys:
    -- it keeps the player between the ball handler and the rim, in a defensive stance when close.
    --
    -- What the game's own movement rules mean for a defender (read from its movement code):
    --   * In a stance the player always faces the ball handler and slides: sideways at full pace,
    --     backwards at 85% of it. A dribbler who runs into a defender set in front of them is
    --     bumped. Sprint does nothing in a stance; it only works when running forwards.
    --   * Out of a stance the player turns to run where the keys point, and can sprint.
    -- So staying set in front is what stops a drive, and that part works as it always did. What
    -- a stance cannot do is win back a lost step: a dribbler who has gone round is level or ahead,
    -- and sliding after them at an angle is slower than they are. Then, and only then, the stance
    -- is dropped and the player turns and sprints to the nearest spot on the dribbler's way to the
    -- rim that can be reached first ("run"), and squares up again there.
    --
    -- In Legit mode it is also paced like a person: what the handler does is seen a moment late
    -- (steady movement is followed well, a sudden cut is not), keys stay down and up for believable
    -- lengths of time, decisions take a moment, and the cushion is never exactly the same twice.
    local guard = {Enum.KeyCode.G, 0x47}
    local sprint = gameKeys.Shift
    local movement = {gameKeys.W, gameKeys.A, gameKeys.S, gameKeys.D}
    local commands = {guard, sprint, gameKeys.W, gameKeys.A, gameKeys.S, gameKeys.D}
    local yieldingKeys = {Enum.KeyCode.LeftShift, Enum.KeyCode.Space, Enum.KeyCode.R, Enum.KeyCode.E}
    local guardActions = { [""] = true, Moving = true, Guarding = true, Defending = true, Contesting = true, DefensiveStance = true }
    defense.conflictingKeys = {[Enum.KeyCode.Q] = true, [Enum.KeyCode.F] = true}
    for _, command in ipairs(commands) do defense.conflictingKeys[command[1]] = true end
    for _, key in ipairs(yieldingKeys) do defense.conflictingKeys[key] = true end

    local held = {}
    local keyTimes = {}     -- Per key: when it last went down or up, and how long before it may change again.
    local target, orbitSide, paintSide, approachDirection, lastPossessionAt
    local sightings = {}    -- Where the guarded handler has been lately: {time, x, z}.
    local glimpses = setmetatable({}, {__mode = "k"})   -- Last look at every opposing handler: {time, x, z, approach}.
    local mind = {}         -- This possession: mode, pacing, and what has been made of the handler's movement.
    local stepping
    local trackedCharacter, trackedRoot
    local axisCooldown = {}
    local nextSample = 0
    defense.trace = {}      -- Finished possessions waiting to be written to the log (see shotLog.flush).

    local function paced()
        return defense.mode ~= "Blatant"
    end

    -- True for a key this script is holding, or let go of so recently that it can still read as
    -- down for a frame or two. Anything else that is down is the player's own finger.
    local function ours(code, now)
        local times = keyTimes[code]
        return held[code] or (times ~= nil and now - times[1] < 0.15)
    end

    local function send(desired, now, force)
        -- Never cancel a physical key we did not press, or add its opposite.
        for index, command in ipairs(movement) do
            if executorInput.keyDown(command[1]) and not ours(command[2], now) then
                local opposite = index == 1 and gameKeys.S or index == 2 and gameKeys.D
                    or index == 3 and gameKeys.W or gameKeys.A
                desired[opposite[2]] = nil
            end
        end
        local human = not force and paced()
        for _, command in ipairs(commands) do
            local code = command[2]
            local times = keyTimes[code]
            if held[code] and not desired[code] then
                -- A finger does not come off a key it has only just pressed...
                if not human or not times or now - times[1] >= times[2] then
                    held[code] = nil
                    releaseKey(code)
                    keyTimes[code] = {now, 0.05 + math.random() * 0.06}
                end
            end
        end
        for _, command in ipairs(commands) do
            local code = command[2]
            local times = keyTimes[code]
            if desired[code] and not held[code] and not executorInput.keyDown(command[1]) then
                -- ...nor go straight back down on one it has only just let go.
                if not human or not times or now - times[1] >= times[2] then
                    held[code] = true
                    keypress(code)
                    keyTimes[code] = {now, 0.08 + math.random() * 0.08}
                end
            end
        end
    end

    -- Keeps a short record of a finished possession (where both players went, which keys were
    -- down) so the footwork can be checked and tuned from real games afterwards.
    local function closeTrace()
        local samples = mind.samples
        if samples and #samples >= 84 and #defense.trace < 6 then
            defense.traceAt = os.clock()
            table.insert(defense.trace, {version = 4, at = os.time(), guard = defense.mode, seconds = mind.traceSeconds,
                ran = mind.ran, columns = "t,myX,myZ,theirX,theirZ,keys,running", samples = samples})
        end
        mind.samples = nil
    end

    function defense.stop(message)
        defense.teleport.stop()
        if next(held) then send({}, os.clock(), true) end
        if mind.samples then closeTrace() end
        target, orbitSide, paintSide, approachDirection, lastPossessionAt = nil, nil, nil, nil, nil
        stepping, trackedCharacter, trackedRoot, nextSample = nil, nil, nil, 0
        if sightings[1] then table.clear(sightings) end
        if next(mind) then table.clear(mind) end
        if next(axisCooldown) then table.clear(axisCooldown) end
        if message then defense.status.Text = message end
    end

    local function planar(vector)
        return Vector2.new(vector.X, vector.Z)
    end

    local function tenth(value)
        return math.floor(value * 10 + 0.5) / 10
    end

    local function sameCourt(character, goal, opponent, otherGoal)
        return sameDefenseCourt(character, goal, opponent, otherGoal)
    end

    local function isFinishing(character)
        local action = character:GetAttribute("Action")
        if type(action) ~= "string" then return false end
        action = action:lower()
        return action == "shooting" or action:find("dunk", 1, true) or action:find("layup", 1, true)
            or action:find("gather", 1, true) or action:find("clutch", 1, true)
    end

    -- How fast a handler is coming at this player, from one look to the next. Known for every
    -- opposing handler, not only the one being guarded, so a runner is picked up in time.
    local function approachOf(model, otherRoot, position, now)
        local spot = otherRoot.Position
        local last = glimpses[model]
        local approach = last and last[4] or 0
        if last and now - last[1] >= 0.02 and now - last[1] <= 0.4 then
            local moved = Vector2.new(spot.X - last[2], spot.Z - last[3]) / (now - last[1])
            local toMe = Vector2.new(position.X - spot.X, position.Z - spot.Z)
            if toMe.Magnitude > 0.5 and moved.Magnitude <= 36 then approach = math.max(0, moved:Dot(toMe.Unit)) end
        elseif last and now - last[1] > 0.4 then
            approach = 0
        end
        if not last or now - last[1] >= 0.02 then glimpses[model] = {now, spot.X, spot.Z, approach} end
        return approach
    end

    local function closestHandler(character, root, team, goal, now)
        local characters = workspace:FindFirstChild("Characters")
        local position = root.Position
        local handler, handlerRoot, handlerGoal, closest, handlerHasBall, bestScore
        for _, other in ipairs(players:GetPlayers()) do
            if other ~= player then
                local model = characters and characters:FindFirstChild(other.Name) or other.Character
                local otherTeam = model and positiveTeamId(model, "Team")
                local otherGoal = otherTeam and characterGoal(model)
                if otherTeam and otherTeam ~= team and otherGoal and otherGoal:IsA("BasePart")
                    and model.Parent and sameCourt(character, goal, model, otherGoal) then
                    local ownsBall = not not heldBall(model)
                    local finishing = isFinishing(model)
                    local finishingGrace = model == target and finishing and lastPossessionAt
                        and now - lastPossessionAt <= (defense.mode == "Blatant" and 0.40 or 0.32)
                    local otherRoot = model:FindFirstChild("HumanoidRootPart")
                    if otherRoot and (ownsBall or finishingGrace) then
                        local offset = otherRoot.Position - position
                        if math.abs(offset.Y) < (finishing and 12 or 5) then
                            local gap = planar(offset).Magnitude
                            local sticky = model == target and defense.stickiness.value or 0
                            local range = defense.range.value + math.min(sticky, 3)
                            -- Someone running at this player is noticed sooner the faster they come,
                            -- and a handler being chased is not dropped for getting a few steps away.
                            range += math.clamp(approachOf(model, otherRoot, position, now) * 0.7, 0, 14)
                            if model == target and mind.mode == "run" then range += 8 end
                            local score = gap - sticky
                            if (gap <= range or (defense.mode == "Blatant" and defense.teleport.enabled)) and (not handler or (ownsBall and not handlerHasBall)
                                or (ownsBall == handlerHasBall and score < bestScore)) then
                                handler, handlerRoot, handlerGoal, closest = model, otherRoot, otherGoal, gap
                                handlerHasBall, bestScore = ownsBall, score
                            end
                        end
                    end
                end
            end
        end
        return handler, handlerRoot, handlerGoal, closest, handlerHasBall
    end

    -- Where the handler was `delay` seconds ago and how they were moving then, plus how old that
    -- sighting really is.
    local function recall(now, delay)
        local count = #sightings
        if count == 0 then return end
        local at = now - delay
        local index = count
        while index > 1 and sightings[index][1] > at do index -= 1 end
        local seen = sightings[index]
        local from = index
        while from > 1 and seen[1] - sightings[from][1] < 0.1 do from -= 1 end
        local first = sightings[from]
        local span = seen[1] - first[1]
        local velocity = Vector2.zero
        if span >= 0.03 then
            velocity = Vector2.new(seen[2] - first[2], seen[3] - first[3]) / span
            if velocity.Magnitude > 36 then velocity = Vector2.zero end
        end
        return Vector2.new(seen[2], seen[3]), velocity, now - seen[1]
    end

    local function useAxis(axis, positive, negative, desired, now)
        local key = (axis > 0 and positive or negative)[2]
        local opposite = (axis > 0 and negative or positive)[2]
        local threshold = held[key] and 0.28 or (defense.mode == "Blatant" and 0.42 or 0.48)
        if math.abs(axis) < threshold then return end
        local slot = positive[2]
        if held[opposite] and math.abs(axis) < 0.78 then
            axisCooldown[slot] = now + (defense.mode == "Blatant" and 0.015 or 0.035)
            return
        end
        if not axisCooldown[slot] or now >= axisCooldown[slot] then desired[key] = true end
    end

    local function footwork(root, opponent, goal, desired, now)
        local camera = workspace.CurrentCamera
        if not camera then return end
        local human = paced()
        local position = planar(root.Position)

        -- What is known about the handler: a look from a moment ago, carried forward as if they
        -- had kept going the same way since.
        local seen, seenVelocity, age = recall(now, human and mind.reaction or 0)
        if not seen then seen, seenVelocity, age = planar(opponent.Position), Vector2.zero, 0 end
        local velocityCap = human and 22 or 30
        if seenVelocity.Magnitude > velocityCap then seenVelocity = seenVelocity.Unit * velocityCap end
        local elapsed = mind.filteredAt and now - mind.filteredAt or 0
        local blend = elapsed > 0 and elapsed / (elapsed + defense.smoothing.value / 1000) or 1
        if not mind.velocityKnown then
            -- The first looks carry no speed yet. Easing up from zero (as this did) cost about a
            -- fifth of a second at the start of every possession; take the first real reading whole.
            mind.velocity = seenVelocity
            mind.velocityKnown = seenVelocity.Magnitude > 0.5 or (mind.startedAt ~= nil and now - mind.startedAt > 0.2)
        else
            mind.velocity = mind.velocity + (seenVelocity - mind.velocity) * blend
        end
        mind.filteredAt = now
        local velocity = mind.velocity
        local ballSide = seen + velocity * age

        -- How fast this player actually covers ground at a sprint, for judging what can be reached.
        if mind.selfAt and now - mind.selfAt >= 0.03 and now - mind.selfAt <= 0.3 then
            local pace = (position - mind.selfPosition).Magnitude / (now - mind.selfAt)
            if held[sprint[2]] and pace > 9 and pace < 30 then
                defense.pace = defense.pace and (defense.pace * 0.85 + pace * 0.15) or pace
            end
        end
        mind.selfPosition, mind.selfAt = position, now

        local basketLine = planar(goal.Position) - ballSide
        local depth, relative = basketLine.Magnitude, position - ballSide
        local inside = depth < 7
        -- On outside jump shots, the no-block choice closes directly into the shooter.
        -- Use live position here so the ordinary orbit/spacing logic cannot pull away.
        if defense.perimeterShot(opponent.Parent, opponent, goal) and not defense.blockPerimeter then
            local delta = planar(opponent.Position) - position
            local cameraRight = planar(camera.CFrame.RightVector)
            mind.mode, mind.sprint, orbitSide, paintSide = "contest", nil, nil, nil
            if delta.Magnitude > 0.25 and cameraRight.Magnitude > 0.1 then
                local right = cameraRight.Unit
                local forward = Vector2.new(right.Y, -right.X)
                useAxis(delta.Unit:Dot(right), gameKeys.D, gameKeys.A, desired, now)
                useAxis(delta.Unit:Dot(forward), gameKeys.W, gameKeys.S, desired, now)
            end
            return false
        end
        -- Lock the approach direction under the rim so crossing it doesn't reverse the route.
        if depth >= 2 or (not approachDirection and depth >= 0.65) then
            local direction = basketLine.Unit
            if approachDirection and approachDirection:Dot(direction) < 0.3 then orbitSide, paintSide = nil, nil end
            approachDirection = direction
        end
        local front = approachDirection or (relative.Magnitude > 0.1 and relative.Unit)
        if not front then return inside end
        local side = Vector2.new(-front.Y, front.X)
        local lead = velocity * (defense.lead.value / 1000)

        local selectedSpacing = inside and math.min(defense.spacing.value, defense.paintSpacing.value) or defense.spacing.value
        if defense.mode == "Blatant" and defense.profiles.Blatant.pressure then selectedSpacing = math.max(1.25, selectedSpacing - 0.75) end
        if human then
            -- Nobody holds exactly the same cushion all possession.
            if not mind.driftAt or now >= mind.driftAt then
                mind.drift, mind.driftAt = (math.random() - 0.45) * 1.1, now + 2.5 + math.random() * 3
            end
            selectedSpacing = math.max(1.6, selectedSpacing + mind.drift)
        end
        local spacing = math.min(selectedSpacing, math.max(1.8, depth - 0.35))
        local goalGap = approachDirection and math.min(spacing, math.max(0.35, depth - 0.35)) or spacing
        local shoulderGap = math.sqrt(math.max(0, spacing * spacing - goalGap * goalGap))
        local lateralLimit = inside and spacing * 0.45 or math.huge
        local towardLead = math.min(lead:Dot(front), math.max(0, depth - goalGap - 0.25))
        local predicted = ballSide + front * towardLead + side * math.clamp(lead:Dot(side), -lateralLimit, lateralLimit)

        local progress, lateral = relative:Dot(front), relative:Dot(side)
        local driving = velocity:Dot(front)
        -- A lost step: they are behind this player's back, or going past on one side. A handler
        -- coming straight on is not past; standing in front of them is the whole point.
        --
        -- Measured in blacktop matches on 2026-11-11: backpedalling in the stance covers about 14
        -- studs/s and drivers come at 18 to 20, so a driver who is off to one side is past before
        -- the slide gets in front, long before they are actually level. The step counts as lost as
        -- soon as the time until they draw level is shorter than the time the slide across needs.
        local across = math.abs(lateral)
        local lostStep = progress < -0.25
            or (driving > 6 and across > 1.5 and progress < math.clamp(driving * (across / 15 + 0.05), 0.8, 7))
        -- Plainly beaten (behind the play, and they are going): nobody needs to think about that.
        local obvious = progress < 0.5 and driving > 8
        local running = mind.mode == "run"

        -- Beaten to the spot: aim for the nearest place on their way to the rim that can be
        -- reached first, or failing that the front of the rim.
        local ahead = goalGap
        if running and lostStep then
            local mySpeed = math.clamp(defense.pace or 16.5, 13, 24)
            local theirSpeed = math.max(driving, 6)
            local farthest = math.max(goalGap, depth - 3)
            ahead = farthest
            local reach = goalGap
            while reach < farthest do
                local spot = ballSide + front * reach
                if (spot - position).Magnitude / mySpeed <= reach / theirSpeed - 0.05 then
                    ahead = reach
                    break
                end
                reach += 1.5
            end
        end

        if progress < -0.25 then
            orbitSide = orbitSide or (lateral < 0 and -1 or 1)
        elseif progress >= math.min(1.6, goalGap * 0.75) and orbitSide then
            paintSide, orbitSide = orbitSide, nil
        end
        local waypoint = predicted + front * ahead
        if orbitSide then
            local clearance = math.clamp(spacing + 0.35, 2.1, 3.6)
            if running then
                -- Running them down from behind: go past their shoulder, not through their back.
                local passing = lateral * orbitSide < clearance - 0.4 and progress < 1.5
                waypoint = ballSide + front * ahead + side * orbitSide * (passing and clearance or clearance * 0.35)
            else
                local sideDepth = lateral * orbitSide < clearance - 0.4 and math.min(progress, 0) or goalGap
                waypoint = predicted + front * sideDepth + side * orbitSide * clearance
            end
        elseif shoulderGap > 0 and not running then
            paintSide = paintSide or (lateral < 0 and -1 or 1)
            waypoint += side * paintSide * shoulderGap
        elseif not inside then
            paintSide = nil
        end

        local delta = waypoint - position
        local gap = delta.Magnitude

        -- Stance or run. Running is for a lost step, and for covering a long way to a handler who
        -- is not close yet; everything else is done set in the stance.
        local wantRun = depth >= 7 and ((lostStep and gap > 2.5) or (gap > 9 and relative.Magnitude > 12))
        local stopRun = depth < 6 or gap < 1.6 or (not lostStep and gap < 4.5)
        if not running then
            if wantRun then
                mind.wantAt = mind.wantAt or now
                -- It takes a moment to realise the slide is lost.
                if now - mind.wantAt >= (human and (obvious and 0.03 or mind.decide) or 0) then
                    mind.mode, mind.modeAt, mind.stopAt, mind.ran = "run", now, nil, true
                end
            else
                mind.wantAt = nil
            end
        elseif stopRun then
            mind.stopAt = mind.stopAt or now
            if now - mind.stopAt >= (human and 0.08 or 0) and now - mind.modeAt >= (human and 0.3 or 0.12) then
                mind.mode, mind.modeAt, mind.wantAt, mind.sprint = "contain", now, nil, nil
            end
        else
            mind.stopAt = nil
        end
        -- Sprint while there is real ground to make up; ease off just before arriving.
        if mind.mode == "run" then
            if gap > (mind.sprint and 1.6 or 2.4) then mind.sprint = true else mind.sprint = nil end
        else
            mind.sprint = nil
        end

        local settleRadius = defense.mode == "Blatant" and (inside and 0.38 or 0.65) or (inside and 0.55 or 0.9)
        -- In front of a handler who is standing still, small shuffles are not mirrored.
        if human and mind.mode ~= "run" and velocity.Magnitude < 2.5 then settleRadius += 0.35 end
        if gap <= settleRadius + (stepping and 0 or (inside and 0.12 or 0.20)) then
            stepping = false
            return inside
        end
        stepping = true
        local cameraRight = planar(camera.CFrame.RightVector)
        if cameraRight.Magnitude < 0.1 then return inside end
        local right = cameraRight.Unit
        local forward = Vector2.new(right.Y, -right.X)
        local direction = delta.Unit
        useAxis(direction:Dot(right), gameKeys.D, gameKeys.A, desired, now)
        useAxis(direction:Dot(forward), gameKeys.W, gameKeys.S, desired, now)
        if mind.sprint then desired[sprint[2]] = true end
        return inside
    end

    function defense.watch(now)
        if rage.movementBlocked and rage.movementBlocked(now) then send({},now,true);return end
        if not defense.enabled then defense.stop(); return end
        if gui.Enabled or capturing then
            defense.stop()
            return
        end
        local bind = bindings["Auto Guard"]
        if not bind or not executorInput.keyDown(bind) then
            defense.stop(bind and ("Hold " .. bind.Name .. " to guard.") or "Set an Auto Guard bind to start.")
            return
        end
        if not automationAvailable() or pendingRelease or not robloxFocused()
            or input:GetFocusedTextBox() or shot or macro or jelly then
            defense.stop("Waiting for gameplay input.")
            return
        end
        if (defense.footwork or (defense.mode == "Blatant" and defense.teleport.enabled)) and defense.manualOverride then
            for _, command in ipairs(movement) do
                if executorInput.keyDown(command[1]) and not ours(command[2], now) then
                    defense.stop("Manual movement has priority.")
                    return
                end
            end
        end
        for _, key in ipairs(yieldingKeys) do
            -- The sprint key counts as the player's own only when this did not press it.
            if executorInput.keyDown(key) and not (key == sprint[1] and ours(sprint[2], now)) then
                defense.stop("Manual input has priority.")
                return
            end
        end
        -- Keep watching the handler between decisions, so their movement is known in detail.
        local watched = mind.root
        if watched and watched.Parent then
            local last = sightings[#sightings]
            if not last or now - last[1] >= 0.011 then
                local spot = watched.Position
                sightings[#sightings + 1] = {now, spot.X, spot.Z}
                while now - sightings[1][1] > 0.7 do table.remove(sightings, 1) end
            end
        end
        if now < nextSample then return end
        -- A person does not act on a metronome.
        nextSample = now + defense.response.value / 1000 * (paced() and (0.8 + math.random() * 0.5) or 1)
        local character, root = findCharacter()
        local team, goal = positiveTeamId(character, "Team"), characterGoal(character)
        if not root or not team or not goal then
            defense.stop("Waiting for an assigned team and court.")
            return
        end
        if trackedCharacter and (trackedCharacter ~= character or trackedRoot ~= root) then defense.stop() end
        trackedCharacter, trackedRoot = character, root
        local action = character:GetAttribute("Action") or ""
        if heldBall(character) or (not guardActions[action] and not antiStun.recovering(character)) then
            defense.stop("Waiting for defense.")
            return
        end
        local handler, opponent, opponentGoal, distance, ownsBall = closestHandler(character, root, team, goal, now)
        if not handler then
            defense.stop("Waiting for an opposing ball handler in range.")
            return
        end
        if handler ~= target then
            if mind.samples then closeTrace() end
            target, orbitSide, paintSide, approachDirection, lastPossessionAt = handler, nil, nil, nil, nil
            stepping = nil
            table.clear(axisCooldown)
            table.clear(sightings)
            table.clear(mind)
            -- How this possession is played: how late things are seen, how long deciding takes.
            mind.mode, mind.modeAt, mind.startedAt = "contain", now, now
            mind.reaction = 0.015 + math.random() * 0.04
            mind.decide = 0.10 + math.random() * 0.08
            mind.samples = {}
        end
        mind.root = opponent
        if ownsBall then lastPossessionAt = now end
        local teleported = defense.teleport.attempt(character, root, handler, opponent, opponentGoal, now, function() send({}, now, true) end)
        if teleported then
            distance = planar(root.Position - opponent.Position).Magnitude
            stepping, mind.sprint = nil, nil
            mind.velocityKnown, mind.filteredAt = nil, nil
        end
        -- Get set sooner for someone coming on fast.
        local closing = 0
        if mind.velocity then
            local toMe = planar(root.Position - opponent.Position)
            if toMe.Magnitude > 0.5 then closing = math.max(0, mind.velocity:Dot(toMe.Unit)) end
        end
        local stance = distance <= defense.stance.value + (held[guard[2]] and 0.8 or 0) + math.clamp(closing * 0.4, 0, 6)
        local desired = {}
        local inside = not teleported and defense.footwork and footwork(root, opponent, opponentGoal, desired, now)
        -- Chasing, the stance comes off: it only slides, and the sprint needs a forward run.
        if mind.sprint then stance = false end
        if stance then desired[guard[2]] = true end
        send(desired, now)
        -- A thin record of the possession, relative to the rim being defended.
        local samples = mind.samples
        if samples and #samples < 7 * 160 and now >= (mind.traceAt or 0) then
            mind.traceAt = now + 0.09
            local rim = opponentGoal.Position
            local keys = (held[gameKeys.W[2]] and 1 or 0) + (held[gameKeys.A[2]] and 2 or 0) + (held[gameKeys.S[2]] and 4 or 0)
                + (held[gameKeys.D[2]] and 8 or 0) + (held[guard[2]] and 16 or 0) + (held[sprint[2]] and 32 or 0)
            local count = #samples
            samples[count + 1] = math.floor((now - mind.startedAt) * 100 + 0.5) / 100
            samples[count + 2], samples[count + 3] = tenth(root.Position.X - rim.X), tenth(root.Position.Z - rim.Z)
            samples[count + 4], samples[count + 5] = tenth(opponent.Position.X - rim.X), tenth(opponent.Position.Z - rim.Z)
            samples[count + 6], samples[count + 7] = keys, mind.mode == "run" and 1 or 0
            mind.traceSeconds = samples[count + 1]
        end
        local status = teleported and "Teleported to handler" or mind.mode == "contest" and "Closing into shooter" or mind.mode == "run" and "Recovering" or orbitSide and "Circling goal-side"
            or (stance and (inside and "Protecting the rim" or "Guard stance") or "Closing distance")
        defense.status.Text = string.format("%s  ·  %s  ·  %.1f studs", defense.mode, status, distance)
    end
end

local function stopMacro(message)
    local active = macro
    if not active then return end
    macro = nil
    if active.tap then releaseKey(active.tap) end
    for index = #active.modifiers, 1, -1 do releaseKey(active.modifiers[index]) end
    if message and not stopped then
        hubControls.macroStatus = message
        refresh()
    end
end

local function beginMacro(move, sequence, step)
    if stopped or pendingRelease or macro or shot or jelly or capturing or input:GetFocusedTextBox()
        or not robloxFocused() then
        return
    end
    if not automationAvailable() then
        hubControls.macroStatus = "Keyboard input is unavailable on this device."
        refresh()
        return
    end
    local character, root = findCharacter()
    local ball = heldBall(character)
    if not ball then
        hubControls.macroStatus = "Pick up a ball before running a move."
        refresh()
        return
    end
    defense.stop()
    local taps, hand = move[2]
    if move == spinMove then
        hand = ballHand(character, root, ball)
        if not hand then
            hubControls.macroStatus = "Wait until the ball is clearly in one hand, then try Spin."
            refresh()
            return
        end
        taps = move.hands[hand]
    end
    for letter in taps:gmatch(".") do
        if executorInput.keyDown(gameKeys[letter][1]) then
            hubControls.macroStatus = "Release the dribble keys first."
            refresh()
            return
        end
    end
    local active = {move = move, taps = taps, index = 1, modifiers = {}, nextAt = os.clock() + 0.025, character = character}
    active.sequence, active.step = sequence, step
    macro = active
    for modifier in (move[3] or ""):gmatch("%S+") do
        local key = gameKeys[modifier]
        if not executorInput.keyDown(key[1]) then
            table.insert(active.modifiers, key[2])
            keypress(key[2])
        end
    end
    hubControls.macroStatus = "Running " .. move[1] .. (hand and (" from " .. hand:lower() .. " hand") or "") .. "…"
    refresh()
end

local function watchMacro(now)
    local active = macro
    if not active then return end
    if not automationAvailable() or not robloxFocused() or input:GetFocusedTextBox() or not active.character.Parent then
        stopMacro("Move interrupted.")
        return
    end
    local spin = active.move == spinMove
    if (spin or active.sequence) and (findCharacter() ~= active.character or not heldBall(active.character)) then
        stopMacro("Move interrupted when possession changed.")
        return
    end
    if now < active.nextAt then return end
    if active.tap then
        local key = active.tap
        active.tap = nil
        releaseKey(key)
        active.index += 1
        if active.index > #active.taps then
            local nextStep = active.sequence and active.step + 1
            if nextStep and active.sequence[nextStep] then
                stopMacro()
                beginMacro(active.sequence[nextStep], active.sequence, nextStep)
                if macro then macro.nextAt = now + hubControls.cadence.value / 1000 end
            else
                stopMacro(active.sequence and "Combo complete." or ("Sent " .. active.move[1] .. "."))
            end
            return
        end
        -- A full Spin needs all three taps before the game commits to the two-key move.
        active.nextAt = spin and (active.tapAt + spinMove.cadence) or (now + hubControls.cadence.value / 1000 - 0.028)
        if now < active.nextAt then return end
    end
    local letter = active.taps:sub(active.index, active.index)
    local key = gameKeys[letter]
    if executorInput.keyDown(key[1]) then
        stopMacro("A dribble key is already held.")
        return
    end
    active.tap = key[2]
    active.tapAt = now
    active.nextAt = now + (spin and spinMove.tapLength or 0.028)
    keypress(active.tap)
end

do
    local defaults = {enabled = false, guardOnly = false, finishes = true, range = 8, lead = 180, cooldown = 850, cone = 160}
    local panel = create("ScrollingFrame", pages.Defense, {Name = "WizardAutoBlockSettings", Visible = false,
        Position = UDim2.fromOffset(0, 83), Size = UDim2.new(1, 0, 1, -83),
        CanvasSize = UDim2.fromOffset(0, 470), BackgroundTransparency = 1, BorderSizePixel = 0,
        ScrollBarThickness = 3, ScrollBarImageColor3 = colors.accent})
    autoBlock.pane = panel
    autoBlock.toggle = switch(panel, "Auto Block", 0, 0)
    autoBlock.guardSwitch = switch(panel, "Only while holding Auto Guard", 350, 0)
    autoBlock.finishesSwitch = switch(panel, "Block dunks and layups", 0, 41)
    autoBlock.bindButton = button(panel, "Set Auto Block keybind", 350, 41, 316, 32, colors.card, colors.text)
    -- What happened to the last attempt to bind the key (shown right here, not only on the Keybinds page).
    autoBlock.bindNote = label(panel, "Click, then press a key. Backspace clears it.", 350, 76, 316, 18, 11, Enum.Font.Gotham, colors.muted)
    autoBlock.range = slider(panel, "Block distance", 0, 102, 3, 14, defaults.range, "%d studs")
    autoBlock.lead = slider(panel, "Jump lead before release", 350, 102, 0, 400, defaults.lead, "%d ms")
    autoBlock.cooldown = slider(panel, "Block cooldown", 0, 166, 500, 2000, defaults.cooldown, "%d ms")
    autoBlock.cone = slider(panel, "Facing angle", 350, 166, 60, 180, defaults.cone, "%d°")
    local explanation = label(panel, "Tracks opposing shooters on your court. Uses the rising shot meter when available, checks distance and sight, and presses Space once per attempt. Rage free jumps are suppressed for automatic blocks.",
        0, 243, 674, 69, 12, Enum.Font.Gotham, colors.muted)
    explanation.TextWrapped = true
    autoBlock.status = label(panel, "Auto Block is off.", 0, 333, 674, 70, 12, Enum.Font.GothamMedium, colors.text)
    autoBlock.status.TextWrapped = true
    local observations = setmetatable({}, {__mode = "k"})
    -- Every shot meter the game has announced, by shooter: when it started, its style, and how
    -- far it has moved. The game sends these for every player on the server.
    local packets = setmetatable({}, {__mode = "k"})
    -- Per meter style: the usual time from a meter starting to it being released (or peaking),
    -- learned from the shots seen in this server. Starts at the common 0.39 s.
    local typical = {}
    autoBlock.trace = {}    -- Blocks waiting to be written to the log (see shotLog.flush).
    local heldUntil, nextScan, nextBlock, sent = nil, 0, 0, 0
    local function settle(packet)
        if packet.connection then packet.connection:Disconnect(); packet.connection = nil end
        if packet.done then return end
        packet.done = true
        local lasted = (packet.farAt or packet.at) - packet.at
        if (packet.count or 0) >= 8 and lasted >= .22 and lasted <= .7 then
            typical[packet.style] = typical[packet.style] and (typical[packet.style] * .7 + lasted * .3) or lasted
        end
    end
    local function meterEvent(name)
        local aero = game:GetService("ReplicatedStorage"):FindFirstChild("Aero")
        local services = aero and aero:FindFirstChild("AeroRemoteServices")
        local folder = services and services:FindFirstChild("MeterService")
        local event = folder and folder:FindFirstChild(name)
        return event and event:IsA("RemoteEvent") and event or nil
    end
    -- Looked for again until found: after a teleport this script starts before the game's remotes exist.
    function autoBlock.connect()
        if not autoBlock.startsLinked then
            local event = meterEvent("RegisterPacket")
            if event then
                autoBlock.startsLinked = true
                connect(event.OnClientEvent, function(character, style)
                    if typeof(character) ~= "Instance" or style == "None" or character == (findCharacter()) then return end
                    local earlier = packets[character]
                    if earlier then settle(earlier) end
                    local packet = {at = os.clock(), style = type(style) == "string" and style or "?", count = 0}
                    packets[character] = packet
                    packet.connection = character:GetAttributeChangedSignal("meterOffset"):Connect(function()
                        local offset = character:GetAttribute("meterOffset")
                        if typeof(offset) ~= "Vector2" then return end
                        local seenAt = os.clock()
                        packet.count += 1
                        if not packet.first then
                            packet.first, packet.far, packet.farAt = offset, 0, seenAt
                            return
                        end
                        local far = (offset - packet.first).Magnitude
                        if far > packet.far + .0005 then
                            packet.far, packet.farAt = far, seenAt
                            packet.fill, packet.fillAt = math.abs(offset.Y), seenAt
                            if not packet.fill0 then packet.fill0, packet.fill0At = packet.fill, seenAt end
                        elseif seenAt - packet.farAt > .06 then
                            -- It has stopped rising: released, or held past the top.
                            settle(packet)
                        end
                    end)
                end)
            end
        end
        if not autoBlock.endsLinked then
            local event = meterEvent("UnregisterPacket")
            if event then
                autoBlock.endsLinked = true
                connect(event.OnClientEvent, function(character)
                    local packet = typeof(character) == "Instance" and packets[character]
                    if packet then settle(packet) end
                end)
            end
        end
        if autoBlock.startsLinked and not autoBlock.linked then
            autoBlock.linked = true
            table.insert(connections, {Disconnect = function()
                for _, packet in pairs(packets) do
                    if packet.connection then packet.connection:Disconnect(); packet.connection = nil end
                end
            end})
        end
    end
    local function actionOf(character)
        local action = character:GetAttribute("Action")
        return type(action) == "string" and action:lower():gsub("[^%w]", "") or ""
    end
    local function sameCourt(me, mine, other, theirs)
        return sameDefenseCourt(me, mine, other, theirs)
    end
    local function visible(me, root, other, otherRoot)
        local ray = RaycastParams.new()
        ray.FilterType = Enum.RaycastFilterType.Exclude
        ray.FilterDescendantsInstances = {me, other}
        ray.RespectCanCollide = true
        local origin = root.Position + Vector3.new(0, 1.5, 0)
        local finish = otherRoot.Position + Vector3.new(0, 1.5, 0)
        return workspace:Raycast(origin, finish - origin, ray) == nil
    end
    -- Decides whether now is the moment to jump at this shooter. Returns the record for the shot
    -- and a short reason when it is.
    local function cue(character, root, now)
        if not defense.blockPerimeter and defense.perimeterShot(character, root, characterGoal(character)) then return end
        local action = actionOf(character)
        local finish = action:find("dunk", 1, true) or action:find("layup", 1, true) or action:find("clutch", 1, true)
        local ping = math.clamp(network.median or network.latest or 0, 0, .25)
        local lead = autoBlock.lead.value / 1000
        local packet = packets[character]
        if packet and now - packet.at <= 1.5 then
            -- The game announced this shot. Not a gather, a dribble move or a pass that also draws a meter.
            observations[character] = nil
            local idle = action == "" or action == "moving" or action:find("gather", 1, true)
                or action:find("dribbl", 1, true) or action:find("pass", 1, true)
            if packet.fired or packet.done or idle then return end
            if finish and not autoBlock.finishes then return end
            -- Time left until the usual release for this meter style...
            local remaining = (typical[packet.style] or .39) - (now - packet.at)
            local why = "meter clock"
            -- ...or, on the Vertical meter whose top is known (1.49), from how fast it is filling.
            if packet.style == "Vertical" and packet.fill0 and packet.fillAt - packet.fill0At >= .045
                and packet.fill > packet.fill0 + .05 then
                local rate = (packet.fill - packet.fill0) / (packet.fillAt - packet.fill0At)
                remaining = (1.49 - packet.fill) / rate - (now - packet.fillAt)
                why = "meter fill"
            end
            packet.remaining = remaining
            -- The jump reaches the server a ping later than this decision is made on what was seen.
            if remaining <= lead + ping and remaining >= -.06 then
                return packet, (finish and "finish, " or "shot, ") .. why
            end
            return
        end
        -- No announcement seen (the remotes were not found): go by the shooter's action alone.
        local shooting = action:find("shoot", 1, true) or action:find("jump", 1, true) or action:find("fade", 1, true)
        local record = observations[character]
        if not (shooting or (autoBlock.finishes and finish)) then observations[character] = nil; return end
        if not record then record = {began = now}; observations[character] = record end
        if heldBall(character) then record.lastBall = now end
        if record.fired or not record.lastBall or now - record.lastBall > .35 then return end
        record.remaining = .39 - (now - record.began)
        if record.remaining <= lead + ping then
            return record, finish and "finish, no meter seen" or "shot, no meter seen"
        end
    end
    function autoBlock.stop(message)
        if heldUntil then releaseKey(dunk.virtualKey); heldUntil = nil end
        nextScan = 0
        table.clear(observations)
        if message then autoBlock.status.Text = message end
    end
    function autoBlock.refresh()
        showSwitch(autoBlock.toggle, autoBlock.enabled)
        showSwitch(autoBlock.guardSwitch, autoBlock.guardOnly)
        showSwitch(autoBlock.finishesSwitch, autoBlock.finishes)
        autoBlock.bindButton.Text = capturing == "Auto Block" and "Press a key…"
            or ("Auto Block key  ·  " .. (bindings["Auto Block"] and bindings["Auto Block"].Name or "Not bound"))
        appearance.paint(autoBlock.bindButton, "TextColor3", capturing == "Auto Block" and "accent" or "text")
        if not autoBlock.enabled then autoBlock.status.Text = "Auto Block is off." end
    end
    function autoBlock.capture()
        return {enabled = autoBlock.enabled, guardOnly = autoBlock.guardOnly, finishes = autoBlock.finishes,
            range = autoBlock.range.value, lead = autoBlock.lead.value, cooldown = autoBlock.cooldown.value, cone = autoBlock.cone.value}
    end
    function autoBlock.apply(saved)
        saved = type(saved) == "table" and saved or {}
        autoBlock.stop()
        autoBlock.enabled, autoBlock.guardOnly, autoBlock.finishes = saved.enabled == true, saved.guardOnly == true, saved.finishes ~= false
        for _, field in ipairs({"range", "lead", "cooldown", "cone"}) do
            local value = saved[field]
            showSlider(autoBlock[field], type(value) == "number" and value == value and value or defaults[field])
        end
        autoBlock.refresh()
    end
    function autoBlock.bind(connectControl, bindKey, redraw)
        for _, entry in ipairs({{autoBlock.toggle, "enabled"}, {autoBlock.guardSwitch, "guardOnly"}, {autoBlock.finishesSwitch, "finishes"}}) do
            local key = entry[2]
            connectControl(entry[1].row.Activated, function()
                autoBlock[key] = not autoBlock[key]
                autoBlock.stop(); autoBlock.refresh(); redraw()
            end)
        end
        connectControl(autoBlock.bindButton.Activated, function() bindKey("Auto Block") end)
        local function tab(blocking)
            defense.guardPane.Visible, panel.Visible = not blocking, blocking
            appearance.paint(defense.guardTab, "TextColor3", blocking and "text" or "accent")
            appearance.paint(defense.blockTab, "TextColor3", blocking and "accent" or "text")
        end
        connectControl(defense.guardTab.Activated, function() tab(false) end)
        connectControl(defense.blockTab.Activated, function() tab(true) end)
        tab(false); autoBlock.apply(nil)
    end
    function autoBlock.jumpOnly(character)
        if not gameplaySafety.ready or heldBall(character) then return false end
        local body,model=gameplaySafety.actor()
        if model~=character or not body or body:GetAttribute("CanMove")==false then return false end
        if antiContestV2.diagnostics and antiContestV2.diagnostics().active then return false end
        local services=body.Services and body.Services.InputService
        local sender=services and services.Jump
        if type(sender)~="table" or type(sender.Fire)~="function" then return false end
        -- Space also sends Shoot=true in the native keyboard handler. A defensive jump must not.
        local ok=pcall(sender.Fire,sender)
        if ok and antiContestV2.recorder then pcall(antiContestV2.recorder.emit,"auto_block_jump_only",{}) end
        return ok
    end

    function autoBlock.watch(now)
        if rage.movementBlocked and rage.movementBlocked(now) then autoBlock.stop();return end
        if heldUntil and now >= heldUntil then releaseKey(dunk.virtualKey); heldUntil = nil end
        -- What became of the last jump: did the game put this player into its block?
        local pending = autoBlock.pending
        if pending then
            local mine = findCharacter()
            if mine and actionOf(mine):find("block", 1, true) then pending.entry.blocking = true end
            if now >= pending.untilAt then
                if #autoBlock.trace < 12 then table.insert(autoBlock.trace, pending.entry) end
                autoBlock.pending = nil
            end
        end
        if not (autoBlock.startsLinked and autoBlock.endsLinked) and now >= (autoBlock.linkAt or 0) then
            autoBlock.linkAt = now + .5
            autoBlock.connect()
        end
        if not autoBlock.enabled or traveling or gui.Enabled or not automationAvailable() or not robloxFocused()
            or input:GetFocusedTextBox() then
            if heldUntil or next(observations) then autoBlock.stop() end
            return
        end
        if now < nextScan then return end
        nextScan = now + .025
        -- Observe the end of attempts even while our own block animation/cooldown runs.
        for model in pairs(observations) do
            local action = actionOf(model)
            if not model.Parent or not (action == "shooting" or action == "jumpshot" or action == "clutchshot"
                or action:find("dunk", 1, true) or action:find("layup", 1, true)) then observations[model] = nil end
        end
        local character, root = findCharacter()
        if not root or heldBall(character) then autoBlock.status.Text = "Waiting until you are defending without the ball."; return end
        if character:GetAttribute("CanMove") == false or character:GetAttribute("InAir") == true then return end
        if rage.diagnostics and rage.diagnostics().jumping then return end
        if autoBlock.guardOnly and not (defense.enabled and bindings["Auto Guard"] and executorInput.keyDown(bindings["Auto Guard"])) then
            autoBlock.status.Text = "Hold the Auto Guard bind to enable blocking."; return
        end
        if executorInput.keyDown(dunk.key) or shot then return end
        local team, goal = positiveTeamId(character, "Team"), characterGoal(character)
        if not team then autoBlock.status.Text = "Waiting for an assigned team."; return end
        local folder = workspace:FindFirstChild("Characters")
        local best, bestRecord, bestWhy, distance = nil, nil, nil, math.huge
        for _, other in ipairs(folder and folder:GetChildren() or {}) do
            local otherTeam = other ~= character and positiveTeamId(other, "Team")
            local otherRoot = otherTeam and otherTeam ~= team and other:FindFirstChild("HumanoidRootPart")
            if otherRoot and sameCourt(character, goal, other, characterGoal(other)) then
                local delta = otherRoot.Position - root.Position
                local gap = Vector3.new(delta.X, 0, delta.Z).Magnitude
                if gap <= autoBlock.range.value and gap < distance and math.abs(delta.Y) <= 10 then
                    local flat = Vector3.new(delta.X, 0, delta.Z)
                    local facing = gap < .1 or root.CFrame.LookVector:Dot(flat.Unit) >= math.cos(math.rad(autoBlock.cone.value / 2))
                    local record, why = cue(other, otherRoot, now)
                    if facing and record and visible(character, root, other, otherRoot) then
                        best, bestRecord, bestWhy, distance = other, record, why, gap
                    end
                end
            end
        end
        if not best then autoBlock.status.Text = "Watching for a nearby opposing shot."; return end
        if now < nextBlock or heldUntil then return end
        local ok = autoBlock.jumpOnly(character)
        if not ok then autoBlock.status.Text = "Waiting for native block control; no shot key sent.";return end
        bestRecord.fired = true
        nextBlock = now + autoBlock.cooldown.value / 1000
        sent += 1
        autoBlock.status.Text = string.format("Block sent · %.1f studs · %s · %d total", distance, bestWhy, sent)
        -- Logged (between shots, with everything else) so the timing can be tuned from real games.
        local function ms(seconds) return seconds and math.floor(seconds * 1000 + .5) or nil end
        autoBlock.pending = {untilAt = now + .9, entry = {version = 4, at = os.time(), block = bestWhy,
            gap = math.floor(distance * 10 + .5) / 10, style = bestRecord.style, action = (actionOf(best)),
            elapsed = bestRecord.at and ms(now - bestRecord.at) or nil, remaining = ms(bestRecord.remaining),
            usual = bestRecord.style and ms(typical[bestRecord.style] or .39) or nil,
            lead = autoBlock.lead.value, ping = ms(network.median)}}
    end
    function autoBlock.diagnostics() return {sent = sent, held = heldUntil ~= nil, cooldownUntil = nextBlock} end
end


local function restoreAttribute(state, name)
    local field = state.fields[name]
    if not field then return end
    if state.character.Parent and state.character:GetAttribute(name) == field.written then
        state.character:SetAttribute(name, field.base)
    end
    state.fields[name] = nil
end

local function restoreMovement()
    if not motion then return end
    for name in pairs(motion.fields) do restoreAttribute(motion, name) end
    motion = nil
end

local function tuneAttribute(state, name, scale, add, ceiling)
    if scale == 1 and add == 0 then
        restoreAttribute(state, name)
        return
    end
    local current = state.character:GetAttribute(name)
    if type(current) ~= "number" then return end
    local field = state.fields[name]
    if not field or current ~= field.written then field = {base = current} end
    field.written = math.clamp(field.base * scale + add, 0, ceiling)
    state.fields[name] = field
    if current ~= field.written then state.character:SetAttribute(name, field.written) end
end

local dribbleMotion = {}
function rage.playerMovementEnabled()
    return config.movement or config.boost or config.glide
end
function rage.usesMovementDriver()
    return (rage.enabled and rage.speed) or rage.playerMovementEnabled()
end
function dribbleMotion.isMove(character)
    local action=tostring(character and character:GetAttribute("Action") or ""):lower()
    return action=="dribbling" or (action=="exitingpost" and character:GetAttribute("GatherType")=="SpinGather")
end
function rage.movementBlocked(now)
    return (rage.courtTeleport.blocksMovement and rage.courtTeleport.blocksMovement(now))
        or (defense.teleport.blocksMovement and defense.teleport.blocksMovement(now)) or false
end
do
    local actor, possession, lastDribble
    function dribbleMotion.reset()
        actor, possession, lastDribble = nil, nil, nil
    end
    local function strength(control)
        local value = control and control.value
        local normalized=type(value)=="number" and value==value and math.clamp(value,0,300)/100 or 0
        return normalized>1 and normalized*normalized or normalized
    end
    function dribbleMotion.sample(character, ball, now, scriptedDribble)
        if actor~=character or possession~=ball then
            actor, possession, lastDribble = character, ball, nil
        end
        local action=tostring(character and character:GetAttribute("Action") or ""):lower()
        local active=dribbleMotion.isMove(character)
        local allowed=action=="" or action=="moving" or active
        if not ball or not allowed
            or character:GetAttribute("CFrame")~=nil or character:GetAttribute("SeatCFrame")~=nil
            or character:GetAttribute("Stunned")==true or character:GetAttribute("Fouled")==true
            or shot or traveling or not robloxFocused() or not gameplaySafety.ready
            or antiStun.recovering(character) or input:GetFocusedTextBox()
            or rage.movementBlocked(now) then
            lastDribble=nil
            return 1,1,0,0
        end
        if active then lastDribble=now end
        if character:GetAttribute("CanMove")==false and not scriptedDribble then return 1,1,0,0 end
        local elapsed=lastDribble and math.max(0,now-lastDribble) or math.huge
        local boost=config.boost and elapsed<=.21 and strength(hubControls.boostStrength) or 0
        local glide=config.glide and elapsed<=.40 and strength(hubControls.glideStrength) or 0
        return (1+.12*boost)*(1+.08*glide*math.max(0,1-elapsed/.40)),1,boost,glide
    end
end

local nextMotionSample=0
local function watchMovement(now)
    if now<nextMotionSample then return end
    nextMotionSample=now+.1
    restoreMovement()
    if not rage.playerMovementEnabled() then dribbleMotion.reset();hubControls.movementStatus.Text="Movement tuning is off.";return end
    if rage.ownsSpeed() then
        dribbleMotion.reset();hubControls.movementStatus.Text="Rage Speed override is active. Turn it off to use Player movement and dribble effects.";return
    end
    local state=rage.diagnostics()
    hubControls.movementStatus.Text=state.source=="player" and string.format("Player target %.1f → %.1f studs/s · %s",state.nativeTarget or 0,state.effective or 0,state.phase or "Waiting")
        or "Waiting for the native movement controller."
end

do
    local state, driver
    local scriptedDribbleBase
    local nextDriverScan, nextStatus = 0, 0
    local movementActions = {[""] = true, moving = true, dribbling = true, guarding = true,
        defending = true, defensivestance = true, contesting = true}
    local telemetry = {version = 2, events = {}, nextFlush = 0}
    local function finite(value) return type(value) == "number" and value == value and math.abs(value) < 1e6 end
    local function actionOf(character)
        local value = character:GetAttribute("Action")
        return type(value) == "string" and value:lower():gsub("[^%w]", "") or ""
    end
    local function planar(v) return Vector3.new(v.X, 0, v.Z) end
    local function note(reason, now)
        if state and state.lastReason == reason then return end
        if state then state.lastReason = reason end
        telemetry.events[#telemetry.events + 1] = {at = os.time(), event = reason,
            withBall = state and state.ball ~= nil or false,
            requested = state and state.requested or 0, effective = state and state.effective or 0}
        while #telemetry.events > 160 do table.remove(telemetry.events, 1) end
        telemetry.dirty = true
        if not telemetry.lastWarn or now - telemetry.lastWarn >= .7 then
            telemetry.lastWarn = now
            warn(prefix .. "Rage: " .. reason)
        end
    end
    local function detach()
        if driver then
            if driver.accelerationWrapper and rawget(driver.object,"GetAcceleration")==driver.accelerationWrapper then
                rawset(driver.object,"GetAcceleration",driver.accelerationPrevious)
            end
            if driver.correction then pcall(driver.correction.Disconnect,driver.correction) end
            if rawget(driver.object, "Update") == driver.wrapper then rawset(driver.object, "Update", driver.previous) end
            pcall(function()
                if driver.lastVelocity and driver.velocity.Parent and driver.velocity.Velocity == driver.lastVelocity then
                    local restored=driver.baseVelocity
                    if driver.scriptedVelocity then
                        restored=nil
                        if state and scriptedDribbleBase then
                            local v=scriptedDribbleBase(driver,state.character,os.clock())
                            if v then
                                restored=Vector3.new(v.X,driver.velocity.Velocity.Y,v.Z)
                            end
                        end
                    end
                    if restored then driver.velocity.Velocity=restored end
                end
            end)
        end
        driver = nil
    end
    function rage.ownsSpeed() return rage.enabled and rage.speed end
    function rage.baseSpeed(character)
        return state and state.character == character and state.nativeSpeed or nil
    end
    function rage.stop()
        dribbleMotion.reset()
        if rage.fly.stop then rage.fly.stop("Rage paused") end
        detach()
        if state then for name in pairs(state.fields) do restoreAttribute(state, name) end end
        state, nextDriverScan, nextStatus = nil, 0, 0
    end
    local function recover(reason, now)
        if not state then return end
        state.recoverUntil = math.max(state.recoverUntil or 0, now + 1)
        if state.effective and state.effective > 0 then
            local base = state.nativeSpeed or 17
            state.ceiling = math.max(base, math.min(state.ceiling or math.huge, state.effective * .80))
        end
        note(reason .. "; returning to native movement before retrying", now)
    end
    local speedRecoveryLimits={}
    local expectedMoveUntil=0
    local pendingRejection
    local function speedProfile()
        return tostring(game.PlaceId).."|"..tostring(game.PlaceVersion).."|"..string.format("%.2f",state.nativeSpeed)
            .."|"..(state.ball and "ball" or "free")
    end
    function rage.clearSpeedRecovery()
        table.clear(speedRecoveryLimits)
        pendingRejection=nil
        if state then state.ceiling=nil end
    end
    -- Call before an intentional reposition, and renew if it takes longer than the window.
    function rage.pauseMovement(seconds)
        local now=os.clock()
        local duration=finite(seconds) and math.clamp(seconds,0,10) or 1.5
        expectedMoveUntil=math.max(expectedMoveUntil,now+duration)
        pendingRejection=nil
        if not state then return end
        state.recoverUntil=math.max(state.recoverUntil or 0,expectedMoveUntil)
        state.lastPosition,state.lastAt,state.lastBoostAt,state.lastBoosting=nil,nil,nil,false
        local attached=driver
        if attached and attached.proxy.Parent then
            local v=attached.proxy.AssemblyLinearVelocity
            attached.proxy.AssemblyLinearVelocity=Vector3.new(0,v.Y,0)
        end
    end
    function rage.captureSpeedRecovery() return table.clone(speedRecoveryLimits) end
    function rage.applySpeedRecovery(saved)
        if type(saved)~="table" then return end
        local count=0
        for key,value in pairs(saved) do
            local base,mode
            if type(key)=="string" then base,mode=key:match("^%d+|%d+|(%d+%.%d+)|(%a+)$") end
            base=tonumber(base)
            if base and (mode=="ball" or mode=="free") and finite(value) and value>=base and value<=150 then
                speedRecoveryLimits[key]=math.min(speedRecoveryLimits[key] or math.huge,value)
                count+=1;if count>=64 then break end
            end
        end
        if state and state.profile then state.ceiling=speedRecoveryLimits[state.profile] end
    end
    function rage.serverMove(frame)
        local attached=driver
        if not attached or not state or not attached.proxy.Parent then return end
        local now=os.clock()
        local fresh=state.lastBoostAt and now-state.lastBoostAt<.4 and state.lastBoosting
        local action=actionOf(state.character)
        local scripted=scriptedDribbleBase and scriptedDribbleBase(attached,state.character,now)~=nil
        local free=(state.character:GetAttribute("CanMove")~=false or scripted) and (movementActions[action] or scripted)
            and state.character.Parent and rawget(attached.owner,"ProxyCharacter")==attached.proxy
            and type(attached.owner.data)=="table" and attached.owner.data.model==state.character
            and state.character:GetAttribute("Stunned")~=true and state.character:GetAttribute("Fouled")~=true
            and state.character:GetAttribute("Blocked")~=true and not antiStun.recovering(state.character)
            and state.character:GetAttribute("CFrame")==nil and state.character:GetAttribute("SeatCFrame")==nil
            and not shot and not stopped and not traveling and robloxFocused() and gameplaySafety.ready
            and now>=expectedMoveUntil
        local gap=frame and state.lastBoostPosition and planar(frame.Position-state.lastBoostPosition).Magnitude or 0
        local rejected=fresh and free and finite(state.effective) and finite(state.nativeSpeed)
            and state.effective>state.nativeSpeed+.5 and gap>math.max(3,state.effective*.2)
        local learned=false
        if rejected then
            local confirmed=pendingRejection and pendingRejection.profile==state.profile
                and now-pendingRejection.at<=30
            recover("Server reposition during boosted movement",now)
            if confirmed and state.profile then
                speedRecoveryLimits[state.profile]=state.ceiling
                pendingRejection=nil
                learned=true
            else
                pendingRejection=state.profile and {profile=state.profile,at=now} or nil
            end
        else
            pendingRejection=nil
        end
        if fresh then
            local v=attached.proxy.AssemblyLinearVelocity
            attached.proxy.AssemblyLinearVelocity=Vector3.new(0,v.Y,0)
        end
        state.recoverUntil=math.max(state.recoverUntil or 0,now+.75)
        state.lastPosition,state.lastAt,state.lastBoostAt,state.lastBoosting=nil,nil,nil,false
        state.corrections=(state.corrections or 0)+1
        if antiContestV2.recorder then
            pcall(antiContestV2.recorder.emit,"speed_server_reposition",{gap=gap,reduced=learned,suspected=rejected,
                ceiling=state.ceiling,requested=state.requested,position=frame and frame.Position})
        end
    end

    local function observe(character, root, now)
        state.nativeSpeed = character:GetAttribute("WalkSpeed")
        if not finite(state.nativeSpeed) or state.nativeSpeed <= 0 then state.nativeSpeed = 17 end
        local ball = heldBall(character)
        if not state.seenPossession then
            state.ball, state.seenPossession = ball, true
            if ball then state.settleUntil = now + .25 end
        elseif ball ~= state.ball then
            local previous = state.ball
            state.ball = ball
            if ball then
                state.settleUntil = now + .3
                state.clampPickup = true
                note("Ball acquired; settling speed for pickup", now)
            elseif previous and movementActions[actionOf(character)] and now > (state.expectedLossUntil or 0)
                and not (shot and (shot.sentAt or shot.releasedAt)) then
                recover("Unexpected possession loss", now)
            end
        end
        local profile=speedProfile()
        if state.profile~=profile then state.profile=profile;state.ceiling=speedRecoveryLimits[profile] end
        if not movementActions[actionOf(character)] or shot then state.expectedLossUntil = now + 1.8 end
    end
    scriptedDribbleBase=function(attached,character,now)
        local owner,proxy=attached.owner,attached.proxy
        if not state or state.character~=character or driver~=attached or not (config.boost or config.glide)
            or rage.ownsSpeed() or not dribbleMotion.isMove(character) or not state.ball or heldBall(character)~=state.ball
            or not character.Parent or not proxy.Parent or rawget(owner,"ProxyCharacter")~=proxy
            or rawget(attached.object,"Root")~=proxy or rawget(attached.object,"RealRoot")~=state.root
            or rawget(attached.object,"MovementVelocity")~=attached.velocity or attached.velocity.Parent~=proxy
            or type(owner.data)~="table" or owner.data.model~=character
            or now<expectedMoveUntil or now<(state.recoverUntil or 0) or now<(state.settleUntil or 0)
            or character:GetAttribute("CanMove")~=false or character:GetAttribute("CFrame")~=nil or character:GetAttribute("SeatCFrame")~=nil
            or character:GetAttribute("Stunned")==true or character:GetAttribute("Fouled")==true or character:GetAttribute("Blocked")==true
            or shot or gui.Enabled or not robloxFocused() or traveling or stopped or not gameplaySafety.ready
            or antiStun.recovering(character) or input:GetFocusedTextBox() or rage.movementBlocked(now)
            or proxy.Anchored or not finite(owner.lastValidHeight) or math.abs(proxy.Position.Y-owner.lastValidHeight)>1.25
            or math.abs(proxy.AssemblyLinearVelocity.Y)>5 or (owner.MainAlignPosition and owner.MainAlignPosition.Enabled)
            or type(owner.GetAttribute)~="function" then return nil end
        for _,hold in pairs({owner.MainMovementPosition,owner.Movement and owner.Movement.MovementPosition}) do
            if hold and (hold.MaxForce.X>0 or hold.MaxForce.Z>0) then return nil end
        end
        local ok,server=pcall(owner.GetAttribute,owner,"ServerVelocity")
        local actionOk,action=pcall(owner.GetAttribute,owner,"Action")
        local postSpin=false
        if action=="ExitingPost" then
            local gatherOk,gather=pcall(owner.GetAttribute,owner,"GatherType")
            postSpin=gatherOk and gather=="SpinGather" and character:GetAttribute("GatherType")=="SpinGather"
        end
        if not ok or not actionOk or action~=character:GetAttribute("Action") or (action~="Dribbling" and not postSpin) or typeof(server)~="Vector3"
            or not finite(server.X) or not finite(server.Y) or not finite(server.Z) or math.abs(server.Y)>.1 then return nil end
        local vector=planar(server)
        return vector.Magnitude>.01 and vector or nil
    end
    local function boost(attached, character, root, now, dt)
        observe(character, root, now)
        local object, proxy, velocity = attached.object, attached.proxy, attached.velocity
        local current = velocity.Velocity
        local original = planar(current)
        attached.baseVelocity = current
        local isRage=rage.ownsSpeed()
        local scriptedVector=not isRage and scriptedDribbleBase(attached,character,now) or nil
        state.scriptedDribble=scriptedVector~=nil
        state.dribbleBase=scriptedVector and scriptedVector.Magnitude or nil
        if scriptedVector then attached.baseVelocity=Vector3.new(scriptedVector.X,current.Y,scriptedVector.Z) end
        local playerScale,_,playerBoost,playerGlide=1,1,0,0
        if not isRage then playerScale,_,playerBoost,playerGlide=dribbleMotion.sample(character,state.ball,now,scriptedVector~=nil) end
        state.source,state.nativeTarget,state.playerBoost,state.playerGlide=isRage and "rage" or "player",original.Magnitude,playerBoost,playerGlide
        local action = actionOf(character)
        local canMove = (character:GetAttribute("CanMove") ~= false or scriptedVector~=nil) and not antiStun.recovering(character)
            and character:GetAttribute("Stunned")~=true and character:GetAttribute("Fouled")~=true and character:GetAttribute("Blocked")~=true
            and not shot and character:GetAttribute("CFrame")==nil and character:GetAttribute("SeatCFrame")==nil
            and not (rage.movementBlocked and rage.movementBlocked(now))
        if not (isRage or rage.playerMovementEnabled()) or not canMove or (not movementActions[action] and not scriptedVector) or proxy.Anchored
            or input:GetFocusedTextBox() then
            state.effective = original.Magnitude
            state.phase = (now<expectedMoveUntil or now<(state.recoverUntil or 0)) and "Recovering native movement"
                or not canMove and "Game movement lock" or "Native action movement"
            return
        end
        local direction = rawget(object, "MoveDirection")
        if typeof(direction) ~= "Vector3" then return end
        direction = planar(direction)
        local requested
        if isRage then requested=state.ball and rage.withBall.value or rage.offBall.value
        else
            local tuning=config.movement and (state.ball and hubControls.withBallSpeed.value or hubControls.offBallSpeed.value)/100 or 1
            requested=scriptedVector and (playerScale>1.00001 and scriptedVector.Magnitude*playerScale or original.Magnitude) or original.Magnitude*tuning*playerScale
            if scriptedVector then direction=scriptedVector.Unit
            elseif direction.Magnitude>.01 and original.Magnitude>.01 then direction=original.Unit end
        end
        state.requested = requested
        if not isRage and (direction.Magnitude<=.01 or original.Magnitude<=.01 or math.abs(requested-original.Magnitude)<.001) then
            state.effective,state.phase=original.Magnitude,"Native Player movement"
            state.lastPosition,state.lastAt,state.lastBoostAt,state.lastBoosting=nil,nil,nil,false
            return
        end
        local actual = planar(proxy.AssemblyLinearVelocity)
        local position = proxy.Position
        if now>=expectedMoveUntil and state.lastPosition and state.lastAt then
            local elapsed = now - state.lastAt
            if elapsed > 0 and elapsed < .25 and (position - state.lastPosition).Magnitude > math.max(12, (actual.Magnitude + 12) * elapsed * 2.5) then
                recover("Position correction observed", now)
            end
        end
        state.lastPosition, state.lastAt = position, now
        local gap = (position - root.Position).Magnitude
        if now>=expectedMoveUntil and gap > math.max(8, actual.Magnitude * math.max(dt, .016) * 3 + 2) then recover("Character and proxy separated", now) end
        if state.clampPickup then
            state.clampPickup = false
            if actual.Magnitude > state.nativeSpeed + 3.35 then
                actual = actual.Unit * (state.nativeSpeed + 3.35)
                local physical = proxy.AssemblyLinearVelocity
                proxy.AssemblyLinearVelocity = Vector3.new(actual.X, physical.Y, actual.Z)
            end
        end
        local settling = now < (state.settleUntil or 0)
        local recovering = now < (state.recoverUntil or 0) or now < expectedMoveUntil
        if recovering or settling then
            state.effective, state.phase = original.Magnitude, recovering and "Recovering native movement" or "Settling possession"
            return
        end
        local speed = math.min(requested, state.ceiling or math.huge)
        -- The game's packet encodes X/Z velocity as signed bytes. Keep carried-ball
        -- movement representable by that exact codec rather than sending clipped speed.
        local packetLimited = false
        if direction.Magnitude > .01 then
            local unit = direction.Unit
            local representable = attached.packetAxisSpeed / math.max(math.abs(unit.X), math.abs(unit.Z), .001)
            packetLimited = speed > representable
            speed = math.min(speed, representable)
        end
        if state.ceiling and state.ceiling < requested and original.Magnitude > speed then
            state.effective,state.phase=original.Magnitude,"Native speed after correction"
            state.lastBoosting=false
            return
        end
        local naturalScale = isRage and math.clamp(original.Magnitude / math.max(1, state.nativeSpeed), 0, 1) or 1
        speed *= naturalScale
        local wanted = direction.Magnitude > .01 and direction.Unit * speed or Vector3.zero
        local delta = wanted - actual
        local acceleration = wanted.Magnitude < actual.Magnitude and math.max(240, rage.ramp.value) or rage.ramp.value
        local maxChange = acceleration * math.clamp(dt, 1 / 300, .05)
        local target = delta.Magnitude > maxChange and actual + delta.Unit * maxChange or wanted
        local peakAxis=math.max(math.abs(target.X),math.abs(target.Z))
        if peakAxis>attached.packetAxisSpeed then target*=attached.packetAxisSpeed/peakAxis;packetLimited=true end
        state.lastBoostAt,state.lastBoostPosition=now,position
        state.lastBoosting=target.Magnitude>(scriptedVector and scriptedVector.Magnitude or original.Magnitude)+.5
        attached.scriptedVelocity=scriptedVector~=nil
        attached.lastVelocity = Vector3.new(target.X, current.Y, target.Z)
        velocity.Velocity = attached.lastVelocity
        state.effective, state.phase = target.Magnitude, packetLimited and (state.ball and "Ball velocity sync limit" or "Velocity sync limit")
            or state.ceiling and "Adjusted after correction" or isRage and "Speed ramp active" or scriptedVector and "Dribble move boosted" or "Player movement active"
        if not isRage and antiContestV2.recorder and now>=(state.nextPlayerTrace or 0) then
            state.nextPlayerTrace=now+.2
            pcall(antiContestV2.recorder.emit,"player_movement_target",{native=original.Magnitude,requested=requested,applied=target.Magnitude,
                actual=actual.Magnitude,boost=playerBoost,glide=playerGlide,scripted=scriptedVector~=nil,serverBase=scriptedVector and scriptedVector.Magnitude,moveAction=character:GetAttribute("Action"),gatherType=character:GetAttribute("GatherType"),withBall=state.ball~=nil,phase=state.phase})
        end
    end
    local function attachDriver(character, root, now)
        if driver then
            if driver.proxy.Parent and driver.velocity.Parent == driver.proxy and rawget(driver.object, "Update") == driver.wrapper
                and rawget(driver.owner, "ProxyCharacter") == driver.proxy and rawget(driver.object, "MovementVelocity") == driver.velocity then return true end
            detach()
        end
        if now < nextDriverScan then return false end
        nextDriverScan = now + 1
        local body,model = gameplaySafety.actor()
        local objects = body and model == character and type(body.Movement) == "table" and {body.Movement} or nil
        if not objects then
            if type(getgc) ~= "function" then return false end
            local ok,found = pcall(getgc, true)
            if not ok or type(found) ~= "table" then return false end
            objects = found
        end
        for _, object in ipairs(objects) do
            if type(object) ~= "table" then continue end
            local owner, proxy, velocity = rawget(object, "State"), rawget(object, "Root"), rawget(object, "MovementVelocity")
            local data = type(owner) == "table" and rawget(owner, "data")
            if type(data) ~= "table" or rawget(data, "model") ~= character or rawget(object, "RealRoot") ~= root
                or rawget(owner, "ProxyCharacter") ~= proxy or typeof(proxy) ~= "Instance" or typeof(velocity) ~= "Instance"
                or not proxy:IsA("BasePart") or not proxy.Parent or not velocity:IsA("BodyVelocity") or velocity.Parent ~= proxy then continue end
            local original = object.Update
            if type(original) ~= "function" then continue end
            local configOk, speedScale = pcall(function() return object.Shared.Replication.ReplicationConfig.Character.SPEED_SCALE end)
            if not configOk or not finite(speedScale) or speedScale<=0 then continue end
            local axisSpeed = 127 / speedScale
            local attached = {object = object, owner = owner, proxy = proxy, velocity = velocity, packetAxisSpeed = axisSpeed, previous = rawget(object, "Update")}
            attached.wrapper = function(self, dt, ...)
                if attached.scriptedVelocity then
                    if self==object and velocity.Parent==proxy and velocity.Velocity==attached.lastVelocity then
                        local v=scriptedDribbleBase(attached,character,os.clock())
                        if v then velocity.Velocity=Vector3.new(v.X,velocity.Velocity.Y,v.Z) end
                    end
                    attached.scriptedVelocity=nil
                end
                local nativeResults=table.pack(original(self, dt, ...))
                if driver ~= attached or self ~= object or not state or not rage.usesMovementDriver() or stopped or traveling
                    or not robloxFocused() or not character.Parent or not proxy.Parent
                    or rawget(owner,"ProxyCharacter")~=proxy or rawget(object,"Root")~=proxy
                    or rawget(object,"RealRoot")~=root or rawget(object,"MovementVelocity")~=velocity
                    or type(owner.data)~="table" or owner.data.model~=character then
                    dribbleMotion.reset();return table.unpack(nativeResults,1,nativeResults.n)
                end
                local now = os.clock()
                boost(attached, character, root, now, finite(dt) and dt > 0 and dt or 1 / 60)
                return table.unpack(nativeResults,1,nativeResults.n)
            end
            if pcall(rawset, object, "Update", attached.wrapper) then
                driver=attached
                local nativeAcceleration=object.GetAcceleration
                if type(nativeAcceleration)=="function" then
                    attached.accelerationPrevious=rawget(object,"GetAcceleration")
                    attached.accelerationWrapper=function(self,...)
                        local values=table.pack(nativeAcceleration(self,...))
                        local direction=rawget(object,"MoveDirection")
                        local now=os.clock()
                        if driver==attached and self==object and state and state.character==character and config.movement and not rage.ownsSpeed()
                            and character.Parent and proxy.Parent and not proxy.Anchored
                            and rawget(owner,"ProxyCharacter")==proxy and rawget(object,"Root")==proxy
                            and rawget(object,"RealRoot")==root and rawget(object,"MovementVelocity")==velocity
                            and type(owner.data)=="table" and owner.data.model==character
                            and not stopped and not traveling and robloxFocused() and not shot
                            and gameplaySafety.ready and now>=expectedMoveUntil and now>=(state.recoverUntil or 0) and now>=(state.settleUntil or 0)
                            and not rage.movementBlocked(now)
                            and character:GetAttribute("CanMove")~=false and movementActions[actionOf(character)]
                            and character:GetAttribute("CFrame")==nil and character:GetAttribute("SeatCFrame")==nil
                            and not antiStun.recovering(character) and not input:GetFocusedTextBox()
                            and typeof(direction)=="Vector3" and direction.Magnitude>.01 and finite(values[1]) then
                            local value=finite(acceleration.value) and math.clamp(acceleration.value,50,180)/100 or 1
                            values[1]*=value
                        end
                        return table.unpack(values,1,values.n)
                    end
                    if not pcall(rawset,object,"GetAcceleration",attached.accelerationWrapper) then attached.accelerationWrapper=nil end
                end
                local physics=owner.Services and owner.Services.PhysicsService
                local event=physics and physics.SetCFrame
                if event and type(event.Connect)=="function" then
                    local ok,connection=pcall(event.Connect,event,function(frame)
                        if driver==attached then rage.serverMove(frame) end
                    end)
                    if not ok then detach();return false end
                    attached.correction=connection
                end
                return true
            end
        end
        return false
    end
    local function writeAttribute(name, desired)
        local current = state.character:GetAttribute(name)
        if not finite(current) then restoreAttribute(state, name); return false end
        local field = state.fields[name]
        if not field or current ~= field.written then field = {base = current} end
        field.written = desired(field.base, current)
        if not finite(field.written) then return false end
        state.fields[name] = field
        if current ~= field.written then state.character:SetAttribute(name, field.written) end
        return true
    end
    function rage.capture()
        return {version = 2, enabled = rage.enabled, speed = rage.speed, stamina = rage.stamina, fly = rage.fly.enabled, keepFly = rage.fly.keep ~= false, noclip = rage.noclip.enabled, courtTeleport = rage.courtTeleport.capture(), speedRecovery = rage.captureSpeedRecovery(),
            offBall = rage.offBall.value, withBall = rage.withBall.value, ramp = rage.ramp.value}
    end
    function rage.apply(saved)
        saved = type(saved) == "table" and saved or {}
        rage.stop()
        rage.enabled, rage.speed = saved.enabled == true, saved.speed ~= false
        rage.stamina = saved.stamina == true
        rage.fly.keep = saved.keepFly ~= false
        rage.fly.enabled = saved.fly == true
        rage.noclip.apply(saved.noclip == true)
        rage.courtTeleport.apply(saved.courtTeleport)
        rage.applySpeedRecovery(saved.speedRecovery)
        for key, control in pairs({offBall = rage.offBall, withBall = rage.withBall, ramp = rage.ramp}) do
            showSlider(control, finite(saved[key]) and saved[key] or control.default)
        end
        rage.refresh()
    end
    function rage.refresh()
        showSwitch(rage.fly.toggle, rage.fly.enabled)
        showSwitch(rage.fly.keepSwitch, rage.fly.keep ~= false)
        showSwitch(rage.noclip.toggle, rage.noclip.enabled)
        rage.courtTeleport.refresh()
        for _, entry in ipairs({{rage.toggle, rage.enabled}, {rage.speedSwitch, rage.speed}, {rage.staminaSwitch, rage.stamina}}) do showSwitch(entry[1], entry[2]) end
        if not rage.enabled then rage.status.Text = "Rage is off." end
    end
    function rage.bind(connectControl, redraw)
        for _, item in ipairs({{rage.toggle, "enabled"}, {rage.speedSwitch, "speed"}, {rage.staminaSwitch, "stamina"}}) do
            local field = item[2]
            connectControl(item[1].row.Activated, function()
                rage.stop(); rage[field] = not rage[field]
                if rage.ownsSpeed() then restoreMovement() end
                rage.refresh(); redraw()
            end)
        end
    end
    function rage.watch(now)
        if not gameplaySafety.ready then
            if state or driver then rage.stop() end
            if rage.enabled then rage.status.Text = "Waiting for Park spawn or match entry to settle." end
            return
        end
        if not rage.enabled and not rage.playerMovementEnabled() then if state or driver then rage.stop() end; return end
        if rage.enabled and rage.fly.enabled then detach();rage.status.Text = rage.fly.message or "Fly waiting";return end
        if traveling or not robloxFocused() then
            if state or driver then rage.stop() end
            rage.status.Text = traveling and "Waiting for the next character." or "Waiting for Roblox focus."
            return
        end
        local character, root = findCharacter()
        local humanoid = character and character:FindFirstChild("Humanoid")
        if not root or not character.Parent or humanoid and finite(humanoid.Health) and humanoid.Health <= 0 then
            rage.stop(); rage.status.Text = "Waiting for a live basketball character."; return
        end
        if state and (state.character ~= character or state.root ~= root) then rage.stop() end
        state = state or {character = character, root = root, fields = {}}
        observe(character, root, now)
        local needed=rage.usesMovementDriver()
        local ready = needed and attachDriver(character, root, now)
        if not needed and driver then detach() end
        if rage.enabled and rage.stamina then
            local maximum = character:GetAttribute("MaxStamina")
            maximum = finite(maximum) and maximum > 0 and maximum <= 1000 and maximum or 100
            writeAttribute("Stamina", function(_, current) return math.max(current, maximum) end)
        else restoreAttribute(state, "Stamina") end
        if now >= nextStatus then
            nextStatus = now + .15
            local rows = {}
            if rage.speed then
                rows[#rows + 1] = ready and string.format("Requested %.0f · applied %.1f studs/s · %s", state.ball and rage.withBall.value or rage.offBall.value,
                    state.effective or 0, state.phase or "Waiting for movement") or "Waiting for the movement controller."
            end
            if rage.stamina then rows[#rows + 1] = "Local stamina refill enabled." end
            rage.status.Text = #rows > 0 and table.concat(rows, "\n") or "Select a Rage feature."
        end
        if telemetry.dirty and storageAvailable and now >= telemetry.nextFlush then
            telemetry.nextFlush = now + 2
            telemetry.path = telemetry.path or ("GymRelease/rage-movement-" .. tostring(os.time()) .. ".jsonl")
            local lines = {}
            for _, row in ipairs(telemetry.events) do lines[#lines + 1] = http:JSONEncode(row) end
            if pcall(writefile, telemetry.path, table.concat(lines, "\n") .. "\n") then telemetry.dirty = false end
        end
    end
    function rage.diagnostics()
        return {phase = state and state.phase, effective = state and state.effective, ceiling = state and state.ceiling,
            source=state and state.source,nativeTarget=state and state.nativeTarget,playerBoost=state and state.playerBoost,playerGlide=state and state.playerGlide,
            scriptedDribble=state and state.scriptedDribble,dribbleBase=state and state.dribbleBase,
            log = telemetry.path,
            requested=state and state.requested,corrections=state and state.corrections,nativeRepositionGuard=driver and driver.correction~=nil}
    end
end

do
    local state
    local ready = "Waiting for a stun or ankle-break signal."
    local stunActions = {
        stun = true, stunned = true, hitstun = true, stunlocked = true, anklestun = true,
        anklebroken = true, anklesbroken = true, staggered = true, stumble = true, stumbling = true,
    }
    local movementActions = {
        [""] = true, moving = true, dribbling = true, guarding = true,
        defending = true, defensivestance = true, contesting = true,
    }
    local stunFlags = {"Stun", "Stunned", "IsStunned", "AnkleBroken", "AnklesBroken", "Staggered"}

    local function actionOf(character)
        local action = character:GetAttribute("Action")
        return type(action) == "string" and action:lower():gsub("[^%w]", "") or (action == nil and "" or nil)
    end

    local function isStunned(character, action)
        if stunActions[action] then return true end
        if action == "anklebreak" or action == "anklebreaker" then return not heldBall(character) end
        -- A stale flag must not override a different action's movement lock.
        if not movementActions[action] or action == "dribbling" then return false end
        local attributes = character:FindFirstChild("Attributes")
        for _, name in ipairs(stunFlags) do
            if character:GetAttribute(name) == true then return true end
            local marker = attributes and attributes:FindFirstChild(name)
            if marker and marker:IsA("BoolValue") and marker.Value then return true end
        end
        return false
    end

    local function canRecover(humanoid)
        return not humanoid or (humanoid.Health > 0 and humanoid.SeatPart == nil)
    end

    local function unlockAttribute(name, locked, normal)
        if normal == nil or state.character:GetAttribute(name) ~= locked then return end
        state.fields[name] = {base = locked, written = normal}
        state.character:SetAttribute(name, normal)
    end

    local function unlockHumanoid(name, locked, normal)
        if not state.humanoid or normal == nil or state.humanoid[name] ~= locked then return end
        state.humanoidFields[name] = {base = locked, written = normal}
        state.humanoid[name] = normal
    end

    function antiStun.recovering(character)
        return state and state.character == character and state.recovering
    end

    function antiStun.stop()
        if not state then return end
        local character, humanoid = state.character, state.humanoid
        if state.recovering and character.Parent and canRecover(humanoid) and isStunned(character, actionOf(character)) then
            for name in pairs(state.fields) do restoreAttribute(state, name) end
            for name, field in pairs(state.humanoidFields) do
                if humanoid.Parent == character and humanoid[name] == field.written then
                    humanoid[name] = field.base
                end
            end
        end
        state = nil
    end

    local function usableSpeed(value)
        return type(value) == "number" and value > 0 and value < math.huge
    end

    function antiStun.watch()
        if not antiStun.enabled or traveling then return end
        local character, root = findCharacter()
        local humanoid = character and character:FindFirstChild("Humanoid")
        if humanoid and not humanoid:IsA("Humanoid") then humanoid = nil end
        if not root or not character.Parent or not canRecover(humanoid) then
            antiStun.stop()
            antiStun.status.Text = "Waiting for your character."
            return
        end
        if not state or state.character ~= character or state.humanoid ~= humanoid then
            antiStun.stop()
            state = {character = character, humanoid = humanoid, fields = {}, humanoidFields = {}}
        end
        local action = actionOf(character)
        if not isStunned(character, action) then
            -- Once the game ends the stun, returning the old lock could freeze the player again.
            if state.recovering then
                table.clear(state.fields)
                table.clear(state.humanoidFields)
                state.recovering = false
            end
            if movementActions[action] and character:GetAttribute("CanMove") ~= false then
                local tuned = motion and motion.character == character and motion.fields.WalkSpeed
                local speed = tuned and tuned.base or rage.baseSpeed(character) or character:GetAttribute("WalkSpeed")
                if usableSpeed(speed) then state.characterSpeed = speed end
                if humanoid and not humanoid.PlatformStand and usableSpeed(humanoid.WalkSpeed) then
                    state.humanoidSpeed = humanoid.WalkSpeed
                end
            end
            antiStun.status.Text = ready
            return
        end

        if motion and motion.character == character then restoreMovement() end
        unlockAttribute("CanMove", false, true)
        unlockAttribute("WalkSpeed", 0, state.characterSpeed)
        unlockHumanoid("PlatformStand", true, false)
        unlockHumanoid("WalkSpeed", 0, state.humanoidSpeed)
        state.recovering = next(state.fields) ~= nil or next(state.humanoidFields) ~= nil
        antiStun.status.Text = state.recovering and "Local stun locks cleared." or "Stun detected. No local lock found."
    end

    function antiStun.apply(enabled)
        antiStun.enabled = enabled
        if not enabled then antiStun.stop() end
        antiStun.status.Text = enabled and ready or "Anti-Stun is off."
    end
end

local function cancelJelly()
    local pending = jelly
    jelly = nil
    if pending and pending.held then releaseKey(pending.style.virtual) end
end

local function watchJelly(now)
    local pending = jelly
    if not pending then return end
    if not autoJelly or not automationAvailable() or not robloxFocused() or input:GetFocusedTextBox() then
        cancelJelly()
        return
    end

    local action = pending.character:GetAttribute("Action")
    if not pending.pressedAt then
        if now < pending.pressAt then return end
        if action ~= pending.initialAction or executorInput.keyDown(pending.style.key) then
            cancelJelly()
            return
        end
        pending.pressedAt, pending.held = now, true
        hubControls.jellyStatus.Text = pending.style.name .. " input sent."
        keypress(pending.style.virtual)
    elseif pending.held and now - pending.pressedAt >= 0.07 then
        pending.held = false
        releaseKey(pending.style.virtual)
    end
    if pending.pressedAt and type(action) == "string" and action ~= pending.initialAction
        and (string.find(string.lower(action), "layup", 1, true) or string.find(string.lower(action), "clutch", 1, true)) then
        if not pending.confirmed then
            pending.confirmed = true
            hubControls.jellyStatus.Text = pending.style.name .. " confirmed."
            warn(prefix .. pending.style.name .. " converted to " .. action .. ".")
        end
        if not pending.held then jelly = nil end
    elseif now - pending.releaseAt >= 0.35 then
        cancelJelly()
        if not pending.confirmed then hubControls.jellyStatus.Text = "No separate finish state was reported." end
    end
end

local function unload()
    if rage.fly.close then rage.fly.close() end
    if rage.noclip.close then rage.noclip.close() end
    rage.courtTeleport.stop()
    defense.teleport.stop()
    if shared.WizardHubDefenseTeleport == defense.teleport then shared.WizardHubDefenseTeleport = nil end
    if shared.WizardHubCourtTeleport == rage.courtTeleport then shared.WizardHubCourtTeleport = nil end
    gameplaySafety.stop()
    if antiContestV2.recorder then pcall(antiContestV2.recorder.stop, "Hub unloaded") end
    pcall(antiContestV2.stop, "Hub unloaded.")
    if shared.WizardHubAntiContestV3 and shared.WizardHubAntiContestV3.owner==antiContestV2 then shared.WizardHubAntiContestV3=nil end
    if shared.WizardHubAntiContestV2 == antiContestV2 then shared.WizardHubAntiContestV2 = nil end
    if shotInput.isNative(shot) and shot.owned and not shot.sentAt and not shot.releasedAt then
        shot.keyUpAt = shot.keyUpAt or os.clock()
    end
    if type(shared.mc1hContestTrial) == "table" and type(shared.mc1hContestTrial.stop) == "function" then
        shared.mc1hContestTrial.stop("Hub unloaded")
    end
    if stopped then return end
    executorInput.releaseAll()
    stopped = true
    if mobileLauncher then mobileLauncher:Destroy(); mobileLauncher = nil end
    for _, connection in ipairs(connections) do connection:Disconnect() end
    table.clear(connections)
    if stopReload then stopReload() end
    drag = nil
    sliderDrag = nil
    stopMacro()
    courtJoin.apply(false)
    defense.stop()
    autoBlock.stop()
    antiStun.stop()
    rage.stop()
    restoreMovement()
    cancelJelly()
    if shot and shot.held then releaseKey(shot.control.virtualKey) end
    shot = nil
    if lineOverlay then
        lineOverlay:Destroy()
        lineOverlay = nil
    end
    visualExtras.clear()
    gameAppearance.stop()
    renderOptions.stop()
    sceneOverrides.restoreAll()
    avatar.suspend()
    privacy.stop()
    hud.destroy()
    gui:Destroy()
    shared.PracticalBasketballGymReleaseStop = nil
    shared.PracticalBasketballGymReleaseCapture = nil
    warn(prefix .. "Unloaded.")
end
shared.PracticalBasketballGymReleaseStop = unload

-- Shot timing.
--
-- The server owns the meter. On every server heartbeat it writes the fill to the character's
-- meterOffset attribute: the fill rises in equal steps, turns around at the peak, and comes
-- back down. How fast it rises differs from shot to shot. When the server handles the release
-- it rates the step it wrote last: Perfect when that step is within the green window of the
-- peak. The window's size is set by the game for each shot and can be too small for any step
-- to land in, in which case no timing can produce a Perfect.
--
-- The bar on screen is a 50 ms tween chasing that attribute, and the release still has to travel
-- to the server, so the bar cannot be timed directly. Instead: fit the arrival times of this
-- shot's steps, work out which upcoming steps fall inside the green window, and send the release
-- one round trip before the middle of their heartbeats. The round trip is measured after every
-- rated shot from the step the server actually stopped on.
local timing = {seenSerial = 0, awaiting = {}}
hubControls.ratingNames = {"Very Early", "Early", "Slightly Early", "Good", "Perfect", "Slightly Late", "Late", "Very Late"}
hubControls.ratingOrder = {}
for order, name in ipairs(hubControls.ratingNames) do hubControls.ratingOrder[string.lower(name) .. " release"] = order end
network.history = {}

-- The shot log and the console. Appending to a file or printing to Real's console can hold a
-- frame for tens of milliseconds (more the bigger the file is), and a held frame hides meter
-- steps. So lines wait here and go out between shots, to a file that is kept small.
local shotLog = {enabled = true, written = 0, bytes = 0, lines = {}, notes = {}}

function shotLog.add(entry)
    if not shotLog.enabled or shotLog.written >= 4000 then return end
    local ok, text = pcall(http.JSONEncode, http, entry)
    if ok and type(text) == "string" then
        shotLog.lines[#shotLog.lines + 1] = text
        shotLog.written += 1
    end
end

function shotLog.say(text)
    local notes = shotLog.notes
    if #notes < 30 then notes[#notes + 1] = text end
end

function shotLog.flush(now)
    -- Auto Guard possessions go into the same log, once the guard key has been up for a moment.
    local blocks = autoBlock.trace
    if blocks and blocks[1] then
        for _, entry in ipairs(blocks) do shotLog.add(entry) end
        table.clear(blocks)
    end
    local traces, guardKey = defense.trace, bindings["Auto Guard"]
    if traces and traces[1] and now - (defense.traceAt or 0) > 1.5 and not (guardKey and executorInput.keyDown(guardKey)) then
        for _, entry in ipairs(traces) do shotLog.add(entry) end
        table.clear(traces)
    end
    local lines, notes = shotLog.lines, shotLog.notes
    if #lines == 0 and #notes == 0 then return end
    -- Never while a shot is being timed or a shot key is down.
    if shot or executorInput.keyDown(jump.key) or executorInput.keyDown(dunk.key) then return end
    shotLog.lines, shotLog.notes = {}, {}
    for _, text in ipairs(notes) do warn(prefix .. text) end
    if #lines == 0 or not shotLog.enabled or type(appendfile) ~= "function" then return end
    local text = table.concat(lines, "\n") .. "\n"
    local ok = pcall(function()
        if not shotLog.path or shotLog.bytes > 60000 then
            if type(makefolder) == "function" then pcall(makefolder, "GymRelease") end
            shotLog.path, shotLog.bytes = string.format("GymRelease/shots-%d.jsonl", os.time()), 0
            writefile(shotLog.path, text)
        else
            appendfile(shotLog.path, text)
        end
        shotLog.bytes += #text
    end)
    if not ok then shotLog.enabled = false end
end

-- Where the player is heading. The game moves characters itself, so their velocity reads as
-- zero; it is worked out here from the last few positions.
timing.travel = {}

function timing.sampleTravel(now, position)
    local samples = timing.travel
    samples[#samples + 1] = {now, position.X, position.Z}
    while samples[1] and now - samples[1][1] > 0.25 do table.remove(samples, 1) end
end

-- Returns the speed over the last tenth of a second, how much of it closes on `target`, and how
-- directly the player is heading there (1 is straight at it, 0 is sideways).
function timing.toward(now, target)
    local samples = timing.travel
    local latest = samples[#samples]
    if not latest or now - latest[1] > 0.06 then return end
    local base
    for index = 1, #samples do
        if latest[1] - samples[index][1] >= 0.09 then base = samples[index] else break end
    end
    if not base then return end
    local elapsed = latest[1] - base[1]
    local vx, vz = (latest[2] - base[2]) / elapsed, (latest[3] - base[3]) / elapsed
    local speed = math.sqrt(vx * vx + vz * vz)
    local dx, dz = target.X - latest[2], target.Z - latest[3]
    local distance = math.sqrt(dx * dx + dz * dz)
    if distance < 0.01 or speed < 0.5 then return speed, 0, 0 end
    local closing = (vx * dx + vz * dz) / distance
    return speed, closing, closing / speed
end

-- The game announces every meter it starts and every rating it gives. Those announcements are
-- exact. Without them the script falls back to watching the fill value and the on-screen label.
local signals = {serial = 0}
do
    local function remote(service, name)
        local aero = game:GetService("ReplicatedStorage"):FindFirstChild("Aero")
        local services = aero and aero:FindFirstChild("AeroRemoteServices")
        local folder = services and services:FindFirstChild(service)
        local event = folder and folder:FindFirstChild(name)
        return event and event:IsA("RemoteEvent") and event or nil
    end
    local function listen(service, name, callback)
        local event = remote(service, name)
        if not event then return false end
        connect(event.OnClientEvent, function(character, ...)
            -- Only this player's shots matter.
            if character == (findCharacter()) then pcall(callback, ...) end
        end)
        return true
    end
    -- After a teleport this script starts before the game has built its remotes and its own input
    -- code, so everything here is looked for again (from the ping sampler, twice a second) until
    -- it is all in place. Measured on 2026-11-11: in blacktop matches none of it was found at
    -- load, so releases went out as simulated key-ups and a dunk turned into a clutch layup.
    function signals.connect()
    signals.meters = signals.meters or listen("MeterService", "RegisterPacket", function(meterType, green)
        signals.serial += 1
        pcall(antiContestV2.meter, meterType, signals.serial)
        signals.green = type(green) == "number" and green or nil
        -- A shot this script is timing moved on to its next meter (gather, then the shot itself):
        -- keep holding the game's own key messages for it.
        local gate, attempt = signals.gate, shot
        if gate and attempt and attempt.owned and not attempt.sentAt and not attempt.releasedAt then
            gate.serial = signals.serial
        end
    end)
    signals.greens = signals.greens or listen("MeterService", "UpdateGreenWindow", function(green)
        if type(green) == "number" then signals.green = green end
    end)
    signals.ratings = signals.ratings or listen("InterfaceService", "ShowFeedback", function(contest, order)
        order = tonumber(order)
        if order and hubControls.ratingNames[order] then
            signals.feedback = {at = os.clock(), order = order, contest = tonumber(contest)}
            local v2ok, v2error = pcall(antiContestV2.feedback, tonumber(contest))
            if not v2ok then pcall(antiContestV2.fail, v2error) end
            -- The shot is over: the game's own key messages can pass again.
            if signals.gate then signals.gate.untilAt = 0 end
        end
    end)
    -- The message the game itself sends to the server when the shot key comes up.
    signals.release = signals.release or remote("InputService", "Shoot")
    if not signals.gate then signals.installGate() end
    signals.tries = (signals.tries or 0) + 1
    local complete = (signals.meters and signals.ratings and signals.release
        and (signals.gate ~= nil or type(getconnections) ~= "function" or signals.tries > 600)) and true or false
    if complete and signals.tries > 1 then
        warn(prefix .. string.format("Shot signals connected %.0f s after loading%s.", (signals.tries - 1) * 0.5,
            signals.gate and "" or " (without the release gate)"))
    end
    signals.complete = complete
    end
    -- The game prints what kind of shot it was, and its make chance, once the shot resolves.
    connect(game:GetService("LogService").MessageOut, function(message)
        if type(message) ~= "string" or not message:find("Shot Feedback", 1, true) then return end
        local kind, contest, chance = message:match("Shot Type %- (%w+) %]%[ Contest %- ([%d%.]+) %]%[ Percentage %- ([%d%.]+)")
        if kind then pcall(timing.describeShot, kind, tonumber(contest), tonumber(chance)) end
    end)

    -- One release per shot, and it is this script's.
    --
    -- This script releases by sending the game's release message itself, which leaves the real
    -- key down. When the player lets go a moment later, the game's own input code sends the same
    -- message again, and on a dunk or layup that is still in the air the server answers a second
    -- release by turning it into a clutch layup (measured: 6 dunks out of 6). And a key let go
    -- too soon (a quick tap, a jump for a lob) releases the shot at the bottom of the meter.
    -- So from the moment the game starts a meter for a shot Auto Green is timing until that shot
    -- is rated, the game's own shoot-key messages are held back here and the release is sent at
    -- the right time instead. They all go through one object in the game's client framework;
    -- only its send function is wrapped, and it is put back when the script unloads.
    function signals.installGate()
    local shootRemote = signals.release
    if not shootRemote or signals.gate then return end
    local sender
    if shootRemote and type(getconnections) == "function" and type(getupvalues) == "function" then
        pcall(function()
            for _, connection in ipairs(getconnections(shootRemote.OnClientEvent)) do
                local listener = connection.Function
                if type(listener) == "function" then
                    for _, held in pairs(getupvalues(listener)) do
                        local fire = type(held) == "table" and rawget(held, "Fire")
                        if type(fire) == "function" then
                            for _, inner in pairs(getupvalues(fire)) do
                                if inner == shootRemote then sender = held end
                            end
                        end
                    end
                end
            end
        end)
    end
    local previous = shared.WizardHubShootGate
    if type(previous) == "table" and type(previous.sender) == "table" and type(previous.original) == "function" then
        -- An earlier copy of this script did not get to put the send function back.
        if rawget(previous.sender, "Fire") == previous.filter then rawset(previous.sender, "Fire", previous.original) end
        if not sender and previous.sender then sender = previous.sender end
        shared.WizardHubShootGate = nil
    end
    if sender and not table.isfrozen(sender) then
        local original = rawget(sender, "Fire")
        local gate = {sender = sender, original = original, swallowed = 0, untilAt = 0}
        local function filter(self, data, ...)
            if type(antiContestV2.trace) == "function" then pcall(antiContestV2.trace, "native_shoot", {data = data, serial = signals.serial, gateUntilAt = gate.untilAt, swallowed = gate.swallowed}) end
            if not stopped and type(data) == "table" and data.Shoot ~= nil
                and os.clock() < gate.untilAt and gate.serial == signals.serial then
                gate.swallowed += 1
                if data.Shoot == false and shot and shot.inputControl and shot.inputControl.touch then
                    shot.keyUpAt = shot.keyUpAt or os.clock()
                end
                return
            end
            local extra = table.pack(...)
            local function send(payload)
                return original(self, payload, table.unpack(extra, 1, extra.n))
            end
            local v2ok, v2used = pcall(antiContestV2.filter, data, send, os.clock())
            if v2ok and v2used then return end
            if not v2ok then pcall(antiContestV2.fail, v2used) end
            if type(data)=="table" and data.Shoot==false then return antiContestV2.forwardRelease(original,self,data,...) end
            return original(self, data, ...)
        end
        gate.filter = filter
        rawset(sender, "Fire", filter)
        signals.gate = gate
        shared.WizardHubShootGate = gate
        table.insert(connections, {Disconnect = function()
            -- Unloading mid-shot: a key-up that was held back still has to reach the server.
            local attempt = shot
            if attempt and attempt.owned and (attempt.keyUpAt or attempt.keyless) and not attempt.sentAt and not attempt.releasedAt then
                pcall(shootRemote.FireServer, shootRemote, {Shoot = false})
            end
            if rawget(sender, "Fire") == filter then rawset(sender, "Fire", original) end
            if shared.WizardHubShootGate == gate then shared.WizardHubShootGate = nil end
        end})
    end
    end
    signals.connect()
end

-- The separate flight recorder used while measuring the meter wrote a large file after every shot.
-- Everything it was needed for is now in this script's own log.
if type(shared.WizardFlightStop) == "function" then pcall(shared.WizardFlightStop) end

function timing.freshModel()
    return {
        peak = 1.49,    -- Fill value where the Vertical meter turns around.
        loop = nil,     -- Seconds from the release until the server handles it, on the step arrival clock.
        loopPing = nil, -- Data ping the loop was measured at.
        history = {},   -- Recent releases, each as the {low, high} range of round trips it allows.
        width = 0.50,   -- Perfect half-width per unit of green window past 0.259 (measured 0.54; kept a little inside).
        frames = 1.15,  -- Frames from keyrelease() until the game sees the key come up (fallback release only).
        lean = 0,       -- Run of early (-) or late (+) ratings on steps that should have been Perfect.
        strays = 0,
    }
end
local model = timing.freshModel()

function timing.peakText()
    return string.format("Peak  %.3f", model.peak)
end
for _, mode in ipairs(modes) do mode.detail = timing.peakText() end

-- How much the round trip has moved with the ping since it was measured.
function timing.pingShift()
    local ping = network.median
    if not (ping and model.loop and model.loopPing) then return 0 end
    local change = ping - model.loopPing
    -- A change this large is another server (or route), not wobble: the round trip moves with it
    -- in full, whether or not Ping compensation is on. Measured on 2026-11-11 across teleports:
    -- the round trip sat a few ms under the data ping on a 31 ms server and on 55 ms ones.
    if math.abs(change) >= 0.010 then
        -- Until the reading is steady (the last five samples within 15 ms of each other), only
        -- apply the difference for now; the reading runs wild around a teleport.
        local history = network.history
        local low, high = math.huge, 0
        for index = math.max(1, #history - 4), #history do
            low, high = math.min(low, history[index]), math.max(high, history[index])
        end
        if #history < 5 or high - low > 0.015 then return math.clamp(change, -0.200, 0.200) end
        -- Then move the estimate over once, whole, so the wobble does not ride along with it.
        model.loop += change
        for _, range in ipairs(model.history) do range[1] += change; range[2] += change end
        model.loopPing, model.strays, model.straySide = ping, 0, 0
        return 0
    end
    if not network.enabled or math.abs(change) <= 0.004 then return 0 end
    -- Follow small ping changes, but not the few milliseconds the reading wobbles by.
    return change - math.sign(change) * 0.004
end

-- Returns the round trip to plan with, and how much of it is ping adjustment.
local function loopLatency()
    local ping = network.median
    if model.loop then
        local shift = timing.pingShift()
        local value = model.loop + shift
        -- Every round trip measured so far sat within 15 ms of the data ping. One that is nowhere
        -- near it was carried over wrongly; it is dropped and measured afresh on this server.
        if not ping or (value >= 0.008 and math.abs(value - (ping - 0.005)) <= 0.030) then
            return math.clamp(value, 0.008, 0.400), shift
        end
        model.loop, model.loopPing, model.history, model.strays, model.straySide = nil, nil, {}, 0, 0
    end
    -- Nothing measured yet. The round trip runs about 3 ms under the data ping.
    return ping and math.clamp(ping - 0.003, 0.008, 0.300) or 0.030, 0
end

local function showPing()
    if not network.latest then
        hubControls.pingStatus.Text = "Shift+F3 data ping unavailable."
        return
    end
    local link = not model.loop and "release link not measured yet"
        or string.format(network.enabled and "release link %.0f ms" or "release link %.0f ms (ping ignored)", loopLatency() * 1000)
    hubControls.pingStatus.Text = string.format("Data ping %.2f ms  •  %s", network.latest * 1000, link)
end

local function watchPing(now)
    if now < network.nextSample then return end
    network.nextSample = now + 0.5
    if not signals.complete then signals.connect() end
    local ok, pingMs = pcall(function()
        return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
    end)
    if ok and type(pingMs) == "number" and pingMs > 0 and pingMs < 3000 then
        local ping = pingMs / 1000
        network.latest = ping
        network.smooth = network.smooth and (network.smooth * 0.72 + ping * 0.28) or ping
        -- The statistic spikes for single samples; a median ignores those.
        local history = network.history
        table.insert(history, ping)
        if #history > 9 then table.remove(history, 1) end
        local sorted = table.clone(history)
        table.sort(sorted)
        network.median = sorted[math.ceil(#sorted / 2)]
    else
        network.latest, network.smooth, network.median = nil, nil, nil
        table.clear(network.history)
    end
    showPing()
end

local function finishAction(action)
    return type(action) == "string" and (action == "Dunking" or action:lower():find("layup", 1, true))
end

-- "Dunk" or "Layup" when the character is finishing at the rim, with the action it is in.
-- The game runs a plain layup as a "Shooting" action with a layup animation.
function timing.finishKind(character)
    local action = character:GetAttribute("Action")
    if action == "Dunking" then return "Dunk", action end
    if finishAction(action) then return "Layup", action end
    local animation = character:GetAttribute("BaseAnimation")
    if action == "Shooting" and type(animation) == "string" and animation:find("Layup", 1, true) then
        return "Layup", action
    end
end

function timing.meterActive(meter)
    if meter and type(meter.GetAttribute) == "function" then return meter:GetAttribute("Active") end
end

function timing.meterValue(character)
    local offset = character and character:GetAttribute("meterOffset")
    if typeof(offset) == "Vector2" then
        local value = -offset.Y
        if value == value and value > -0.5 and value < 5 then return value end
    end
end

function timing.greenWindow(meter)
    -- The third keypoint is where the green zone starts. The server sets it for each shot.
    local ok, edge = pcall(function()
        local green = meter:FindFirstChild("Meter_Green")
        local gradient = green and green:FindFirstChild("UIGradient", true)
        local point = gradient and gradient.Transparency.Keypoints[3]
        return point and point.Time
    end)
    if ok and type(edge) == "number" and edge == edge then return edge end
end

-- How far from the peak a step can be and still rate Perfect, for a given green window.
function timing.reach(green)
    return green and math.max(0, model.width * (green - 0.259)) or nil
end

function timing.newStream(stale)
    -- `stale` is the fill left over from the previous shot; the meter is live once it changes.
    return {count = 0, times = {}, values = {}, raws = {}, stale = stale}
end

function timing.measureSteps(stream)
    -- One sample can cover two server steps when both land in the same frame, so count steps
    -- by how far the fill moved rather than by how many samples arrived. Only recent steps
    -- count, so a meter that changes speed is followed.
    local values, times, count = stream.values, stream.times, stream.count
    local first = math.max(3, count - 12)
    local rises = {}
    for index = first, count do rises[#rises + 1] = values[index] - values[index - 1] end
    table.sort(rises)
    local typical = rises[math.ceil(#rises / 2)]
    if typical < 0.004 then return end
    -- When frames run slow, several server steps arrive at once and the typical rise is a
    -- multiple of the real step. The smallest rise is the real one if the typical rise is a
    -- whole number of it.
    local unit = typical
    for _, rise in ipairs(rises) do
        if rise >= 0.004 then
            local ratio = typical / rise
            if ratio > 1.5 and math.abs(ratio - math.floor(ratio + 0.5)) < 0.12 then unit = rise end
            break
        end
    end
    local function countSteps(size)
        local steps = 0
        for index = first, count do
            steps += math.max(1, math.floor((values[index] - values[index - 1]) / size + 0.5))
        end
        return steps
    end
    local steps = countSteps(unit)
    local span, elapsed = values[count] - values[first - 1], times[count] - times[first - 1]
    -- The server steps 60 times a second. If even the smallest rise took much longer than
    -- that, it covered several steps too.
    local each = elapsed / steps
    if each > 0.030 then
        steps = countSteps(unit / math.max(2, math.floor(each * 60 + 0.5)))
    end
    stream.step = span / steps
    stream.period = math.clamp(elapsed / steps, 1 / 240, 1 / 10)
end

-- Records a new fill value. Values are stored unfolded: after the turnaround they keep rising
-- (peak plus the distance travelled back down), so one straight line describes the whole meter.
-- Returns "restart" when the value can only belong to a new meter.
function timing.addStep(stream, now, raw)
    if stream.closed or raw == stream.raw or (stream.count == 0 and raw == stream.stale) then return false end
    local values, times, raws = stream.values, stream.times, stream.raws
    local count, value = stream.count, raw
    if count > 0 then
        local previous, step = values[count], stream.step
        if raw < stream.raw - 0.5 or (raw < stream.raw and not stream.falling and (not step or raw <= 0.6)) then
            -- The fill fell back to the bottom: a new meter has started.
            return "restart"
        elseif stream.falling then
            value = 2 * stream.peak - raw
            if value <= previous then
                -- The fill bottomed out and is rising again. Nothing after this helps.
                stream.closed = true
                return false
            end
        elseif step then
            local elapsed = (now - times[count]) / stream.period
            -- How well a candidate lands on the server's step grid, and after how many steps.
            local function grid(candidate)
                local steps = math.max(1, math.floor((candidate - previous) / step + 0.5))
                return math.abs(candidate - previous - steps * step) / step + 0.25 * math.abs(steps - elapsed), steps
            end
            local risingScore = grid(raw)
            local fallingScore, fallingSteps = math.huge, 1
            if raw <= model.peak + 0.01 then fallingScore, fallingSteps = grid(2 * model.peak - raw) end
            if raw < previous or fallingScore + 0.05 < risingScore then
                -- The fill reflected off the peak between the last two samples.
                local steps = fallingSteps
                local least = math.max(1, math.ceil((previous - raw) / step - 0.05))
                local timed = math.max(1, math.floor(elapsed + 0.5))
                if raw < previous and timed >= least and math.abs(elapsed - timed) < 0.3 then
                    -- The gap pins the step count, so this measures the peak directly.
                    steps = timed
                    stream.peakSeen = (raw + previous + steps * step) / 2
                end
                steps = math.max(steps, least)
                stream.falling, stream.rising = true, count
                stream.peak = (raw + previous + steps * step) / 2
                value = previous + steps * step
            end
        end
    end
    count += 1
    values[count], times[count], raws[count] = value, now, raw
    stream.count, stream.raw = count, raw
    if not stream.falling and count >= 4 then timing.measureSteps(stream) end
    return true
end

-- Fits arrival time against fill over the most recent rising steps up to `last`.
-- Returns seconds per unit of fill, plus one point on the line (time, fill).
function timing.fit(stream, last)
    local values, times = stream.values, stream.times
    last = math.min(last, stream.rising or stream.count)
    if last < 6 then return end
    local first = math.max(2, last - 13)
    local origin, base = values[last], times[last]
    local function regress(skip)
        local n, sumV, sumT, sumVV, sumVT = 0, 0, 0, 0, 0
        for index = first, last do
            if not (skip and skip[index]) then
                local v, t = values[index] - origin, times[index] - base
                n += 1
                sumV += v
                sumT += t
                sumVV += v * v
                sumVT += v * t
            end
        end
        local spread = n * sumVV - sumV * sumV
        if n < 4 or spread <= 1e-9 then return end
        local slope = (n * sumVT - sumV * sumT) / spread
        return slope, (sumT - slope * sumV) / n
    end
    local slope, intercept = regress(nil)
    if not slope then return end
    -- A packet can arrive late but never early. Refit without clear stragglers.
    local total, skip = 0, nil
    for index = first, last do
        local miss = times[index] - base - intercept - slope * (values[index] - origin)
        total += miss * miss
    end
    local limit = math.max(0.005, 2.5 * math.sqrt(total / (last - first + 1)))
    for index = first, last do
        if math.abs(times[index] - base - intercept - slope * (values[index] - origin)) > limit then
            skip = skip or {}
            skip[index] = true
        end
    end
    if skip then
        local trimmedSlope, trimmedIntercept = regress(skip)
        if trimmedSlope then slope, intercept = trimmedSlope, trimmedIntercept end
    end
    if slope < 0.08 or slope > 1.5 then return end
    return slope, base + intercept, origin
end

function timing.plan(attempt)
    local stream = attempt.stream
    local step = stream.step
    if not step then return end
    local slope, anchorTime, anchorValue = timing.fit(stream, stream.count)
    if not slope then return end
    local period = slope * step
    if period < 1 / 240 or period > 1 / 10 then return end
    local function arrival(value)
        return anchorTime + slope * (value - anchorValue)
    end
    -- The server keeps stepping from the last value seen. Find the step that lands nearest the
    -- peak, then every neighbouring step that also falls inside the green window.
    local peak, last = model.peak, stream.values[stream.count]
    local top = last + math.floor((peak - last) / step + 0.5) * step
    local reach = timing.reach(signals.green or attempt.green)
    local first, final = top, top
    local inWindow = reach ~= nil and math.abs(top - peak) <= reach
    if inWindow then
        for _ = 1, 3 do
            if math.abs(first - step - peak) <= reach then first -= step end
            if math.abs(final + step - peak) <= reach then final += step end
        end
    end
    -- The server rates whichever step it wrote last, so the release must be handled between the
    -- first good step being written and the heartbeat after the last one. Aim for the middle.
    local aim = (arrival(first) + arrival(final) + period) / 2
    local bias = (attempt.mode == jump and hubControls.jumpBias.value or hubControls.finishBias.value) / 1000
    return {top = top, first = first, final = final, reach = reach, inWindow = inWindow, aim = aim,
        releaseAt = aim - attempt.loop + bias, step = step, period = period, slope = slope}
end

-- The round trip that fits the most recent releases. Each release only narrows it to one
-- heartbeat, so several are combined and the middle of the best-supported range is used.
function timing.consensus(history, prior)
    local low, high = prior - 0.008, prior + 0.008
    for _, range in ipairs(history) do
        low, high = math.min(low, range[1]), math.max(high, range[2])
    end
    local values, counts, best = {}, {}, 0
    local value = math.floor(low * 1000 + 0.5) / 1000
    while value <= high + 0.0005 and #values < 600 do
        local count = 0
        for _, range in ipairs(history) do
            if value > range[1] and value <= range[2] then count += 1 end
        end
        -- With little to go on, the starting estimate counts for a release and a half: one odd
        -- release cannot move it, two that agree can.
        if #history < 4 and math.abs(value - prior) <= 0.008 then count += 1.5 end
        values[#values + 1], counts[#counts + 1] = value, count
        best = math.max(best, count)
        value += 0.001
    end
    local bestStart, bestLength, runStart = 1, 0, nil
    for index = 1, #counts + 1 do
        if counts[index] == best then
            runStart = runStart or index
        elseif runStart then
            if index - runStart > bestLength then bestStart, bestLength = runStart, index - runStart end
            runStart = nil
        end
    end
    if bestLength == 0 then return prior end
    return (values[bestStart] + values[bestStart + bestLength - 1]) / 2
end

-- Learns from a rated release. Returns what the server registered, or nil when it cannot be measured.
function timing.learn(attempt, order)
    local stream, released = attempt.stream, attempt.releasedAt
    local step = stream.step
    if not order or not released or attempt.feedbackAmbiguous or not step then return end
    local slope, anchorTime, anchorValue = timing.fit(stream, attempt.fitCount or 0)
    if not slope then return end
    local count, period, peak = stream.count, slope * step, model.peak
    local final = stream.values[count]
    local arrival = anchorTime + slope * (final - anchorValue)
    -- The server handled the release during the heartbeat after it wrote this step.
    local low = arrival - released
    local high = low + period
    if low < -2 * period or low > 0.6 or math.abs(stream.times[count] - arrival) > 0.04 then return end

    local used, plan = attempt.loop or loopLatency(), attempt.plan
    local best = final - math.floor((final - peak) / step + 0.5) * step
    local result = {landed = stream.raw, final = final, peak = stream.peak or peak, turned = stream.falling == true,
        low = low, high = high, used = used, period = period, slope = slope,
        reach = timing.reach(attempt.green), bestDepth = math.abs(best - peak),
        offset = attempt.sentAt and plan and math.floor((final - plan.top) / step + 0.5) or nil}
    -- A key-up the game picked up late (a stalled frame) says nothing about the connection.
    local delay = attempt.sentAt and released - attempt.sentAt
    if delay and delay > 0.030 then
        result.stalled = delay
        return result
    end

    -- Only an ordinary release near the peak measures the round trip well.
    if (attempt.fitCount or 0) >= 10 and math.abs(final - peak) < 0.35 then
        local history, shift, previous = model.history, attempt.loopShift or 0, model.loop
        local range = {low - shift, high - shift}
        -- Which side of the current estimate this release fell on, if it missed it altogether.
        -- About one release in four arrives a server step late for no lasting reason, so only a
        -- run of misses on the same side means the connection itself has changed.
        local side = 0
        if previous then
            if previous <= range[1] - 0.002 then side = 1 elseif previous > range[2] + 0.002 then side = -1 end
        end
        if side ~= 0 and side == model.straySide then
            model.strays += 1
        else
            model.strays, model.straySide = side ~= 0 and 1 or 0, side
        end
        table.insert(history, range)
        if model.strays >= 4 then
            while #history > 4 do table.remove(history, 1) end
            for _, kept in ipairs(history) do kept[1], kept[2] = kept[1] + shift, kept[2] + shift end
            model.strays, model.straySide, model.loopPing = 0, 0, network.median
        end
        while #history > 16 do table.remove(history, 1) end
        model.loop = math.clamp(timing.consensus(history, previous or used), 0.004, 0.400)
        model.loopPing = model.loopPing or network.median
    end

    local seen = stream.peakSeen
    if seen and seen > 1 and seen < 2 then
        if math.abs(seen - model.peak) <= 0.03 then
            model.peak += (seen - model.peak) * 0.2
            model.peakOdd = nil
        elseif model.peakOdd and math.abs(seen - model.peakOdd) <= 0.015 then
            model.peak, model.peakOdd = (seen + model.peakOdd) / 2, nil
        else
            model.peakOdd = seen
        end
    end

    -- A step inside the green window always rates Perfect. If it keeps rating early or late
    -- instead, the game's peak has moved: walk toward it half a step at a time.
    if result.reach and math.abs(final - peak) <= result.reach then
        if order == 5 then
            model.lean = 0
        elseif order <= 4 then
            model.lean = math.min(model.lean, 0) - 1
        else
            model.lean = math.max(model.lean, 0) + 1
        end
        if math.abs(model.lean) >= 3 then
            model.peak = math.clamp(model.peak - math.sign(model.lean) * 0.5 * step, 1.2, 1.8)
            model.lean = 0
        end
    end

    -- Keep the green window's measured width honest: Perfect proves a step was inside it,
    -- anything else on a step the model called safe proves it is narrower.
    local span = attempt.green and attempt.green - 0.259
    if span and span > 0.004 and math.abs(final - peak) < 0.2 then
        local ratio = math.abs(final - peak) / span
        if order == 5 then
            if ratio > model.width then model.width = math.min(0.56, ratio) end
        elseif ratio < model.width then
            model.width = math.max(0.30, ratio * 0.97)
        end
    end

    -- With the fallback release, the key-up is picked up when the next frame reads input.
    local frame = attempt.sentFrame
    if delay and frame and delay >= 0.0005 then
        model.frames = math.clamp(model.frames + math.clamp(delay / frame - model.frames, -1, 1) * 0.15, 0.5, 3)
    end
    return result
end

-- Queues one line per finished attempt for Real's workspace so timing can be checked afterwards.
function timing.record(attempt, reason, rating, order, result)
    if not shotLog.enabled then return end
    local stream, origin = attempt.stream, attempt.start
    local function ms(seconds)
        return seconds and math.floor(seconds * 10000 + 0.5) / 10 or nil
    end
    local function since(moment)
        return moment and ms(moment - origin) or nil
    end
    local times, fills = {}, {}
    for index = 1, math.min(stream.count, 90) do
        times[index] = since(stream.times[index])
        fills[index] = math.floor(stream.raws[index] * 10000 + 0.5) / 10000
    end
    local plan, feedback = attempt.plan, attempt.rated
    local entry = {
        version = 4, at = os.time(), serial = attempt.serial, reason = reason, rating = rating, order = order,
        contest = feedback and feedback.contest, antiContest = attempt.antiContest, kind = attempt.kind, key = (attempt.inputControl and attempt.inputControl.label or attempt.control.keyName), source = attempt.source,
        assisted = attempt.sentAt ~= nil, direct = attempt.direct, action = attempt.action, green = attempt.green,
        speed = attempt.character:GetAttribute("ShotSpeed"), gather = attempt.character:GetAttribute("GatherType"),
        stamina = attempt.character:GetAttribute("Stamina"), distance = attempt.distance, frame = ms(attempt.frameInterval),
        ping = ms(network.latest), pingMedian = ms(network.median), armed = since(attempt.armedAt), sent = since(attempt.sentAt),
        released = since(attempt.releasedAt), ratedAt = feedback and since(feedback.at), callMs = ms(attempt.callTime),
        worstFrame = ms(attempt.worstFrame), fitCount = attempt.fitCount, loopUsed = ms(attempt.loop), loopNow = ms(model.loop),
        width = model.width, peak = model.peak, step = stream.step, period = ms(stream.period), turned = stream.rising,
        times = times, fills = fills,
    }
    if plan then
        entry.plan = {top = plan.top, first = plan.first, final = plan.final, reach = plan.reach, inWindow = plan.inWindow,
            aim = since(plan.aim), releaseAt = since(plan.releaseAt), period = ms(plan.period)}
    end
    if result then
        entry.result = {landed = result.landed, final = result.final, turned = result.turned, stalled = ms(result.stalled),
            low = ms(result.low), high = ms(result.high), offset = result.offset, reach = result.reach, bestDepth = result.bestDepth}
    end
    -- Where the player was heading when the key went down, and for a dunk or layup what became
    -- of it after the release.
    local heading, finish = attempt.travel, attempt.finish
    if heading then
        entry.travel = {speed = math.floor(heading.speed * 10 + 0.5) / 10, closing = math.floor(heading.closing * 10 + 0.5) / 10,
            heading = math.floor(heading.heading * 100 + 0.5) / 100, sprint = heading.sprint}
    end
    if finish then
        entry.finish = {kind = finish.kind, began = finish.began, ended = finish.ended, changed = since(finish.changedAt),
            keyUp = since(attempt.keyUpAt), heldBack = finish.heldBack, jelly = finish.jelly,
            animation = attempt.character:GetAttribute("BaseAnimation")}
    end
    if type(antiContestV2.trace) == "function" then pcall(antiContestV2.trace, "auto_green_shot", entry) end
    shotLog.add(entry)
end

-- Remembers a rated shot until the game says what kind of shot it was.
function timing.await(rating, serial, suffix)
    local rated = {at = os.clock(), rating = rating, serial = serial, suffix = suffix}
    timing.lastRated = rated
    local awaiting = timing.awaiting
    awaiting[#awaiting + 1] = rated
    while #awaiting > 6 do table.remove(awaiting, 1) end
end

-- The game's own name for the shot arrives a moment after the rating (up to three seconds for
-- a long jump shot), sometimes after the next shot has already begun.
function timing.describeShot(kind, contest, chance)
    local now, awaiting = os.clock(), timing.awaiting
    while awaiting[1] and now - awaiting[1].at > 4.5 do table.remove(awaiting, 1) end
    local rated = table.remove(awaiting, 1)
    if not rated then return end
    local name = kind:gsub("(%l)(%u)", "%1 %2")
    -- Only the latest shot's line on the HUD may change, and not while another is being timed.
    if rated == timing.lastRated and not shot then hud.describe(name .. (rated.suffix or "")) end
    shotLog.say(string.format("%s | %s | make chance %.0f%%", name, rated.rating, chance or 0))
    shotLog.add({version = 4, at = os.time(), serial = rated.serial, shotType = kind,
        contest = contest, chance = chance, rating = rated.rating})
end

function timing.capture()
    return {peak = model.peak, loop = model.loop, loopPing = model.loopPing, frames = model.frames, width = model.width}
end

function timing.restore(saved)
    model = timing.freshModel()
    if type(saved) ~= "table" then return end
    local function within(value, low, high)
        return type(value) == "number" and value == value and value >= low and value <= high and value or nil
    end
    model.peak = within(saved.peak, 1.2, 1.8) or model.peak
    -- A saved round trip may come from another server; the ping difference is applied to it
    -- and the first few releases here correct the rest.
    model.loop = within(saved.loop, 0.004, 0.400)
    model.loopPing = model.loop and within(saved.loopPing, 0.0005, 3) or nil
    -- Without the ping it was measured at, a saved round trip cannot be moved to this server.
    if not model.loopPing then model.loop = nil end
    model.frames = within(saved.frames, 0.5, 3) or model.frames
    model.width = within(saved.width, 0.30, 0.56) or model.width
end

function timing.classify(attempt, action)
    local kind = timing.finishKind(attempt.character)
    if kind then
        -- A dunk or a layup.
    elseif action == "Shooting" then
        kind = "Jump"
    elseif attempt.armedAt then
        -- The game started a meter for this shot, whatever it calls the action.
        kind = attempt.kind or "Shot"
    end
    if kind == attempt.kind then return end
    attempt.kind = kind
    if not kind then return end
    local mode = (kind == "Jump" and jump) or ((kind == "Dunk" or kind == "Layup") and dunk) or attempt.mode
    if mode ~= attempt.mode then attempt.mode.result = attempt.mode.ready end
    attempt.mode = mode
    mode.result = "Timing the release…"
    refresh()
end

function timing.beginGeneration(attempt, now)
    -- A new meter started: nothing measured from the previous one applies.
    attempt.stream = timing.newStream(nil)
    attempt.armedAt = now
    attempt.plan, attempt.planCount, attempt.loop, attempt.loopShift, attempt.fitCount = nil, nil, nil, nil, nil
    attempt.shown, attempt.action, attempt.kind = nil, nil, nil
    timing.own(attempt, now)
end

-- Takes over the release of a shot Auto Green is timing: from now until it is rated, the
-- game's own shoot-key messages are held back (see the gate above) and this script sends the
-- release. Without the gate, or with Auto Green off, the key keeps working as the game made it.
function timing.canAssist(attempt)
    if not shotInput.isNative(attempt) then return automationAvailable() end
    local gate = signals.gate
    return signals.release ~= nil and gate ~= nil and rawget(gate.sender, "Fire") == gate.filter
end
function timing.stopControl(attempt)
    if shotInput.isNative(attempt) and attempt.owned and not attempt.sentAt and not attempt.releasedAt then
        attempt.keyUpAt = attempt.keyUpAt or os.clock()
    end
end
function timing.own(attempt, now)
    if shotInput.isNative(attempt) and not timing.canAssist(attempt) then return end
    local gate = signals.gate
    if not gate or not signals.release or not attempt.assist then return end
    if not attempt.owned then attempt.owned, gate.before = true, gate.swallowed end
    gate.untilAt, gate.serial = now + 2, signals.serial
end

-- True while the gate is holding this attempt's key messages back.
function timing.holding(attempt)
    local gate = signals.gate
    return gate ~= nil and attempt.owned == true and os.clock() < gate.untilAt and gate.serial == signals.serial
end

-- Hands the key back to the game. If the player has already let go (that key-up was held back),
-- the release they are owed is sent now.
function timing.settle(attempt)
    local gate = signals.gate
    if not gate or not attempt.owned then return end
    attempt.owned = false
    gate.untilAt = 0
    if (attempt.keyUpAt or attempt.keyless) and not attempt.sentAt and not attempt.releasedAt then
        local remote = signals.release
        attempt.sentAt = os.clock()
        if remote and pcall(antiContestV2.forwardRelease, remote.FireServer, remote, {Shoot = false}) then
            attempt.releasedAt, attempt.fitCount, attempt.direct = attempt.sentAt, attempt.stream.count, true
        end
    end
end

-- Called when a shot has just been released. For a dunk or layup it starts keeping track of
-- what the game makes of it, and queues the chosen finish (jelly or double clutch) if wanted.
function timing.queueFinish(attempt, releasedAt)
    local kind, action = timing.finishKind(attempt.character)
    if not kind then return end
    attempt.finish = {kind = kind, began = action, last = action}
    if not autoJelly or not automationAvailable() or jelly or (attempt.stream.raw or 0) < 0.35 then return end
    if autoDunk and kind == "Dunk" then
        -- Auto Dunk asks for dunks: one the game has started stays a dunk. Layups get the finish.
        hubControls.jellyStatus.Text = "Dunk kept (Auto Dunk is on)."
        return
    end
    local style = hubControls.finishStyles[config.finish]
    if not style.key then
        style = hubControls.finishStyles[nextFinish]
        nextFinish = 3 - nextFinish
    end
    jelly = {character = attempt.character, initialAction = action, style = style,
        releaseAt = releasedAt, pressAt = releasedAt + 0.052}
    attempt.finish.jelly = style.name
    hubControls.jellyStatus.Text = "Waiting for the finish window…"
end

-- Tells the server the shot key came up. Sending the game's own release message is exact.
-- Faking a key-up through Windows instead froze the game for about 70 ms on some shots and,
-- with the key still physically held, made Windows press it again; that path is only the
-- fallback for when the game's message cannot be found.
function timing.release(attempt, now)
    if antiContestV2 and antiContestV2.markRelease then pcall(antiContestV2.markRelease) end
    attempt.sentAt = now
    local remote, gate = signals.release, signals.gate
    -- A key this script pressed comes up through the game's own input code, which sends the
    -- release too. Unless that copy can be held back, let it be the only one.
    local nativeReleaseAttempted=false
    local function forwardNativeRelease()
        nativeReleaseAttempted=true
        return pcall(antiContestV2.forwardRelease,remote.FireServer,remote,{Shoot=false})
    end
    if remote and (gate or not attempt.held) and forwardNativeRelease() then
        attempt.releasedAt, attempt.fitCount, attempt.direct = now, attempt.stream.count, true
        timing.queueFinish(attempt, now)
        if gate then
            if not attempt.owned then gate.before = gate.swallowed end
            -- A dunk or layup stays in the air for most of a second, and a second release would
            -- turn it into a clutch layup: keep the key held back until it is rated. A jump shot
            -- is rated at once, so the key is handed back almost immediately.
            gate.untilAt, gate.serial = now + (attempt.finish and 1.6 or 0.4), signals.serial
            attempt.owned = true
        end
        if attempt.held then releaseKey(attempt.control.virtualKey) end
        attempt.held = false
        return
    end
    if nativeReleaseAttempted and antiContestV2.variant=="v3" then
        attempt.releaseFailed,attempt.assist=true,false
        if gate then gate.untilAt,gate.serial=now+.4,signals.serial;attempt.owned=true end
        if attempt.held and gate then releaseKey(attempt.control.virtualKey) end
        attempt.held=false
        attempt.mode.result="Native release failed; V3 stopped without retrying the shot."
        return
    end
    if shotInput.isNative(attempt) then
        attempt.sentAt, attempt.assist = nil, false
        timing.settle(attempt)
        attempt.mode.result = "Native release unavailable; normal button release restored."
        return
    end
    timing.settle(attempt)
    attempt.sentFrame, attempt.held = attempt.frameInterval, false
    local before = os.clock()
    releaseKey(attempt.control.virtualKey)
    attempt.callTime = os.clock() - before
end

-- Ends an attempt that will not be rated.
function timing.drop(attempt, message, reason)
    timing.stopControl(attempt)
    timing.settle(attempt)
    if attempt.held then releaseKey(attempt.control.virtualKey) end
    if shot == attempt then shot = nil end
    attempt.mode.result = message
    refresh()
    -- A key press the game never started a meter for (a tap to gather, a press without the
    -- ball) was not a shot; only real attempts and this script's own presses are kept.
    if attempt.armedAt or attempt.automated then
        pcall(timing.record, attempt, reason)
        shotLog.say(attempt.mode.name .. " | " .. privacy.redact(message))
    end
end

function timing.fail(failure)
    -- A timing fault must never leave a key held or stall the rest of the dashboard.
    local attempt = shot
    shot = nil
    if attempt then timing.stopControl(attempt); pcall(timing.settle, attempt) end
    if attempt and attempt.held then releaseKey(attempt.control.virtualKey) end
    local now = os.clock()
    if now >= (timing.nextFailureReport or 0) then
        timing.nextFailureReport = now + 10
        warn(prefix .. "Shot timing stopped on an error: " .. tostring(failure))
    end
end

local function applyRating(attempt, rating, order)
    local mode = attempt.mode
    order = order or hubControls.ratingOrder[string.lower(rating)]
    attempt.green = signals.green or timing.greenWindow(attempt.meter)
    -- The rating must still reach the HUD if measuring the release goes wrong.
    local learned, result = pcall(timing.learn, attempt, order)
    if not learned then
        shotLog.say("Could not measure this release: " .. tostring(result))
        result = nil
    end
    -- Some shots are given a green window too small for any server step to land in.
    local noWindow = result and result.reach and result.bestDepth > result.reach
    if result then
        mode.detail = string.format("Landed  %.3f", result.landed)
        if noWindow then
            -- What usually closes the window: a three from too far out, or a moving shot when tired.
            local stamina = attempt.character:GetAttribute("Stamina")
            mode.detail = "No green window"
            if attempt.distance and type(stamina) == "number" then
                mode.detail ..= string.format("\n%.0f studs, stamina %.0f", attempt.distance, stamina)
            end
        end
    end
    -- A dunk or layup: what did it end as?
    local finish = attempt.finish
    if finish then
        finish.ended = finish.ended or finish.began
        local gate = signals.gate
        if gate and gate.before then finish.heldBack = gate.swallowed - gate.before end
    end
    local isLayup = attempt.kind == "Layup" or (finishAction(attempt.action) and attempt.action ~= "Dunking")
    local shotName = attempt.kind and (isLayup and "Layup" or mode.name) or ("Shot " .. (attempt.inputControl and attempt.inputControl.label or attempt.control.keyName))
    if not attempt.sentAt then shotName ..= " (manual)" end
    local suffix = noWindow and " (no green window)" or ""
    timing.await(rating, attempt.serial, suffix)
    hud.onRating(shotName .. suffix, rating)
    mode.result = rating
    refresh()
    local context = (attempt.kind or "unclassified") .. "/" .. (attempt.inputControl and attempt.inputControl.label or attempt.control.keyName)
    if result then
        local aim = "manual"
        if result.stalled then
            aim = string.format("key-up stalled %.0f ms", result.stalled * 1000)
        elseif result.offset then
            aim = result.offset == 0 and "on the aimed step" or string.format("%+d step from aim", result.offset)
        end
        shotLog.say(string.format("%s | %s | %s | %s | landed %.3f of peak %.3f | %s | %s | link %.1f ms",
            mode.name, rating, attempt.source, context, result.landed, result.peak, aim,
            noWindow and "no step could reach the green window" or string.format("green reach %.3f", result.reach or 0),
            (model.loop or result.used) * 1000))
    else
        shotLog.say(string.format("%s | %s | %s | %s | release not measured (%d steps seen)",
            mode.name, rating, attempt.source, context, attempt.stream.count))
    end
    if finish then
        shotLog.say(string.format("%s %s | key messages held back: %d%s", finish.kind,
            finish.ended == finish.began and "stayed as it was" or ("became " .. tostring(finish.ended)),
            finish.heldBack or 0, finish.jelly and (" | " .. finish.jelly .. " sent") or ""))
    end
    pcall(timing.record, attempt, "rated", rating, order, result)
    showPing()
end

-- `live` is set when the game's meter is already running for this key (the key went down before
-- the script could see a shot starting).
local function startShot(mode, automated, source, live, physical)
    if automated and shotInput.manualOnly then timing.refused = "Automatic shot start blocked: shot input required";return end
    -- Why a key press was not followed is kept for the log line of a shot that then went untracked.
    timing.refused = (stopped and "script stopped") or (traveling and "teleporting") or (pendingRelease and "a key release is pending")
        or (macro and "a dribble macro is running") or (capturing and "a keybind is being set")
        or (input:GetFocusedTextBox() and "a text box has focus") or nil
    if timing.refused then return end
    if not automated then timing.lastKeyAt = os.clock() end
    if shot then
        timing.refused = "the previous key press was still being followed"
        if automated or not (shot.releasedAt or shot.sentAt) then return end
        -- A release is still waiting for its rating. The same key going down again this soon is
        -- the key being held, not a new shot.
        if shot.control == mode and os.clock() - (shot.releasedAt or shot.sentAt) < 1.2 then return end
        if shot.armedAt then pcall(timing.record, shot, "replaced") end
        timing.refused = nil
    end
    if not robloxFocused() or (automated and (not automationAvailable() or executorInput.keyDown(mode.key))) then
        timing.refused = "Roblox window not focused"
        return
    end

    local character, root = findCharacter()
    -- A meter the game has already started (`live`) is a shot whether or not the ball counted as
    -- in hand when the key went down: jumping for a lob, the key comes first and the ball after.
    if not root or not (live or heldBall(character)) then
        timing.refused = "no ball in hand"
        if automated then report(mode, mode.ready) end
        return
    end
    local meter, gradient, feedback, rating = findMeter(root)
    if not meter then
        timing.refused = "Vertical meter not found"
        if automated then report(mode, "Select the Vertical meter before shooting.") end
        return
    end
    defense.stop()
    local goal = characterGoal(character)
    local pos = root.Position
    local distance, heading
    if goal and goal:IsA("BasePart") then
        distance = Vector2.new(goal.Position.X - pos.X, goal.Position.Z - pos.Z).Magnitude
        -- Which way the player was moving decides what the game starts: a dunk or layup on a
        -- straight run at the rim, a moving jump shot otherwise.
        local speed, closing, direct = timing.toward(os.clock(), goal.Position)
        if speed then
            heading = {speed = speed, closing = closing, heading = direct, sprint = character:GetAttribute("Sprinting") == true}
        end
    end
    local priorRating = privacy.readText(rating)
    shot = {
        control = mode, mode = mode, character = character, root = root,
        inputControl = physical or (not automated and shotInput.held(mode))
            or shotInput.describe(mode, Enum.UserInputType.Keyboard, mode.key),
        meter = meter, gradient = gradient, feedback = feedback, rating = rating,
        -- With the game's announcements, nothing counts until it starts a meter after this key
        -- press. Without them, the fill left over from the previous shot has to change first.
        stream = timing.newStream(timing.meterValue(character)),
        serial = signals.serial - (live and 1 or 0),
        start = os.clock(), automated = automated, held = automated,
        assist = automated or assistKeys, source = source or (automated and "button" or "key"),
        feedbackCleared = not (feedback.Enabled and rating.Visible and priorRating ~= ""), priorRating = priorRating,
        feedbackAmbiguous = shot ~= nil,
        distance = distance, travel = heading,
    }
    mode.result = "Watching the meter..."
    refresh()
    if automated then keypress(mode.virtualKey) end
    return true
end

function antiContestV2.cancelTracked(character)
    local attempt = shot
    if attempt and attempt.character == character and not attempt.armedAt then
        timing.drop(attempt, "Shot cancelled before server acknowledgement.", "v2 cancelled")
    end
end

local function nearestRim(character, position)
    local hoops = workspace:FindFirstChild("Hoops")
    if not hoops then return end
    local attributes = character:FindFirstChild("Attributes")
    local goalValue = attributes and attributes:FindFirstChild("Goal")
    local goal = goalValue and goalValue:IsA("ObjectValue") and goalValue.Value
    local closest, distance = nil, math.huge
    for _, hoop in ipairs(hoops:GetChildren()) do
        local board = hoop:FindFirstChild("Backboard")
        local functionals = board and board:FindFirstChild("Functionals")
        local objects = functionals and functionals:FindFirstChild("Objects")
        local clientRim = objects and objects:FindFirstChild("ClientRim")
        local rim = clientRim and clientRim:FindFirstChild("Rim")
        if rim and rim:IsA("BasePart") then
            local delta = rim.Position - position
            local gap = Vector2.new(delta.X, delta.Z).Magnitude
            if goal and goal.Parent == hoop then return rim, gap end
            if gap < distance then closest, distance = rim, gap end
        end
    end
    return closest, distance
end

-- Auto Dunk: presses Space for the player on a straight run at the rim.
--
-- What the game starts on that press depends on where the player is heading. Straight at the
-- rim it starts a dunk or a layup; with a sideways key held it starts a moving jump shot
-- instead (every earlier press made while strafing became a mid-range fadeaway). So the press
-- waits for a straight run, and is made from the distance dunks were actually seen to start at
-- (13 to 20 studs) rather than from right under the rim.
local approach
local nextApproachSample = 0
local function watchApproach(now)
    local character, root = findCharacter()
    if not root then
        approach = nil
        return
    end
    timing.sampleTravel(now, root.Position)
    if now < nextApproachSample then return end
    nextApproachSample = now + 0.025
    if shotInput.manualOnly or not autoDunk or not automationAvailable() or not robloxFocused() then
        approach = nil
        return
    end

    local ball = heldBall(character)
    if not ball then
        approach = nil
        return
    end
    local rim, distance = nearestRim(character, root.Position)
    if not rim then return end

    if not approach or approach.ball ~= ball or approach.rim ~= rim then
        approach = {ball = ball, rim = rim, since = now}
    end
    -- One press per run at the rim; backing out past the zone readies the next.
    if distance > 18.5 then approach.used = nil end
    if approach.used or shot or macro or drag or sliderDrag or now - approach.since < 0.25 then return end
    if distance < 12 or distance > 16.5 then return end
    if shotInput.held(jump) or shotInput.held(dunk) or input:GetFocusedTextBox() then return end
    -- A shot key the player pressed a moment ago means they are setting up their own shot.
    if now - (timing.lastKeyAt or 0) < 1 then return end

    -- Below about walking pace the game answers the press with a standing jump shot, not a finish.
    local speed, closing, heading = timing.toward(now, rim.Position)
    if not speed or closing < 12 or heading < 0.9 then return end

    if startShot(dunk, true, "run-up") then
        approach.used = true
        shotLog.say(string.format("Auto Dunk pressed %.1f studs out, moving %.1f studs/s, %.0f%% straight at the rim.",
            distance, speed, heading * 100))
    else
        -- Could not press just now (no meter, another input in progress): try again shortly.
        nextApproachSample = now + 0.4
    end
end

local function updateSliderAt(item, x)
    local width = item.track.AbsoluteSize.X
    if width <= 0 then return end
    local position = math.clamp((x - item.track.AbsolutePosition.X) / width, 0, 1)
    showSlider(item, item.min + (item.max - item.min) * position)
end

local function mouseRelease(original, event)
    return original == event or (event.UserInputType == Enum.UserInputType.MouseButton1
        and original.UserInputType == Enum.UserInputType.MouseButton1)
end

local actions = {
    Menu = function()
        gui.Enabled = not gui.Enabled
        drag, sliderDrag = nil, nil
        if gui.Enabled then
            menuLayout.recover()
            appearance.pop()
        end
    end,
    ["Auto Green"] = function()
        assistKeys = not assistKeys
        if shot and not shot.automated then shot.assist = assistKeys end
        refresh()
    end,
    ["Ping compensation"] = function()
        network.enabled = not network.enabled
        showPing()
        refresh()
    end,
    ["Auto Dunk"] = function()
        autoDunk = not autoDunk
        refresh()
    end,
    ["Auto Jelly"] = function()
        autoJelly = not autoJelly
        if not autoJelly then cancelJelly() end
        hubControls.jellyStatus.Text = autoJelly and ("Ready for " .. hubControls.finishStyles[config.finish].name .. " after release.")
            or ""
        refresh()
    end,
    ["Auto Guard"] = function()
        defense.enabled = not defense.enabled
        defense.stop(defense.enabled and "Close the menu and hold your guard bind." or "Auto Guard is off.")
        refresh()
    end,
    ["Movement tuning"] = function()
        config.movement = not config.movement
        if not config.movement then restoreMovement() end
        refresh()
    end,
    ["Auto Block"] = function()
        autoBlock.enabled = not autoBlock.enabled
        autoBlock.stop(); autoBlock.refresh(); refresh()
    end,
    ["Dribble combo"] = function()
        if #combo.moves == 0 then hubControls.macroStatus = "Choose at least one move."; refresh(); return end
        local sequence = table.clone(combo.moves)
        beginMacro(sequence[1], sequence, 1)
    end,
    ["Court teleport"] = function() rage.courtTeleport.press() end,
    ["Rage"] = function()
        rage.stop()
        rage.enabled = not rage.enabled
        if rage.ownsSpeed() then restoreMovement() end
        refresh()
    end,
    ["Dribble boost"] = function() config.boost = not config.boost; refresh() end,
    ["Dribble glide"] = function() config.glide = not config.glide; refresh() end,
}

local reserved = {}
for name in ("E Space Q F W A S D C Z X V G H R T B LeftShift LeftControl RightControl LeftAlt RightAlt"
    .. " Zero One Two Three Four Five Six Seven Eight Nine"):gmatch("%S+") do
    reserved[name] = true
end
for name in ("Tab Return Slash Escape Backspace F6 F7 Unknown"):gmatch("%S+") do
    reserved[name] = "all"
end

local function assignable(key, target)
    if not key or key.Value >= 1000 then return false end
    if key == Enum.KeyCode.RightShift then return target == "Menu" end
    if target == "Auto Guard" then return reserved[key.Name] ~= "all" and not defense.conflictingKeys[key] end
    return not reserved[key.Name]
end

local function bindingMessage(message)
    hubControls.bindStatus = message
    if type(capturing) == "table" or capturing == "Dribble combo" then hubControls.macroStatus = message end
    if capturing == "Auto Guard" then defense.status.Text = message end
    if capturing == "Auto Block" and autoBlock.bindNote then autoBlock.bindNote.Text = message end
    refresh()
end

local function beginBinding(target)
    if input.TouchEnabled and not input.KeyboardEnabled then
        capturing = nil
        bindingMessage("Use the touch dock for actions. Connect a keyboard to edit keybinds.")
        return
    end
    capturing = target
    bindingMessage("Press a key, Backspace to clear, or Escape to cancel.")
end

local function setBinding(key)
    local target = capturing
    if key == Enum.KeyCode.Escape then
        bindingMessage("Binding canceled.")
    elseif key == Enum.KeyCode.Backspace then
        if target == "Menu" then
            bindings.Menu = Enum.KeyCode.RightShift
            bindingMessage("Menu restored to Right Shift.")
        else
            bindings[target] = nil
            bindingMessage("Binding cleared.")
        end
    else
        if not assignable(key, target) then
            bindingMessage("That key conflicts with this control. Choose another key.")
            return
        end
        for other, bound in pairs(bindings) do
            if other ~= target and key == bound then
                bindingMessage("Already assigned to " .. (type(other) == "table" and other[1] or other) .. ".")
                return
            end
        end
        bindings[target] = key
        bindingMessage("Bound to " .. key.Name .. ".")
    end
    capturing = nil
    refresh()
end

hubControls.settingSliders = {jumpBias = hubControls.jumpBias, finishBias = hubControls.finishBias, cadence = hubControls.cadence,
    boostStrength = hubControls.boostStrength, glideStrength = hubControls.glideStrength,
    offBall = hubControls.offBallSpeed, withBall = hubControls.withBallSpeed, acceleration = acceleration,
    guardRange = defense.range, guardSpacing = defense.spacing, guardStance = defense.stance,
    guardLead = defense.lead, guardResponse = defense.response, autoJoinInterval = courtJoin.interval}

local function captureConfig()
    local data = {
        autoGreen = assistKeys, autoDunk = autoDunk, autoJelly = autoJelly, manualShotsOnly = shotInput.manualOnly, drawThree = drawThree, guard = defense.enabled,
        guardFootwork = defense.footwork, antiStun = antiStun.enabled,
        defense = defense.capture(), rage = rage.capture(), autoBlock = autoBlock.capture(), antiContestV2 = antiContestV2.capture(),
        movement = config.movement, boost = config.boost, glide = config.glide, finish = config.finish,
        autoJoinCourt = courtJoin.enabled,
        ping = network.enabled, timingVersion = 4, timing = timing.capture(),
        sliders = {}, binds = {}, macroBinds = {}, learned = {},
        hud = hud.capture(), visuals = visualExtras.capture(), menu = menuLayout.capture(), privacy = privacy.capture(),
        avatar = avatar.capture(), menuAppearance = appearance.capture(), gameAppearance = gameAppearance.capture(), performance = renderOptions.capture(),
    }
    data.comboMoves = {}
    for i, move in ipairs(combo.moves) do data.comboMoves[i] = move[1] end
    for name, sliderItem in pairs(hubControls.settingSliders) do data.sliders[name] = sliderItem.value end
    data.binds["Auto Guard"] = false
    data.binds["Court teleport"] = false
    for target, key in pairs(bindings) do
        if type(target) == "table" then
            data.macroBinds[target[1]] = key.Name
        else
            data.binds[target] = key.Name
        end
    end
    return data
end

local function restoreBindings(data)
    local keyByName = {}
    for _, key in ipairs(Enum.KeyCode:GetEnumItems()) do keyByName[key.Name] = key end
    local used = {}
    table.clear(bindings)
    local function restore(target, name)
        local key = type(name) == "string" and keyByName[name]
        if target == "Menu" and not assignable(key, target) then key = Enum.KeyCode.RightShift end
        if assignable(key, target) and not used[key] then
            used[key], bindings[target] = true, key
        end
    end
    local saved = type(data.binds) == "table" and data.binds or {Menu = "RightShift"}
    local macroBinds = type(data.macroBinds) == "table" and data.macroBinds or {}
    for _, name in ipairs(hubControls.bindNames) do restore(name, saved[name]) end
    restore("Dribble combo", saved["Dribble combo"])
    for _, move in ipairs(moves) do restore(move, macroBinds[move[1]]) end
    if not bindings[spinMove] then restore(spinMove, macroBinds["Spin R to L"]) end
    if not bindings[spinMove] then restore(spinMove, macroBinds["Spin L to R"]) end
    if saved["Auto Guard"] == nil then restore("Auto Guard", "F4") end
    if saved["Court teleport"] == nil then
        for _, name in ipairs({"F8", "F9", "F10"}) do
            restore("Court teleport", name)
            if bindings["Court teleport"] then break end
        end
    end
end

local function applyConfig(data)
    assistKeys = data.autoGreen ~= false
    shotInput.manualOnly = data.manualShotsOnly ~= false
    autoDunk, autoJelly, drawThree = data.autoDunk == true, data.autoJelly == true, data.drawThree == true
    defense.enabled = data.guard == true
    defense.footwork = data.guardFootwork ~= false
    defense.stop(defense.enabled and "Waiting for defense." or "Auto Guard is off.")
    antiStun.apply(data.antiStun == true)
    config.movement, config.boost, config.glide = data.movement == true, data.boost == true, data.glide == true
    courtJoin.apply(data.autoJoinCourt == true)
    config.finish = (data.finish == 2 or data.finish == 3) and data.finish or 1
    network.enabled = data.ping ~= false
    privacy.apply(data.privacy)
    avatar.apply(data.avatar)
    appearance.apply(data.menuAppearance)
    gameAppearance.apply(data.gameAppearance)
    renderOptions.apply(data.performance)
    hud.apply(data.hud)
    visualExtras.apply(data.visuals)
    menuLayout.apply(data.menu)
    local values = type(data.sliders) == "table" and data.sliders or {}
    for name, item in pairs(hubControls.settingSliders) do
        local value = values[name]
        showSlider(item, type(value) == "number" and value == value and value or item.default)
    end
    defense.apply(data.defense)
    autoBlock.apply(data.autoBlock)
    stopMacro()
    table.clear(combo.moves)
    combo.slot = 1
    if type(data.comboMoves) == "table" then
        for i = 1, 5 do
            for _, move in ipairs(moves) do
                if move[1] == data.comboMoves[i] then table.insert(combo.moves, move); break end
            end
        end
    end
    restoreBindings(data)
    -- Timing learned from the on-screen bar (versions 3 and earlier) does not carry over.
    timing.restore(type(data.timingVersion) == "number" and data.timingVersion >= 4 and data.timing or nil)
    for _, mode in ipairs(modes) do mode.result, mode.detail = mode.ready, timing.peakText() end
    restoreMovement()
    rage.apply(data.rage)
    antiContestV2.apply(data.antiContestV2)
    updateThreePointLines()
    hubControls.jellyStatus.Text = autoJelly and ("Ready for " .. hubControls.finishStyles[config.finish].name .. " after release.")
        or ""
    showPing()
end

local function configUpdate(message)
    hubControls.configStatus = message
    refresh()
end

local function savePreference(field, value, message)
    local previous = settings[field]
    settings[field] = value
    if saveSettings() then
        configUpdate(message)
        return true
    end
    settings[field] = previous
    configUpdate("Real could not save that preference.")
    return false
end

local function loadSelectedConfig()
    local data = settings.slots[tostring(settings.slot)]
    if type(data) ~= "table" then
        configUpdate("Slot " .. settings.slot .. " is empty.")
    elseif shot or macro or jelly then
        configUpdate("Wait for the current shot or move to finish.")
    else
        applyConfig(data)
        configUpdate("Loaded slot " .. settings.slot .. ".")
    end
end

function timing.watch(now, frameDt)
    shotInput.refresh(now)
    local attempt = shot
    local meterStarted = signals.serial ~= timing.seenSerial
    timing.seenSerial = signals.serial
    if attempt then
        timing.orphanAt = nil
    elseif assistKeys then
        -- The game started a meter that no key press this script acted on belongs to: the key
        -- went down before the ball arrived (jumping for a lob), or is already up again. Follow
        -- it if a shot key is down, or if the character is going up for a dunk or layup.
        if meterStarted then timing.orphanAt = now end
        if timing.orphanAt and now - timing.orphanAt > 0.35 then timing.orphanAt = nil end
        if timing.orphanAt then
            local held, physical = shotInput.current()
            physical = physical or shotInput.recent(now)
            local body = findCharacter()
            local touch = not physical and input.TouchEnabled and input:GetLastInputType() == Enum.UserInputType.Touch
            local nativeMode = body and timing.finishKind(body) and dunk or jump
            if touch then physical = shotInput.touchControl(nativeMode) end
            if held or touch or (body and timing.finishKind(body)) then
                timing.orphanAt = nil
                if startShot(held or (touch and nativeMode) or dunk, false,
                    touch and "native touch meter" or (held and "held input" or "meter"), true, physical) then
                    attempt = shot
                    attempt.keyless = not held and not touch
                end
            end
        end
    end
    if not attempt then
        local feedback = signals.feedback
        if feedback and not feedback.used then
            -- A rating for a shot this script was not following.
            feedback.used = true
            local rating = hubControls.ratingNames[feedback.order] .. " Release"
            timing.await(rating, signals.serial)
            hud.onRating("Shot (untracked)", rating)
            shotLog.say("Untracked shot | " .. rating .. " | last key press not followed: " .. tostring(timing.refused or "no key press seen"))
        end
        -- Between shots is the time to write the log.
        shotLog.flush(now)
        return
    end
    local character, root = findCharacter()
    local mode = attempt.mode
    local meter, gradient, feedback, ratingLabel
    if root then meter, gradient, feedback, ratingLabel = findMeter(root) end
    if character ~= attempt.character or root ~= attempt.root or not attempt.character.Parent
        or meter ~= attempt.meter or gradient ~= attempt.gradient or feedback ~= attempt.feedback or ratingLabel ~= attempt.rating
        or not robloxFocused() or (attempt.automated and not automationAvailable())
        or (shotInput.isController(attempt) and not shotInput.connected(attempt.inputControl.device)) then
        timing.drop(attempt, "Shot interrupted.", "interrupted")
        return
    end
    local interval = math.clamp(frameDt, 1 / 500, 0.050)
    attempt.frameInterval = attempt.frameInterval and attempt.frameInterval * 0.75 + interval * 0.25 or interval
    if attempt.sentAt and now - attempt.sentAt < 0.25 then
        attempt.worstFrame = math.max(attempt.worstFrame or 0, frameDt)
    end
    local waiting = not attempt.sentAt and not attempt.releasedAt

    -- Follow the server's meter. Steps keep arriving after the key comes up, until the
    -- server handles the release; the last one is what it rated.
    local value = timing.meterValue(character)
    local stream = attempt.stream
    if signals.meters then
        if signals.serial ~= attempt.serial then
            attempt.serial = signals.serial
            if waiting then
                timing.beginGeneration(attempt, now)
                -- This meter began after the key press, so its rating belongs to this attempt.
                attempt.feedbackAmbiguous = false
                stream = attempt.stream
            else
                -- The next shot's meter has begun; it says nothing about this release.
                stream.closed = true
            end
        end
        -- Until the game starts a meter, the fill is only what the previous shot left behind.
        if not attempt.armedAt then value = nil end
    end
    if value and timing.addStep(stream, now, value) == "restart" then
        if waiting then
            timing.beginGeneration(attempt, attempt.armedAt or now)
            stream = attempt.stream
            timing.addStep(stream, now, value)
        else
            stream.closed = true
        end
    end

    if signals.ratings then
        local verdict = signals.feedback
        if verdict and not verdict.used then
            verdict.used = true
            local rating = hubControls.ratingNames[verdict.order] .. " Release"
            if attempt.armedAt or (not signals.meters and not waiting) then
                attempt.rated = verdict
                if attempt.held then
                    releaseKey(attempt.control.virtualKey)
                    attempt.held = false
                end
                shot = nil
                applyRating(attempt, rating, verdict.order)
                return
            end
            -- Rated before this attempt's meter began: it belongs to an earlier shot.
            timing.await(rating, signals.serial)
            hud.onRating("Shot (untracked)", rating)
            shotLog.say("Untracked shot | " .. rating)
        end
    end

    if waiting then
        local enabled = attempt.meter.Enabled and timing.meterActive(attempt.meter) ~= false
        if enabled then
            attempt.shown = true
        elseif attempt.shown and stream.count >= 2 then
            timing.drop(attempt, "The meter reset before release.", "meter ended")
            return
        end
        if stream.count > 0 then
            local action = attempt.character:GetAttribute("Action")
            if action ~= attempt.action or not attempt.kind then
                attempt.action = action
                timing.classify(attempt, action)
                mode = attempt.mode
            end
        end
        if attempt.assist and attempt.kind and stream.count >= 6 and stream.raw >= 0.35 and timing.canAssist(attempt) then
            -- A new ping sample must not move the goalposts halfway through this meter.
            if not attempt.loop then attempt.loop, attempt.loopShift = loopLatency() end
            if attempt.planCount ~= stream.count then
                -- Every new step sharpens the fit. Keep the last good plan if one cannot be made.
                attempt.planCount = stream.count
                attempt.plan = timing.plan(attempt) or attempt.plan
            end
            local plan = attempt.plan
            if plan then
                local prepared, problem = pcall(antiContestV2.prepareRelease, now, plan.releaseAt)
                if not prepared then pcall(antiContestV2.fail, problem) end
            end
            -- The game's release message leaves at once; a faked key-up is only picked up when the
            -- next frame reads input. Either way, go on the frame that lands closest.
            local frame = attempt.frameInterval
            local direct = signals.release and (signals.gate or not attempt.held)
            local delay = direct and 0 or math.clamp(model.frames * frame, 0.002, 0.030)
            if plan and now + delay + frame / 2 >= plan.releaseAt then timing.release(attempt, now) end
        end
        if attempt.owned and not attempt.sentAt then
            -- This script holds the release for this shot, so it must not leave it hanging.
            local armedFor = now - (attempt.armedAt or now)
            if not attempt.assist then
                -- Auto Green was switched off mid-shot: the key is the player's again.
                timing.settle(attempt)
            elseif stream.falling or armedFor >= 1.5 then
                -- Past the top without a planned release: let it go now.
                timing.release(attempt, now)
            elseif armedFor >= 0.7 and stream.count < 3 then
                -- The meter never got going (a gather that led nowhere): hand the key back.
                timing.settle(attempt)
            end
        end
        if attempt.automated and attempt.held and now - attempt.start >= attempt.control.maxHold then
            timing.release(attempt, now)
        elseif not attempt.automated and not attempt.sentAt and now - attempt.start >= 2.5 then
            timing.drop(attempt, mode.ready, "never released")
        end
        return
    end

    -- A dunk or layup stays in the air for most of a second after the release. Note what the
    -- game makes of it, and let the shot key through again as soon as it is over.
    local finish = attempt.finish
    if finish then
        local action = attempt.character:GetAttribute("Action")
        if action ~= finish.last then
            finish.last = action
            if finishAction(action) then
                if action ~= finish.began and not finish.ended then finish.ended, finish.changedAt = action, now end
            elseif signals.gate then
                signals.gate.untilAt = 0
            end
        end
    end

    if not signals.ratings then
        local rating = privacy.readText(attempt.rating)
        local visible = attempt.feedback.Enabled and attempt.rating.Visible and rating ~= ""
        if not visible then
            attempt.feedbackCleared, attempt.feedbackAmbiguous = true, false
        elseif not attempt.feedbackAmbiguous and (attempt.feedbackCleared or rating ~= attempt.priorRating) then
            shot = nil
            applyRating(attempt, rating)
            return
        end
    end
    if now - (attempt.releasedAt or attempt.sentAt) >= 1.6 then
        timing.drop(attempt, stream.count > 0 and "No release rating appeared." or mode.ready, "no rating")
    end
end

connect(run.RenderStepped, function(frameDt)
    -- Release input before optional overlay, scene scanning, and movement work.
    local ok, failure = pcall(timing.watch, os.clock(), frameDt)
    if not ok then timing.fail(failure) end
    local now = os.clock()
    local entryOk,entryError = pcall(gameplaySafety.watch, now)
    if not entryOk then gameplaySafety.ready = false end
    courtJoin.watch(now)
    watchPing(now)
    hud.sample(now, frameDt, network.latest and network.latest * 1000)
    privacy.watch(now)
    visualExtras.watch(now)
    avatar.watch(now)
    antiStun.watch()
    rage.courtTeleport.watch(now)
    watchMovement(now)
    rage.watch(now)
    local v2ok, v2error = pcall(antiContestV2.watch, now)
    if not v2ok then pcall(antiContestV2.fail, v2error) end
    watchMacro(now)
    watchJelly(now)
    watchApproach(now)
    defense.watch(now)
    autoBlock.watch(now)
    local renderingOk, renderingError = pcall(renderOptions.watch, now, frameDt)
    if not renderingOk then renderOptions.stop(); warn(prefix .. "Performance options: " .. tostring(renderingError)) end
    local visualsOk, visualsError = pcall(gameAppearance.watch, now)
    if not visualsOk then
        gameAppearance.stop()
        warn(prefix .. "Game appearance stopped: " .. tostring(visualsError))
    end
end)

connect(input.InputEnded, function(event)
    if drag and mouseRelease(drag.input, event) then drag = nil end
    if sliderDrag and mouseRelease(sliderDrag.input, event) then sliderDrag = nil end
    if event.KeyCode == bindings["Auto Guard"] then defense.stop() end
    if shot and shotInput.matches(shot, event) then
        if shot.releasedAt or timing.holding(shot) then
            -- Already released, or Auto Green holds the release for this shot: the key coming
            -- up changes nothing (the game's own message for it is held back).
            shot.keyUpAt = shot.keyUpAt or os.clock()
        else
            -- The player let go and the release is theirs: this key-up is it.
            shot.releasedAt = os.clock()
            shot.held = false
            -- Only steps that had arrived by now could inform the release, so they define the fit.
            shot.fitCount = shot.stream.count
            if not shot.loop then shot.loop, shot.loopShift = loopLatency() end
            timing.queueFinish(shot, shot.releasedAt)
        end
    end
end)

connect(input.GamepadDisconnected, function(device)
    if shotInput.isController(shot) and shot.inputControl.device == device then
        timing.drop(shot, "Controller disconnected; normal input restored.", "controller disconnected")
    end
end)
connect(input.InputBegan, function(event)
    if shotInput.isGamepad(event.UserInputType) then
        if input:GetFocusedTextBox() or gui.Enabled or capturing then return end
        local mode, physical = shotInput.fromEvent(event)
        if mode and not (shot and (shot.sentAt or shot.releasedAt)) then
            if macro then stopMacro("Move interrupted by a shot.") end
            startShot(mode, false, "controller", false, physical)
        end
        return
    end
    if input:GetFocusedTextBox() or event.UserInputType ~= Enum.UserInputType.Keyboard then return end
    if event.KeyCode == jump.key and courtJoin.onE(os.clock()) then return end
    if capturing then
        setBinding(event.KeyCode)
        return
    end
    for name, key in pairs(bindings) do
        if key == event.KeyCode then
            if type(name) == "table" then
                beginMacro(name)
            elseif name ~= "Auto Guard" then
                actions[name]()
            end
            return
        end
    end
    if event.KeyCode == jump.key or event.KeyCode == dunk.key then
        if macro then stopMacro("Move interrupted by a shot.") end
        startShot(event.KeyCode == jump.key and jump or dunk, false)
    end
end)

function menuLayout.beginDrag(event)
    if input.TouchEnabled then return end -- Swipe the canvas instead of moving it off-screen.
    local inputType = event.UserInputType
    if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
        drag = {input = event, cursor = event.Position, position = dashboard.Position}
    end
end
connect(dragHandle.InputBegan, function(event) menuLayout.beginDrag(event) end)
for _, entry in ipairs({{menuLayout.smaller, -1}, {menuLayout.larger, 1}}) do
    connect(entry[1].Activated, function()
        menuLayout.zoom = math.clamp((math.round(menuLayout.zoom * 10) + entry[2]) / 10, 0.55, 1.6)
        resize()
        menuLayout.recover()
    end)
end
connect(input.InputChanged, function(event)
    if sliderDrag then
        local pointer = sliderDrag.input
        if event == pointer or (pointer.UserInputType == Enum.UserInputType.MouseButton1
            and event.UserInputType == Enum.UserInputType.MouseMovement) then
            updateSliderAt(sliderDrag.item, event.Position.X)
        end
        return
    end
    if not drag then return end
    local mouseMove = drag.input.UserInputType == Enum.UserInputType.MouseButton1
        and event.UserInputType == Enum.UserInputType.MouseMovement
    if mouseMove or event == drag.input then
        local delta = event.Position - drag.cursor
        moveDashboard(drag.position.X.Offset + delta.X, drag.position.Y.Offset + delta.Y)
    end
end)

for name, item in pairs(nav) do
    connect(item.row.Activated, function()
        currentPage = name
        capturing = nil
        refresh()
    end)
end
hud.connect(connect)
appearance.bind(connect, refresh)
gameAppearance.bind(connect)
renderOptions.bind(connect)
menuLayout.bind(connect, refresh)
rage.bind(connect, refresh)
connect(rage.resetSpeedButton.Activated,function()
    rage.clearSpeedRecovery();rage.pauseMovement(.3);rage.stop()
    rage.status.Text="Learned speed limits cleared. Movement will ramp again."
end)
connect(run.PreSimulation or run.Stepped, function()
    pcall(gameplaySafety.physics)
    local ok,problem = pcall(rage.noclip.watch)
