-- Local gameplay diagnostics; no synthetic input, movement edits, or outbound remotes.
function antiContestV2.startRecorder()
    local previous = shared.mc1hSessionRecorder
    if type(previous) == "table" and type(previous.stop) == "function" then previous.stop("Logger replaced") end
    if not storageAvailable or type(makefolder) ~= "function" or type(isfolder) ~= "function" then
        warn(prefix .. "Detailed logging needs Real's file and folder APIs."); return
    end
    local session = {alive = true, links = {}, actorLinks = {}, startedAt = DateTime.now().UnixTimestampMillis,
        origin = os.clock(), counts = {}, errors = {}, sampleHz = 20}
    pcall(function()
        local prior=http:JSONDecode(readfile("GymRelease/session-log-status.json"))
        if type(prior)=="table" then session.previousSession=prior.session end
    end)
    local stamp = string.format("%.0f", session.startedAt)
    session.id = stamp .. "-" .. game.JobId:sub(1,8) .. "-" .. http:GenerateGUID(false):sub(1,8)
    session.directory = "GymRelease/logs/" .. session.id
    local ready, setupError = pcall(function()
        for _, directory in ipairs({"GymRelease", "GymRelease/logs", session.directory}) do
            if not isfolder(directory) then makefolder(directory) end
        end
    end)
    if not ready then warn(prefix .. "Detailed logging setup failed: " .. tostring(setupError)); return end
    local function makeSessionWriter(env)
    local writer = {queue = {}, queuedBytes = 0, queuedRecords = 0, sequence = 0, written = 0, bytes = 0,
        dropped = 0, failures = 0, segment = 0, segmentBytes = 0, files = {}, busy = false,
        limit = env.limit or 256 * 1024 * 1024, segmentLimit = env.segmentLimit or 4 * 1024 * 1024,
        queueLimit = env.queueLimit or 2 * 1024 * 1024, closed = false}
    local function encode(row)
        local ok, line = pcall(env.encode, row)
        if not ok or type(line) ~= "string" then writer.failures += 1; writer.error = tostring(line); return end
        return line .. "\n"
    end
    function writer.push(kind, data, stamp)
        if writer.closed or writer.full then return false end
        writer.sequence += 1
        local line = encode({seq = writer.sequence, t = stamp, kind = kind, data = data})
        if not line then return false end
        if #line > 65536 or writer.queuedBytes + #line > writer.queueLimit then
            writer.dropped += 1
            return false
        end
        table.insert(writer.queue, line)
        writer.queuedBytes += #line
        writer.queuedRecords += 1
        return true
    end
    function writer.pump()
        if writer.busy or writer.closed or #writer.queue == 0 then return false end
        writer.busy = true
        local batch, count = table.concat(writer.queue), writer.queuedRecords
        writer.queue, writer.queuedBytes, writer.queuedRecords = {}, 0, 0
        if writer.bytes + #batch > writer.limit then
            writer.full, writer.error = true, "Session log storage limit reached. Existing logs were preserved."
            writer.dropped += count
            writer.busy = false
            return false
        end
        local append = type(env.append) == "function"
        local nextFile = not append or writer.segment == 0 or writer.segmentBytes + #batch > writer.segmentLimit
        local segment = writer.segment + (nextFile and 1 or 0)
        local file = env.directory .. string.format("/events-%04d.jsonl", segment)
        local ok, problem = pcall(function()
            if nextFile then env.write(file, batch) else env.append(file, batch) end
        end)
        if ok then
            writer.segment = segment
            writer.segmentBytes = (nextFile and 0 or writer.segmentBytes) + #batch
            writer.bytes += #batch; writer.written += count
            if nextFile then table.insert(writer.files, file) end
            writer.error = nil
        else
            -- A failed append may have written a prefix. Never append that batch to the same
            -- file again; preserve the failed segment and retry in a fresh segment.
            writer.failures += 1; writer.error = tostring(problem)
            if not nextFile then writer.segmentBytes = writer.segmentLimit end
            if nextFile then
                writer.segment = segment; writer.segmentBytes = writer.segmentLimit
                table.insert(writer.files, file)
            end
            if #batch + writer.queuedBytes <= writer.queueLimit then
                table.insert(writer.queue, 1, batch); writer.queuedBytes += #batch; writer.queuedRecords += count
            else writer.dropped += count end
        end
        writer.busy = false
        return ok
    end
    function writer.status()
        return {sequence = writer.sequence, written = writer.written, bytes = writer.bytes, files = table.clone(writer.files),
            bufferedBytes = writer.queuedBytes, dropped = writer.dropped, writeFailures = writer.failures,
            error = writer.error, full = writer.full == true, closed = writer.closed}
    end
    return writer
end

    local writer = makeSessionWriter({directory = session.directory, encode = function(row) return http:JSONEncode(row) end,
        write = writefile, append = type(appendfile) == "function" and appendfile or nil})
    local function finite(value) return type(value) == "number" and value == value and math.abs(value) < math.huge end
    local function number(value) return finite(value) and math.round(value * 10000) / 10000 or nil end
    local function vec(value)
        return typeof(value) == "Vector3" and {number(value.X), number(value.Y), number(value.Z)} or nil
    end
    local function frame(value)
        if typeof(value) ~= "CFrame" then return nil end
        local x,y,z = value:ToOrientation()
        return {position = vec(value.Position), rotation = {number(x),number(y),number(z)}}
    end
    local function pack(value, depth, seen)
        local kind = typeof(value)
        if kind == "number" then return finite(value) and value or tostring(value) end
        if kind == "string" then return #value > 4096 and value:sub(1,4096) .. " [truncated]" or value end
        if kind == "nil" or kind == "boolean" then return value end
        if kind == "Vector3" then return vec(value) end
        if kind == "Vector2" then return {number(value.X),number(value.Y)} end
        if kind == "CFrame" then return frame(value) end
        if kind == "EnumItem" then return tostring(value) end
        if kind == "Instance" then return {class = value.ClassName, path = value:GetFullName()} end
        if kind ~= "table" then return "[" .. kind .. "]" end
        depth, seen = depth or 0, seen or {}
        if depth >= 5 then return "[depth limit]" end
        if seen[value] then return "[cycle]" end
        seen[value] = true
        local result, count = {}, 0
        for key, child in pairs(value) do
            count += 1
            if count > 80 then result._omitted = true; break end
            if type(key) == "string" or type(key) == "number" then result[key] = pack(child,depth+1,seen) end
        end
        seen[value] = nil
        return result
    end
    function session.emit(kind, data)
        if not session.alive then return end
        local ok, clean = pcall(pack, data)
        if not ok then clean = {serializationError = tostring(clean)} end
        session.counts[kind] = (session.counts[kind] or 0) + 1
        writer.push(kind, clean, math.floor((os.clock() - session.origin) * 1000000 + .5) / 1000)
    end
    local function recordError(where, problem)
        local key = where .. ": " .. tostring(problem)
        session.errors[key] = (session.errors[key] or 0) + 1
        if session.errors[key] <= 3 then session.emit("recorder_error", {where=where,problem=tostring(problem)}) end
    end
    local function link(signal, fn, into)
        local connection = signal:Connect(function(...)
            if not session.alive then return end
            local ok, problem = pcall(fn,...)
            if not ok then recordError("event",problem) end
        end)
        table.insert(into or session.links, connection)
