        local attempt=shot
        local row={serverTime=number(workspace:GetServerTimeNow()),focused=robloxFocused(),menu=gui.Enabled,
            entryReady=gameplaySafety.ready,fly={enabled=rage.fly.enabled,active=rage.fly.active,message=rage.fly.message,method=rage.fly.method,desired=vec(rage.fly.desiredVelocity)},
            flyLift=constraint(proxy,"WizardFlyLift"),
