            rage=rage.diagnostics(),
            textFocus=input:GetFocusedTextBox()~=nil,root=partInfo(root),proxy=partInfo(proxy),attributes=values(),
            replicationOwner=native and {controllerMatches=native.Controllers and native.Controllers.Player and native.Character==native.Controllers.Player.Character,
                observedMatches=native.Character==body,modelMatches=native.Character and native.Character.data and native.Character.data.model==actor},
            keys=table.clone(inputState),frameMs=number(frames>0 and worstFrame*1000 or 0),frames=frames,
            pingMs=number(network.latest and network.latest*1000),pingMedianMs=number(network.median and network.median*1000),
            gate=signals.gate and {serial=signals.gate.serial,untilAt=signals.gate.untilAt,swallowed=signals.gate.swallowed},
            meterSerial=signals.serial,meterGreen=signals.green,v2=antiContestV2.liveState and antiContestV2.liveState(),
            movementPosition=constraint(proxy,"BodyPosition"),serverMovementPosition=constraint(root,"BodyPosition"),
            alignPosition=constraint(proxy and proxy:FindFirstChild("Physics"),"AlignPosition"),
            serverAlignPosition=constraint(root and root:FindFirstChild("Physics"),"AlignPosition"),
            movementVelocity=constraint(proxy,"MovementVelocity"),ball=partInfo(ball),ballHeld=held~=nil,
            ballAttributes=ball and ball:GetAttributes(),
            forcedFrame=body and frame(safeCall(function() return body:GetAttribute("CFrame") end)),
            camera=camera and {cf=frame(camera.CFrame),fov=camera.FieldOfView},
            lastValidHeight=body and body.lastValidHeight,proxyAnchored=body and body.ProxyAnchored}
        if not row.textFocus then
            row.keyboard={}
            for _,name in ipairs({"E","Space","W","A","S","D","LeftShift","RightShift","Q","F","T","Z","X","C","V"}) do
                row.keyboard[name]=executorInput.keyDown(Enum.KeyCode[name])
            end
        end
        if root then row.bounds=boundsInfo(root.Position);row.peers=peers(root.Position) end
        if attempt then
            local stream,plan=attempt.stream,attempt.plan
            row.shot={kind=attempt.kind,source=attempt.source,input=attempt.inputControl and attempt.inputControl.label,
                start=attempt.start,armedAt=attempt.armedAt,sentAt=attempt.sentAt,releasedAt=attempt.releasedAt,
                owned=attempt.owned,assist=attempt.assist,direct=attempt.direct,serial=attempt.serial,
                raw=stream and stream.raw,count=stream and stream.count,period=stream and stream.period,
                falling=stream and stream.falling,green=attempt.green,plan=plan and {releaseAt=plan.releaseAt,aim=plan.aim,reach=plan.reach,inWindow=plan.inWindow}}
        end
        return row
    end
    local function status()
        return {version=1,session=session.id,directory=session.directory,startedAt=session.startedAt,
            updatedAt=DateTime.now().UnixTimestampMillis,alive=session.alive,sampleHz=session.sampleHz,
            phase=session.teleporting and "departing" or (session.alive and "running" or "closed"),previousSession=session.previousSession,
            jobPrefix=game.JobId:sub(1,8),placeId=game.PlaceId,placeVersion=game.PlaceVersion,
            counters=table.clone(session.counts),storage=writer.status(),errors=table.clone(session.errors),
            v2=antiContestV2.diagnostics(),actorReady=actor~=nil,replicationReady=native~=nil,
            shotLaunch=shotObserver and shotObserver.diagnostics()}
    end
    local function saveStatus()
        local encoded=http:JSONEncode(status())
        writefile(session.directory.."/manifest.json",encoded)
        if shared.mc1hSessionRecorder==session then writefile("GymRelease/session-log-status.json",encoded) end
    end
    function session.flush()
        local deadline=os.clock()+.5
        while writer.busy and os.clock()<deadline do task.wait() end
        writer.pump()
        local ok,problem=pcall(saveStatus)
        if not ok then recordError("status",problem) end
    end
    function session.depart()
        session.teleporting=true
        session.emit("teleport_departure",{snapshot=safeCall(snapshot),config=captureConfig()})
        session.flush()
    end
    function session.stop(reason)
        if not session.alive then return end
        session.emit("session_stop",{reason=reason or "Stopped",snapshot=safeCall(snapshot)})
        if shotObserver then pcall(shotObserver.stop) end
        session.alive=false
        disconnect(session.links);disconnect(session.actorLinks)
        if antiContestV2.trace==session.emit then antiContestV2.trace=nil end
        session.flush();writer.closed=true;pcall(saveStatus)
        if shared.mc1hSessionRecorder==session then shared.mc1hSessionRecorder=nil end
    end
    session.diagnostics=status
    antiContestV2.recorder=session
    shared.mc1hSessionRecorder=session
    antiContestV2.trace=session.emit
    local function newShotLaunchObserver(deps)
    local api={}
    local stopped,actor,record,window=false,nil,nil,nil
    local actorLinks,watchedValues,watchedValueCount={},{},0
    local actionWasShooting=false
    local counters={samples=0,markers=0,detailMarkers=0,priorityMarkers=0,boundaryMarkers=0,dropped=0,droppedDetail=0,droppedPriority=0,errors=0,ownedLinks=0,windows=0}
    local SAMPLE_INTERVAL,MAX_WINDOW,POST_DETACH=1/60,3.5,1
    local MAX_SAMPLES,MAX_MARKERS,MAX_PRIORITY,MAX_NODES=240,512,128,12
    local pollHeld,scanNodes,openWindow,closeWindow,bindBall,unbindBall,pollAction
    local function safe(fn,...)
        local ok,value=pcall(fn,...)
        if ok then return value end
    end
    local function finite(n)return type(n)=="number"and n==n and math.abs(n)<math.huge end
    local function clock(value)
        if finite(value)then return value end
        local t=deps.clock and safe(deps.clock)
        return finite(t)and t or os.clock()
    end
    local function get(object,key)return object and safe(function()return object[key]end)end
    local function attribute(object,name)return object and safe(function()return object:GetAttribute(name)end)end
    local function isA(object,class)return object and safe(function()return object:IsA(class)end)==true end
    local function alive(object)return object~=nil and get(object,"Parent")~=nil end
    local function context()
        local source=deps.snapshot and safe(deps.snapshot)or{}
        if type(source)~="table"then source={}end
        return {mode=source.mode or source.variant or(type(source.v2)=="table"and source.v2.variant),
            meterSerial=source.meterSerial,shotSerial=source.shotSerial or(type(source.shot)=="table"and source.shot.serial),
            shotActive=source.shotActive==true}
    end
    local function owned()
        return not stopped and actor~=nil and safe(deps.actor)==actor and alive(actor)
    end
    local function disconnect(links)
        for i=#links,1,-1 do
            local item=links[i]
            if not item.closed then
                item.closed=true;pcall(item.connection.Disconnect,item.connection)
                counters.ownedLinks-=1
            end
            links[i]=nil
        end
    end
    local function connect(links,signal,callback)
        if not signal then return end
        local ok,connection=pcall(function()return signal:Connect(callback)end)
        if ok and connection then
            table.insert(links,{connection=connection,closed=false});counters.ownedLinks+=1
        end
    end
    local function propertySignal(object,name)return safe(function()return object:GetPropertyChangedSignal(name)end)end
    local function attributeSignal(object,name)return safe(function()return object:GetAttributeChangedSignal(name)end)end
    local function frameData(at,inspectOwnership)
        local ctx=context()
        local ball=record and record.ball
        local root=deps.root and safe(deps.root,actor)
        local data={observedAt=at,actor=actor,ball=ball,mode=ctx.mode,meterSerial=ctx.meterSerial,shotSerial=ctx.shotSerial,
            action=attribute(actor,"Action"),replicationId=attribute(actor,"ReplicationId"),team=attribute(actor,"Team"),court=attribute(actor,"CourtNumber"),
            held=record and record.held or false,midShot=attribute(ball,"MidShot"),ballTag=attribute(ball,"Tag"),ballId=attribute(ball,"ID"),
            ballParent=get(ball,"Parent"),ballFrame=get(ball,"CFrame"),ballPosition=get(ball,"Position"),
            ballVelocity=get(ball,"AssemblyLinearVelocity"),ballAnchored=get(ball,"Anchored"),
            rootFrame=get(root,"CFrame"),rootPosition=get(root,"Position"),rootVelocity=get(root,"AssemblyLinearVelocity")}
        if inspectOwnership and type(deps.ownership)=="function" then
            local ballOwned=ball and safe(deps.ownership,ball)
            local rootOwned=root and safe(deps.ownership,root)
            if type(ballOwned)=="boolean"then data.ballLocallyOwned=ballOwned end
            if type(rootOwned)=="boolean"then data.rootLocallyOwned=rootOwned end
            data.ballAssemblyRoot=get(ball,"AssemblyRootPart")
        end
        if window then data.window=window.id;data.reason=window.reason;data.detachedAt=window.detachedAt end
        return data
    end
    local function emit(kind,fields,at,force)
        if stopped or not window then return end
        at=clock(at)
        local priority=kind=="action"or kind=="transition"or kind=="parent"or kind=="ball_bound"
            or(kind=="attribute"and fields and(fields.name=="MidShot"or fields.name=="Tag"or fields.name=="ID"))
            or((kind=="joint_change"or kind=="attachment_change")and fields
                and(fields.property=="Parent"or fields.property=="Part0"or fields.property=="Part1"))
        if not force and(at>window.deadline or(priority and window.priority>=MAX_PRIORITY)or(not priority and window.detail>=MAX_MARKERS))then
            counters.dropped+=1;window.dropped+=1
            if priority then counters.droppedPriority+=1;window.droppedPriority+=1 else counters.droppedDetail+=1;window.droppedDetail+=1 end
            return
        end
        local data=frameData(at,priority or force)
        data.eventPriority=force and"boundary"or priority and"transition"or"detail"
        for key,value in pairs(fields or{})do data[key]=value end
        local ok=pcall(deps.emit,"shot_launch_"..kind,data)
        if ok then
            counters.markers+=1;window.markers+=1
            if force then counters.boundaryMarkers+=1
            elseif priority then counters.priorityMarkers+=1;window.priority+=1
            else counters.detailMarkers+=1;window.detail+=1 end
        else counters.errors+=1 end
    end
    closeWindow=function(reason,at)
        if not window then return end
        emit("window_end",{endReason=reason,samples=window.samples,dropped=window.dropped,
            droppedDetail=window.droppedDetail,droppedPriority=window.droppedPriority},at,true)
        window=nil
    end
    openWindow=function(reason,at)
        if stopped or not owned()then return end
        at=clock(at)
        if window and at>window.deadline then closeWindow("expired_before_transition",at)end
        if window then return end
        counters.windows+=1
        window={id=counters.windows,reason=reason,began=at,deadline=at+MAX_WINDOW,maximum=at+MAX_WINDOW,
            nextSample=-math.huge,nextScan=-math.huge,samples=0,markers=0,detail=0,priority=0,dropped=0,droppedDetail=0,droppedPriority=0}
        if record and record.detachedAt then window.detachedAt=record.detachedAt;window.deadline=math.min(window.deadline,record.detachedAt+POST_DETACH)end
        emit("window_start",{sampleHz=60,maxSeconds=MAX_WINDOW,postDetachSeconds=POST_DETACH},at,true)
        if record then emit("ball_bound",{},at)end
    end
    local function jointRelated(node,r)
        return (isA(node,"JointInstance")or isA(node,"WeldConstraint"))
            and(get(node,"Part0")==r.ball or get(node,"Part1")==r.ball)
    end
    local function attachmentRelated(node,r)
        if not isA(node,"Attachment")then return false end
        local parent=get(node,"Parent")
        if parent==r.ball then return true end
        for joint in pairs(r.nodes)do
            if jointRelated(joint,r)and(parent==get(joint,"Part0")or parent==get(joint,"Part1"))then return true end
        end
        return false
    end
    local function watchNode(node,r)
        if r.nodes[node]or r.nodeCount>=MAX_NODES then return end
        local joint=jointRelated(node,r)
        if not joint and not attachmentRelated(node,r)then return end
        local links={};r.nodes[node]=links;r.nodeCount+=1
        local properties=joint and(isA(node,"Motor6D")and{"Parent","Part0","Part1","C0","C1","Transform"}
            or isA(node,"JointInstance")and{"Parent","Part0","Part1","C0","C1"}or{"Parent","Part0","Part1","Enabled"})
            or{"Parent","CFrame","Position","Axis","SecondaryAxis"}
        for _,property in ipairs(properties)do
            connect(links,propertySignal(node,property),function()
                if record~=r or not owned()then return end
                local at=clock()
                if window and at<=window.deadline then
                    emit(joint and"joint_change"or"attachment_change",{node=node,property=property,value=get(node,property),
                        part0=joint and get(node,"Part0"),part1=joint and get(node,"Part1")},at)
                end
                if (property=="Part0"or property=="Part1"or property=="Parent")
                    and not jointRelated(node,r)and not attachmentRelated(node,r)then disconnect(links);r.nodes[node]=nil end
            end)
        end
    end
    scanNodes=function()
        local r=record;if not r then return end
        local joints=safe(function()return r.ball:GetJoints()end)or{}
        for _,joint in ipairs(joints)do
            watchNode(joint,r)
            for _,part in ipairs({get(joint,"Part0"),get(joint,"Part1")})do
                local children=part and safe(function()return part:GetChildren()end)or{}
                for _,node in ipairs(children)do if isA(node,"Attachment")then watchNode(node,r)end end
            end
        end
        local children=safe(function()return r.ball:GetChildren()end)or{}
        for _,node in ipairs(children)do watchNode(node,r)end
    end
    unbindBall=function()
        if not record then return end
        disconnect(record.links)
        for _,links in pairs(record.nodes)do disconnect(links)end
        record=nil
    end
    bindBall=function(ball,at)
        record={ball=ball,held=true,links={},nodes={},nodeCount=0}
        local r=record
        for _,name in ipairs({"MidShot","Active","Anchored","Tag","ID","LastShotBase","lastShotType"})do
            connect(r.links,attributeSignal(ball,name),function()
                if record~=r or not owned()then return end
                local now=clock();pollHeld(now,"ball_attribute")
                if record~=r then return end
                if not window and r.held and name=="MidShot"and attribute(ball,name)==true then openWindow("midshot_attribute",now)end
                emit("attribute",{name=name,value=attribute(ball,name)},now)
            end)
        end
        connect(r.links,propertySignal(ball,"Parent"),function()
            if record~=r or not owned()then return end
            local now=clock();pollHeld(now,"ball_parent")
            if record~=r then return end
            emit("parent",{parent=get(ball,"Parent")},now)
            if not alive(ball)then closeWindow("ball_removed",now);unbindBall()else scanNodes()end
        end)
        connect(r.links,get(ball,"DescendantAdded"),function(node)
            if record==r and owned()then watchNode(node,r)end
        end)
        scanNodes()
    end
    pollHeld=function(at,source)
        if not actor then return end
        local held=safe(deps.heldBall,actor)
        if not alive(held)or not isA(held,"BasePart")then held=nil end
        if held and(not record or record.ball~=held)then
            if record then closeWindow("own_ball_changed",at);unbindBall();actionWasShooting=false end
            bindBall(held,at)
        elseif held and record and not record.held then
            record.held=true;record.detachedAt=nil
            emit("transition",{transition="detached_to_held",source=source},at)
        elseif not held and record and record.held then
            record.held=false;record.detachedAt=at
            openWindow("held_to_detached",at)
            if window then window.detachedAt=at;window.deadline=math.min(window.maximum,at+POST_DETACH)end
            emit("transition",{transition="held_to_detached",source=source},at)
        end
        if record and record.detachedAt and at>record.detachedAt+POST_DETACH then
            closeWindow("post_detach_complete",at);unbindBall()
        end
    end
    local function shooting(action)
        action=tostring(action or""):lower()
        return action:find("shoot",1,true)or action:find("dunk",1,true)or action:find("layup",1,true)
            or action:find("clutch",1,true)or action:find("gather",1,true)
    end
    pollAction=function(at,source)
        local action=attribute(actor,"Action")
        local active=not not shooting(action)or context().shotActive
        if active and not actionWasShooting then
            if window then closeWindow("new_shooting_action",at)end
            openWindow("own_shooting_action",at);scanNodes()
        end
        if window and active~=actionWasShooting then emit("action",{value=action,shooting=active,source=source},at)end
        if window and not active and not window.detachedAt then window.deadline=math.min(window.deadline,at+.2)end
        actionWasShooting=active
    end
    local function watchHeldValue(node)
        if watchedValues[node]or watchedValueCount>=4 or get(node,"Name")~="Basketball"or not isA(node,"ValueBase")then return end
        watchedValues[node]=true;watchedValueCount+=1
        connect(actorLinks,get(node,"Changed"),function()if owned()then pollHeld(clock(),"held_value")end end)
    end
    local function bindActor(nextActor,at)
        closeWindow("actor_changed",at);unbindBall();disconnect(actorLinks)
        actor=nextActor;watchedValues={};watchedValueCount=0;actionWasShooting=false
        if not actor then return end
        local bound=actor
        connect(actorLinks,attributeSignal(actor,"Action"),function()
            if owned()and actor==bound then local now=clock();pollHeld(now,"action");pollAction(now,"attribute")end
        end)
        connect(actorLinks,attributeSignal(actor,"Basketball"),function()if owned()and actor==bound then pollHeld(clock(),"held_attribute")end end)
        connect(actorLinks,get(actor,"DescendantAdded"),function(node)
            if owned()and actor==bound then watchHeldValue(node);if record then watchNode(node,record)end end
        end)
        local attributes=safe(function()return actor:FindFirstChild("Attributes")end)
        local heldValue=attributes and safe(function()return attributes:FindFirstChild("Basketball")end)
        if heldValue then watchHeldValue(heldValue)end
    end
    function api.step(now)
        if stopped then return end
        now=clock(now)
        local nextActor=safe(deps.actor)
        if not alive(nextActor)then nextActor=nil end
        if nextActor~=actor then bindActor(nextActor,now)end
        if not actor then return end
        pollHeld(now,"frame");pollAction(now,"frame")
        if window and now>window.deadline then closeWindow("window_complete",now)end
        if not window then return end
        if now>=window.nextScan then window.nextScan=now+.1;scanNodes()end
        if now+1e-9<window.nextSample then return end
        window.nextSample=now+SAMPLE_INTERVAL
        if window.samples>=MAX_SAMPLES then counters.dropped+=1;window.dropped+=1;return end
        local data=frameData(now);local joints={}
        if record then for node in pairs(record.nodes)do
            table.insert(joints,{node=node,parent=get(node,"Parent"),part0=get(node,"Part0"),part1=get(node,"Part1"),
                c0=get(node,"C0"),c1=get(node,"C1"),transform=get(node,"Transform"),frame=get(node,"CFrame")})
        end end
        data.joints=joints
        local ok=pcall(deps.emit,"shot_launch_sample",data)
        if ok then window.samples+=1;counters.samples+=1 else counters.errors+=1 end
    end
    function api.stop()
        if stopped then return end
        closeWindow("observer_stopped",clock());stopped=true
        unbindBall();disconnect(actorLinks);actor=nil;watchedValues={}
    end
    function api.diagnostics()
        return {active=window~=nil,ballBound=record~=nil,actorBound=actor~=nil,stopped=stopped,
            samples=counters.samples,markers=counters.markers,dropped=counters.dropped,errors=counters.errors,ownedLinks=counters.ownedLinks,
            detailMarkers=counters.detailMarkers,priorityMarkers=counters.priorityMarkers,boundaryMarkers=counters.boundaryMarkers,
            droppedDetail=counters.droppedDetail,droppedPriority=counters.droppedPriority,
            windows=counters.windows,sampleHz=60,maxWindow=MAX_WINDOW,postDetach=POST_DETACH}
    end
    return api
end

    shotObserver=newShotLaunchObserver({actor=function()return actor end,root=function()return root end,
        heldBall=function(model)return model and heldBall(model)end,emit=session.emit,clock=os.clock,
        ownership=type(isnetworkowner)=="function"and function(part)return isnetworkowner(part)end or nil,
        snapshot=function()return {mode=antiContestV2.variant=="v3"and("v3:"..antiContestV2.v3ReturnAt)or"v2",
            meterSerial=signals.serial,shotSerial=shot and shot.serial,shotActive=shot~=nil and not shot.rated}end})
    local function changedActor(model,newRoot,newBody)
        if model==actor and newRoot==root and newBody==body then return end
        disconnect(session.actorLinks)
        actor,root,body=model,newRoot,newBody
        lastPosition,lastAction,observedBall=nil,nil,nil
        session.emit("actor_changed",{model=model,root=newRoot,attributes=values()})
        if not actor then return end
        link(actor.AttributeChanged,function(name)
            if attributes[name] then session.emit("attribute",{name=name,value=actor:GetAttribute(name)}) end
        end,session.actorLinks)
        local folder=actor:FindFirstChild("Attributes")
        local function bindValue(node)
            if node:IsA("ValueBase") and attributes[node.Name] then
                link(node.Changed,function() session.emit("attribute_value",{name=node.Name,value=node.Value}) end,session.actorLinks)
            end
        end
        if folder then
            for _,node in ipairs(folder:GetChildren()) do bindValue(node) end
            link(folder.ChildAdded,bindValue,session.actorLinks)
        end
    end
    local function bindRemote(service,name,localOnly,actorArgument)
        local aero=game:GetService("ReplicatedStorage"):FindFirstChild("Aero")
        local services=aero and aero:FindFirstChild("AeroRemoteServices")
        local folder=services and services:FindFirstChild(service)
        local remote=folder and folder:FindFirstChild(name)
        local key=service.."."..name
        if not remote or not remote:IsA("RemoteEvent") or remoteLinks[key]==remote then return end
        remoteLinks[key]=remote
        link(remote.OnClientEvent,function(...)
            local args=table.pack(...)
            if localOnly and args[actorArgument or 1]~=actor then return end
            session.emit("server_event",{name=key,args=args,snapshot=safeCall(snapshot)})
            if service=="PhysicsService" then task.defer(function()
                session.emit("after_server_correction",{name=key,snapshot=safeCall(snapshot)})
            end) end
        end)
        session.emit("remote_connected",{name=key})
    end
    local nextPacketMetadata=0
    local function attachEcho()
        local remote=game:GetService("ReplicatedStorage"):FindFirstChild("Replication")
        if not remote or remoteLinks.Replication==remote then return end
        remoteLinks.Replication=remote
        link(remote.OnClientEvent,function(payload)
            if typeof(payload)~="buffer" or not native or not actor then return end
            local bytes=buffer.len(payload)
            if not antiContestV2.isSupported() then
                if os.clock()>=nextPacketMetadata then
                    nextPacketMetadata=os.clock()+.5;session.emit("replication_metadata",{bytes=bytes,decoded=false})
                end
                return
            end
            if bytes<8 or bytes>8+255*12 or (bytes-8)%12~=0 then session.emit("replication_layout",{bytes=bytes});return end
            local lib=native.Shared.Replication.Buffer
            local range=workspace:GetAttribute("Gamemode")=="Plaza" and 4000 or 1000
            local scale=native.Shared.Replication.ReplicationConfig.Character.SPEED_SCALE
            if type(scale)~="number" or scale<=0 then return end
            local reader=lib.reader(payload)
            local clock=lib.Float64.Read(reader)
            for _=1,(bytes-8)/12 do
                local id=lib.UInt8.Read(reader)
                local stamp=clock-lib.Int16.Read(reader)/10000
                local position=Vector3.new(lib.RangedFloat16.Read(reader,-range,range),lib.RangedFloat16.Read(reader,-range,range),lib.RangedFloat16.Read(reader,-range,range))
                local velocityX,velocityZ=lib.Int8.Read(reader),lib.Int8.Read(reader)
                local velocity=Vector3.new(velocityX/scale,0,velocityZ/scale)
                local yawByte=lib.UInt8.Read(reader)
                local yaw=yawByte/256*2*math.pi
                if id==actor:GetAttribute("ReplicationId") then
                    if rage.courtTeleport.observeOwnPosition then
                        pcall(rage.courtTeleport.observeOwnPosition,id,stamp,position)
                    end
                    session.emit("own_server_position",{id=id,stamp=stamp,clock=clock,position=position,velocity=velocity,
                        velocityX=velocityX,velocityZ=velocityZ,yaw=yaw,yawByte=yawByte,bytes=bytes})
                end
            end
        end)
    end
    local function resolve()
        local scripts=player:FindFirstChild("PlayerScripts")
        local aero=scripts and scripts:FindFirstChild("Aero")
        local controllers=aero and aero:FindFirstChild("Controllers")
        local module=controllers and controllers:FindFirstChild("Replication")
        if module and type(getconnections)=="function" and type(getupvalues)=="function" then
            for _,connection in ipairs(getconnections(run.Heartbeat)) do
                local fn=connection.Function
                if type(fn)=="function" and debug.info(fn,"s")==module:GetFullName() then
                    for _,value in pairs(getupvalues(fn)) do
                        if type(value)=="table" and type(rawget(value,"Packets"))=="table" and type(rawget(value,"CreatePacket"))=="function" then native=value end
                    end
                end
            end
        end
        local model,newRoot=findCharacter()
        local newBody=native and native.Controllers.Player.Character
        if newBody and (not newBody.data or newBody.data.model~=model) then newBody=nil end
        changedActor(model,newRoot,newBody)
        bindRemote("PhysicsService","SetCFrame",false)
        bindRemote("PhysicsService","SetVelocity",false)
        bindRemote("MeterService","RegisterPacket",true)
        bindRemote("MeterService","UnregisterPacket",true)
        bindRemote("MeterService","UpdateGreenWindow",true)
        bindRemote("GameplayService","Meter",true,2)
        bindRemote("InterfaceService","ShowFeedback",true)
        bindRemote("InputService","Shoot",false)
        bindRemote("InputService","Jump",false)
        attachEcho()
    end
    local gameplayKeys={E=true,Space=true,W=true,A=true,S=true,D=true,LeftShift=true,RightShift=true,
        Q=true,F=true,T=true,Z=true,X=true,C=true,V=true,ButtonX=true,ButtonY=true,ButtonR1=true,ButtonR2=true,
        ButtonL1=true,ButtonL2=true,Thumbstick1=true,Thumbstick2=true,ButtonA=true,ButtonB=true}
    local function inputEvent(kind,event,processed)
        if not gameplayKeys[event.KeyCode.Name] then return end
        local key=event.UserInputType.Name..":"..event.KeyCode.Name
        if kind=="input_ended" then inputState[key]=nil end
        if input:GetFocusedTextBox() then return end
        inputState[key]=kind=="input_began" or nil
        session.emit(kind,{key=event.KeyCode.Name,device=event.UserInputType.Name,processed=processed,focused=robloxFocused(),
            position=vec(event.Position),state=event.UserInputState.Name})
    end
    link(input.InputBegan,function(event,processed) inputEvent("input_began",event,processed) end)
    link(input.InputEnded,function(event,processed) inputEvent("input_ended",event,processed) end)
    local nextAnalog={}
    link(input.InputChanged,function(event,processed)
        local key=event.UserInputType.Name..":"..event.KeyCode.Name
        if os.clock()<(nextAnalog[key] or 0) or (event.KeyCode.Name~="Thumbstick1" and event.KeyCode.Name~="Thumbstick2") then return end
        nextAnalog[key]=os.clock()+.05
        session.emit("controller_axis",{device=event.UserInputType.Name,key=event.KeyCode.Name,position=vec(event.Position),processed=processed})
    end)
    link(input.WindowFocusReleased,function() table.clear(inputState);session.emit("focus",{active=false}) end)
    link(input.WindowFocused,function() session.emit("focus",{active=true}) end)
    link(input.GamepadConnected,function(device) session.emit("gamepad_connected",{device=device}) end)
    link(input.GamepadDisconnected,function(device) session.emit("gamepad_disconnected",{device=device}) end)
    link(player.OnTeleport,function(state,placeId)
        if state==Enum.TeleportState.Failed then session.teleporting=false end
        session.emit("teleport_state",{state=state,placeId=placeId});session.flush()
    end)
    link(game:GetService("LogService").MessageOut,function(message,messageType)
        if type(message)~="string" then return end
        if message:find("Shot Feedback",1,true) or message:find("[WizardHub]",1,true)
            or tostring(messageType):find("Error",1,true) then
            session.emit("game_log",{text=message,type=messageType})
        end
    end)
    local function notices()
        for _,node in ipairs(playerGui:GetDescendants()) do
            if (node:IsA("TextLabel") or node:IsA("TextButton")) then
                local text=tostring(node.Text)
                if text:lower():find("out of bounds",1,true) then
                    local visible=node.Visible
                    local parent=node.Parent
                    while visible and parent and parent~=playerGui do
                        if parent:IsA("GuiObject") then visible=parent.Visible
                        elseif parent:IsA("ScreenGui") then visible=parent.Enabled end
                        parent=parent.Parent
                    end
                    local signature=tostring(visible).."|"..text
                    if noticeState[node]~=signature then
                        noticeState[node]=signature
                        session.emit("bounds_notice",{visible=visible,text=text,snapshot=visible and safeCall(snapshot) or nil})
                    end
                end
            end
        end
    end
    session.emit("session_start",{gameId=game.GameId,placeId=game.PlaceId,placeVersion=game.PlaceVersion,jobPrefix=game.JobId:sub(1,8),
        clientVersion=version(),startedAt=session.startedAt,config=captureConfig(),sampleHz=session.sampleHz,previousSession=session.previousSession,
        storageLimit=writer.limit,scope="Gameplay controls only; client-observable state and server messages. No chat or text-box input."})
    local ok,problem=pcall(resolve)
    if not ok then recordError("initial_resolve",problem) end
    link(run.Heartbeat,function(dt)
        frames+=1;worstFrame=math.max(worstFrame,dt)
        local now=os.clock()
        if root and root.Parent then
            local position=root.Position
            if lastPosition then
                local distance=(position-lastPosition).Magnitude
                if distance>6 then session.emit("movement_discontinuity",{distance=distance,dt=dt,from=lastPosition,to=position,snapshot=safeCall(snapshot)}) end
            end
            lastPosition=position
        end
        if now>=nextResolve then
            nextResolve=now+.5
            local resolved,issue=pcall(resolve)
            if not resolved then recordError("resolve",issue) end
        end
        if shotObserver then
            local observed,issue=pcall(shotObserver.step,now)
            if not observed then recordError("shot_launch",issue)end
        end
        if now>=nextSample then
            nextSample=now+1/session.sampleHz
            local sampled,row=pcall(snapshot)
            if sampled then session.emit("movement",row) else recordError("snapshot",row) end
            worstFrame,frames=0,0
        end
        if now>=nextBounds then nextBounds=now+.25;notices() end
        if now>=nextStatus then
            nextStatus=now+1
            local config=captureConfig()
            local relevant={rage=config.rage,v2=config.antiContestV2,
                autoGreen=config.autoGreen,autoDunk=config.autoDunk,autoJelly=config.autoJelly,manualShotsOnly=config.manualShotsOnly,
                movement=config.movement,boost=config.boost,glide=config.glide,ping=config.ping,
                defense=config.defense,autoBlock=config.autoBlock,sliders=config.sliders}
            local encoded=http:JSONEncode(pack(relevant))
            if encoded~=lastConfig then lastConfig=encoded;session.emit("settings_changed",relevant) end
            local assets=workspace:FindFirstChild("Assets")
            local bounds=assets and assets:FindFirstChild("CourtBounds")
            local geometry={}
            if bounds then for _,part in ipairs(bounds:GetChildren()) do
                if part:IsA("BasePart") then table.insert(geometry,{name=part.Name,cf=frame(part.CFrame),size=vec(part.Size)}) end
            end end
            local boundsEncoded=http:JSONEncode(geometry)
            if boundsEncoded~=lastBounds then lastBounds=boundsEncoded;session.emit("court_bounds",geometry) end
            task.defer(function() if session.alive then pcall(saveStatus) end end)
        end
    end)
    task.spawn(function()
        while session.alive do
            task.wait(.5)
            if session.alive then writer.pump() end
        end
    end)
    session.flush()
    warn(prefix .. "Detailed gameplay logs started; logging restarts after each teleport.")
end
antiContestV2.startRecorder()

warn(prefix .. "Controller Auto Green ready: X/Square shoots; Y/Triangle dunks. Native controller remaps are followed.")
warn(prefix .. "Anti Contest v2 available in Rage; movement glitches are possible and 0% contest is not guaranteed.")

]=]
return assert(loadstring(source, "WizardHub"))(source)
